// The workflow host injects a phase reporter; direct maintenance/self-test CLI modes
// intentionally degrade to a no-op reporter instead of failing before their first gate.
const phase =
  typeof globalThis.phase === "function" ? globalThis.phase.bind(globalThis) : () => undefined;

function deepFreezeExact(value) {
  if (value === null || typeof value !== "object" || Object.isFrozen(value)) return value;
  for (const key of Reflect.ownKeys(value)) deepFreezeExact(value[key]);
  return Object.freeze(value);
}

function ownEnvironmentString(source, key, { required = false } = {}) {
  const descriptor = Object.getOwnPropertyDescriptor(source, key);
  if (!descriptor) {
    if (required) throw new Error("TASK-540 required environment value is missing: " + key);
    return null;
  }
  if (
    !Object.hasOwn(descriptor, "value") ||
    typeof descriptor.value !== "string" ||
    (required && descriptor.value.length === 0)
  ) {
    throw new Error("TASK-540 environment value is invalid: " + key);
  }
  return descriptor.value;
}

function parseStrictRepoEnvironment(source) {
  if (
    typeof source !== "string" ||
    Buffer.byteLength(source) > 1024 * 1024 ||
    source.includes("\0")
  ) {
    throw new Error("TASK-540 repo environment is unavailable or invalid");
  }
  const seen = new Set();
  for (const line of source.split(/\r?\n/u)) {
    const match = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=/u.exec(line);
    if (!match) continue;
    if (seen.has(match[1])) throw new Error("TASK-540 repo environment repeats a key");
    seen.add(match[1]);
  }
  const parsed = parseEnv(source);
  const result = Object.create(null);
  for (const key of Reflect.ownKeys(parsed)) {
    if (typeof key !== "string" || ["__proto__", "prototype", "constructor"].includes(key)) {
      throw new Error("TASK-540 repo environment contains an unsafe key");
    }
    const value = ownEnvironmentString(parsed, key, { required: true });
    const processControlKey =
      /^(?:PATH|BUN_.+|NODE_.+|NPM_CONFIG_.+|PNPM_.+|YARN_.+|DENO_.+|GIT_.+|SSH_.+|LD_.+|DYLD_.+|BASH_ENV|ENV|IFS|SHELLOPTS|CDPATH|HTTP_PROXY|HTTPS_PROXY|ALL_PROXY|NO_PROXY|SSL_CERT_FILE|SSL_CERT_DIR)$/iu.test(
        key
      );
    if (processControlKey && !REPO_FIXED_PROCESS_CONTROL_KEYS.includes(key)) {
      throw new Error("TASK-540 repo environment contains a process-control key");
    }
    result[key] = value;
  }
  return Object.freeze(result);
}

const execFileAsync = promisify(execFile);
const ROOT_GIT_EXECUTABLE = "/usr/bin/git";
const ROOT_PROJECT_PARENT = "/home/coder/project";
const ROOT_EXPECTED_GIT_COMMON_DIR = ROOT_PROJECT_PARENT + "/Coderso/.git";
const ROOT_EXPECTED_BRANCH = "feature/tasks-fixes";
const ROOT_EXPECTED_MODULE_BASENAME = "task-540-implement.mjs";
const ROOT_DERIVATION_DEPENDENCY_KEYS = Object.freeze([
  "execFile",
  "fileURLToPath",
  "lstat",
  "readFile",
  "realpath",
]);
const ROOT_RUNTIME_DEPENDENCY_KEYS = Object.freeze(["lstat", "realpath"]);
const ROOT_GIT_ENVIRONMENT = Object.freeze(
  Object.assign(Object.create(null), {
    GIT_CONFIG_GLOBAL: "/dev/null",
    GIT_CONFIG_NOSYSTEM: "1",
    GIT_OPTIONAL_LOCKS: "0",
    GIT_TERMINAL_PROMPT: "0",
    HOME: "/nonexistent/task540-implement-root-git-home",
    LANG: "C.UTF-8",
    LC_ALL: "C.UTF-8",
    PATH: "/usr/bin:/bin",
  })
);
const ROOT_LIVE_DEPS = Object.freeze({
  execFile: execFileAsync,
  fileURLToPath,
  lstat,
  readFile,
  realpath,
});
const ROOT_RUNTIME_LIVE_DEPS = Object.freeze({ lstat, realpath });

function rootInvariant(condition, message) {
  if (!condition) throw new Error(message);
}

function requireExactRootFunctionDependencies(deps, expectedKeys, label) {
  rootInvariant(
    deps !== null &&
      typeof deps === "object" &&
      !Array.isArray(deps) &&
      Object.keys(deps).sort().join(",") === [...expectedKeys].sort().join(","),
    label + ": dependency keys drift"
  );
  for (const key of expectedKeys) {
    const descriptor = Object.getOwnPropertyDescriptor(deps, key);
    rootInvariant(
      descriptor && Object.hasOwn(descriptor, "value") && typeof descriptor.value === "function",
      label + ": dependency is not an own function"
    );
  }
  return deps;
}

function requireSingleLineRootGitObservation(result, label) {
  rootInvariant(
    result !== null &&
      typeof result === "object" &&
      !Array.isArray(result) &&
      Object.keys(result).sort().join(",") === "stderr,stdout" &&
      typeof result.stdout === "string" &&
      typeof result.stderr === "string" &&
      result.stderr.length === 0 &&
      Buffer.byteLength(result.stdout) <= 4096 &&
      /^[^\0\r\n]+(?:\r?\n)?$/u.test(result.stdout),
    label + ": Git observation is malformed"
  );
  return result.stdout.trim();
}

function requireTask540WorktreeRootProjection(projection, label) {
  if (
    projection === null ||
    typeof projection !== "object" ||
    Array.isArray(projection) ||
    Object.keys(projection).sort().join(",") !== "branch,gitCommonDir,gitDir,modulePath,root" ||
    dirname(projection.root) !== ROOT_PROJECT_PARENT ||
    !/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/u.test(basename(projection.root)) ||
    projection.modulePath !==
      projection.root + "/_docs/_workflows/" + ROOT_EXPECTED_MODULE_BASENAME ||
    projection.branch !== ROOT_EXPECTED_BRANCH ||
    projection.gitCommonDir !== ROOT_EXPECTED_GIT_COMMON_DIR ||
    basename(projection.gitCommonDir) !== ".git" ||
    dirname(dirname(projection.gitCommonDir)) !== ROOT_PROJECT_PARENT ||
    !/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/u.test(basename(dirname(projection.gitCommonDir))) ||
    projection.gitDir === projection.gitCommonDir ||
    dirname(projection.gitDir) !== projection.gitCommonDir + "/worktrees" ||
    basename(projection.gitDir) !== basename(projection.root)
  ) {
    throw new Error(label + ": dedicated worktree relationship drift");
  }
  return deepFreezeExact({ ...projection });
}

async function deriveTask540WorktreeRoot(moduleUrl, deps = ROOT_LIVE_DEPS) {
  const authorityDeps = requireExactRootFunctionDependencies(
    deps,
    ROOT_DERIVATION_DEPENDENCY_KEYS,
    "TASK-540 implementation root"
  );
  rootInvariant(typeof moduleUrl === "string", "TASK-540 implementation module URL is invalid");
  const modulePath = authorityDeps.fileURLToPath(moduleUrl);
  rootInvariant(
    typeof modulePath === "string" &&
      modulePath.startsWith(ROOT_PROJECT_PARENT + "/") &&
      resolve(modulePath) === modulePath,
    "TASK-540 implementation module path is invalid"
  );
  const candidate = resolve(dirname(modulePath), "../..");
  if (modulePath !== candidate + "/_docs/_workflows/" + ROOT_EXPECTED_MODULE_BASENAME) {
    throw new Error("TASK-540 implementation module path drift");
  }
  const paths = [
    ROOT_PROJECT_PARENT,
    candidate,
    candidate + "/_docs",
    candidate + "/_docs/_workflows",
    modulePath,
  ];
  for (const [index, target] of paths.entries()) {
    const info = await authorityDeps.lstat(target);
    if (
      info.isSymbolicLink() ||
      !(index === paths.length - 1 ? info.isFile() : info.isDirectory()) ||
      (await authorityDeps.realpath(target)) !== target
    ) {
      throw new Error("TASK-540 implementation root path is not canonical");
    }
  }
  const gitFilePath = candidate + "/.git";
  const gitFileInfo = await authorityDeps.lstat(gitFilePath);
  rootInvariant(
    !gitFileInfo.isSymbolicLink() &&
      gitFileInfo.isFile() &&
      (await authorityDeps.realpath(gitFilePath)) === gitFilePath,
    "TASK-540 implementation worktree Git file is not canonical"
  );
  const gitFileSource = await authorityDeps.readFile(gitFilePath, "utf8");
  rootInvariant(
    typeof gitFileSource === "string" &&
      Buffer.byteLength(gitFileSource) <= 4096 &&
      /^gitdir: \/[^\0\r\n]+\r?\n$/u.test(gitFileSource),
    "TASK-540 implementation worktree Git file is malformed"
  );
  const gitFileTarget = await authorityDeps.realpath(gitFileSource.slice("gitdir: ".length).trim());
  const options = {
    cwd: candidate,
    encoding: "utf8",
    env: ROOT_GIT_ENVIRONMENT,
    maxBuffer: 64 * 1024,
  };
  const [topLevelResult, gitDirResult, gitCommonDirResult, branchResult] = await Promise.all([
    authorityDeps.execFile(ROOT_GIT_EXECUTABLE, ["rev-parse", "--show-toplevel"], options),
    authorityDeps.execFile(
      ROOT_GIT_EXECUTABLE,
      ["rev-parse", "--path-format=absolute", "--git-dir"],
      options
    ),
    authorityDeps.execFile(
      ROOT_GIT_EXECUTABLE,
      ["rev-parse", "--path-format=absolute", "--git-common-dir"],
      options
    ),
    authorityDeps.execFile(ROOT_GIT_EXECUTABLE, ["branch", "--show-current"], options),
  ]);
  const topLevel = await authorityDeps.realpath(
    requireSingleLineRootGitObservation(topLevelResult, "TASK-540 implementation Git top-level")
  );
  const gitDir = await authorityDeps.realpath(
    requireSingleLineRootGitObservation(gitDirResult, "TASK-540 implementation Git directory")
  );
  const gitCommonDir = await authorityDeps.realpath(
    requireSingleLineRootGitObservation(
      gitCommonDirResult,
      "TASK-540 implementation Git common directory"
    )
  );
  const branch = requireSingleLineRootGitObservation(
    branchResult,
    "TASK-540 implementation Git branch"
  );
  if (topLevel !== candidate || gitDir !== gitFileTarget) {
    throw new Error("TASK-540 implementation Git top-level or worktree Git-file relation drift");
  }
  return requireTask540WorktreeRootProjection(
    {
      branch,
      gitCommonDir,
      gitDir,
      modulePath,
      root: candidate,
    },
    "TASK-540 implementation root"
  );
}

async function requireTask540LocalRuntimeAuthority(rootAuthority, deps = ROOT_RUNTIME_LIVE_DEPS) {
  const authorityDeps = requireExactRootFunctionDependencies(
    deps,
    ROOT_RUNTIME_DEPENDENCY_KEYS,
    "TASK-540 implementation runtime"
  );
  const verifiedRoot = requireTask540WorktreeRootProjection(
    { ...rootAuthority },
    "TASK-540 implementation runtime root"
  ).root;
  const resources = Object.freeze([
    Object.freeze({ kind: "file", path: verifiedRoot + "/.env" }),
    Object.freeze({ kind: "directory", path: verifiedRoot + "/node_modules" }),
  ]);
  for (const resource of resources) {
    const info = await authorityDeps.lstat(resource.path);
    const linkDescriptor = Object.getOwnPropertyDescriptor(info, "nlink");
    const safeLinkCount =
      linkDescriptor &&
      Object.hasOwn(linkDescriptor, "value") &&
      Number.isSafeInteger(linkDescriptor.value) &&
      linkDescriptor.value >= 1;
    rootInvariant(
      !info.isSymbolicLink() &&
        (resource.kind === "file" ? info.isFile() : info.isDirectory()) &&
        safeLinkCount &&
        (resource.kind !== "file" || linkDescriptor.value === 1) &&
        (await authorityDeps.realpath(resource.path)) === resource.path,
      "TASK-540 implementation runtime resource is not worktree-local"
    );
  }
  return deepFreezeExact({
    envPath: resources[0].path,
    nodeModulesPath: resources[1].path,
    root: verifiedRoot,
  });
}

function createTask540RootAuthorityFixture(overrides = {}) {
  const root = overrides.root ?? ROOT_PROJECT_PARENT + "/Coderso-task540-exec";
  const modulePath =
    overrides.modulePath ?? root + "/_docs/_workflows/" + ROOT_EXPECTED_MODULE_BASENAME;
  const gitCommonDir = overrides.gitCommonDir ?? ROOT_EXPECTED_GIT_COMMON_DIR;
  const gitDir = overrides.gitDir ?? gitCommonDir + "/worktrees/" + basename(root);
  const gitFileTarget =
    overrides.gitFileTarget ?? ROOT_PROJECT_PARENT + "/Coderso/.git/worktrees/" + basename(root);
  const symlinks = new Set(overrides.symlinks ?? []);
  const pathKinds = new Map(
    [
      [ROOT_PROJECT_PARENT, "directory"],
      [root, "directory"],
      [root + "/_docs", "directory"],
      [root + "/_docs/_workflows", "directory"],
      [root + "/.git", "file"],
      [modulePath, "file"],
      ...(overrides.pathKinds ?? []),
    ].map(([path, kind]) => [path, kind])
  );
  const realpaths = new Map(overrides.realpaths ?? []);
  const gitRows = new Map([
    ["rev-parse\0--show-toplevel", overrides.topLevel ?? root],
    ["rev-parse\0--path-format=absolute\0--git-dir", gitDir],
    ["rev-parse\0--path-format=absolute\0--git-common-dir", gitCommonDir],
    ["branch\0--show-current", overrides.branch ?? ROOT_EXPECTED_BRANCH],
  ]);
  const deps = Object.freeze({
    execFile: async (executable, args, options) => {
      rootInvariant(
        executable === ROOT_GIT_EXECUTABLE &&
          options.cwd === root &&
          options.encoding === "utf8" &&
          options.env === ROOT_GIT_ENVIRONMENT &&
          options.maxBuffer === 64 * 1024,
        "TASK-540 implementation fake Git invocation drift"
      );
      const key = args.join("\0");
      rootInvariant(gitRows.has(key), "TASK-540 implementation fake Git argv drift");
      return (
        overrides.gitResults?.[key] ?? {
          stderr: "",
          stdout: gitRows.get(key) + "\n",
        }
      );
    },
    fileURLToPath: (url) => {
      rootInvariant(url === "task540:fixture", "TASK-540 implementation fake module URL drift");
      return modulePath;
    },
    lstat: async (target) => {
      const kind = pathKinds.get(target);
      rootInvariant(kind !== undefined, "TASK-540 implementation fake lstat path drift");
      return Object.freeze({
        isDirectory: () => kind === "directory",
        isFile: () => kind === "file",
        isSymbolicLink: () => symlinks.has(target),
      });
    },
    readFile: async (target, encoding) => {
      rootInvariant(
        target === root + "/.git" && encoding === "utf8",
        "TASK-540 implementation fake Git-file read drift"
      );
      return overrides.gitFileSource ?? "gitdir: " + gitFileTarget + "\n";
    },
    realpath: async (target) => realpaths.get(target) ?? target,
  });
  return Object.freeze({ deps, moduleUrl: "task540:fixture", root });
}

async function assertTask540RootAuthorityContract() {
  const baselineFixture = createTask540RootAuthorityFixture();
  const baseline = await deriveTask540WorktreeRoot(baselineFixture.moduleUrl, baselineFixture.deps);
  rootInvariant(
    baseline.root === baselineFixture.root &&
      baseline.modulePath.endsWith("/" + ROOT_EXPECTED_MODULE_BASENAME),
    "TASK-540 implementation root fixture baseline drift"
  );
  const rejectionFixtures = [
    createTask540RootAuthorityFixture({
      symlinks: [
        ROOT_PROJECT_PARENT +
          "/Coderso-task540-exec/_docs/_workflows/" +
          ROOT_EXPECTED_MODULE_BASENAME,
      ],
    }),
    createTask540RootAuthorityFixture({
      symlinks: [ROOT_PROJECT_PARENT + "/Coderso-task540-exec"],
    }),
    createTask540RootAuthorityFixture({
      symlinks: [ROOT_PROJECT_PARENT + "/Coderso-task540-exec/_docs/_workflows"],
    }),
    createTask540RootAuthorityFixture({
      symlinks: [ROOT_PROJECT_PARENT + "/Coderso-task540-exec/.git"],
    }),
    createTask540RootAuthorityFixture({
      pathKinds: [
        [
          ROOT_PROJECT_PARENT +
            "/Coderso-task540-exec/_docs/_workflows/" +
            ROOT_EXPECTED_MODULE_BASENAME,
          "directory",
        ],
      ],
    }),
    createTask540RootAuthorityFixture({
      realpaths: [
        [ROOT_PROJECT_PARENT + "/Coderso-task540-exec", ROOT_PROJECT_PARENT + "/Coderso-sibling"],
      ],
    }),
    createTask540RootAuthorityFixture({ root: "/tmp/Coderso-task540-exec" }),
    createTask540RootAuthorityFixture({ root: ROOT_PROJECT_PARENT + "/-unsafe" }),
    createTask540RootAuthorityFixture({
      modulePath: ROOT_PROJECT_PARENT + "/Coderso-task540-exec/_docs/_workflows/task-540-copy.mjs",
    }),
    createTask540RootAuthorityFixture({
      root: ROOT_PROJECT_PARENT + "/Coderso",
      gitCommonDir: ROOT_PROJECT_PARENT + "/Coderso/.git",
      gitDir: ROOT_PROJECT_PARENT + "/Coderso/.git",
    }),
    createTask540RootAuthorityFixture({
      root: ROOT_PROJECT_PARENT + "/Coderso-sibling",
      branch: "feat/implementations",
    }),
    createTask540RootAuthorityFixture({ branch: "feat/implementations" }),
    createTask540RootAuthorityFixture({ topLevel: ROOT_PROJECT_PARENT + "/Coderso" }),
    createTask540RootAuthorityFixture({
      gitDir: ROOT_PROJECT_PARENT + "/Coderso/.git/other/Coderso-task540-exec",
    }),
    createTask540RootAuthorityFixture({
      gitCommonDir: ROOT_PROJECT_PARENT + "/Elsewhere/.git",
      gitDir: ROOT_PROJECT_PARENT + "/Elsewhere/.git/worktrees/Coderso-task540-exec",
      gitFileTarget: ROOT_PROJECT_PARENT + "/Elsewhere/.git/worktrees/Coderso-task540-exec",
    }),
    createTask540RootAuthorityFixture({
      gitFileSource: "gitdir: relative/worktree\n",
    }),
    createTask540RootAuthorityFixture({
      gitResults: {
        ["branch\0--show-current"]: {
          stderr: "",
          stdout: ROOT_EXPECTED_BRANCH + "\nsecond-line\n",
        },
      },
    }),
  ];
  let rejected = 0;
  for (const fixture of rejectionFixtures) {
    try {
      await deriveTask540WorktreeRoot(fixture.moduleUrl, fixture.deps);
    } catch {
      rejected += 1;
    }
  }
  const spoofDependencyKeys = ["argv", "cwd", "env", "global"];
  for (const key of spoofDependencyKeys) {
    try {
      await deriveTask540WorktreeRoot(
        baselineFixture.moduleUrl,
        Object.freeze({ ...baselineFixture.deps, [key]: "/tmp/spoof" })
      );
    } catch {
      rejected += 1;
    }
  }
  const originalCwd = process.cwd();
  const originalArgv = process.argv;
  const originalEnvDescriptor = Object.getOwnPropertyDescriptor(process.env, "TASK540_ROOT");
  const originalGlobalDescriptor = Object.getOwnPropertyDescriptor(globalThis, "TASK540_ROOT");
  let ambientSpoofPass = false;
  try {
    process.chdir("/tmp");
    process.argv = [...process.argv, "--root=/tmp/spoof"];
    process.env.TASK540_ROOT = "/tmp/spoof";
    Object.defineProperty(globalThis, "TASK540_ROOT", {
      configurable: true,
      value: "/tmp/spoof",
      writable: true,
    });
    ambientSpoofPass =
      (await deriveTask540WorktreeRoot(baselineFixture.moduleUrl, baselineFixture.deps)).root ===
      baseline.root;
  } finally {
    process.chdir(originalCwd);
    process.argv = originalArgv;
    if (originalEnvDescriptor) {
      Object.defineProperty(process.env, "TASK540_ROOT", originalEnvDescriptor);
    } else {
      delete process.env.TASK540_ROOT;
    }
    if (originalGlobalDescriptor) {
      Object.defineProperty(globalThis, "TASK540_ROOT", originalGlobalDescriptor);
    } else {
      delete globalThis.TASK540_ROOT;
    }
  }
  rootInvariant(
    rejected === rejectionFixtures.length + spoofDependencyKeys.length && ambientSpoofPass,
    "TASK-540 implementation root authority mutants failed"
  );
  const runtimePaths = new Map([
    [baseline.root + "/.env", "file"],
    [baseline.root + "/node_modules", "directory"],
  ]);
  const runtimeDeps = Object.freeze({
    lstat: async (target) => {
      const kind = runtimePaths.get(target);
      rootInvariant(kind !== undefined, "TASK-540 implementation fake runtime path drift");
      return Object.freeze({
        isDirectory: () => kind === "directory",
        isFile: () => kind === "file",
        isSymbolicLink: () => false,
        nlink: 1,
      });
    },
    realpath: async (target) => target,
  });
  await requireTask540LocalRuntimeAuthority(baseline, runtimeDeps);
  let runtimeRejected = 0;
  for (const deps of [
    Object.freeze({
      ...runtimeDeps,
      lstat: async (target) => {
        const info = await runtimeDeps.lstat(target);
        return target.endsWith("/.env")
          ? Object.freeze({ ...info, isSymbolicLink: () => true })
          : info;
      },
    }),
    Object.freeze({
      ...runtimeDeps,
      lstat: async (target) => {
        const info = await runtimeDeps.lstat(target);
        return target.endsWith("/.env")
          ? Object.freeze({
              ...info,
              isDirectory: () => true,
              isFile: () => false,
            })
          : info;
      },
    }),
    Object.freeze({
      ...runtimeDeps,
      lstat: async (target) => {
        const info = await runtimeDeps.lstat(target);
        return target.endsWith("/node_modules")
          ? Object.freeze({
              ...info,
              isDirectory: () => false,
              isFile: () => true,
            })
          : info;
      },
    }),
    Object.freeze({
      ...runtimeDeps,
      lstat: async (target) => {
        const info = await runtimeDeps.lstat(target);
        return target.endsWith("/node_modules")
          ? Object.freeze({ ...info, isSymbolicLink: () => true })
          : info;
      },
    }),
    Object.freeze({
      ...runtimeDeps,
      realpath: async (target) =>
        target.endsWith("/.env") ? ROOT_PROJECT_PARENT + "/Coderso/.env" : target,
    }),
    Object.freeze({
      ...runtimeDeps,
      realpath: async (target) =>
        target.endsWith("/node_modules") ? ROOT_PROJECT_PARENT + "/Coderso/node_modules" : target,
    }),
    Object.freeze({
      ...runtimeDeps,
      lstat: async (target) => {
        const info = await runtimeDeps.lstat(target);
        return target.endsWith("/.env") ? Object.freeze({ ...info, nlink: 2 }) : info;
      },
    }),
    Object.freeze({
      ...runtimeDeps,
      lstat: async (target) => {
        const info = await runtimeDeps.lstat(target);
        return target.endsWith("/node_modules") ? Object.freeze({ ...info, nlink: 0 }) : info;
      },
    }),
    Object.freeze({ ...runtimeDeps, env: "/tmp/spoof" }),
  ]) {
    try {
      await requireTask540LocalRuntimeAuthority(baseline, deps);
    } catch {
      runtimeRejected += 1;
    }
  }
  rootInvariant(runtimeRejected === 9, "TASK-540 implementation runtime mutants failed");
  return deepFreezeExact({
    ambientSpoofCases: 4,
    derivationCases: rejectionFixtures.length + spoofDependencyKeys.length + 1,
    runtimeCases: runtimeRejected + 1,
  });
}

