const EVIDENCE_BEGIN = "<!-- TASK-540-SMOKE-EVIDENCE:BEGIN -->";
const EVIDENCE_END = "<!-- TASK-540-SMOKE-EVIDENCE:END -->";
function sameUniqueSet(actual, expected) {
  return (
    actual.length === expected.length &&
    new Set(actual).size === actual.length &&
    actual.every((value) => expected.includes(value))
  );
}

function resultPassed(result) {
  return result.pass === true && result.errors.length === 0;
}

const SENSITIVE_FIELD_NAME =
  "password|passwd|secret|api[_\\s.-]*key|private[_\\s.-]*key|" +
  "csrf(?:[_\\s.-]*token)?(?:[_\\s.-]*hash)?|" +
  "authorization|cookie|set-cookie|access[_\\s.-]*token|refresh[_\\s.-]*token|" +
  "session[_\\s.-]*(?:token|hash|cookie)|token[_\\s.-]*hash|password[_\\s.-]*hash";
const SENSITIVE_ASSIGNMENT_PATTERN = new RegExp(
  "(?:^[ \\t]*[+-]?[ \\t]*|[\\r\\n][ \\t]*[+-]?[ \\t]*|[ \\t,{;])" +
    "(?:[\\\"']?(?:" +
    SENSITIVE_FIELD_NAME +
    ")[\\\"']?)\\s*(?::|=)\\s*",
  "gi"
);
const RAW_AUTHORIZATION_PATTERN =
  /\b(?:authorization|proxy-authorization)\s*:\s*(?!\[?redacted\]?|<redacted>)[^\r\n]+/i;
const RAW_COOKIE_HEADER_PATTERN =
  /\b(?:cookie|set-cookie)\s*:\s*(?!\[?redacted\]?|<redacted>)[^\r\n]+/i;
const RAW_BEARER_PATTERN = /\bbearer\s+[a-z0-9._~+\/-]{8,}/i;
const JWT_VALUE_PATTERN = /\beyJ[a-zA-Z0-9_-]{8,}\.[a-zA-Z0-9_-]{8,}\.[a-zA-Z0-9_-]{8,}\b/;
const SECRET_BROWSER_ACCESS_PATTERN =
  /\bdocument\.cookie\b|\b(?:localStorage|sessionStorage)\.getItem\(\s*["'][^"']*(?:token|cookie|csrf|secret|password)[^"']*["']/i;
const SAFE_REDACTED_VALUE_PATTERN =
  /^(?:\$[A-Z][A-Z0-9_]*|\[?(?:discarded|discard-me|redacted)\]?|<redacted>|null|undefined|true|false)$/i;

function scanSensitiveBlockScalarEnd(value, rhsStart) {
  let end = value.indexOf("\n", rhsStart);
  if (end < 0) return value.length;
  if (end > rhsStart && value[end - 1] === "\r") end -= 1;
  let cursor = value.indexOf("\n", rhsStart);
  while (cursor >= 0 && cursor + 1 < value.length) {
    const lineStart = cursor + 1;
    const nextNewline = value.indexOf("\n", lineStart);
    const physicalLineEnd = nextNewline < 0 ? value.length : nextNewline;
    const lineEnd =
      physicalLineEnd > lineStart && value[physicalLineEnd - 1] === "\r"
        ? physicalLineEnd - 1
        : physicalLineEnd;
    const line = value.slice(lineStart, lineEnd);
    if (!/^(?:[ \t]+|[+-](?:[ \t]+|$))/.test(line)) break;
    end = lineEnd;
    if (nextNewline < 0) break;
    cursor = nextNewline;
  }
  return end;
}

function slashBeginsSensitiveRegex(value, rhsStart, slashIndex) {
  let prior = slashIndex - 1;
  while (prior >= rhsStart && /\s/.test(value[prior])) prior -= 1;
  if (
    value[prior] === "<" &&
    /^\/(?:>|[A-Za-z_$][A-Za-z0-9_$:.-]*[ \t]*>)/.test(value.slice(slashIndex))
  ) {
    return false;
  }
  return prior < rhsStart || "([{:;,=!?&|+-*%^~<>".includes(value[prior]);
}

function scanSensitiveAssignmentRhsEnd(value, rhsStart) {
  if (value[rhsStart] === "|" || value[rhsStart] === ">") {
    return scanSensitiveBlockScalarEnd(value, rhsStart);
  }

  const expectedClosers = [];
  let quote = null;
  let escaped = false;
  let blockComment = false;
  let regexLiteral = false;
  let regexCharacterClass = false;
  for (let index = rhsStart; index < value.length; index += 1) {
    const character = value[index];
    const next = value[index + 1];
    if (quote !== null) {
      if (escaped) {
        escaped = false;
      } else if (character === "\\") {
        escaped = true;
      } else if (character === quote) {
        quote = null;
      }
      continue;
    }
    if (regexLiteral) {
      if (escaped) {
        escaped = false;
      } else if (character === "\\") {
        escaped = true;
      } else if (character === "[") {
        regexCharacterClass = true;
      } else if (character === "]") {
        regexCharacterClass = false;
      } else if (character === "/" && !regexCharacterClass) {
        regexLiteral = false;
      } else if (character === "\r" || character === "\n") {
        return value.length;
      }
      continue;
    }
    if (blockComment) {
      if (character === "*" && next === "/") {
        blockComment = false;
        index += 1;
      }
      continue;
    }
    if (character === '"' || character === "'" || character === "`") {
      quote = character;
      continue;
    }
    if (character === "/" && next === "*") {
      blockComment = true;
      index += 1;
      continue;
    }
    if (character === "/" && next === "/") {
      const lineEnd = value.indexOf("\n", index + 2);
      if (lineEnd < 0) return value.length;
      if (expectedClosers.length === 0) return lineEnd;
      index = lineEnd;
      continue;
    }
    if (character === "/" && slashBeginsSensitiveRegex(value, rhsStart, index)) {
      regexLiteral = true;
      regexCharacterClass = false;
      escaped = false;
      continue;
    }
    if (character === "(") {
      expectedClosers.push(")");
      continue;
    }
    if (character === "[") {
      expectedClosers.push("]");
      continue;
    }
    if (character === "{") {
      expectedClosers.push("}");
      continue;
    }
    if (character === "<") {
      expectedClosers.push(">");
      continue;
    }
    if (character === ">") {
      if (expectedClosers.at(-1) === ">") expectedClosers.pop();
      continue;
    }
    if (character === ")" || character === "]" || character === "}") {
      if (expectedClosers.length === 0) return index;
      if (expectedClosers.at(-1) !== character) return value.length;
      expectedClosers.pop();
      continue;
    }
    if (
      expectedClosers.length === 0 &&
      (character === "," || character === ";" || character === "\r" || character === "\n")
    ) {
      return index;
    }
  }
  return value.length;
}

function sensitiveAssignmentRanges(value) {
  const ranges = [];
  SENSITIVE_ASSIGNMENT_PATTERN.lastIndex = 0;
  for (let match = SENSITIVE_ASSIGNMENT_PATTERN.exec(value); match !== null;) {
    const rhsStart = match.index + match[0].length;
    const rhsEnd = scanSensitiveAssignmentRhsEnd(value, rhsStart);
    ranges.push({ rhsEnd, rhsStart });
    if (rhsEnd > SENSITIVE_ASSIGNMENT_PATTERN.lastIndex) {
      SENSITIVE_ASSIGNMENT_PATTERN.lastIndex = rhsEnd;
    }
    match = SENSITIVE_ASSIGNMENT_PATTERN.exec(value);
  }
  return ranges;
}

function sensitiveAssignedValueIsSafe(value) {
  const clean = value.trim().replace(/^["'`]|["'`]$/g, "");
  return SAFE_REDACTED_VALUE_PATTERN.test(clean);
}
const SENSITIVE_ENV_KEY_PATTERN =
  /(?:^ADMIN_EMAIL$|PASSWORD|PASSWD|SECRET|(?:^|_)TOKEN(?:_|$)|(?:^|_)KEY(?:_|$)|API[_-]?KEY|PRIVATE[_-]?KEY|ACCESS[_-]?KEY|(?:ENC|HASH)[_-]?KEY|CONNECTION[_-]?STRING|DATABASE_URL|REDIS_URL|DSN)/i;
const REQUIRED_REDACTION_CREDENTIAL_KEYS = Object.freeze(["ADMIN_EMAIL", "ADMIN_PASSWORD"]);
function buildSensitiveValueCorpus() {
  const values = new Set();
  const addClassifiedValue = (value) => {
    if (typeof value === "string" && value.length > 0) values.add(value);
  };

  for (const key of REQUIRED_REDACTION_CREDENTIAL_KEYS) {
    if (typeof REPO_ENV[key] !== "string" || REPO_ENV[key].length === 0) {
      throw new Error("TASK-540 required smoke credentials are unavailable");
    }
    addClassifiedValue(REPO_ENV[key]);
  }
  for (const environment of [INHERITED_ENV_FOR_REDACTION, REPO_ENV]) {
    for (const [key, value] of Object.entries(environment)) {
      if (!SENSITIVE_ENV_KEY_PATTERN.test(key)) continue;
      // Every non-empty classified value joins the corpus. Short/weak values
      // use boundary-aware matching below instead of silently bypassing scans.
      addClassifiedValue(value);
      if (/(?:DATABASE_URL\d*|REDIS_URL\d*|DSN\d*)$/i.test(key) && typeof value === "string") {
        try {
          const parsed = new URL(value);
          addClassifiedValue(parsed.password);
          addClassifiedValue(decodeURIComponent(parsed.password));
        } catch {
          // The full configured value remains in the corpus even when it is not a URL.
        }
      }
    }
  }
  return Object.freeze([...values]);
}

const SENSITIVE_VALUE_CORPUS = buildSensitiveValueCorpus();

function containsConfiguredSensitiveValue(value, secret) {
  if (secret.length >= 6) return value.includes(secret);
  const escaped = secret.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp("(?:^|[^A-Za-z0-9])" + escaped + "(?=$|[^A-Za-z0-9])").test(value);
}

function hasSensitiveEvidence(value) {
  if (
    SENSITIVE_VALUE_CORPUS.some((secret) => containsConfiguredSensitiveValue(value, secret)) ||
    RAW_AUTHORIZATION_PATTERN.test(value) ||
    RAW_COOKIE_HEADER_PATTERN.test(value) ||
    RAW_BEARER_PATTERN.test(value) ||
    JWT_VALUE_PATTERN.test(value) ||
    SECRET_BROWSER_ACCESS_PATTERN.test(value)
  ) {
    return true;
  }
  for (const { rhsEnd, rhsStart } of sensitiveAssignmentRanges(value)) {
    if (!sensitiveAssignedValueIsSafe(value.slice(rhsStart, rhsEnd))) return true;
  }
  return false;
}

function globalPattern(pattern) {
  return new RegExp(
    pattern.source,
    pattern.flags.includes("g") ? pattern.flags : pattern.flags + "g"
  );
}

function sanitizeSensitiveEvidence(value) {
  let sanitized = value;
  for (const secret of SENSITIVE_VALUE_CORPUS) {
    const escaped = secret.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    if (secret.length >= 6) {
      sanitized = sanitized.replace(new RegExp(escaped, "g"), "[redacted]");
    } else {
      sanitized = sanitized.replace(
        new RegExp("(^|[^A-Za-z0-9])" + escaped + "(?=$|[^A-Za-z0-9])", "g"),
        "$1[redacted]"
      );
    }
  }
  for (const pattern of [RAW_AUTHORIZATION_PATTERN, RAW_COOKIE_HEADER_PATTERN]) {
    sanitized = sanitized.replace(globalPattern(pattern), "[redacted-sensitive-evidence]");
  }
  const assignmentRanges = sensitiveAssignmentRanges(sanitized);
  for (let index = assignmentRanges.length - 1; index >= 0; index -= 1) {
    const { rhsEnd, rhsStart } = assignmentRanges[index];
    if (sensitiveAssignedValueIsSafe(sanitized.slice(rhsStart, rhsEnd))) continue;
    sanitized = sanitized.slice(0, rhsStart) + "[redacted]" + sanitized.slice(rhsEnd);
  }
  for (const pattern of [RAW_BEARER_PATTERN, JWT_VALUE_PATTERN, SECRET_BROWSER_ACCESS_PATTERN]) {
    sanitized = sanitized.replace(globalPattern(pattern), "[redacted-sensitive-evidence]");
  }
  if (hasSensitiveEvidence(sanitized)) {
    throw new Error("TASK-540 sensitive evidence could not be sanitized");
  }
  return sanitized;
}

function hasSensitiveEvidenceDeep(value) {
  if (typeof value === "string") return hasSensitiveEvidence(value);
  if (Array.isArray(value)) return value.some(hasSensitiveEvidenceDeep);
  if (value && typeof value === "object") {
    return Object.entries(value).some(
      ([key, item]) => hasSensitiveEvidence(key) || hasSensitiveEvidenceDeep(item)
    );
  }
  return false;
}

function requireSensitiveSafeAgentResult(result, label) {
  if (hasSensitiveEvidenceDeep(result)) {
    throw new Error(label + ": structured agent result failed value-aware redaction");
  }
  return result;
}

async function dispatchAgentSafely(grounded, options) {
  if (
    !grounded ||
    typeof grounded !== "object" ||
    typeof grounded.text !== "string" ||
    !grounded.context
  ) {
    throw new Error(options.label + ": grounded agent prompt is invalid");
  }
  requireGroundedPromptBytes(grounded.text, options.label);
  await requireWorkflowSensitiveEnvBaseline(options.label + " before agent dispatch");
  await requireInitialGitIndexBaseline(options.label + " before agent dispatch");
  await requireGroundedContextCurrent(
    grounded.context,
    options.label + " immediately before agent dispatch"
  );
  let result = null;
  let dispatchError = null;
  try {
    result = requireSensitiveSafeAgentResult(await agent(grounded.text, options), options.label);
  } catch {
    // Agent/schema errors may contain rejected structured output. Discard the
    // original object/message before it can enter failures, logs, or a prompt.
    dispatchError = new Error(options.label + ": agent dispatch failed; details discarded");
  }
  const boundaryErrors = [];
  if (dispatchError) boundaryErrors.push(dispatchError);
  try {
    await requireInitialGitIndexBaseline(options.label + " after agent dispatch");
  } catch (error) {
    boundaryErrors.push(error);
  }
  try {
    await requireWorkflowSensitiveEnvBaseline(options.label + " after agent dispatch");
  } catch (error) {
    boundaryErrors.push(error);
  }
  try {
    await agent.finalize(boundaryErrors.length === 0 ? "accepted" : "rejected_rolled_back");
  } catch (error) {
    boundaryErrors.push(error);
  }
  if (boundaryErrors.length > 1) {
    throw new AggregateError(
      boundaryErrors,
      options.label + ": agent dispatch or its repository boundaries failed"
    );
  }
  if (boundaryErrors.length === 1) throw boundaryErrors[0];
  return result;
}

function delay(milliseconds) {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

function requireAllResults(results, expectedIds, label) {
  if (!Array.isArray(results) || results.length !== expectedIds.length) {
    throw new Error(label + ": missing result count");
  }
  for (let index = 0; index < expectedIds.length; index += 1) {
    const item = results[index];
    if (!item || item.id !== expectedIds[index] || item.result == null) {
      throw new Error(label + ": missing/reordered result " + expectedIds[index]);
    }
  }
  return results;
}

async function git(args) {
  const result = await execFileAsync(
    await requireValidationExecutableIdentity("git"),
    materializeObservationalGitArgs(args),
    {
      cwd: ROOT,
      encoding: "utf8",
      env: buildObservationalGitEnvironment(),
      maxBuffer: 32 * 1024 * 1024,
    }
  );
  return result.stdout;
}

async function gitBytes(args) {
  const result = await execFileAsync(
    await requireValidationExecutableIdentity("git"),
    materializeObservationalGitArgs(args),
    {
      cwd: ROOT,
      encoding: "buffer",
      env: buildObservationalGitEnvironment(),
      maxBuffer: 64 * 1024 * 1024,
    }
  );
  return Buffer.isBuffer(result.stdout) ? result.stdout : Buffer.from(result.stdout);
}

function splitNul(value) {
  return value.split("\0").filter(Boolean);
}

const GIT_INDEX_AUTHORITY_KEYS = Object.freeze(["identity", "indexFile", "stageProjection"]);
const GIT_INDEX_IDENTITY_KEYS = Object.freeze([
  "resolvedPathByteLength",
  "resolvedPathSha256",
  "device",
  "inode",
  "mode",
  "linkCount",
  "mtimeNs",
  "ctimeNs",
]);
const GIT_INDEX_BYTE_PROJECTION_KEYS = Object.freeze(["byteLength", "sha256"]);

function hasExactOwnStringKeys(value, expected) {
  if (!value || typeof value !== "object") return false;
  const keys = Reflect.ownKeys(value);
  return (
    keys.length === expected.length &&
    keys.every((key) => typeof key === "string" && expected.includes(key))
  );
}

function freezeGitIndexByteProjection(value, label) {
  if (
    !hasExactOwnStringKeys(value, GIT_INDEX_BYTE_PROJECTION_KEYS) ||
    !Number.isSafeInteger(value.byteLength) ||
    value.byteLength < 0 ||
    typeof value.sha256 !== "string" ||
    !/^[0-9a-f]{64}$/.test(value.sha256)
  ) {
    throw new Error(label + ": malformed Git index byte projection");
  }
  return Object.freeze({ byteLength: value.byteLength, sha256: value.sha256 });
}

function freezeGitIndexAuthority(value, label) {
  if (
    !hasExactOwnStringKeys(value, GIT_INDEX_AUTHORITY_KEYS) ||
    !hasExactOwnStringKeys(value.identity, GIT_INDEX_IDENTITY_KEYS) ||
    !Number.isSafeInteger(value.identity.resolvedPathByteLength) ||
    value.identity.resolvedPathByteLength <= 0 ||
    typeof value.identity.resolvedPathSha256 !== "string" ||
    !/^[0-9a-f]{64}$/.test(value.identity.resolvedPathSha256) ||
    !["device", "inode", "mode", "linkCount", "mtimeNs", "ctimeNs"].every(
      (key) => typeof value.identity[key] === "string" && /^\d+$/.test(value.identity[key])
    )
  ) {
    throw new Error(label + ": malformed resolved Git index identity");
  }
  return Object.freeze({
    identity: Object.freeze({
      resolvedPathByteLength: value.identity.resolvedPathByteLength,
      resolvedPathSha256: value.identity.resolvedPathSha256,
      device: value.identity.device,
      inode: value.identity.inode,
      mode: value.identity.mode,
      linkCount: value.identity.linkCount,
      mtimeNs: value.identity.mtimeNs,
      ctimeNs: value.identity.ctimeNs,
    }),
    indexFile: freezeGitIndexByteProjection(value.indexFile, label + " index file"),
    stageProjection: freezeGitIndexByteProjection(
      value.stageProjection,
      label + " stage projection"
    ),
  });
}

function sameGitIndexAuthority(left, right) {
  return (
    left.identity.resolvedPathByteLength === right.identity.resolvedPathByteLength &&
    left.identity.resolvedPathSha256 === right.identity.resolvedPathSha256 &&
    left.identity.device === right.identity.device &&
    left.identity.inode === right.identity.inode &&
    left.identity.mode === right.identity.mode &&
    left.identity.linkCount === right.identity.linkCount &&
    left.identity.mtimeNs === right.identity.mtimeNs &&
    left.identity.ctimeNs === right.identity.ctimeNs &&
    left.indexFile.byteLength === right.indexFile.byteLength &&
    left.indexFile.sha256 === right.indexFile.sha256 &&
    left.stageProjection.byteLength === right.stageProjection.byteLength &&
    left.stageProjection.sha256 === right.stageProjection.sha256
  );
}

function createGitIndexBaselineController() {
  let initial = null;
  return Object.freeze({
    captureInitial(authority, label) {
      if (initial !== null) {
        throw new Error(label + ": refusing mid-run Git index baseline adoption");
      }
      initial = freezeGitIndexAuthority(authority, label);
      return initial;
    },
    requireUnchanged(authority, label) {
      if (initial === null) {
        throw new Error(label + ": initial Git index baseline is not captured");
      }
      const current = freezeGitIndexAuthority(authority, label);
      if (!sameGitIndexAuthority(initial, current)) {
        throw new Error(label + ": exact initial Git index baseline changed");
      }
      return current;
    },
  });
}

function parseResolvedGitIndexPath(output, label) {
  if (!Buffer.isBuffer(output) || output.length < 2 || output.at(-1) !== 0x0a) {
    throw new Error(label + ": Git index path output is not one complete line");
  }
  let end = output.length - 1;
  if (end > 0 && output[end - 1] === 0x0d) end -= 1;
  const path = output.subarray(0, end);
  if (path.length === 0 || path.includes(0x00) || path.includes(0x0a) || path.includes(0x0d)) {
    throw new Error(label + ": resolved Git index path is ambiguous");
  }
  return Buffer.from(path);
}

function gitIndexStatIdentity(info, resolvedPath) {
  return Object.freeze({
    resolvedPathByteLength: resolvedPath.length,
    resolvedPathSha256: createHash("sha256").update(resolvedPath).digest("hex"),
    device: info.dev.toString(),
    inode: info.ino.toString(),
    mode: info.mode.toString(),
    linkCount: info.nlink.toString(),
    mtimeNs: info.mtimeNs.toString(),
    ctimeNs: info.ctimeNs.toString(),
  });
}

function sameGitIndexStat(left, right) {
  return (
    left.dev === right.dev &&
    left.ino === right.ino &&
    left.mode === right.mode &&
    left.nlink === right.nlink &&
    left.size === right.size &&
    left.mtimeNs === right.mtimeNs &&
    left.ctimeNs === right.ctimeNs
  );
}

async function readStableRegularFile(path, label, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes <= 0) {
    throw new Error(label + ": stable-file bound is invalid");
  }
  const pathBefore = await lstat(path, { bigint: true });
  if (!pathBefore.isFile() || pathBefore.isSymbolicLink()) {
    throw new Error(label + ": stable-file path is not a regular file");
  }
  const handle = await open(
    path,
    FS_CONSTANTS.O_RDONLY | FS_CONSTANTS.O_NOFOLLOW | FS_CONSTANTS.O_CLOEXEC
  );
  try {
    const handleBefore = await handle.stat({ bigint: true });
    if (
      !handleBefore.isFile() ||
      !sameGitIndexStat(pathBefore, handleBefore) ||
      handleBefore.size > BigInt(maxBytes)
    ) {
      throw new Error(label + ": stable-file identity or bound changed before read");
    }
    const byteLength = Number(handleBefore.size);
    const bytes = Buffer.alloc(byteLength);
    let offset = 0;
    while (offset < byteLength) {
      const { bytesRead } = await handle.read(bytes, offset, byteLength - offset, offset);
      if (bytesRead <= 0) throw new Error(label + ": stable-file read ended early");
      offset += bytesRead;
    }
    const [handleAfter, pathAfter] = await Promise.all([
      handle.stat({ bigint: true }),
      lstat(path, { bigint: true }),
    ]);
    if (
      !handleAfter.isFile() ||
      !pathAfter.isFile() ||
      pathAfter.isSymbolicLink() ||
      !sameGitIndexStat(handleBefore, handleAfter) ||
      !sameGitIndexStat(handleAfter, pathAfter) ||
      BigInt(bytes.length) !== handleAfter.size
    ) {
      throw new Error(label + ": stable-file identity changed during read");
    }
    return Object.freeze({ bytes, stat: handleAfter });
  } finally {
    await handle.close();
  }
}

async function readGitIndexFileAuthority(label) {
  const unresolvedPath = parseResolvedGitIndexPath(
    await gitBytes(["rev-parse", "--path-format=absolute", "--git-path", "index"]),
    label
  );
  const resolvedPath = await realpath(unresolvedPath, { encoding: "buffer" });
  if (!Buffer.isBuffer(resolvedPath) || resolvedPath.length === 0) {
    throw new Error(label + ": Git index path did not resolve as bytes");
  }
  const { bytes, stat: after } = await readStableRegularFile(
    resolvedPath,
    label + " resolved Git index",
    64 * 1024 * 1024
  );
  return freezeGitIndexAuthority(
    {
      identity: gitIndexStatIdentity(after, resolvedPath),
      indexFile: {
        byteLength: bytes.length,
        sha256: createHash("sha256").update(bytes).digest("hex"),
      },
      // Filled only by captureGitIndexAuthority after the binary stage projection
      // is observed between two byte-identical index-file reads.
      stageProjection: {
        byteLength: 0,
        sha256: createHash("sha256").update(Buffer.alloc(0)).digest("hex"),
      },
    },
    label
  );
}

async function captureGitIndexAuthority(label) {
  const before = await readGitIndexFileAuthority(label + " before projection");
  const stageProjection = await gitBytes(["ls-files", "--stage", "-z"]);
  const after = await readGitIndexFileAuthority(label + " after projection");
  if (
    !sameGitIndexAuthority(
      before,
      Object.freeze({ ...after, stageProjection: before.stageProjection })
    )
  ) {
    throw new Error(label + ": Git index changed around its raw stage projection");
  }
  return freezeGitIndexAuthority(
    {
      identity: after.identity,
      indexFile: after.indexFile,
      stageProjection: {
        byteLength: stageProjection.length,
        sha256: createHash("sha256").update(stageProjection).digest("hex"),
      },
    },
    label
  );
}

const GIT_INDEX_BASELINE = createGitIndexBaselineController();

async function captureInitialGitIndexBaseline(label) {
  return GIT_INDEX_BASELINE.captureInitial(await captureGitIndexAuthority(label), label);
}

async function requireInitialGitIndexBaseline(label) {
  return GIT_INDEX_BASELINE.requireUnchanged(await captureGitIndexAuthority(label), label);
}

async function assertTask540GitIndexBaselineContract() {
  const emptySha256 = createHash("sha256").update(Buffer.alloc(0)).digest("hex");
  const base = Object.freeze({
    identity: Object.freeze({
      resolvedPathByteLength: 38,
      resolvedPathSha256: "1".repeat(64),
      device: "43",
      inode: "1001",
      mode: "33188",
      linkCount: "1",
      mtimeNs: "1000000000",
      ctimeNs: "1000000001",
    }),
    indexFile: Object.freeze({ byteLength: 256, sha256: "2".repeat(64) }),
    stageProjection: Object.freeze({ byteLength: 64, sha256: "3".repeat(64) }),
  });
  const withChanges = ({ identity, indexFile, stageProjection }) => ({
    identity: { ...base.identity, ...identity },
    indexFile: { ...base.indexFile, ...indexFile },
    stageProjection: { ...base.stageProjection, ...stageProjection },
  });
  const rejects = (operation) => {
    try {
      operation();
      return false;
    } catch {
      return true;
    }
  };
  const cases = [
    {
      label: "empty stage projection baseline is accepted unchanged",
      test() {
        const controller = createGitIndexBaselineController();
        const empty = withChanges({
          stageProjection: { byteLength: 0, sha256: emptySha256 },
        });
        controller.captureInitial(empty, "empty initial");
        controller.requireUnchanged(empty, "empty unchanged");
        return true;
      },
    },
    {
      label: "non-empty stage projection baseline is accepted unchanged",
      test() {
        const controller = createGitIndexBaselineController();
        controller.captureInitial(base, "non-empty initial");
        controller.requireUnchanged(withChanges({}), "non-empty unchanged");
        return true;
      },
    },
    {
      label: "index byte hash mutation is rejected",
      test() {
        const controller = createGitIndexBaselineController();
        controller.captureInitial(base, "byte hash initial");
        return rejects(() =>
          controller.requireUnchanged(
            withChanges({ indexFile: { sha256: "4".repeat(64) } }),
            "byte hash mutation"
          )
        );
      },
    },
    {
      label: "resolved index file identity mutation is rejected",
      test() {
        const controller = createGitIndexBaselineController();
        controller.captureInitial(base, "identity initial");
        return rejects(() =>
          controller.requireUnchanged(
            withChanges({ identity: { inode: "1002" } }),
            "identity mutation"
          )
        );
      },
    },
    {
      label: "raw stage projection hash mutation is rejected",
      test() {
        const controller = createGitIndexBaselineController();
        controller.captureInitial(base, "stage hash initial");
        return rejects(() =>
          controller.requireUnchanged(
            withChanges({ stageProjection: { sha256: "5".repeat(64) } }),
            "stage hash mutation"
          )
        );
      },
    },
    {
      label: "raw stage projection byte-count mutation is rejected",
      test() {
        const controller = createGitIndexBaselineController();
        controller.captureInitial(base, "stage count initial");
        return rejects(() =>
          controller.requireUnchanged(
            withChanges({ stageProjection: { byteLength: 65 } }),
            "stage count mutation"
          )
        );
      },
    },
    {
      label: "mid-run recapture is rejected without adopting the candidate",
      test() {
        const controller = createGitIndexBaselineController();
        controller.captureInitial(base, "single-assignment initial");
        const candidate = withChanges({ identity: { inode: "1003" } });
        const recaptureRejected = rejects(() =>
          controller.captureInitial(candidate, "mid-run recapture")
        );
        controller.requireUnchanged(withChanges({}), "original remains authoritative");
        return recaptureRejected;
      },
    },
  ];
  for (const testCase of cases) {
    if (testCase.test() !== true) {
      throw new Error("TASK-540 Git index baseline self-test failed: " + testCase.label);
    }
  }
  const liveController = createGitIndexBaselineController();
  liveController.captureInitial(
    await captureGitIndexAuthority("TASK-540 live Git index self-test initial"),
    "TASK-540 live Git index self-test initial"
  );
  liveController.requireUnchanged(
    await captureGitIndexAuthority("TASK-540 live Git index self-test unchanged"),
    "TASK-540 live Git index self-test unchanged"
  );
  return cases.length + 1;
}

function hashStableRegularFileAuthority(bytes, stat) {
  if (!Buffer.isBuffer(bytes)) {
    throw new Error("TASK-540 stable-file fingerprint bytes are invalid");
  }
  const identityKeys = Object.freeze(["dev", "ino", "mode", "nlink", "size", "mtimeNs", "ctimeNs"]);
  if (identityKeys.some((key) => typeof stat?.[key] !== "bigint")) {
    throw new Error("TASK-540 stable-file fingerprint identity is invalid");
  }
  const hash = createHash("sha256");
  hash.update("stable-file-v1\0");
  for (const key of identityKeys) hash.update(key + "\0" + stat[key].toString() + "\0");
  hash.update(bytes);
  return hash.digest("hex");
}

async function hashPath(relativePath) {
  const absolute = ROOT + "/" + relativePath;
  try {
    const before = await lstat(absolute, { bigint: true });
    if (before.isSymbolicLink()) {
      const linkBytes = await readlink(absolute, { encoding: "buffer" });
      const after = await lstat(absolute, { bigint: true });
      if (
        !Buffer.isBuffer(linkBytes) ||
        !after.isSymbolicLink() ||
        !sameGitIndexStat(before, after)
      ) {
        throw new Error("TASK-540 worktree symlink changed during snapshot");
      }
      const hash = createHash("sha256");
      hash.update("stable-symlink-v1\0");
      for (const key of ["dev", "ino", "mode", "nlink", "size", "mtimeNs", "ctimeNs"]) {
        hash.update(key + "\0" + after[key].toString() + "\0");
      }
      hash.update(linkBytes);
      return hash.digest("hex");
    }
    if (!before.isFile()) throw new Error("TASK-540 worktree snapshot path is unsupported");
    const { bytes, stat } = await readStableRegularFile(
      absolute,
      "TASK-540 worktree file snapshot",
      64 * 1024 * 1024
    );
    return hashStableRegularFileAuthority(bytes, stat);
  } catch (error) {
    if (error && error.code === "ENOENT") return "<missing>";
    throw error;
  }
}

function isRootSensitiveEnvironmentName(name) {
  return (
    typeof name === "string" &&
    name.startsWith(".env") &&
    !name.includes("/") &&
    !name.includes("\0") &&
    Buffer.byteLength(name) <= 255
  );
}

function selectRootSensitiveEnvironmentNames(entries) {
  if (!Array.isArray(entries)) {
    throw new Error("TASK-540 private environment directory projection is invalid");
  }
  const candidates = entries
    .map((entry) => entry?.name)
    .filter((name) => typeof name === "string" && name.startsWith(".env"));
  if (candidates.some((name) => !isRootSensitiveEnvironmentName(name))) {
    throw new Error("TASK-540 private environment name is unsafe");
  }
  if (candidates.length > 64) {
    throw new Error("TASK-540 private environment projection exceeds its entry bound");
  }
  return Object.freeze([...candidates].sort());
}

async function hashSensitiveEnvProjection() {
  if (HERMETIC_SELF_TEST_MODE) return HERMETIC_SELF_TEST_SENSITIVE_ENV_PROJECTION;
  const entries = selectRootSensitiveEnvironmentNames(await readdir(ROOT, { withFileTypes: true }));
  const hashes = Object.create(null);
  for (const relativePath of entries) hashes[relativePath] = await hashPath(relativePath);
  return Object.freeze(hashes);
}

async function captureWorkflowSensitiveEnvBaseline(label) {
  if (workflowSensitiveEnvBaseline !== null) {
    throw new Error(label + ": private environment baseline was already captured");
  }
  const projection = await hashSensitiveEnvProjection();
  if (
    INITIAL_REPO_ENVIRONMENT_FINGERPRINT !== null &&
    projection[".env"] !== INITIAL_REPO_ENVIRONMENT_FINGERPRINT
  ) {
    throw new Error(label + ": private environment changed after its stable initial parse");
  }
  workflowSensitiveEnvBaseline = projection;
}

async function requireWorkflowSensitiveEnvBaseline(label) {
  if (
    workflowSensitiveEnvBaseline !== null &&
    !equalHashMaps(workflowSensitiveEnvBaseline, await hashSensitiveEnvProjection())
  ) {
    throw new Error(label + ": private environment baseline changed");
  }
}

async function worktreeSnapshot(
  label = "TASK-540 worktree snapshot",
  additionalPaths = Object.freeze([])
) {
  if (
    !Array.isArray(additionalPaths) ||
    additionalPaths.some(
      (relativePath) =>
        typeof relativePath !== "string" ||
        relativePath.length === 0 ||
        relativePath.startsWith("/") ||
        relativePath.includes("..") ||
        relativePath.includes("\0")
    )
  ) {
    throw new Error(label + ": repository snapshot additional paths are invalid");
  }
  const [head, branch, headTracked, stagedTracked, unstagedTracked, untracked, indexAuthority] =
    await Promise.all([
      git(["rev-parse", "HEAD"]),
      git(["branch", "--show-current"]),
      git(["diff", "--name-only", "-z", "HEAD"]),
      git(["diff", "--cached", "--name-only", "-z", "HEAD"]),
      git(["diff", "--name-only", "-z"]),
      git(["ls-files", "--others", "--exclude-standard", "-z"]),
      requireInitialGitIndexBaseline(label + " index authority"),
    ]);
  const paths = [
    ...new Set([
      ...splitNul(headTracked),
      ...splitNul(stagedTracked),
      ...splitNul(unstagedTracked),
      ...splitNul(untracked),
      ...additionalPaths,
    ]),
  ].sort();
  const hashes = Object.create(null);
  for (const path of paths) hashes[path] = await hashPath(path);
  return {
    head: head.trim(),
    branch: branch.trim(),
    indexAuthority,
    paths,
    hashes,
  };
}

function isLineLimitedHumanAuthoredModule(relativePath) {
  if (!HUMAN_AUTHORED_MODULE_PATTERN.test(relativePath)) return false;
  const productionRoot = /^(?:core|packages|store)\//u.test(relativePath);
  const testRoot = relativePath.startsWith("tests/");
  if (!productionRoot && !testRoot) return false;
  if (
    /(?:^|\/)(?:node_modules|vendor|dist|build|coverage)(?:\/|$)/u.test(relativePath) ||
    /(?:^|\/)migrations\/meta(?:\/|$)/u.test(relativePath) ||
    /(?:^|\/)[^/]+\.generated\.[cm]?[jt]sx?$/u.test(relativePath)
  ) {
    return false;
  }
  return true;
}

function physicalLineCount(bytes) {
  if (bytes.length === 0) return 0;
  let count = 0;
  for (let index = 0; index < bytes.length; index += 1) {
    if (bytes[index] === 0x0d) {
      count += 1;
      if (bytes[index + 1] === 0x0a) index += 1;
      continue;
    }
    if (bytes[index] === 0x0a) {
      count += 1;
      continue;
    }
    if (
      bytes[index] === 0xe2 &&
      bytes[index + 1] === 0x80 &&
      (bytes[index + 2] === 0xa8 || bytes[index + 2] === 0xa9)
    ) {
      count += 1;
      index += 2;
    }
  }
  const last = bytes.length - 1;
  const endsWithLineTerminator =
    bytes[last] === 0x0a ||
    bytes[last] === 0x0d ||
    (last >= 2 &&
      bytes[last - 2] === 0xe2 &&
      bytes[last - 1] === 0x80 &&
      (bytes[last] === 0xa8 || bytes[last] === 0xa9));
  return count + (endsWithLineTerminator ? 0 : 1);
}

function requireTask540FamilyBaselineProjection(projection, label) {
  const firstCommitLine = projection.firstCommitLine.trim().split(/\s+/u);
  if (
    firstCommitLine.length !== 2 ||
    firstCommitLine[0] !== TASK_540_FIRST_FAMILY_COMMIT ||
    firstCommitLine[1] !== TASK_540_PRE_FAMILY_BASELINE ||
    projection.baselineMergeBase.trim() !== TASK_540_PRE_FAMILY_BASELINE ||
    projection.firstCommitMergeBase.trim() !== TASK_540_FIRST_FAMILY_COMMIT
  ) {
    throw new Error(label + ": TASK-540 family baseline/ancestry drifted");
  }
}

function task540LineLimitOwnerIds(relativePath) {
  const writableOwners = LEAVES.filter(({ allowedFiles }) =>
    allowedFiles.includes(relativePath)
  ).map(({ id }) => id);
  const readOnlyOwners = TASK_540_READ_ONLY_CONSUMER_OWNERS.filter(
    ({ path }) => path === relativePath
  ).map(({ owner }) => owner);
  return [...writableOwners, ...readOnlyOwners];
}

async function requireTask540FamilyBaseline(label) {
  const [firstCommitLine, baselineMergeBase, firstCommitMergeBase] = await Promise.all([
    git(["rev-list", "--parents", "-n", "1", TASK_540_FIRST_FAMILY_COMMIT]),
    git(["merge-base", TASK_540_PRE_FAMILY_BASELINE, "HEAD"]),
    git(["merge-base", TASK_540_FIRST_FAMILY_COMMIT, "HEAD"]),
  ]);
  requireTask540FamilyBaselineProjection(
    { firstCommitLine, baselineMergeBase, firstCommitMergeBase },
    label
  );
}

function requireTask540FrozenModulePathAuthority(label) {
  const sorted = [...TASK_540_FROZEN_PRE_SPLIT_MODULE_PATHS].sort();
  const owners = TASK_540_FROZEN_PRE_SPLIT_MODULE_PATHS.map((path) => {
    const matches = task540LineLimitOwnerIds(path);
    if (matches.length !== 1) {
      throw new Error(label + ": frozen TASK-540 path must have exactly one owner: " + path);
    }
    return Object.freeze({ path, owner: matches[0] });
  });
  if (
    TASK_540_FROZEN_PRE_SPLIT_MODULE_PATHS.length !== 91 ||
    new Set(TASK_540_FROZEN_PRE_SPLIT_MODULE_PATHS).size !== 91 ||
    JSON.stringify(TASK_540_FROZEN_PRE_SPLIT_MODULE_PATHS) !== JSON.stringify(sorted) ||
    TASK_540_FROZEN_PRE_SPLIT_MODULE_PATHS.some(
      (path) => !isLineLimitedHumanAuthoredModule(path)
    ) ||
    createHash("sha256").update(JSON.stringify(sorted)).digest("hex") !==
      TASK_540_FROZEN_PRE_SPLIT_PATHS_SHA256 ||
    createHash("sha256").update(JSON.stringify(owners)).digest("hex") !==
      TASK_540_FROZEN_PRE_SPLIT_OWNERS_SHA256
  ) {
    throw new Error(label + ": frozen TASK-540 module path authority drifted");
  }
  return TASK_540_FROZEN_PRE_SPLIT_MODULE_PATHS;
}

function buildTask540TouchedModulePathAuthority(
  committedHistory,
  currentTracked,
  untracked,
  label
) {
  if (
    [committedHistory, currentTracked, untracked].some(
      (paths) =>
        !Array.isArray(paths) || paths.some((path) => typeof path !== "string" || path.length === 0)
    )
  ) {
    throw new Error(label + ": dynamic TASK-540 module path authority is invalid");
  }
  const frozen = requireTask540FrozenModulePathAuthority(label);
  const trackedPaths = [...new Set([...frozen, ...committedHistory, ...currentTracked])].sort();
  const trackedSet = new Set(trackedPaths);
  const untrackedPaths = [...new Set(untracked)].filter((path) => !trackedSet.has(path)).sort();
  return Object.freeze({
    trackedPaths: Object.freeze(trackedPaths),
    untrackedPaths: Object.freeze(untrackedPaths),
  });
}

async function task540TouchedModulePathAuthority(label) {
  await requireTask540FamilyBaseline(label);
  const [committedHistory, currentTracked, untracked] = await Promise.all([
    git([
      "log",
      "--format=",
      "--name-only",
      "--no-renames",
      "-z",
      TASK_540_PRE_FAMILY_BASELINE + "..HEAD",
      "--",
      "core",
      "packages",
      "store",
      "tests",
    ]).then(splitNul),
    git(["diff", "--name-only", "-z", "HEAD"]).then(splitNul),
    git(["ls-files", "--others", "--exclude-standard", "-z"]).then(splitNul),
  ]);
  return buildTask540TouchedModulePathAuthority(committedHistory, currentTracked, untracked, label);
}

async function requireTask540TouchedModuleLineLimit(
  label,
  ownedPaths = null,
  selfTestAuthority = null
) {
  if (
    ownedPaths !== null &&
    (!Array.isArray(ownedPaths) ||
      new Set(ownedPaths).size !== ownedPaths.length ||
      ownedPaths.some((path) => typeof path !== "string" || path.length === 0))
  ) {
    throw new Error(label + ": invalid scoped line-limit paths");
  }
  if (selfTestAuthority !== null) {
    const keys =
      selfTestAuthority && typeof selfTestAuthority === "object"
        ? Object.keys(selfTestAuthority).sort()
        : [];
    if (
      !HERMETIC_SELF_TEST_MODE ||
      keys.join(",") !== "fileBytesByPath,trackedPaths,untrackedPaths" ||
      !Array.isArray(selfTestAuthority.trackedPaths) ||
      !Array.isArray(selfTestAuthority.untrackedPaths) ||
      !selfTestAuthority.fileBytesByPath ||
      typeof selfTestAuthority.fileBytesByPath !== "object"
    ) {
      throw new Error(label + ": invalid hermetic line-limit self-test authority");
    }
    const authorityPaths = [...selfTestAuthority.trackedPaths, ...selfTestAuthority.untrackedPaths];
    if (
      new Set(authorityPaths).size !== authorityPaths.length ||
      authorityPaths.some((path) => typeof path !== "string" || path.length === 0) ||
      Object.keys(selfTestAuthority.fileBytesByPath).sort().join("\0") !==
        [...authorityPaths].sort().join("\0") ||
      authorityPaths.some((path) => !Buffer.isBuffer(selfTestAuthority.fileBytesByPath[path]))
    ) {
      throw new Error(label + ": invalid hermetic line-limit path projection");
    }
  }
  const ownedPathSet = ownedPaths === null ? null : new Set(ownedPaths);
  const [trackedPaths, untrackedPaths] =
    selfTestAuthority === null
      ? await task540TouchedModulePathAuthority(label).then((authority) => [
          authority.trackedPaths,
          authority.untrackedPaths,
        ])
      : [selfTestAuthority.trackedPaths, selfTestAuthority.untrackedPaths];
  const paths = [...new Set([...trackedPaths, ...untrackedPaths])]
    .filter(isLineLimitedHumanAuthoredModule)
    .filter((relativePath) => ownedPathSet === null || ownedPathSet.has(relativePath))
    .sort();
  const violations = [];
  const evidence = [];
  for (const relativePath of paths) {
    if (
      relativePath.startsWith("/") ||
      relativePath.includes("\0") ||
      relativePath.split("/").includes("..")
    ) {
      throw new Error(label + ": unsafe line-limit path");
    }
    let owner = null;
    if (selfTestAuthority === null) {
      const owners = task540LineLimitOwnerIds(relativePath);
      if (owners.length !== 1) {
        throw new Error(
          label +
            ": task-family line-limit path must have exactly one leaf owner: " +
            relativePath +
            "=" +
            JSON.stringify(owners)
        );
      }
      [owner] = owners;
    }
    let bytes;
    if (selfTestAuthority !== null) {
      bytes = selfTestAuthority.fileBytesByPath[relativePath];
    } else {
      let entry;
      try {
        entry = await lstat(ROOT + "/" + relativePath);
      } catch (error) {
        if (error?.code === "ENOENT") {
          throw new Error(label + ": touched historical module is missing: " + relativePath);
        }
        throw error;
      }
      if (!entry.isFile() || entry.isSymbolicLink()) {
        throw new Error(label + ": line-limited path is not a regular file: " + relativePath);
      }
      ({ bytes } = await readStableRegularFile(
        ROOT + "/" + relativePath,
        label + ":" + relativePath,
        8 * 1024 * 1024
      ));
    }
    const lines = physicalLineCount(bytes);
    evidence.push(
      Object.freeze({
        path: relativePath,
        lines,
        ...(owner ? { owner } : {}),
        sha256: createHash("sha256").update(bytes).digest("hex"),
      })
    );
    if (lines > HUMAN_AUTHORED_MODULE_LINE_LIMIT) {
      violations.push(relativePath + "=" + lines);
    }
  }
  if (violations.length > 0) {
    throw new Error(
      label +
        ": touched human-authored production/test module exceeds 1000 physical lines: " +
        violations.join(", ")
    );
  }
  return Object.freeze(evidence);
}

function snapshotDelta(before, after) {
  const paths = [...new Set([...before.paths, ...after.paths])].sort();
  return paths.filter(
    (path) => (before.hashes[path] ?? "<clean>") !== (after.hashes[path] ?? "<clean>")
  );
}

function canonicalRepositoryFingerprint(snapshot) {
  const projection = JSON.stringify({
    head: snapshot.head,
    branch: snapshot.branch,
    indexAuthority: snapshot.indexAuthority,
    paths: snapshot.paths,
    hashes: snapshot.hashes,
  });
  return Object.freeze({
    head: snapshot.head,
    branch: snapshot.branch,
    worktreeSha256: createHash("sha256").update(projection).digest("hex"),
  });
}

function sameRepositoryFingerprint(left, right) {
  return (
    left.head === right.head &&
    left.branch === right.branch &&
    left.worktreeSha256 === right.worktreeSha256
  );
}

function createBoundedCommandStream() {
  const hash = createHash("sha256");
  const chunks = [];
  let byteLength = 0;
  let retainedBytes = 0;
  let truncated = false;
  return Object.freeze({
    push(chunk) {
      const bytes = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      byteLength += bytes.length;
      hash.update(bytes);
      const remaining = MAX_VALIDATION_STREAM_BYTES - retainedBytes;
      if (remaining > 0) {
        const retained = bytes.subarray(0, remaining);
        chunks.push(retained);
        retainedBytes += retained.length;
      }
      if (bytes.length > Math.max(remaining, 0)) truncated = true;
      return truncated;
    },
    finish() {
      return Object.freeze({
        bytes: byteLength,
        sha256: hash.digest("hex"),
        truncated,
        retained: Buffer.concat(chunks, retainedBytes),
      });
    },
  });
}

function parseValidationProcStat(source, expectedPid) {
  if (typeof source !== "string" || source.length === 0) {
    throw new Error("TASK-540 validation proc stat is invalid");
  }
  const close = source.lastIndexOf(")");
  const pid = Number(source.slice(0, source.indexOf(" ")));
  const fields =
    close > 0
      ? source
          .slice(close + 1)
          .trim()
          .split(/\s+/)
      : [];
  if (!Number.isSafeInteger(pid) || pid !== expectedPid || fields.length < 20) {
    throw new Error("TASK-540 validation proc identity is invalid");
  }
  const ppid = Number(fields[1]);
  const processGroupId = Number(fields[2]);
  const sessionId = Number(fields[3]);
  const startTime = fields[19];
  if (
    !/^[A-Zt]$/.test(fields[0]) ||
    ![ppid, processGroupId, sessionId].every(
      (value) => Number.isSafeInteger(value) && value >= 0
    ) ||
    !/^\d+$/.test(startTime)
  ) {
    throw new Error("TASK-540 validation proc authority is invalid");
  }
  return Object.freeze({
    pid,
    ppid,
    processGroupId,
    sessionId,
    startTime,
    state: fields[0],
  });
}

async function readValidationProcessIdentity(pid) {
  try {
    return parseValidationProcStat(await readFile("/proc/" + pid + "/stat", "utf8"), pid);
  } catch (error) {
    if (error?.code === "ENOENT" || error?.code === "ESRCH") return null;
    throw error;
  }
}

async function readValidationProcessTable() {
  const names = await readdir("/proc");
  const rows = await Promise.all(
    names
      .filter((name) => /^\d+$/.test(name))
      .map((name) => readValidationProcessIdentity(Number(name)))
  );
  return rows.filter((row) => row !== null);
}

function sameValidationProcessIdentity(left, right) {
  return left.pid === right.pid && left.startTime === right.startTime;
}

function isOwnedValidationProcess(row, authority, retainedIdentities = []) {
  return (
    sameValidationProcessIdentity(row, authority) ||
    row.processGroupId === authority.processGroupId ||
    row.sessionId === authority.sessionId ||
    retainedIdentities.some((identity) => sameValidationProcessIdentity(row, identity))
  );
}

async function captureValidationProcessAuthority(pid) {
  if (!Number.isSafeInteger(pid) || pid <= 1) {
    throw new Error("TASK-540 validation child PID is invalid");
  }
  let observedAuthority = null;
  try {
    for (let attempt = 0; attempt < 40; attempt += 1) {
      const identity = await readValidationProcessIdentity(pid);
      if (identity) {
        if (identity.processGroupId !== pid || identity.sessionId !== pid) {
          throw new Error("TASK-540 validation child is not its process-group/session leader");
        }
        if (observedAuthority === null) observedAuthority = identity;
        if (!sameValidationProcessIdentity(identity, observedAuthority)) {
          throw new Error("TASK-540 validation child identity changed during acquisition");
        }
        if (identity.state === "T" || identity.state === "t") return identity;
      }
      await delay(25);
    }
  } catch (error) {
    error.observedAuthority = observedAuthority;
    throw error;
  }
  const error = new Error("TASK-540 validation process authority was not observable");
  error.observedAuthority = observedAuthority;
  throw error;
}

async function captureOwnedValidationProcesses(authority) {
  return (await readValidationProcessTable()).filter((row) =>
    isOwnedValidationProcess(row, authority)
  );
}

async function waitForValidationProcessAbsence(authority, retainedIdentities, timeoutMs) {
  const deadline = performance.now() + timeoutMs;
  do {
    const active = (await readValidationProcessTable()).filter((row) =>
      isOwnedValidationProcess(row, authority, retainedIdentities)
    );
    if (active.length === 0) return true;
    await delay(100);
  } while (performance.now() < deadline);
  return false;
}

async function signalOwnedValidationProcessGroup(authority, retainedIdentities, signal) {
  const table = await readValidationProcessTable();
  const currentLeader = table.find((row) => row.pid === authority.pid);
  if (currentLeader && !sameValidationProcessIdentity(currentLeader, authority)) {
    throw new Error("TASK-540 validation leader PID was recycled");
  }
  const active = table.filter((row) =>
    isOwnedValidationProcess(row, authority, retainedIdentities)
  );
  if (active.length === 0) return false;
  try {
    process.kill(-authority.processGroupId, signal);
  } catch (error) {
    if (error?.code !== "ESRCH") throw error;
  }
  return true;
}

function releaseLocalCommandHandles(child) {
  child.stdin?.destroy();
  child.stdout?.destroy();
  child.stderr?.destroy();
  child.unref();
}

async function disposeUnboundValidationChild(child, closePromise, observedAuthority = null) {
  if (observedAuthority) {
    await terminateLocalCommand(child, closePromise, observedAuthority);
    return;
  }
  const earlyCompletion = await Promise.race([closePromise, delay(25).then(() => null)]);
  if (earlyCompletion === null) child.kill("SIGKILL");
  const completion =
    earlyCompletion ??
    (await Promise.race([closePromise, delay(VALIDATION_ABSENCE_TIMEOUT_MS).then(() => null)]));
  releaseLocalCommandHandles(child);
  if (completion === null) {
    throw new Error("TASK-540 unbound validation child did not close safely");
  }
}

async function signalOwnedValidationLeader(child, authority, signal) {
  const current = await readValidationProcessIdentity(authority.pid);
  if (
    current === null ||
    !sameValidationProcessIdentity(current, authority) ||
    current.processGroupId !== authority.processGroupId ||
    current.sessionId !== authority.sessionId
  ) {
    throw new Error("TASK-540 validation leader changed before signal");
  }
  return child.kill(signal);
}

async function authorizeAndResumeStoppedValidationChild({ label, authorize, resume, cleanup }) {
  if (
    typeof label !== "string" ||
    label.length === 0 ||
    typeof authorize !== "function" ||
    typeof resume !== "function" ||
    typeof cleanup !== "function"
  ) {
    throw new Error("TASK-540 validation pre-resume dependencies are invalid");
  }
  try {
    await authorize();
    if (!(await resume())) throw new Error("TASK-540 validation child could not resume");
  } catch {
    const authorizationError = new Error(
      label + ": validation child pre-resume authorization failed; details discarded"
    );
    try {
      await cleanup();
    } catch (cleanupError) {
      throw new AggregateError(
        [authorizationError, cleanupError],
        label + ": validation child pre-resume authorization and cleanup failed"
      );
    }
    throw authorizationError;
  }
}

async function terminateLocalCommand(child, closePromise, authority) {
  const retainedIdentities = await captureOwnedValidationProcesses(authority);
  await signalOwnedValidationProcessGroup(authority, retainedIdentities, "SIGTERM");
  if (
    await waitForValidationProcessAbsence(
      authority,
      retainedIdentities,
      VALIDATION_TERMINATION_GRACE_MS
    )
  ) {
    const completion = await Promise.race([closePromise, delay(250).then(() => null)]);
    releaseLocalCommandHandles(child);
    return completion;
  }
  await signalOwnedValidationProcessGroup(authority, retainedIdentities, "SIGKILL");
  const absent = await waitForValidationProcessAbsence(
    authority,
    retainedIdentities,
    VALIDATION_ABSENCE_TIMEOUT_MS
  );
  const completion = await Promise.race([closePromise, delay(250).then(() => null)]);
  releaseLocalCommandHandles(child);
  if (!absent) throw new Error("TASK-540 validation process group/session did not terminate");
  return completion;
}

function parseValidationCommandArgv(command) {
  if (typeof command !== "string" || command.length === 0 || command.includes("\0")) {
    throw new Error("TASK-540 validation command is invalid");
  }
  const words = [];
  let word = "";
  let started = false;
  let quote = null;
  const pushWord = () => {
    if (!started) return;
    words.push(word);
    word = "";
    started = false;
  };
  for (let index = 0; index < command.length; index += 1) {
    const character = command[index];
    if (quote === "single") {
      if (character === "'") quote = null;
      else word += character;
      continue;
    }
    if (quote === "double") {
      if (character === '"') {
        quote = null;
      } else if (character === "\\") {
        index += 1;
        if (index >= command.length) throw new Error("TASK-540 validation escape is incomplete");
        word += command[index];
      } else {
        if (character === "$" || character === "`") {
          throw new Error("TASK-540 validation command expansion is forbidden");
        }
        word += character;
      }
      continue;
    }
    if (/\s/u.test(character)) {
      pushWord();
      continue;
    }
    if (character === "'") {
      quote = "single";
      started = true;
      continue;
    }
    if (character === '"') {
      quote = "double";
      started = true;
      continue;
    }
    if (character === "\\") {
      index += 1;
      if (index >= command.length) throw new Error("TASK-540 validation escape is incomplete");
      word += command[index];
      started = true;
      continue;
    }
    if (/[;&|<>`$\r\n]/u.test(character)) {
      throw new Error("TASK-540 validation shell syntax is forbidden");
    }
    word += character;
    started = true;
  }
  if (quote !== null) throw new Error("TASK-540 validation quote is incomplete");
  pushWord();
  if (
    words.length === 0 ||
    !/^(?:[A-Za-z0-9_.-]+|\.\/[A-Za-z0-9_./-]+)$/u.test(words[0]) ||
    words[0].includes("..")
  ) {
    throw new Error("TASK-540 validation executable is invalid");
  }
  return Object.freeze(words);
}

async function buildValidationCommandInvocation(spec) {
  if (!VALIDATION_COMMAND_AUTHORITY.has(spec.id + "\0" + spec.command)) {
    throw new Error("TASK-540 validation command is outside its closed authority");
  }
  const repositoryEnvironment = HERMETIC_VALIDATION_COMMAND_IDS.includes(spec.id)
    ? HERMETIC_SELF_TEST_REPO_ENVIRONMENT
    : REPO_ENV;
  if (spec.id === "fullTest") {
    if (spec.command !== "bun run test") {
      throw new Error("TASK-540 full test command drifted");
    }
    await requireExactTestEnvironmentSourceScripts();
    const environment = buildStrictValidationEnvironment(process.env, repositoryEnvironment);
    return Object.freeze({
      executable: await requireValidationExecutableIdentity("bun"),
      args: Object.freeze(["run", "test"]),
      environment,
      identityKeys: Object.freeze(["bun"]),
    });
  }
  if (spec.command === "bun run test") {
    throw new Error("TASK-540 full test command escaped its sole authority");
  }
  const argv = parseValidationCommandArgv(spec.command);
  if (
    !VALIDATION_EXECUTABLE_ALLOWLIST.includes(argv[0]) ||
    ["bash", "sh", "env", "/bin/bash", "/bin/sh", "/usr/bin/env"].includes(argv[0]) ||
    (argv[0] === "bun" &&
      argv[1] === "run" &&
      ["test", "test:bun", "test:vitest"].includes(argv[2]))
  ) {
    throw new Error("TASK-540 validation executable/argv authority is forbidden");
  }
  if (argv[0] === "git") {
    return Object.freeze({
      executable: await requireValidationExecutableIdentity("git"),
      args: materializeObservationalGitArgs(argv.slice(1)),
      environment: buildObservationalGitEnvironment(),
      identityKeys: Object.freeze(["git"]),
    });
  }
  const environment = buildStrictValidationEnvironment(process.env, repositoryEnvironment);
  let executableKey = argv[0] === "bunx" ? "bun" : argv[0];
  let identityKeys = Object.freeze([executableKey]);
  let args =
    argv[0] === "bunx"
      ? Object.freeze(["x", "--no-install", ...argv.slice(1)])
      : Object.freeze(argv.slice(1));
  if (argv[0] === "./node_modules/.bin/tsc") {
    const tscPath = await requireValidationExecutableIdentity("tsc");
    executableKey = "node";
    identityKeys = Object.freeze(["node", "tsc"]);
    args = Object.freeze([tscPath, ...argv.slice(1)]);
  }
  return Object.freeze({
    executable: await requireValidationExecutableIdentity(executableKey),
    args,
    environment,
    identityKeys,
  });
}

async function executeLocalValidationCommand(spec, label) {
  const [before, sensitiveEnvBefore] = await Promise.all([
    worktreeSnapshot(label + " before local command"),
    hashSensitiveEnvProjection(),
  ]);
  const startFingerprint = canonicalRepositoryFingerprint(before);
  const stdout = createBoundedCommandStream();
  const stderr = createBoundedCommandStream();
  const startedAtEpochMs = Date.now();
  let timedOut = false;
  let outputLimitExceeded = false;
  let spawnError = null;
  let lifecycleFailure = false;
  let requestAbort;
  const abortPromise = new Promise((resolve) => {
    requestAbort = (reason) => resolve(reason);
  });
  const invocation = await buildValidationCommandInvocation(spec);
  const launcherExecutable = await requireValidationExecutableIdentity("node");
  const child = spawn(
    launcherExecutable,
    ["--eval", VALIDATION_LAUNCHER_SOURCE, invocation.executable, ...invocation.args],
    {
      cwd: ROOT,
      env: invocation.environment,
      detached: true,
      stdio: ["ignore", "pipe", "pipe"],
    }
  );
  const closePromise = new Promise((resolve) => {
    child.once("close", (code, signal) => resolve({ code, signal }));
  });
  const captureChunk = (stream, chunk) => {
    if (stream.push(chunk) && !outputLimitExceeded) {
      outputLimitExceeded = true;
      requestAbort("output-limit");
    }
  };
  child.stdout.on("data", (chunk) => captureChunk(stdout, chunk));
  child.stderr.on("data", (chunk) => captureChunk(stderr, chunk));
  child.once("error", (error) => {
    spawnError = error;
    requestAbort("spawn-error");
  });
  if (!Number.isSafeInteger(child.pid)) {
    await disposeUnboundValidationChild(child, closePromise);
    throw new Error(label + ": validation child could not establish authority");
  }
  let authority;
  try {
    authority = await captureValidationProcessAuthority(child.pid);
  } catch (error) {
    const authorityError = new Error(
      label + ": validation child authority failed; details discarded"
    );
    try {
      await disposeUnboundValidationChild(child, closePromise, error?.observedAuthority ?? null);
    } catch (cleanupError) {
      throw new AggregateError(
        [authorityError, cleanupError],
        label + ": validation child authority and cleanup failed"
      );
    }
    throw authorityError;
  }
  await authorizeAndResumeStoppedValidationChild({
    label,
    authorize: async () => {
      for (const executableKey of invocation.identityKeys) {
        await requireValidationExecutableIdentity(executableKey);
      }
      await requireValidationExecutableIdentity("node");
    },
    resume: () => signalOwnedValidationLeader(child, authority, "SIGCONT"),
    cleanup: () => terminateLocalCommand(child, closePromise, authority),
  });
  const timeout = setTimeout(() => {
    timedOut = true;
    requestAbort("timeout");
  }, VALIDATION_COMMAND_TIMEOUT_MS);
  const outcome = await Promise.race([
    closePromise.then((completion) => ({ kind: "closed", completion })),
    abortPromise.then((reason) => ({ kind: "aborted", reason })),
  ]);
  clearTimeout(timeout);
  let completion;
  if (outcome.kind === "aborted") {
    completion =
      (await terminateLocalCommand(child, closePromise, authority)) ??
      Object.freeze({ code: null, signal: null });
  } else {
    completion = outcome.completion;
    const absent = await waitForValidationProcessAbsence(
      authority,
      [],
      VALIDATION_ABSENCE_TIMEOUT_MS
    );
    if (!absent) {
      lifecycleFailure = true;
      await terminateLocalCommand(child, closePromise, authority);
    } else {
      releaseLocalCommandHandles(child);
    }
  }
  const [after, sensitiveEnvAfter] = await Promise.all([
    worktreeSnapshot(label + " after local command"),
    hashSensitiveEnvProjection(),
  ]);
  const endFingerprint = canonicalRepositoryFingerprint(after);
  const stdoutResult = stdout.finish();
  const stderrResult = stderr.finish();
  const status = timedOut
    ? 124
    : outputLimitExceeded
      ? 125
      : spawnError
        ? 127
        : lifecycleFailure
          ? 128
          : (completion.code ?? 128);
  const receipt = {
    runnerVersion: "orchestrator-local-v1",
    id: spec.id,
    command: spec.command,
    status,
    signal: completion.signal ?? null,
    timedOut,
    outputLimitExceeded,
    startedAtEpochMs,
    endedAtEpochMs: Date.now(),
    stdoutBytes: stdoutResult.bytes,
    stderrBytes: stderrResult.bytes,
    stdoutSha256: stdoutResult.sha256,
    stderrSha256: stderrResult.sha256,
    stdoutTruncated: stdoutResult.truncated,
    stderrTruncated: stderrResult.truncated,
    repository: Object.freeze({
      start: startFingerprint,
      end: endFingerprint,
      unchanged:
        sameRepositoryFingerprint(startFingerprint, endFingerprint) &&
        equalHashMaps(sensitiveEnvBefore, sensitiveEnvAfter),
    }),
  };
  LOCAL_COMMAND_AUTHORITY.set(
    receipt,
    Object.freeze({
      label,
      stdout: stdoutResult.retained,
      stderr: stderrResult.retained,
      containsSensitiveOutput:
        hasSensitiveEvidence(stdoutResult.retained.toString("utf8")) ||
        hasSensitiveEvidence(stderrResult.retained.toString("utf8")),
      spawnError: Boolean(spawnError),
    })
  );
  return Object.freeze(receipt);
}

async function runLocalValidationCommand(spec, label) {
  await requireWorkflowSensitiveEnvBaseline(label + " before local command");
  let receipt = null;
  let executionError = null;
  try {
    receipt = await executeLocalValidationCommand(spec, label);
  } catch (error) {
    executionError = error;
  }
  let environmentError = null;
  try {
    await requireWorkflowSensitiveEnvBaseline(label + " after local command");
  } catch (error) {
    environmentError = error;
  }
  if (executionError && environmentError) {
    throw new AggregateError(
      [executionError, environmentError],
      label + ": local command and private environment boundary failed"
    );
  }
  if (executionError) throw executionError;
  if (environmentError) throw environmentError;
  return receipt;
}

function localCommandAuthority(receipt, label) {
  const authority = LOCAL_COMMAND_AUTHORITY.get(receipt);
  if (!authority || authority.label !== label) {
    throw new Error(label + ": local command authority is missing");
  }
  if (typeof authority.containsSensitiveOutput !== "boolean") {
    throw new Error(label + ": local command redaction authority is missing");
  }
  if (receipt.stdoutTruncated || receipt.stderrTruncated) {
    throw new Error(label + ": bounded local command output was truncated");
  }
  if (
    createHash("sha256").update(authority.stdout).digest("hex") !== receipt.stdoutSha256 ||
    createHash("sha256").update(authority.stderr).digest("hex") !== receipt.stderrSha256 ||
    authority.stdout.length !== receipt.stdoutBytes ||
    authority.stderr.length !== receipt.stderrBytes
  ) {
    throw new Error(label + ": local command bytes do not match their receipt");
  }
  return authority;
}

function localFailureKind(receipt) {
  const authority = LOCAL_COMMAND_AUTHORITY.get(receipt);
  const output = authority
    ? Buffer.concat([authority.stdout, Buffer.from("\n"), authority.stderr]).toString("utf8")
    : "";
  if (
    receipt.timedOut ||
    receipt.outputLimitExceeded ||
    receipt.status === 125 ||
    receipt.status === 126 ||
    receipt.status === 127 ||
    receipt.id === "dbPreflight" ||
    /\b(?:ECONNREFUSED|ENOTFOUND|ETIMEDOUT|database .*unavailable|could not connect|command not found|failed to spawn)\b/i.test(
      output
    )
  ) {
    return "infrastructure";
  }
  return "code-test";
}

function fullValidationMismatchDetail(result) {
  const receipts = Array.isArray(result?.commands) ? result.commands : [];
  for (let index = 0; index < FULL_GATE_COMMANDS.length; index += 1) {
    const expected = FULL_GATE_COMMANDS[index];
    const receipt = receipts[index];
    if (!receipt) {
      return "id=" + expected.id + ",receipt=missing";
    }
    const expectedStatus = 0;
    if (
      receipt.id !== expected.id ||
      receipt.command !== expected.command ||
      receipt.status !== expectedStatus
    ) {
      const status = Number.isInteger(receipt.status) ? receipt.status : -1;
      return (
        "id=" +
        expected.id +
        ",status=" +
        status +
        ",timedOut=" +
        String(receipt.timedOut === true) +
        ",outputLimitExceeded=" +
        String(receipt.outputLimitExceeded === true) +
        ",repositoryUnchanged=" +
        String(receipt.repository?.unchanged === true)
      );
    }
  }
  if (receipts.length !== FULL_GATE_COMMANDS.length) {
    return "id=command-matrix,receipt=extra";
  }
  const baselineBefore = receipts.find(({ id }) => id === "smokeBaselineBeforeFullTest");
  const baselineAfter = receipts.find(({ id }) => id === "smokeBaselineAfterFullGate");
  if (
    !baselineBefore ||
    !baselineAfter ||
    baselineBefore.stdoutSha256 !== baselineAfter.stdoutSha256 ||
    baselineBefore.stdoutBytes !== baselineAfter.stdoutBytes
  ) {
    return "id=smokeBaseline,unchanged=false";
  }
  if (
    result?.database?.configured !== true ||
    result?.database?.reachable !== true ||
    result?.database?.selectOne !== 1
  ) {
    return "id=dbPreflight,databaseReceipt=invalid";
  }
  return "id=aggregate,receipt=non-passing";
}

async function runNamedIsolationCommands(spec, receipt, label) {
  const metadata = spec.isolationCommands ?? [];
  if (metadata.length === 0) return Object.freeze([]);
  const authority = localCommandAuthority(receipt, label + ":" + spec.id);
  const output = Buffer.concat([authority.stdout, Buffer.from("\n"), authority.stderr]).toString(
    "utf8"
  );
  const failureLines = output
    .split(/\r?\n/)
    .filter((line) => /\bfail(?:ed|ure)?\b|\berror\b|[✗×]/i.test(line));
  let selected = metadata.filter(({ file }) => failureLines.some((line) => line.includes(file)));
  if (selected.length === 0) {
    const mentioned = metadata.filter(({ file }) => output.includes(file));
    if (mentioned.length === 1) selected = mentioned;
  }
  if (selected.length > 8) {
    throw new Error(label + ": named isolation set exceeds the bounded maximum");
  }
  const receipts = [];
  for (const isolation of selected) {
    const isolationLabel = label + ":isolate:" + isolation.file;
    const isolationReceipt = await runLocalValidationCommand(
      { id: "isolate:" + isolation.file, command: isolation.command },
      isolationLabel
    );
    localCommandAuthority(isolationReceipt, isolationLabel);
    if (!isolationReceipt.repository.unchanged) {
      throw new Error(label + ": named isolation command changed repository authority");
    }
    receipts.push(isolationReceipt);
  }
  return Object.freeze(receipts);
}

async function runLocalCommandSequence(commands, { label } = {}) {
  await requireWorkflowSensitiveEnvBaseline(label + " before local sequence");
  const [before, sensitiveEnvStart] = await Promise.all([
    worktreeSnapshot(label + " before local sequence"),
    hashSensitiveEnvProjection(),
  ]);
  const start = canonicalRepositoryFingerprint(before);
  const receipts = [];
  const isolationReceipts = [];
  let failedReceipt = null;
  let strictScan = null;
  for (const spec of commands) {
    if (!equalHashMaps(sensitiveEnvStart, await hashSensitiveEnvProjection())) {
      throw new Error(label + ": private environment projection changed between commands");
    }
    const commandLabel = label + ":" + spec.id;
    const receipt = await runLocalValidationCommand(spec, commandLabel);
    receipts.push(receipt);
    localCommandAuthority(receipt, commandLabel);
    if (!receipt.repository.unchanged) {
      failedReceipt = receipt;
      break;
    }
    if (spec.id === "strictScan") {
      strictScan = requireZeroFindingStrictScanReceipt(receipt, commandLabel);
      if (!strictScan.accepted) {
        failedReceipt = receipt;
        break;
      }
      continue;
    }
    if (receipt.status !== 0) {
      isolationReceipts.push(...(await runNamedIsolationCommands(spec, receipt, label)));
      failedReceipt = receipt;
      break;
    }
  }
  const [after, sensitiveEnvEnd] = await Promise.all([
    worktreeSnapshot(label + " after local sequence"),
    hashSensitiveEnvProjection(),
  ]);
  const end = canonicalRepositoryFingerprint(after);
  const unchanged =
    sameRepositoryFingerprint(start, end) && equalHashMaps(sensitiveEnvStart, sensitiveEnvEnd);
  await requireWorkflowSensitiveEnvBaseline(label + " after local sequence");
  if (!unchanged && !failedReceipt) {
    failedReceipt = Object.freeze({
      id: "repositoryFingerprint",
      command: "orchestrator-local repository fingerprint comparison",
      status: 1,
      timedOut: false,
    });
  }
  return Object.freeze({
    receipts: Object.freeze(receipts),
    isolationReceipts: Object.freeze(isolationReceipts),
    failedReceipt,
    strictScan,
    authority: Object.freeze({
      runner: "orchestrator-local-v1",
      start,
      end,
      unchanged,
    }),
  });
}

async function runWorkflowMechanicalGateLocally(label) {
  const execution = await runLocalCommandSequence(WORKFLOW_MECHANICAL_GATE_COMMANDS, {
    label,
  });
  const receiptsMatch =
    execution.failedReceipt === null &&
    execution.authority.unchanged &&
    execution.receipts.length === WORKFLOW_MECHANICAL_GATE_COMMANDS.length &&
    execution.receipts.every((receipt, index) => {
      const expected = WORKFLOW_MECHANICAL_GATE_COMMANDS[index];
      return (
        receipt.id === expected.id &&
        receipt.command === expected.command &&
        receipt.status === 0 &&
        receipt.signal === null &&
        !receipt.timedOut &&
        !receipt.outputLimitExceeded &&
        !receipt.stdoutTruncated &&
        !receipt.stderrTruncated &&
        receipt.repository.unchanged
      );
    });
  if (!receiptsMatch) {
    throw new Error(label + ": local mechanical command gate failed; output discarded");
  }
  const projection = Object.freeze({
    pass: true,
    runner: execution.authority.runner,
    repository: Object.freeze({
      unchanged: execution.authority.unchanged,
      start: execution.authority.start,
      end: execution.authority.end,
    }),
    commands: Object.freeze(
      execution.receipts.map((receipt) =>
        Object.freeze({
          id: receipt.id,
          command: receipt.command,
          status: receipt.status,
          stdoutSha256: receipt.stdoutSha256,
          stderrSha256: receipt.stderrSha256,
          repositoryUnchanged: receipt.repository.unchanged,
        })
      )
    ),
  });
  return requireSensitiveSafeAgentResult(projection, label + " projection");
}

function requireSafeRollbackPath(relativePath, label) {
  if (
    typeof relativePath !== "string" ||
    relativePath.startsWith("/") ||
    relativePath.split("/").includes("..") ||
    !/^_docs\/(?:_TASKS|_CHANGELOG)\//.test(relativePath) ||
    relativePath.split("/").some((segment) => /^\.env(?:\.|$)/.test(segment))
  ) {
    throw new Error(label + ": unsafe exact-rollback path " + relativePath);
  }
  return relativePath;
}

const EXACT_ROLLBACK_PARENT_PATHS = Object.freeze(new Set(["_docs/_TASKS", "_docs/_CHANGELOG"]));

async function requireCanonicalRollbackParent(relativePath, label) {
  requireSafeRollbackPath(relativePath, label);
  const separator = relativePath.lastIndexOf("/");
  const parentRelativePath = relativePath.slice(0, separator);
  const basename = relativePath.slice(separator + 1);
  if (!EXACT_ROLLBACK_PARENT_PATHS.has(parentRelativePath) || !basename || basename.includes("/")) {
    throw new Error(label + ": rollback path has an unowned canonical parent");
  }
  const rootInfo = await lstat(ROOT);
  if (!rootInfo.isDirectory() || rootInfo.isSymbolicLink() || (await realpath(ROOT)) !== ROOT) {
    throw new Error(label + ": repository root is not its exact canonical directory");
  }
  const parentAbsolutePath = ROOT + "/" + parentRelativePath;
  const parentInfo = await lstat(parentAbsolutePath);
  if (
    !parentInfo.isDirectory() ||
    parentInfo.isSymbolicLink() ||
    (await realpath(parentAbsolutePath)) !== parentAbsolutePath
  ) {
    throw new Error(label + ": rollback parent is not its exact canonical directory");
  }
  return Object.freeze({
    parentAbsolutePath,
    absolutePath: parentAbsolutePath + "/" + basename,
    basename,
  });
}

function exactBytesSha256(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

const EXACT_TRANSACTION_STABLE_OBSERVATIONS = 3;
const EXACT_TRANSACTION_MAX_OBSERVATIONS = 24;
const EXACT_TRANSACTION_OBSERVATION_DELAYS_MS = Object.freeze([0, 1, 2, 4, 8, 16, 25]);
const EXACT_TRANSACTION_MOUNT_CLASS = "fakeowner-handle-observation-v1";
const EXACT_TRANSACTION_FAKEOWNER_FS_TYPE = 0x6a656a63n;
const EXACT_TRANSACTION_FAKEOWNER_BACKING_MODE = 0o600;
const EXACT_TRANSACTION_MAX_FILE_BYTES = 64n * 1024n * 1024n;
const EXACT_ROLLBACK_FAKEOWNER_MODE_EVIDENCE = Symbol(
  "task-540-exact-rollback-fakeowner-mode-evidence"
);
const COMMITTED_RENAME_FAKEOWNER_CONVERGENCE_AUTHORITY = Symbol(
  "task-540-committed-rename-fakeowner-convergence-authority"
);

class ExactRollbackReadRaceError extends Error {}
class ExactTransactionCollisionError extends Error {
  constructor(message, relativePath) {
    super(message);
    this.relativePath = relativePath;
  }
}
class ExactTransactionVisibilityError extends Error {}

function exactRollbackEntrySafeDiagnostic(entry) {
  return Object.freeze({
    relativePath: entry.relativePath,
    exists: entry.exists,
    byteLength: entry.byteLength,
    sha256: entry.sha256,
    mode: entry.mode === null ? null : "0" + entry.mode.toString(8),
    mountClass: EXACT_TRANSACTION_MOUNT_CLASS,
  });
}

function freezeExactRollbackObservedEntry(entry, fakeownerModeEvidence = false) {
  if (!entry || typeof entry !== "object" || typeof fakeownerModeEvidence !== "boolean") {
    throw new Error("TASK-540 exact-rollback observed entry evidence is malformed");
  }
  if (fakeownerModeEvidence) {
    Object.defineProperty(entry, EXACT_ROLLBACK_FAKEOWNER_MODE_EVIDENCE, {
      configurable: false,
      enumerable: false,
      writable: false,
      value: true,
    });
  }
  return Object.freeze(entry);
}

function hasExactRollbackFakeownerModeEvidence(entry) {
  return entry?.[EXACT_ROLLBACK_FAKEOWNER_MODE_EVIDENCE] === true;
}

function exactTransactionObservationDelay(attempt) {
  return EXACT_TRANSACTION_OBSERVATION_DELAYS_MS[
    Math.min(attempt, EXACT_TRANSACTION_OBSERVATION_DELAYS_MS.length - 1)
  ];
}

async function waitForExactTransactionObservation(milliseconds) {
  if (milliseconds <= 0) {
    await Promise.resolve();
    return;
  }
  await new Promise((resolve) => setTimeout(resolve, milliseconds));
}

function sameExactRollbackCrossViewIdentity(left, right) {
  return (
    left.dev === right.dev &&
    left.ino === right.ino &&
    left.nlink === right.nlink &&
    left.size === right.size
  );
}

function requireExactRollbackStableFileView(view, relativePath, label) {
  if (
    !view?.isFile() ||
    view.isSymbolicLink() ||
    view.nlink !== 1n ||
    typeof view.size !== "bigint" ||
    view.size < 0n ||
    view.size > EXACT_TRANSACTION_MAX_FILE_BYTES
  ) {
    throw new ExactTransactionCollisionError(
      label + ": exact-rollback stable view is not one bounded regular file: " + relativePath,
      relativePath
    );
  }
  return view;
}

function classifyExactRollbackDualView(
  { pathBefore, handleBefore, handleAfter, pathAfter, fsTypeBefore, fsTypeAfter },
  relativePath,
  label
) {
  if (
    typeof fsTypeBefore !== "bigint" ||
    typeof fsTypeAfter !== "bigint" ||
    fsTypeBefore !== fsTypeAfter ||
    !sameGitIndexStat(pathBefore, pathAfter) ||
    !sameGitIndexStat(handleBefore, handleAfter)
  ) {
    throw new ExactRollbackReadRaceError(
      label + ": exact-rollback path or handle view changed while read: " + relativePath
    );
  }
  for (const view of [pathBefore, handleBefore, handleAfter, pathAfter]) {
    requireExactRollbackStableFileView(view, relativePath, label);
  }
  if (
    !sameExactRollbackCrossViewIdentity(pathBefore, handleBefore) ||
    !sameExactRollbackCrossViewIdentity(pathAfter, handleAfter)
  ) {
    throw new ExactTransactionCollisionError(
      label + ": exact-rollback stable path and handle identities differ: " + relativePath,
      relativePath
    );
  }
  const pathMode = Number(pathAfter.mode & 0o7777n);
  const handleMode = Number(handleAfter.mode & 0o7777n);
  if (pathMode === handleMode) return pathMode;
  if (
    fsTypeAfter === EXACT_TRANSACTION_FAKEOWNER_FS_TYPE &&
    handleMode === EXACT_TRANSACTION_FAKEOWNER_BACKING_MODE
  ) {
    return pathMode;
  }
  throw new ExactTransactionCollisionError(
    label + ": exact-rollback stable path and handle modes disagree: " + relativePath,
    relativePath
  );
}

function isExactRollbackFakeownerBackingModeView({
  pathBefore,
  handleBefore,
  handleAfter,
  pathAfter,
  fsTypeBefore,
  fsTypeAfter,
}) {
  const views = [pathBefore, handleBefore, handleAfter, pathAfter];
  return Boolean(
    fsTypeBefore === EXACT_TRANSACTION_FAKEOWNER_FS_TYPE &&
    fsTypeAfter === EXACT_TRANSACTION_FAKEOWNER_FS_TYPE &&
    views.every(
      (view) =>
        view?.isFile() &&
        !view.isSymbolicLink() &&
        view.nlink === 1n &&
        typeof view.size === "bigint" &&
        view.size >= 0n &&
        view.size <= EXACT_TRANSACTION_MAX_FILE_BYTES &&
        Number(view.mode & 0o7777n) === EXACT_TRANSACTION_FAKEOWNER_BACKING_MODE
    ) &&
    sameGitIndexStat(pathBefore, pathAfter) &&
    sameGitIndexStat(handleBefore, handleAfter) &&
    sameExactRollbackCrossViewIdentity(pathBefore, handleBefore) &&
    sameExactRollbackCrossViewIdentity(pathAfter, handleAfter)
  );
}

function combineExactRollbackReadAndCloseErrors(readError, closeError, label) {
  if (readError && closeError) {
    return new AggregateError(
      [readError, closeError],
      label + ": exact-rollback read/classification and handle close both failed"
    );
  }
  return readError ?? closeError ?? null;
}

async function readOptionalRollbackFile(relativePath, label) {
  const { absolutePath } = await requireCanonicalRollbackParent(relativePath, label);
  let pathBefore;
  let result = null;
  let readError = null;
  try {
    pathBefore = await lstat(absolutePath, { bigint: true });
  } catch (error) {
    if (error?.code === "ENOENT") {
      try {
        await lstat(absolutePath, { bigint: true });
      } catch (confirmationError) {
        if (confirmationError?.code === "ENOENT") {
          return Object.freeze({
            relativePath,
            exists: false,
            bytesBase64: null,
            byteLength: null,
            sha256: null,
            mode: null,
          });
        }
        throw confirmationError;
      }
      throw new ExactRollbackReadRaceError(
        label + ": exact-rollback missing path appeared during read: " + relativePath
      );
    }
    throw error;
  }
  requireExactRollbackStableFileView(pathBefore, relativePath, label);
  let fsTypeBefore;
  try {
    fsTypeBefore = (await statfs(absolutePath, { bigint: true })).type;
  } catch (error) {
    if (["ENOENT", "ENOTDIR", "ELOOP"].includes(error?.code)) {
      throw new ExactRollbackReadRaceError(
        label + ": exact-rollback path changed before open: " + relativePath
      );
    }
    throw error;
  }
  let handle;
  try {
    handle = await open(
      absolutePath,
      FS_CONSTANTS.O_RDONLY | FS_CONSTANTS.O_NOFOLLOW | FS_CONSTANTS.O_CLOEXEC
    );
  } catch (error) {
    if (["ENOENT", "ENOTDIR", "ELOOP"].includes(error?.code)) {
      throw new ExactRollbackReadRaceError(
        label + ": exact-rollback path disappeared before open: " + relativePath
      );
    }
    throw error;
  }
  try {
    const before = await handle.stat({ bigint: true });
    requireExactRollbackStableFileView(before, relativePath, label);
    const bytes = await handle.readFile();
    const after = await handle.stat({ bigint: true });
    let pathAfter;
    let fsTypeAfter;
    try {
      pathAfter = await lstat(absolutePath, { bigint: true });
      fsTypeAfter = (await statfs(absolutePath, { bigint: true })).type;
    } catch (error) {
      if (["ENOENT", "ENOTDIR", "ELOOP"].includes(error?.code)) {
        throw new ExactRollbackReadRaceError(
          label + ": exact-rollback path changed after handle read: " + relativePath
        );
      }
      throw error;
    }
    const mode = classifyExactRollbackDualView(
      {
        pathBefore,
        handleBefore: before,
        handleAfter: after,
        pathAfter,
        fsTypeBefore,
        fsTypeAfter,
      },
      relativePath,
      label
    );
    if (BigInt(bytes.length) !== after.size) {
      throw new ExactRollbackReadRaceError(
        label + ": exact-rollback handle changed while it was read: " + relativePath
      );
    }
    const fakeownerModeEvidence = isExactRollbackFakeownerBackingModeView({
      pathBefore,
      handleBefore: before,
      handleAfter: after,
      pathAfter,
      fsTypeBefore,
      fsTypeAfter,
    });
    result = freezeExactRollbackObservedEntry(
      {
        relativePath,
        exists: true,
        bytesBase64: bytes.toString("base64"),
        byteLength: bytes.length,
        sha256: exactBytesSha256(bytes),
        mode,
      },
      fakeownerModeEvidence
    );
  } catch (error) {
    readError = error;
  }
  let closeError = null;
  try {
    await handle.close();
  } catch (error) {
    closeError = error;
  }
  const terminalError = combineExactRollbackReadAndCloseErrors(readError, closeError, label);
  if (terminalError) throw terminalError;
  return result;
}

function sameExactRollbackSemanticState(left, right) {
  return Boolean(
    left &&
    right &&
    left.relativePath === right.relativePath &&
    left.exists === right.exists &&
    left.bytesBase64 === right.bytesBase64 &&
    left.byteLength === right.byteLength &&
    left.sha256 === right.sha256 &&
    left.mode === right.mode
  );
}

function exactRollbackFakeownerModeCandidate(current, terminalStates) {
  if (
    !hasExactRollbackFakeownerModeEvidence(current) ||
    current?.exists !== true ||
    current.mode !== EXACT_TRANSACTION_FAKEOWNER_BACKING_MODE
  ) {
    return null;
  }
  return (
    terminalStates.find(
      (terminal) =>
        terminal?.exists === true &&
        terminal.relativePath === current.relativePath &&
        terminal.bytesBase64 === current.bytesBase64 &&
        terminal.byteLength === current.byteLength &&
        terminal.sha256 === current.sha256 &&
        Number.isSafeInteger(terminal.mode) &&
        terminal.mode !== EXACT_TRANSACTION_FAKEOWNER_BACKING_MODE
    ) ?? null
  );
}

function exactRollbackCommittedConvergenceCollision(label, relativePath, reason) {
  return new ExactTransactionCollisionError(
    label + ": committed fakeowner convergence collided: " + reason + ": " + relativePath,
    relativePath
  );
}

async function observeExactRollbackSemanticState(
  relativePath,
  terminalStates,
  transitionalStates,
  label,
  {
    readEntry = readOptionalRollbackFile,
    wait = waitForExactTransactionObservation,
    maxObservations = EXACT_TRANSACTION_MAX_OBSERVATIONS,
    stableObservations = EXACT_TRANSACTION_STABLE_OBSERVATIONS,
    committedRenameFakeownerConvergenceAuthority = null,
  } = {}
) {
  const allowCommittedFakeownerConvergence =
    committedRenameFakeownerConvergenceAuthority ===
    COMMITTED_RENAME_FAKEOWNER_CONVERGENCE_AUTHORITY;
  if (
    !Array.isArray(terminalStates) ||
    terminalStates.length === 0 ||
    new Set(terminalStates.map(({ relativePath: path }) => path)).size !== 1 ||
    terminalStates.some(({ relativePath: path }) => path !== relativePath) ||
    !Array.isArray(transitionalStates) ||
    transitionalStates.some(({ relativePath: path }) => path !== relativePath) ||
    !Number.isSafeInteger(maxObservations) ||
    maxObservations < stableObservations ||
    !Number.isSafeInteger(stableObservations) ||
    stableObservations < 1 ||
    (committedRenameFakeownerConvergenceAuthority !== null && !allowCommittedFakeownerConvergence)
  ) {
    throw new Error(label + ": exact observation authority is malformed");
  }
  let stableState = null;
  let stableCount = 0;
  let transientReadErrors = 0;
  let sawFakeownerModeCandidate = false;
  for (let attempt = 0; attempt < maxObservations; attempt += 1) {
    let current;
    try {
      current = await readEntry(relativePath, label + " observation " + (attempt + 1));
    } catch (error) {
      if (!(error instanceof ExactRollbackReadRaceError)) throw error;
      if (allowCommittedFakeownerConvergence && stableCount > 0) {
        throw exactRollbackCommittedConvergenceCollision(
          label,
          relativePath,
          "read race after terminal confirmation began"
        );
      }
      stableState = null;
      stableCount = 0;
      transientReadErrors += 1;
      await wait(exactTransactionObservationDelay(attempt));
      continue;
    }
    const terminal = terminalStates.find((entry) => sameExactRollbackSemanticState(current, entry));
    const fakeownerModeCandidate = allowCommittedFakeownerConvergence
      ? exactRollbackFakeownerModeCandidate(current, terminalStates)
      : null;
    if (terminal) {
      if (stableState && sameExactRollbackSemanticState(stableState, terminal)) {
        stableCount += 1;
      } else {
        stableState = terminal;
        stableCount = 1;
      }
      if (stableCount === stableObservations) {
        return Object.freeze({
          state: terminal,
          observations: attempt + 1,
          transientReadErrors,
          diagnostic: exactRollbackEntrySafeDiagnostic(terminal),
        });
      }
    } else if (fakeownerModeCandidate) {
      if (stableCount > 0) {
        throw exactRollbackCommittedConvergenceCollision(
          label,
          relativePath,
          "backing mode returned after terminal confirmation began"
        );
      }
      sawFakeownerModeCandidate = true;
      stableState = null;
      stableCount = 0;
    } else if (transitionalStates.some((entry) => sameExactRollbackSemanticState(current, entry))) {
      if (allowCommittedFakeownerConvergence && stableCount > 0) {
        throw exactRollbackCommittedConvergenceCollision(
          label,
          relativePath,
          "transitional state returned after terminal confirmation began"
        );
      }
      stableState = null;
      stableCount = 0;
    } else {
      throw new ExactTransactionCollisionError(
        label +
          ": exact observation found a third state: " +
          JSON.stringify({
            path: relativePath,
            current: exactRollbackEntrySafeDiagnostic(current),
            terminals: terminalStates.map(exactRollbackEntrySafeDiagnostic),
            mountClass: EXACT_TRANSACTION_MOUNT_CLASS,
          }),
        relativePath
      );
    }
    await wait(exactTransactionObservationDelay(attempt));
  }
  if (allowCommittedFakeownerConvergence && (sawFakeownerModeCandidate || stableCount > 0)) {
    throw exactRollbackCommittedConvergenceCollision(
      label,
      relativePath,
      "bounded observation ended before three terminal confirmations"
    );
  }
  throw new ExactTransactionVisibilityError(
    label +
      ": exact observation did not converge: " +
      JSON.stringify({
        path: relativePath,
        maxObservations,
        stableObservations,
        transientReadErrors,
        terminals: terminalStates.map(exactRollbackEntrySafeDiagnostic),
        mountClass: EXACT_TRANSACTION_MOUNT_CLASS,
      })
  );
}

async function observeExactRollbackSnapshot(
  expectedSnapshot,
  label,
  { transitionalSnapshot = null, observationOptions = undefined } = {}
) {
  const transitionalByPath = new Map(
    (transitionalSnapshot?.entries ?? []).map((entry) => [entry.relativePath, entry])
  );
  const observations = [];
  for (const expected of expectedSnapshot.entries) {
    const transitional = transitionalByPath.get(expected.relativePath);
    observations.push(
      await observeExactRollbackSemanticState(
        expected.relativePath,
        [expected],
        transitional && !sameExactRollbackSemanticState(transitional, expected)
          ? [transitional]
          : [],
        label,
        observationOptions
      )
    );
  }
  return Object.freeze(observations);
}

function freezeWorktreeAuthority(snapshot) {
  return Object.freeze({
    head: snapshot.head,
    branch: snapshot.branch,
    indexAuthority: freezeGitIndexAuthority(
      snapshot.indexAuthority,
      "TASK-540 frozen worktree index authority"
    ),
    paths: Object.freeze([...snapshot.paths]),
    hashes: Object.freeze({ ...snapshot.hashes }),
  });
}

function equalWorktreeAuthority(left, right) {
  return (
    left.head === right.head &&
    left.branch === right.branch &&
    sameGitIndexAuthority(left.indexAuthority, right.indexAuthority) &&
    JSON.stringify(left.paths) === JSON.stringify(right.paths) &&
    equalHashMaps(left.hashes, right.hashes)
  );
}

async function captureExactRollbackFiles(relativePaths, label, { allowMissing = [] } = {}) {
  if (new Set(relativePaths).size !== relativePaths.length) {
    throw new Error(label + ": exact-rollback snapshot paths are duplicated");
  }
  const missingAllowed = new Set(allowMissing);
  const [authorityBefore, sensitiveEnvBefore] = await Promise.all([
    worktreeSnapshot(label + " before exact snapshot capture"),
    hashSensitiveEnvProjection(),
  ]);
  const entries = await Promise.all(
    relativePaths.map((relativePath) => readOptionalRollbackFile(relativePath, label))
  );
  for (const entry of entries) {
    if (!entry.exists && !missingAllowed.has(entry.relativePath)) {
      throw new Error(label + ": required exact-rollback file is missing: " + entry.relativePath);
    }
  }
  const [authorityAfter, sensitiveEnvAfter] = await Promise.all([
    worktreeSnapshot(label + " after exact snapshot capture"),
    hashSensitiveEnvProjection(),
  ]);
  if (
    !equalWorktreeAuthority(authorityBefore, authorityAfter) ||
    !equalHashMaps(sensitiveEnvBefore, sensitiveEnvAfter)
  ) {
    throw new Error(label + ": repository authority changed during exact snapshot capture");
  }
  return Object.freeze({
    authority: freezeWorktreeAuthority(authorityBefore),
    sensitiveEnv: sensitiveEnvBefore,
    entries: Object.freeze(entries),
  });
}

async function verifyExactRollbackFiles(snapshot, label) {
  const errors = [];
  for (const expected of snapshot.entries) {
    try {
      const actual = await readOptionalRollbackFile(expected.relativePath, label);
      if (
        actual.exists !== expected.exists ||
        actual.bytesBase64 !== expected.bytesBase64 ||
        actual.byteLength !== expected.byteLength ||
        actual.sha256 !== expected.sha256 ||
        actual.mode !== expected.mode
      ) {
        throw new Error(label + ": exact bytes were not restored for " + expected.relativePath);
      }
    } catch (error) {
      errors.push(error);
    }
  }
  if (errors.length > 0) {
    throw new AggregateError(errors, label + ": exact persisted rollback verification failed");
  }
}

async function verifyExactRollbackFileSubset(snapshot, relativePaths, label) {
  const requested = new Set(relativePaths);
  if (requested.size !== relativePaths.length) {
    throw new Error(label + ": exact snapshot subset paths are duplicated");
  }
  const entries = snapshot.entries.filter(({ relativePath }) => requested.has(relativePath));
  if (entries.length !== requested.size) {
    throw new Error(label + ": exact snapshot subset is incomplete");
  }
  await verifyExactRollbackFiles(Object.freeze({ entries: Object.freeze(entries) }), label);
}

function exactRollbackEntryBytes(entry, label) {
  if (
    !entry.exists ||
    typeof entry.bytesBase64 !== "string" ||
    !Number.isSafeInteger(entry.byteLength) ||
    entry.byteLength < 0 ||
    typeof entry.sha256 !== "string" ||
    !/^[0-9a-f]{64}$/.test(entry.sha256)
  ) {
    throw new Error(label + ": exact-rollback byte snapshot is malformed: " + entry.relativePath);
  }
  const bytes = Buffer.from(entry.bytesBase64, "base64");
  if (
    bytes.toString("base64") !== entry.bytesBase64 ||
    bytes.length !== entry.byteLength ||
    exactBytesSha256(bytes) !== entry.sha256
  ) {
    throw new Error(
      label + ": exact-rollback byte snapshot is not canonical: " + entry.relativePath
    );
  }
  return bytes;
}

function exactRollbackEntryUtf8(entry, label) {
  const bytes = exactRollbackEntryBytes(entry, label);
  const source = bytes.toString("utf8");
  if (!Buffer.from(source, "utf8").equals(bytes)) {
    throw new Error(
      label + ": semantic task/changelog source is not strict UTF-8: " + entry.relativePath
    );
  }
  return source;
}

function requireExactRollbackSnapshotEntry(snapshot, relativePath, label) {
  const entries = snapshot.entries.filter((entry) => entry.relativePath === relativePath);
  if (entries.length !== 1 || !entries[0].exists) {
    throw new Error(label + ": exact-rollback snapshot entry is missing: " + relativePath);
  }
  exactRollbackEntryBytes(entries[0], label);
  return entries[0];
}

function requireExactRollbackSnapshotUtf8(snapshot, relativePath, label) {
  return exactRollbackEntryUtf8(
    requireExactRollbackSnapshotEntry(snapshot, relativePath, label),
    label
  );
}

async function readRollbackTargetInfo(absolutePath) {
  try {
    return await lstat(absolutePath);
  } catch (error) {
    if (error?.code === "ENOENT") return null;
    throw error;
  }
}

async function unlinkSafeRollbackTarget(absolutePath, relativePath, label) {
  const info = await readRollbackTargetInfo(absolutePath);
  if (!info) return false;
  if (!info.isFile() && !info.isSymbolicLink()) {
    throw new Error(label + ": rollback target became a non-file: " + relativePath);
  }
  await unlink(absolutePath);
  return true;
}

async function requireReplaceableRollbackTarget(absolutePath, relativePath, label) {
  const info = await readRollbackTargetInfo(absolutePath);
  if (info && !info.isFile() && !info.isSymbolicLink()) {
    throw new Error(label + ": rollback target became a non-file: " + relativePath);
  }
}

async function syncCanonicalRollbackParent(parentAbsolutePath, label) {
  const handle = await open(
    parentAbsolutePath,
    FS_CONSTANTS.O_RDONLY | FS_CONSTANTS.O_DIRECTORY | FS_CONSTANTS.O_CLOEXEC
  );
  let syncError = null;
  try {
    await handle.sync();
  } catch (error) {
    syncError = error;
  }
  let closeError = null;
  try {
    await handle.close();
  } catch (error) {
    closeError = error;
  }
  if (syncError && closeError) {
    throw new AggregateError(
      [syncError, closeError],
      label + ": parent-directory sync and close both failed"
    );
  }
  if (syncError) throw syncError;
  if (closeError) throw closeError;
}

function exactWriteReceipt(relativePath, operation, beforeEntry, afterEntry, parentSynced) {
  return Object.freeze({
    relativePath,
    operation,
    committed: true,
    parentSynced,
    before: exactRollbackEntrySafeDiagnostic(beforeEntry),
    after: exactRollbackEntrySafeDiagnostic(afterEntry),
    mountClass: EXACT_TRANSACTION_MOUNT_CLASS,
  });
}

function wrapCommittedExactWriteError(error, receipt, label) {
  const wrapped = new Error(label + ": committed exact write did not finish verification", {
    cause: error,
  });
  Object.defineProperty(wrapped, "exactWriteReceipt", {
    configurable: false,
    enumerable: false,
    writable: false,
    value: receipt,
  });
  return wrapped;
}

function exactWriteReceiptFromError(error) {
  return error?.exactWriteReceipt ?? null;
}

function wrapAccumulatedExactRollbackError(error, receipts, label) {
  if (!Array.isArray(receipts) || receipts.length === 0) return error;
  const wrapped = new Error(label + ": reverse rollback stopped after committed receipts", {
    cause: error,
  });
  Object.defineProperty(wrapped, "exactRollbackReceipts", {
    configurable: false,
    enumerable: false,
    writable: false,
    value: Object.freeze([...receipts]),
  });
  return wrapped;
}

function exactRollbackReceiptsFromError(error) {
  if (Array.isArray(error?.exactRollbackReceipts)) return error.exactRollbackReceipts;
  if (error instanceof AggregateError) {
    for (const nested of error.errors) {
      const receipts = exactRollbackReceiptsFromError(nested);
      if (receipts.length > 0) return receipts;
    }
  }
  return error?.cause ? exactRollbackReceiptsFromError(error.cause) : Object.freeze([]);
}

function exactTransactionErrorContains(error, ErrorType) {
  if (error instanceof ErrorType) return true;
  if (error instanceof AggregateError) {
    return error.errors.some((nested) => exactTransactionErrorContains(nested, ErrorType));
  }
  return error?.cause ? exactTransactionErrorContains(error.cause, ErrorType) : false;
}

const COMMITTED_UNLINK_SEQUENCE_IO = Object.freeze({
  unlinkTarget: unlinkSafeRollbackTarget,
  resolveLocation: requireCanonicalRollbackParent,
  syncParent: syncCanonicalRollbackParent,
  observeState: observeExactRollbackSemanticState,
});

function requireCommittedUnlinkSequenceIo(io, label) {
  const keys = ["observeState", "resolveLocation", "syncParent", "unlinkTarget"];
  if (
    io !== COMMITTED_UNLINK_SEQUENCE_IO &&
    (!HERMETIC_SELF_TEST_MODE ||
      JSON.stringify(Object.keys(io ?? {}).sort()) !== JSON.stringify(keys))
  ) {
    throw new Error(label + ": committed-unlink sequencing I/O lacks hermetic authority");
  }
  for (const key of keys) {
    if (typeof io?.[key] !== "function") {
      throw new Error(label + ": committed-unlink sequencing I/O is missing " + key);
    }
  }
  return io;
}

async function commitExactUnlinkBoundary(
  entry,
  expectedCurrentEntry,
  location,
  label,
  { observeCommitted, observationOptions, sequenceIo = COMMITTED_UNLINK_SEQUENCE_IO }
) {
  requireCommittedUnlinkSequenceIo(sequenceIo, label);
  const unlinked = await sequenceIo.unlinkTarget(location.absolutePath, entry.relativePath, label);
  if (!unlinked) return null;

  // The receipt is intentionally synchronous with successful unlink completion.
  // No post-commit await may occur before this recoverable boundary exists.
  let committedReceipt = exactWriteReceipt(
    entry.relativePath,
    "unlink",
    expectedCurrentEntry ?? entry,
    entry,
    false
  );
  try {
    location = await sequenceIo.resolveLocation(entry.relativePath, label);
    await sequenceIo.syncParent(location.parentAbsolutePath, label + " committed unlink");
    committedReceipt = exactWriteReceipt(
      entry.relativePath,
      "unlink",
      expectedCurrentEntry ?? entry,
      entry,
      true
    );
    if (observeCommitted) {
      await sequenceIo.observeState(
        entry.relativePath,
        [entry],
        expectedCurrentEntry ? [expectedCurrentEntry] : [],
        label + " committed unlink visibility",
        observationOptions
      );
    }
  } catch (error) {
    throw wrapCommittedExactWriteError(error, committedReceipt, label);
  }
  return committedReceipt;
}

async function restoreExactRollbackEntry(
  entry,
  label,
  {
    expectedCurrentEntry = null,
    observeCommitted = expectedCurrentEntry !== null,
    observationOptions = undefined,
    unlinkSequenceIo = COMMITTED_UNLINK_SEQUENCE_IO,
  } = {}
) {
  let location = await requireCanonicalRollbackParent(entry.relativePath, label);
  let committedReceipt = null;
  if (!entry.exists) {
    if (expectedCurrentEntry) {
      await observeExactRollbackSemanticState(
        entry.relativePath,
        [expectedCurrentEntry],
        [],
        label + " immediate pre-unlink guard",
        observationOptions
      );
    }
    return commitExactUnlinkBoundary(entry, expectedCurrentEntry, location, label, {
      observeCommitted,
      observationOptions,
      sequenceIo: unlinkSequenceIo,
    });
  }
  const bytes = exactRollbackEntryBytes(entry, label);

  const temporaryPath =
    location.parentAbsolutePath +
    "/." +
    location.basename +
    ".task-540-rollback-" +
    randomUUID() +
    ".tmp";
  let handle = null;
  let temporaryExists = false;
  let mutationError = null;
  try {
    handle = await open(temporaryPath, "wx", 0o600);
    temporaryExists = true;
    await handle.writeFile(bytes);
    await handle.chmod(entry.mode);
    await handle.sync();
    await handle.close();
    handle = null;

    location = await requireCanonicalRollbackParent(entry.relativePath, label);
    await requireReplaceableRollbackTarget(location.absolutePath, entry.relativePath, label);
    location = await requireCanonicalRollbackParent(entry.relativePath, label);
    if (expectedCurrentEntry) {
      await observeExactRollbackSemanticState(
        entry.relativePath,
        [expectedCurrentEntry],
        [],
        label + " immediate pre-rename guard",
        observationOptions
      );
    }
    await rename(temporaryPath, location.absolutePath);
    temporaryExists = false;
    committedReceipt = exactWriteReceipt(
      entry.relativePath,
      "rename",
      expectedCurrentEntry ?? entry,
      entry,
      false
    );
    location = await requireCanonicalRollbackParent(entry.relativePath, label);
    await syncCanonicalRollbackParent(location.parentAbsolutePath, label + " committed rename");
    committedReceipt = exactWriteReceipt(
      entry.relativePath,
      "rename",
      expectedCurrentEntry ?? entry,
      entry,
      true
    );
    if (observeCommitted) {
      await observeExactRollbackSemanticState(
        entry.relativePath,
        [entry],
        expectedCurrentEntry ? [expectedCurrentEntry] : [],
        label + " committed rename visibility",
        {
          ...observationOptions,
          committedRenameFakeownerConvergenceAuthority:
            COMMITTED_RENAME_FAKEOWNER_CONVERGENCE_AUTHORITY,
        }
      );
    }
  } catch (error) {
    mutationError = error;
  }

  const cleanupErrors = [];
  if (handle) {
    try {
      await handle.close();
    } catch (error) {
      cleanupErrors.push(error);
    }
  }
  if (temporaryExists) {
    try {
      await unlink(temporaryPath);
      await syncCanonicalRollbackParent(
        location.parentAbsolutePath,
        label + " temporary cleanup unlink"
      );
    } catch (error) {
      if (error?.code !== "ENOENT") cleanupErrors.push(error);
    }
  }
  if (mutationError && cleanupErrors.length > 0) {
    const combined = new AggregateError(
      [mutationError, ...cleanupErrors],
      label + ": exact rollback write and temporary cleanup both failed"
    );
    throw committedReceipt
      ? wrapCommittedExactWriteError(combined, committedReceipt, label)
      : combined;
  }
  if (mutationError) {
    throw committedReceipt
      ? wrapCommittedExactWriteError(mutationError, committedReceipt, label)
      : mutationError;
  }
  if (cleanupErrors.length > 0) {
    throw new AggregateError(cleanupErrors, label + ": exact rollback temporary cleanup failed");
  }
  return committedReceipt;
}

function isAuthorizedExactRollbackResidual(relativePath, rollbackOwnedPathSet, residualPathSet) {
  return rollbackOwnedPathSet.has(relativePath) || residualPathSet.has(relativePath);
}

function buildExactRollbackRestorePlan(targetSnapshot, currentSnapshot, label) {
  const targetPaths = targetSnapshot.entries.map(({ relativePath }) => relativePath);
  const currentPaths = currentSnapshot.entries.map(({ relativePath }) => relativePath);
  if (!sameUniqueSet(targetPaths, currentPaths)) {
    throw new Error(label + ": current exact snapshot does not cover rollback authority");
  }
  const currentByPath = new Map(
    currentSnapshot.entries.map((entry) => [entry.relativePath, entry])
  );
  return Object.freeze(
    targetSnapshot.entries.flatMap((targetEntry) => {
      const currentEntry = currentByPath.get(targetEntry.relativePath);
      if (!currentEntry) {
        throw new Error(label + ": current exact snapshot omitted " + targetEntry.relativePath);
      }
      return sameExactRollbackSemanticState(targetEntry, currentEntry)
        ? []
        : [Object.freeze({ targetEntry, currentEntry })];
    })
  );
}

async function executeExactRollbackRestorePlan(
  targetSnapshot,
  currentSnapshot,
  restorePlan,
  label,
  io = SNAPSHOT_DERIVED_EXACT_TRANSACTION_IO
) {
  requireSnapshotDerivedExactTransactionIo(io, label);
  const receipts = [];
  const committedPaths = () => receipts.map(({ relativePath }) => relativePath);
  try {
    await io.requireAuthority(currentSnapshot, [], label + " initial authority");
    for (const { targetEntry, currentEntry } of restorePlan) {
      await io.requireAuthority(
        currentSnapshot,
        committedPaths(),
        label + " authority before " + targetEntry.relativePath
      );
      let receipt = null;
      try {
        receipt = await io.writeEntry(
          currentEntry,
          targetEntry,
          label + " guarded restore " + targetEntry.relativePath
        );
      } catch (error) {
        const committed = exactWriteReceiptFromError(error);
        if (committed) {
          receipts.push(
            sequenceExactWriteReceipt(
              committed,
              receipts.length + 1,
              currentEntry,
              targetEntry,
              label
            )
          );
          try {
            await io.requireAuthority(
              currentSnapshot,
              committedPaths(),
              label + " authority after failed write " + targetEntry.relativePath
            );
          } catch (authorityError) {
            throw new AggregateError(
              [error, authorityError],
              label + ": exact rollback write and closing authority both failed"
            );
          }
        }
        throw error;
      }
      receipts.push(
        sequenceExactWriteReceipt(receipt, receipts.length + 1, currentEntry, targetEntry, label)
      );
      await io.requireAuthority(
        currentSnapshot,
        committedPaths(),
        label + " authority after " + targetEntry.relativePath
      );
    }
    await io.verifySnapshot(targetSnapshot, label + " stable restored target", {
      transitionalSnapshot: currentSnapshot,
    });
    await io.requireAuthority(
      currentSnapshot,
      committedPaths(),
      label + " authority after restored target"
    );
    await io.verifySnapshot(targetSnapshot, label + " target after closing authority", {
      transitionalSnapshot: currentSnapshot,
    });
  } catch (error) {
    throw wrapAccumulatedExactRollbackError(error, receipts, label);
  }
  return Object.freeze([...receipts]);
}

async function restoreExactRollbackFiles(
  snapshot,
  owner,
  label,
  { allowedResidualPaths = [] } = {}
) {
  // Rollback stays orchestrator-local: these task/index snapshots can be large,
  // and exact bytes must never be serialized into an agent prompt or shell command.
  if (
    !sameUniqueSet(
      snapshot.entries.map((entry) => entry.relativePath),
      owner.allowedFiles
    )
  ) {
    throw new Error(label + ": exact snapshot does not cover every rollback-owned file");
  }
  for (const entry of snapshot.entries) {
    if (!owner.allowedFiles.includes(entry.relativePath)) {
      throw new Error(label + ": rollback owner does not own " + entry.relativePath);
    }
  }
  if (new Set(allowedResidualPaths).size !== allowedResidualPaths.length) {
    throw new Error(label + ": residual rollback paths are duplicated");
  }
  const residualPathSet = new Set(allowedResidualPaths);
  for (const relativePath of residualPathSet) {
    if (
      typeof relativePath !== "string" ||
      relativePath.length === 0 ||
      relativePath.startsWith("/") ||
      relativePath.split("/").includes("..") ||
      relativePath.split("/").some((segment) => /^\.env(?:\.|$)/.test(segment)) ||
      owner.allowedFiles.includes(relativePath)
    ) {
      throw new Error(label + ": unsafe residual rollback path " + relativePath);
    }
  }
  const [currentAuthority, currentSensitiveEnv] = await Promise.all([
    worktreeSnapshot(label + " before exact rollback restore"),
    hashSensitiveEnvProjection(),
  ]);
  if (
    currentAuthority.head !== snapshot.authority.head ||
    currentAuthority.branch !== snapshot.authority.branch ||
    !sameGitIndexAuthority(currentAuthority.indexAuthority, snapshot.authority.indexAuthority) ||
    !equalHashMaps(currentSensitiveEnv, snapshot.sensitiveEnv)
  ) {
    throw new Error(label + ": exact rollback authority changed before restore");
  }
  const preRestoreDelta = snapshotDelta(snapshot.authority, currentAuthority);
  if (
    preRestoreDelta.some(
      (relativePath) =>
        !owner.allowedFiles.includes(relativePath) && !residualPathSet.has(relativePath)
    )
  ) {
    throw new Error(
      label + ": unrelated worktree state changed before rollback: " + preRestoreDelta.join(", ")
    );
  }
  const currentSnapshot = await captureExactRollbackFiles(
    owner.allowedFiles,
    label + " current exact rollback state",
    { allowMissing: owner.allowedFiles }
  );
  if (
    !equalWorktreeAuthority(currentAuthority, currentSnapshot.authority) ||
    !equalHashMaps(currentSensitiveEnv, currentSnapshot.sensitiveEnv)
  ) {
    throw new Error(label + ": repository authority changed during current rollback capture");
  }
  const restorePlan = buildExactRollbackRestorePlan(snapshot, currentSnapshot, label);
  await executeExactRollbackRestorePlan(snapshot, currentSnapshot, restorePlan, label);
}

async function assertTask540ExactRollbackResidualContract() {
  const bytes = Buffer.from("same rollback bytes", "utf8");
  const beforeStat = Object.freeze({
    dev: 1n,
    ino: 10n,
    mode: 0o100644n,
    nlink: 1n,
    size: BigInt(bytes.length),
    mtimeNs: 100n,
    ctimeNs: 100n,
  });
  const afterAtomicRenameStat = Object.freeze({
    ...beforeStat,
    ino: 11n,
    mtimeNs: 101n,
    ctimeNs: 101n,
  });
  if (
    hashStableRegularFileAuthority(bytes, beforeStat) ===
    hashStableRegularFileAuthority(bytes, afterAtomicRenameStat)
  ) {
    throw new Error("TASK-540 exact rollback self-test lost metadata-sensitive authority");
  }

  const rollbackOwnedPathSet = new Set(["owned/task.md", "owned/board.md"]);
  const residualPathSet = new Set(["allowed/source.ts"]);
  const cases = Object.freeze([
    Object.freeze({ path: "owned/task.md", expected: true }),
    Object.freeze({ path: "owned/board.md", expected: true }),
    Object.freeze({ path: "allowed/source.ts", expected: true }),
    Object.freeze({ path: "owned/task.md.extra", expected: false }),
    Object.freeze({ path: "owned", expected: false }),
    Object.freeze({ path: "unrelated/task.md", expected: false }),
  ]);
  for (const testCase of cases) {
    if (
      isAuthorizedExactRollbackResidual(testCase.path, rollbackOwnedPathSet, residualPathSet) !==
      testCase.expected
    ) {
      throw new Error("TASK-540 exact rollback residual self-test failed: " + testCase.path);
    }
  }

  const restoreEntry = (relativePath, token) =>
    Object.freeze({
      relativePath,
      exists: true,
      bytesBase64: token,
      byteLength: token.length,
      sha256: token.padEnd(64, "0"),
      mode: 0o644,
    });
  const targetEntries = Object.freeze([
    restoreEntry("owned/root.md", "1"),
    restoreEntry("owned/child.md", "2"),
    restoreEntry("owned/leaf.md", "3"),
    restoreEntry("owned/board.md", "4"),
  ]);
  const plannerTargetSnapshot = Object.freeze({ entries: targetEntries });
  const noOpPlan = buildExactRollbackRestorePlan(
    plannerTargetSnapshot,
    plannerTargetSnapshot,
    "fixture no-op"
  );
  const changedChild = restoreEntry("owned/child.md", "5");
  const changedPlan = buildExactRollbackRestorePlan(
    plannerTargetSnapshot,
    Object.freeze({
      entries: Object.freeze([targetEntries[0], changedChild, targetEntries[2], targetEntries[3]]),
    }),
    "fixture changed child"
  );
  let incompleteRejected = false;
  try {
    buildExactRollbackRestorePlan(
      plannerTargetSnapshot,
      Object.freeze({ entries: targetEntries.slice(0, 3) }),
      "fixture incomplete"
    );
  } catch {
    incompleteRejected = true;
  }
  if (
    noOpPlan.length !== 0 ||
    changedPlan.length !== 1 ||
    changedPlan[0].targetEntry !== targetEntries[1] ||
    changedPlan[0].currentEntry !== changedChild ||
    !incompleteRejected
  ) {
    throw new Error("TASK-540 exact rollback restore-plan self-test failed");
  }

  const targetSnapshot = exactTransactionFixtureSnapshot([
    { relativePath: "owned/root.md", source: "root target", mode: 0o644 },
    { relativePath: "owned/board.md", source: "board target", mode: 0o644 },
  ]);
  const noOpHarness = createHermeticExactTransactionIo(targetSnapshot);
  await executeExactRollbackRestorePlan(
    targetSnapshot,
    targetSnapshot,
    buildExactRollbackRestorePlan(targetSnapshot, targetSnapshot, "fixture exact no-op"),
    "fixture exact no-op",
    noOpHarness.io
  );
  const noOp = noOpHarness.inspect(targetSnapshot);

  const currentSnapshot = exactTransactionFixtureSnapshot([
    { relativePath: "owned/root.md", source: "root target", mode: 0o644 },
    { relativePath: "owned/board.md", source: "board current", mode: 0o644 },
  ]);
  const changedHarness = createHermeticExactTransactionIo(currentSnapshot, {
    postWriteVisibilitySequence: ["before", "after", "after", "after"],
  });
  await executeExactRollbackRestorePlan(
    targetSnapshot,
    currentSnapshot,
    buildExactRollbackRestorePlan(targetSnapshot, currentSnapshot, "fixture exact changed"),
    "fixture exact changed",
    changedHarness.io
  );
  const changed = changedHarness.inspect(targetSnapshot);

  const bothChangedSnapshot = exactTransactionFixtureSnapshot([
    { relativePath: "owned/root.md", source: "root current", mode: 0o644 },
    { relativePath: "owned/board.md", source: "board current", mode: 0o644 },
  ]);
  const collisionHarness = createHermeticExactTransactionIo(bothChangedSnapshot, {
    collideBeforeWrite: 1,
  });
  let collisionRejected = false;
  try {
    await executeExactRollbackRestorePlan(
      targetSnapshot,
      bothChangedSnapshot,
      buildExactRollbackRestorePlan(targetSnapshot, bothChangedSnapshot, "fixture exact collision"),
      "fixture exact collision",
      collisionHarness.io
    );
  } catch (error) {
    collisionRejected = exactTransactionErrorContains(error, ExactTransactionCollisionError);
  }
  const collision = collisionHarness.inspect();

  const driftHarness = createHermeticExactTransactionIo(bothChangedSnapshot, {
    authorityDriftAtCalls: [3],
  });
  let authorityDriftRejected = false;
  try {
    await executeExactRollbackRestorePlan(
      targetSnapshot,
      bothChangedSnapshot,
      buildExactRollbackRestorePlan(
        targetSnapshot,
        bothChangedSnapshot,
        "fixture exact authority drift"
      ),
      "fixture exact authority drift",
      driftHarness.io
    );
  } catch {
    authorityDriftRejected = true;
  }
  const drift = driftHarness.inspect();
  if (
    !noOp.exact ||
    noOp.writePaths.length !== 0 ||
    !changed.exact ||
    JSON.stringify(changed.writePaths) !== JSON.stringify(["owned/board.md"]) ||
    changed.visibilityReads !== 4 ||
    !collisionRejected ||
    collision.writePaths.length !== 0 ||
    !collision.collisionPreserved ||
    !authorityDriftRejected ||
    JSON.stringify(drift.writePaths) !== JSON.stringify(["owned/root.md"])
  ) {
    throw new Error("TASK-540 exact rollback execution self-test failed");
  }
  return cases.length + 8;
}

async function assertTask540TouchedModuleLineLimitContract() {
  const pathCases = Object.freeze([
    Object.freeze({ path: "core/services/example.ts", expected: true }),
    Object.freeze({ path: "packages/sdk/src/example.tsx", expected: true }),
    Object.freeze({ path: "store/src/example.mjs", expected: true }),
    Object.freeze({ path: "tests/integration/support/example.ts", expected: true }),
    Object.freeze({
      path: "tests/integration/routes/customScreensDefinitionIntegrityRoutes.test.ts",
      expected: true,
    }),
    Object.freeze({ path: "_docs/_workflows/example.mjs", expected: false }),
    Object.freeze({ path: "core/db/migrations/meta/0001_snapshot.ts", expected: false }),
    Object.freeze({ path: "core/services/example.generated.ts", expected: false }),
  ]);
  for (const testCase of pathCases) {
    if (isLineLimitedHumanAuthoredModule(testCase.path) !== testCase.expected) {
      throw new Error("TASK-540 line-limit path self-test failed: " + testCase.path);
    }
  }
  const lineCases = Object.freeze([
    Object.freeze({ bytes: Buffer.alloc(0), expected: 0 }),
    Object.freeze({ bytes: Buffer.from("one"), expected: 1 }),
    Object.freeze({ bytes: Buffer.from("one\n"), expected: 1 }),
    Object.freeze({ bytes: Buffer.from("one\ntwo"), expected: 2 }),
    Object.freeze({ bytes: Buffer.from("one\ntwo\n"), expected: 2 }),
    Object.freeze({ bytes: Buffer.from("one\rtwo"), expected: 2 }),
    Object.freeze({ bytes: Buffer.from("one\rtwo\r"), expected: 2 }),
    Object.freeze({ bytes: Buffer.from("one\r\ntwo\r\n"), expected: 2 }),
    Object.freeze({ bytes: Buffer.from("one\rtwo\nthree\r\n"), expected: 3 }),
    Object.freeze({ bytes: Buffer.from("one\u2028two\u2029"), expected: 2 }),
    Object.freeze({ bytes: Buffer.from("x\n".repeat(1_000)), expected: 1_000 }),
    Object.freeze({ bytes: Buffer.from("x\n".repeat(1_001)), expected: 1_001 }),
  ]);
  for (const testCase of lineCases) {
    if (physicalLineCount(testCase.bytes) !== testCase.expected) {
      throw new Error("TASK-540 physical-line-count self-test failed");
    }
  }
  if (HUMAN_AUTHORED_MODULE_LINE_LIMIT !== 1_000) {
    throw new Error("TASK-540 human-authored module line limit drifted");
  }
  const readOnlyOwnerCases = Object.freeze([
    Object.freeze({
      path: "tests/vitest/ui-integration/custom-screen-widget-picker.test.tsx",
      owner: "540-05-L01",
    }),
    Object.freeze({
      path: "core/admin/ui/entries/FieldRenderer.tsx",
      owner: "540-06-L01",
    }),
    Object.freeze({
      path: "core/admin/ui/media/MediaPicker.tsx",
      owner: "540-06-L01",
    }),
    Object.freeze({
      path: "tests/vitest/ui/entry-field-relation-interaction.test.tsx",
      owner: "540-06-L01",
    }),
    Object.freeze({
      path: "tests/vitest/ui/entry-field-relation-option-identity.test.tsx",
      owner: "540-06-L01",
    }),
  ]);
  if (
    readOnlyOwnerCases.some(
      ({ path, owner }) =>
        !isLineLimitedHumanAuthoredModule(path) ||
        JSON.stringify(task540LineLimitOwnerIds(path)) !== JSON.stringify([owner]) ||
        LEAVES.some(({ allowedFiles }) => allowedFiles.includes(path))
    )
  ) {
    throw new Error("TASK-540 read-only line-limit owner self-test failed");
  }
  const emptyDynamicAuthority = buildTask540TouchedModulePathAuthority(
    [],
    [],
    [],
    "TASK-540 hermetic frozen authority self-test"
  );
  const dynamicTrackedPath = "core/services/customScreens/newTrackedContract.ts";
  const dynamicUntrackedPath = "tests/vitest/admin/new-untracked-contract.test.ts";
  const expandedAuthority = buildTask540TouchedModulePathAuthority(
    [dynamicTrackedPath],
    [dynamicTrackedPath, TASK_540_FROZEN_PRE_SPLIT_MODULE_PATHS[0]],
    [dynamicTrackedPath, dynamicUntrackedPath, dynamicUntrackedPath],
    "TASK-540 hermetic expanded authority self-test"
  );
  if (
    emptyDynamicAuthority.trackedPaths.length !== 91 ||
    emptyDynamicAuthority.untrackedPaths.length !== 0 ||
    !expandedAuthority.trackedPaths.includes(dynamicTrackedPath) ||
    expandedAuthority.trackedPaths.filter((path) => path === dynamicTrackedPath).length !== 1 ||
    expandedAuthority.untrackedPaths.join("\n") !== dynamicUntrackedPath
  ) {
    throw new Error("TASK-540 frozen/dynamic path union self-test failed");
  }
  const validAncestryProjection = Object.freeze({
    firstCommitLine: TASK_540_FIRST_FAMILY_COMMIT + " " + TASK_540_PRE_FAMILY_BASELINE,
    baselineMergeBase: TASK_540_PRE_FAMILY_BASELINE,
    firstCommitMergeBase: TASK_540_FIRST_FAMILY_COMMIT,
  });
  requireTask540FamilyBaselineProjection(
    validAncestryProjection,
    "TASK-540 valid ancestry self-test"
  );
  for (const invalidProjection of [
    { ...validAncestryProjection, firstCommitLine: TASK_540_FIRST_FAMILY_COMMIT + " bad-parent" },
    { ...validAncestryProjection, baselineMergeBase: "bad-baseline" },
    { ...validAncestryProjection, firstCommitMergeBase: "bad-first-commit" },
  ]) {
    let rejected = false;
    try {
      requireTask540FamilyBaselineProjection(
        invalidProjection,
        "TASK-540 invalid ancestry self-test"
      );
    } catch {
      rejected = true;
    }
    if (!rejected) throw new Error("TASK-540 invalid ancestry projection self-test failed");
  }
  const plannedUntrackedPath =
    "tests/integration/routes/customScreensDefinitionIntegrityRoutes.test.ts";
  if (
    physicalLineCount(Buffer.from("x\n".repeat(1_000))) > HUMAN_AUTHORED_MODULE_LINE_LIMIT ||
    physicalLineCount(Buffer.from("x\n".repeat(1_001))) <= HUMAN_AUTHORED_MODULE_LINE_LIMIT ||
    !PLANNED_TASK_540_TEST_FILES.includes(plannedUntrackedPath) ||
    !TRACKED_TEST_FILES.includes(plannedUntrackedPath)
  ) {
    throw new Error("TASK-540 line-limit threshold/untracked authority self-test failed");
  }
  const atLimitEvidence = await requireTask540TouchedModuleLineLimit(
    "TASK-540 hermetic untracked at-limit self-test",
    [plannedUntrackedPath],
    Object.freeze({
      trackedPaths: Object.freeze([]),
      untrackedPaths: Object.freeze([plannedUntrackedPath]),
      fileBytesByPath: Object.freeze({
        [plannedUntrackedPath]: Buffer.from("x\n".repeat(1_000)),
      }),
    })
  );
  if (
    atLimitEvidence.length !== 1 ||
    atLimitEvidence[0].path !== plannedUntrackedPath ||
    atLimitEvidence[0].lines !== 1_000 ||
    atLimitEvidence[0].sha256 !==
      createHash("sha256")
        .update(Buffer.from("x\n".repeat(1_000)))
        .digest("hex")
  ) {
    throw new Error("TASK-540 untracked at-limit evidence self-test failed");
  }
  const historicalPath = "core/services/example.ts";
  const historicalEvidence = await requireTask540TouchedModuleLineLimit(
    "TASK-540 hermetic committed-history self-test",
    [historicalPath],
    Object.freeze({
      trackedPaths: Object.freeze([historicalPath]),
      untrackedPaths: Object.freeze([]),
      fileBytesByPath: Object.freeze({
        [historicalPath]: Buffer.from("history\n"),
      }),
    })
  );
  if (
    historicalEvidence.length !== 1 ||
    historicalEvidence[0].path !== historicalPath ||
    historicalEvidence[0].lines !== 1
  ) {
    throw new Error("TASK-540 committed-history evidence self-test failed");
  }
  let overLimitRejected = false;
  try {
    await requireTask540TouchedModuleLineLimit(
      "TASK-540 hermetic untracked over-limit self-test",
      [plannedUntrackedPath],
      Object.freeze({
        trackedPaths: Object.freeze([]),
        untrackedPaths: Object.freeze([plannedUntrackedPath]),
        fileBytesByPath: Object.freeze({
          [plannedUntrackedPath]: Buffer.from("x\n".repeat(1_001)),
        }),
      })
    );
  } catch (error) {
    overLimitRejected =
      error instanceof Error && error.message.includes(plannedUntrackedPath + "=1001");
  }
  if (!overLimitRejected) {
    throw new Error("TASK-540 untracked over-limit rejection self-test failed");
  }
  let duplicateAuthorityRejected = false;
  try {
    await requireTask540TouchedModuleLineLimit(
      "TASK-540 hermetic duplicate history/untracked self-test",
      [historicalPath],
      Object.freeze({
        trackedPaths: Object.freeze([historicalPath]),
        untrackedPaths: Object.freeze([historicalPath]),
        fileBytesByPath: Object.freeze({
          [historicalPath]: Buffer.from("history\n"),
        }),
      })
    );
  } catch (error) {
    duplicateAuthorityRejected =
      error instanceof Error &&
      error.message.includes("invalid hermetic line-limit path projection");
  }
  if (!duplicateAuthorityRejected) {
    throw new Error("TASK-540 duplicate history/untracked authority self-test failed");
  }
  return pathCases.length + lineCases.length + readOnlyOwnerCases.length + 10;
}

async function requireNoPendingTask540ModularityRepairs(label) {
  const pending = [];
  for (const file of PENDING_MODULARITY_REPAIR_TASK_FILES) {
    const source = await readFile(TASKS + "/" + file, "utf8");
    const matches = source.match(/^\*\*Modularity Repair Pending:\*\*/gmu) ?? [];
    if (matches.length > 1) {
      throw new Error(label + ": duplicate modularity repair field in " + file);
    }
    if (matches.length === 1) pending.push(file);
  }
  if (pending.length > 0) {
    throw new Error(
      label +
        ": source-owner modularity repairs require sequential implementation and fresh gates: " +
        pending.join(", ")
    );
  }
}

const MODULARITY_FAMILY_REVALIDATED_VALUE =
  RUN_DATE + " — eight source-owner modularity repairs and exact gates passed.";
const MODULARITY_FAMILY_REVALIDATED_SUFFIXES = Object.freeze([
  "eight source-owner modularity repairs and exact gates passed.",
  "eight source-owner modularity repairs and their then-exact gates passed. This remains split/line evidence only and does not gate the current L03 overflow repair.",
]);

function isCanonicalModularityFamilyRevalidation(value) {
  if (typeof value !== "string") return false;
  const separator = value.indexOf(" — ");
  if (separator < 0) return false;
  const date = value.slice(0, separator);
  const evidence = value.slice(separator + 3);
  try {
    requireCanonicalReceiptDate(date, "TASK-540 modularity family revalidation");
  } catch {
    return false;
  }
  return MODULARITY_FAMILY_REVALIDATED_SUFFIXES.includes(evidence);
}

function pendingTask540ModularityFamilyStates(states) {
  return states.filter(
    ({ source, staleField }) =>
      Boolean(readTaskMetadataField(source, staleField)) ||
      !isCanonicalModularityFamilyRevalidation(
        readTaskMetadataField(source, "Modularity Repair Revalidated")
      )
  );
}

async function synchronizeTask540ModularityFamilyMetadata() {
  const closureParentPath = LEAF_STATUS_GROUPS["540-06-L01"].childPath;
  const closureLeafPath = LEAF_STATUS_GROUPS["540-06-L01"].leafPath;
  const specs = Object.freeze([
    Object.freeze({
      relativePath: ROOT_TASK_PATH,
      staleField: "Modularity Repair Started",
    }),
    Object.freeze({
      relativePath: closureParentPath,
      staleField: "Modularity Repair Pending",
    }),
    Object.freeze({
      relativePath: closureLeafPath,
      staleField: "Modularity Repair Pending",
    }),
  ]);
  const states = await Promise.all(
    specs.map(async (spec) =>
      Object.freeze({ ...spec, ...(await readCanonicalTaskStatus(spec.relativePath)) })
    )
  );
  const pendingStates = pendingTask540ModularityFamilyStates(states);
  if (pendingStates.length === 0) return;
  const owner = Object.freeze({
    id: "task-540-modularity-family-metadata",
    allowedFiles: Object.freeze(pendingStates.map(({ relativePath }) => relativePath)),
    requiredFiles: Object.freeze(pendingStates.map(({ relativePath }) => relativePath)),
    taskContractMutations: Object.freeze(
      pendingStates.map(({ relativePath, staleField }) =>
        Object.freeze({
          relativePath,
          tableTaskIds: [],
          mutableFields: Object.freeze([staleField, "Modularity Repair Revalidated"]),
        })
      )
    ),
  });
  await runMutatingAgent(
    "Repository " +
      ROOT +
      ". Synchronize TASK-540 modularity metadata after all " +
      MODULARITY_REPAIR_LEAF_IDS.length +
      " sequential source-owner gates. " +
      "Edit only " +
      JSON.stringify(owner.allowedFiles) +
      ". Preserve every status, table row, historical receipt, closure receipt, task body, board, " +
      "changelog, source, test, workflow, stage, and commit byte-identically except these exact " +
      "metadata fields. For every listed path remove its Modularity Repair Started or Modularity " +
      "Repair Pending field, whichever is present. On every listed path write exact `**Modularity Repair Revalidated:** " +
      MODULARITY_FAMILY_REVALIDATED_VALUE +
      "`. Never stage or commit.",
    { label: "task-540-modularity-family-metadata", phase: "Start gate" },
    owner
  );
  await requireTask540ModularityFamilyMetadata(
    "TASK-540 modularity family metadata synchronization"
  );
}

async function requireTask540ModularityFamilyMetadata(label) {
  const paths = [
    ROOT_TASK_PATH,
    LEAF_STATUS_GROUPS["540-06-L01"].childPath,
    LEAF_STATUS_GROUPS["540-06-L01"].leafPath,
  ];
  for (const relativePath of paths) {
    const { source } = await readCanonicalTaskStatus(relativePath);
    if (
      readTaskMetadataField(source, "Modularity Repair Pending") ||
      readTaskMetadataField(source, "Modularity Repair Started") ||
      !isCanonicalModularityFamilyRevalidation(
        readTaskMetadataField(source, "Modularity Repair Revalidated")
      )
    ) {
      throw new Error(label + ": TASK-540 modularity family metadata is not revalidated");
    }
  }
}

async function taskStatusState() {
  const rows = [];
  for (const file of TASK_FILES) {
    const { bytes } = await readStableRegularFile(
      TASKS + "/" + file,
      "TASK-540 grounded task status",
      8 * 1024 * 1024
    );
    const source = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    const status = source.match(/^\*\*Status:\*\*\s*(.+)$/m)?.[1] ?? "<missing>";
    rows.push(
      Object.freeze({
        file,
        status,
        byteLength: bytes.length,
        sha256: createHash("sha256").update(bytes).digest("hex"),
      })
    );
  }
  return Object.freeze(rows);
}

const GROUNDED_TASK_STATUS_PATHS = Object.freeze(TASK_FILES.map((file) => "_docs/_TASKS/" + file));

function sameGroundedFileStat(left, right) {
  return (
    left.dev === right.dev &&
    left.ino === right.ino &&
    left.mode === right.mode &&
    left.size === right.size &&
    left.mtimeNs === right.mtimeNs &&
    left.ctimeNs === right.ctimeNs
  );
}

function isNonNegotiableSensitiveGroundedPath(relativePath) {
  return (
    /(?:^|\/)\.env[^/]*(?:\/|$)/iu.test(relativePath) ||
    /(?:^|\/)\.git(?:\/|$)/u.test(relativePath) ||
    SENSITIVE_ENV_KEY_PATTERN.test(relativePath) ||
    hasSensitiveEvidence(relativePath)
  );
}

function hasSensitiveGroundedFilenameHeuristic(relativePath) {
  return /(?:credential|password|private[_-]?key|secret|session|token)/iu.test(relativePath);
}

function isSensitiveGroundedPath(relativePath) {
  return (
    isNonNegotiableSensitiveGroundedPath(relativePath) ||
    hasSensitiveGroundedFilenameHeuristic(relativePath)
  );
}

function isDeclaredTask540GroundedPath(relativePath) {
  return LEAVES.some(({ allowedFiles }) => allowedFiles.includes(relativePath));
}

function isDeclaredRouteSessionComponentFalsePositive(relativePath, declared) {
  return declared && /(?:^|\/)CustomScreen(?:Entry|Editor)RouteSession\.tsx$/u.test(relativePath);
}

function isUnsafeGroundedRepositoryPathWithDeclaration(relativePath, declared) {
  return (
    isNonNegotiableSensitiveGroundedPath(relativePath) ||
    (hasSensitiveGroundedFilenameHeuristic(relativePath) &&
      !isDeclaredRouteSessionComponentFalsePositive(relativePath, declared))
  );
}

function isUnsafeGroundedRepositoryPath(relativePath) {
  return isUnsafeGroundedRepositoryPathWithDeclaration(
    relativePath,
    isDeclaredTask540GroundedPath(relativePath)
  );
}

function canonicalGroundedJson(value) {
  if (value === null || typeof value === "string" || typeof value === "boolean") {
    return JSON.stringify(value);
  }
  if (typeof value === "number") {
    if (!Number.isSafeInteger(value)) {
      throw new Error("TASK-540 grounded manifest contains a non-canonical number");
    }
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) return "[" + value.map(canonicalGroundedJson).join(",") + "]";
  if (!value || typeof value !== "object" || Object.getPrototypeOf(value) !== Object.prototype) {
    throw new Error("TASK-540 grounded manifest contains a non-canonical value");
  }
  return (
    "{" +
    Object.keys(value)
      .sort()
      .map((key) => JSON.stringify(key) + ":" + canonicalGroundedJson(value[key]))
      .join(",") +
    "}"
  );
}

function groundedProjectionSha256(value) {
  return createHash("sha256").update(canonicalGroundedJson(value)).digest("hex");
}

function decodeGroundedNulProjection(bytes, label) {
  if (!Buffer.isBuffer(bytes)) throw new Error(label + ": Git projection is not bytes");
  if (bytes.length === 0) return Object.freeze([]);
  if (bytes.at(-1) !== 0) throw new Error(label + ": Git projection is not NUL terminated");
  let source;
  try {
    source = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    throw new Error(label + ": Git projection is not canonical UTF-8");
  }
  const tokens = source.split("\0");
  if (tokens.pop() !== "" || tokens.some((token) => token.length === 0)) {
    throw new Error(label + ": Git projection contains an ambiguous empty record");
  }
  return Object.freeze(tokens);
}

function requireGroundedRepositoryPath(relativePath, label) {
  if (
    typeof relativePath !== "string" ||
    relativePath.length === 0 ||
    Buffer.byteLength(relativePath, "utf8") > 4096 ||
    relativePath.startsWith("/") ||
    relativePath.trim() !== relativePath ||
    relativePath.normalize("NFC") !== relativePath ||
    /[\u0000-\u001f\u007f\\]/u.test(relativePath) ||
    relativePath.split("/").some((part) => part.length === 0 || part === "." || part === "..") ||
    isUnsafeGroundedRepositoryPath(relativePath)
  ) {
    throw new Error(label + ": grounded repository path is unsafe or ambiguous");
  }
  return relativePath;
}

function splitGroundedPorcelainFields(record, count, label) {
  const fields = [];
  let rest = record;
  for (let index = 0; index < count; index += 1) {
    const separator = rest.indexOf(" ");
    if (separator <= 0) throw new Error(label + ": porcelain record is truncated");
    fields.push(rest.slice(0, separator));
    rest = rest.slice(separator + 1);
  }
  if (rest.length === 0) throw new Error(label + ": porcelain path is missing");
  return Object.freeze({ fields: Object.freeze(fields), rest });
}

function parseGroundedPorcelain(bytes, label) {
  const entries = new Map();
  for (const token of decodeGroundedNulProjection(bytes, label)) {
    if (token.startsWith("? ")) {
      const path = requireGroundedRepositoryPath(token.slice(2), label);
      const previous = entries.get(path);
      if (previous?.untracked) throw new Error(label + ": duplicate untracked porcelain path");
      entries.set(path, Object.freeze({ tracked: previous?.tracked ?? null, untracked: true }));
      continue;
    }
    if (!token.startsWith("1 ")) {
      throw new Error(label + ": unsupported rename, conflict, ignored, or unknown porcelain row");
    }
    const { fields, rest: rawPath } = splitGroundedPorcelainFields(token.slice(2), 7, label);
    const [xy, sub, headMode, indexMode, worktreeMode, headBlob, indexBlob] = fields;
    const path = requireGroundedRepositoryPath(rawPath, label);
    const previous = entries.get(path);
    if (
      previous?.tracked ||
      !/^[MADT.]{2}$/u.test(xy) ||
      !/^[A-Z.]{4}$/u.test(sub) ||
      !/^[0-7]{6}$/u.test(headMode) ||
      !/^[0-7]{6}$/u.test(indexMode) ||
      !/^[0-7]{6}$/u.test(worktreeMode) ||
      !/^[0-9a-f]{40,64}$/u.test(headBlob) ||
      !/^[0-9a-f]{40,64}$/u.test(indexBlob)
    ) {
      throw new Error(label + ": malformed or duplicate ordinary porcelain row");
    }
    entries.set(
      path,
      Object.freeze({
        tracked: Object.freeze({
          stagedStatus: xy[0] === "." ? null : xy[0],
          unstagedStatus: xy[1] === "." ? null : xy[1],
          sub,
          headMode,
          indexMode,
          worktreeMode,
          headBlob,
          indexBlob,
        }),
        untracked: previous?.untracked ?? false,
      })
    );
  }
  return entries;
}

function parseGroundedNameStatus(bytes, label) {
  const tokens = decodeGroundedNulProjection(bytes, label);
  if (tokens.length % 2 !== 0) throw new Error(label + ": name/status projection is truncated");
  const entries = new Map();
  for (let index = 0; index < tokens.length; index += 2) {
    const status = tokens[index];
    const path = requireGroundedRepositoryPath(tokens[index + 1], label);
    if (!/^[MADT]$/u.test(status) || entries.has(path)) {
      throw new Error(label + ": name/status projection is unsupported or duplicated");
    }
    entries.set(path, status);
  }
  return entries;
}

function parseGroundedNumstat(bytes, label) {
  const entries = new Map();
  for (const token of decodeGroundedNulProjection(bytes, label)) {
    const first = token.indexOf("\t");
    const second = first < 0 ? -1 : token.indexOf("\t", first + 1);
    const added = first < 0 ? "" : token.slice(0, first);
    const deleted = second < 0 ? "" : token.slice(first + 1, second);
    const path = requireGroundedRepositoryPath(second < 0 ? "" : token.slice(second + 1), label);
    if (
      !/^(?:[0-9]+|-)$/u.test(added) ||
      !/^(?:[0-9]+|-)$/u.test(deleted) ||
      (added === "-") !== (deleted === "-") ||
      entries.has(path)
    ) {
      throw new Error(label + ": numstat projection is malformed or duplicated");
    }
    entries.set(path, Object.freeze({ added, deleted }));
  }
  return entries;
}

function parseGroundedHeadIdentity(bytes, wantedPaths, label) {
  const identities = new Map();
  for (const token of decodeGroundedNulProjection(bytes, label)) {
    const tab = token.indexOf("\t");
    const metadata = tab < 0 ? [] : token.slice(0, tab).split(" ");
    if (
      metadata.length !== 3 ||
      !/^[0-7]{6}$/u.test(metadata[0]) ||
      !/^(?:blob|commit)$/u.test(metadata[1]) ||
      !/^[0-9a-f]{40,64}$/u.test(metadata[2])
    ) {
      throw new Error(label + ": HEAD tree projection is malformed");
    }
    const path = token.slice(tab + 1);
    if (!wantedPaths.has(path)) continue;
    requireGroundedRepositoryPath(path, label);
    if (identities.has(path)) throw new Error(label + ": HEAD identity is duplicated");
    identities.set(path, Object.freeze({ mode: metadata[0], blob: metadata[2] }));
  }
  return identities;
}

function parseGroundedIndexIdentity(bytes, wantedPaths, label) {
  const identities = new Map();
  for (const token of decodeGroundedNulProjection(bytes, label)) {
    const tab = token.indexOf("\t");
    const metadata = tab < 0 ? [] : token.slice(0, tab).split(" ");
    if (
      metadata.length !== 3 ||
      !/^[0-7]{6}$/u.test(metadata[0]) ||
      !/^[0-9a-f]{40,64}$/u.test(metadata[1]) ||
      !/^[0-3]$/u.test(metadata[2])
    ) {
      throw new Error(label + ": index stage projection is malformed");
    }
    const path = token.slice(tab + 1);
    if (!wantedPaths.has(path)) continue;
    requireGroundedRepositoryPath(path, label);
    if (metadata[2] !== "0" || identities.has(path)) {
      throw new Error(label + ": index identity is conflicted or duplicated");
    }
    identities.set(path, Object.freeze({ mode: metadata[0], blob: metadata[1] }));
  }
  return identities;
}

function sameGroundedIdentity(left, right) {
  return left === null
    ? right === null
    : right !== null && left.mode === right.mode && left.blob === right.blob;
}

function groundedGitMode(worktree) {
  if (worktree.kind === "missing") return "000000";
  if (worktree.kind === "symlink") return "120000";
  return (worktree.mode & 0o111) === 0 ? "100644" : "100755";
}

function requireSameGroundedPathSet(left, right, label) {
  const leftPaths = [...left].sort();
  const rightPaths = [...right].sort();
  if (JSON.stringify(leftPaths) !== JSON.stringify(rightPaths)) {
    throw new Error(label + ": independent path projections disagree");
  }
}

function safeGroundedLaneProjection(lane, path, status, numstat, patch, head, index, worktree) {
  return Object.freeze({
    status,
    numstat,
    safePatchSha256: groundedProjectionSha256({
      lane,
      path,
      status,
      numstat,
      wholePatchSha256: patch.sha256,
      head,
      index,
      worktree,
    }),
  });
}

function reconcileGroundedChangeRecords(projection, label) {
  const {
    porcelain,
    stagedNames,
    stagedNumstat,
    unstagedNames,
    unstagedNumstat,
    untrackedPaths,
    snapshotPaths,
    headIdentities,
    indexIdentities,
    worktreeEntries,
    patches,
  } = projection;
  requireSameGroundedPathSet(stagedNames.keys(), stagedNumstat.keys(), label + " staged");
  requireSameGroundedPathSet(unstagedNames.keys(), unstagedNumstat.keys(), label + " unstaged");
  const porcelainStaged = [...porcelain]
    .filter(([, entry]) => entry.tracked?.stagedStatus)
    .map(([path]) => path);
  const porcelainUnstaged = [...porcelain]
    .filter(([, entry]) => entry.tracked?.unstagedStatus)
    .map(([path]) => path);
  const porcelainUntracked = [...porcelain]
    .filter(([, entry]) => entry.untracked)
    .map(([path]) => path);
  requireSameGroundedPathSet(porcelainStaged, stagedNames.keys(), label + " staged status");
  requireSameGroundedPathSet(porcelainUnstaged, unstagedNames.keys(), label + " unstaged status");
  requireSameGroundedPathSet(porcelainUntracked, untrackedPaths, label + " untracked status");
  const completeUnion = new Set([
    ...porcelain.keys(),
    ...stagedNames.keys(),
    ...unstagedNames.keys(),
    ...untrackedPaths,
    ...snapshotPaths,
  ]);
  requireSameGroundedPathSet(completeUnion, porcelain.keys(), label + " complete union");
  requireSameGroundedPathSet(completeUnion, worktreeEntries.keys(), label + " worktree union");
  const records = [];
  for (const path of [...completeUnion].sort()) {
    const state = porcelain.get(path);
    const tracked = state.tracked;
    const head = headIdentities.get(path) ?? null;
    const index = indexIdentities.get(path) ?? null;
    const worktree = worktreeEntries.get(path);
    if (
      !state ||
      !worktree ||
      (tracked && (stagedNames.get(path) ?? null) !== tracked.stagedStatus) ||
      (tracked && (unstagedNames.get(path) ?? null) !== tracked.unstagedStatus)
    ) {
      throw new Error(label + ": status projection disagrees at " + path);
    }
    if (tracked) {
      const porcelainHead = /^0+$/u.test(tracked.headMode)
        ? null
        : Object.freeze({ mode: tracked.headMode, blob: tracked.headBlob });
      const porcelainIndex = /^0+$/u.test(tracked.indexMode)
        ? null
        : Object.freeze({ mode: tracked.indexMode, blob: tracked.indexBlob });
      if (
        !sameGroundedIdentity(head, porcelainHead) ||
        !sameGroundedIdentity(index, porcelainIndex) ||
        (!state.untracked && groundedGitMode(worktree) !== tracked.worktreeMode) ||
        (state.untracked && tracked.worktreeMode !== "000000")
      ) {
        throw new Error(label + ": HEAD/index/worktree identity disagrees at " + path);
      }
    } else if (head !== null || index !== null) {
      throw new Error(label + ": untracked path unexpectedly has a HEAD/index identity");
    }
    const staged = tracked?.stagedStatus
      ? safeGroundedLaneProjection(
          "staged",
          path,
          tracked.stagedStatus,
          stagedNumstat.get(path),
          patches.headToIndex,
          head,
          index,
          worktree
        )
      : null;
    const unstaged = tracked?.unstagedStatus
      ? safeGroundedLaneProjection(
          "unstaged",
          path,
          tracked.unstagedStatus,
          unstagedNumstat.get(path),
          patches.indexToWorktree,
          head,
          index,
          worktree
        )
      : null;
    const untracked = state.untracked
      ? Object.freeze({
          kind: worktree.kind,
          safePatchSha256: groundedProjectionSha256({
            lane: "untracked",
            path,
            worktree,
            wholePatchSha256: patches.headToWorktree.sha256,
          }),
        })
      : null;
    records.push(Object.freeze({ path, staged, unstaged, untracked, head, index, worktree }));
  }
  return Object.freeze(records);
}

function projectSanitizedGroundedPatch(bytes, label) {
  if (!Buffer.isBuffer(bytes) || bytes.length > MAX_GROUNDED_DIFF_BYTES) {
    throw new Error(label + ": raw patch exceeds its scan bound");
  }
  let source;
  try {
    source = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    throw new Error(label + ": raw patch is not canonical UTF-8");
  }
  const sanitized = sanitizeSensitiveEvidence(source);
  const safeBytes = Buffer.from(sanitized, "utf8");
  return Object.freeze({
    byteLength: safeBytes.length,
    sha256: createHash("sha256").update(safeBytes).digest("hex"),
  });
}

function groundedPhysicalMode(info) {
  return Number(info.mode & 0o7777n);
}

async function captureGroundedWorktreeEntries(paths, untrackedPaths, label) {
  const entries = new Map();
  let untrackedTextBytes = 0;
  for (const relativePath of [...paths].sort()) {
    const absolutePath = ROOT + "/" + relativePath;
    let before;
    try {
      before = await lstat(absolutePath, { bigint: true });
    } catch (error) {
      if (error?.code !== "ENOENT") throw error;
      entries.set(
        relativePath,
        Object.freeze({ kind: "missing", mode: null, byteLength: 0, sha256: null })
      );
      continue;
    }
    if (before.isSymbolicLink()) {
      const linkValue = await readlink(absolutePath);
      const after = await lstat(absolutePath, { bigint: true });
      if (
        !sameGroundedFileStat(before, after) ||
        linkValue.startsWith("/") ||
        linkValue.includes("\0") ||
        linkValue.split("/").includes("..") ||
        isSensitiveGroundedPath(linkValue) ||
        hasSensitiveEvidence(linkValue)
      ) {
        throw new Error(label + ": grounded symlink changed or is unsafe");
      }
      const linkBytes = Buffer.from(linkValue, "utf8");
      entries.set(
        relativePath,
        Object.freeze({
          kind: "symlink",
          mode: groundedPhysicalMode(after),
          byteLength: linkBytes.length,
          sha256: createHash("sha256").update(linkBytes).digest("hex"),
        })
      );
      continue;
    }
    if (!before.isFile()) throw new Error(label + ": grounded worktree entry is unsupported");
    const maxBytes = untrackedPaths.has(relativePath)
      ? MAX_GROUNDED_UNTRACKED_FILE_BYTES
      : 64 * 1024 * 1024;
    const { bytes, stat } = await readStableRegularFile(absolutePath, label, maxBytes);
    let text = null;
    try {
      text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
      if (bytes.includes(0)) text = null;
    } catch {
      text = null;
    }
    if (untrackedPaths.has(relativePath) && text !== null) {
      untrackedTextBytes += bytes.length;
      if (untrackedTextBytes > MAX_GROUNDED_UNTRACKED_BYTES || hasSensitiveEvidence(text)) {
        throw new Error(label + ": grounded untracked text is excessive or sensitive");
      }
    }
    entries.set(
      relativePath,
      Object.freeze({
        kind: text === null ? "binary" : "text",
        mode: groundedPhysicalMode(stat),
        byteLength: bytes.length,
        sha256: createHash("sha256").update(bytes).digest("hex"),
      })
    );
  }
  return entries;
}

function safeGroundedIndexProjection(indexAuthority) {
  return Object.freeze({
    indexFile: Object.freeze({ ...indexAuthority.indexFile }),
    stageProjection: Object.freeze({ ...indexAuthority.stageProjection }),
  });
}

function requireGroundedChangeManifest(manifest, label) {
  const keys = [
    "kind",
    "version",
    "head",
    "branch",
    "patches",
    "indexProjection",
    "worktreeFingerprint",
    "taskStatuses",
    "records",
    "manifestSha256",
  ];
  if (
    !hasExactOwnStringKeys(manifest, keys) ||
    manifest.kind !== "GroundedChangeManifest" ||
    manifest.version !== 1 ||
    !/^[0-9a-f]{40,64}$/u.test(manifest.head) ||
    typeof manifest.branch !== "string" ||
    !Array.isArray(manifest.taskStatuses) ||
    manifest.taskStatuses.length !== TASK_FILES.length ||
    !Array.isArray(manifest.records) ||
    !/^[0-9a-f]{64}$/u.test(manifest.manifestSha256)
  ) {
    throw new Error(label + ": grounded change manifest shape is invalid");
  }
  const paths = manifest.records.map((record) => record?.path);
  if (
    paths.some((path) => {
      try {
        requireGroundedRepositoryPath(path, label);
        return false;
      } catch {
        return true;
      }
    }) ||
    JSON.stringify(paths) !== JSON.stringify([...new Set(paths)].sort()) ||
    manifest.taskStatuses.some(
      (row, index) =>
        row?.file !== TASK_FILES[index] ||
        typeof row.status !== "string" ||
        !Number.isSafeInteger(row.byteLength) ||
        row.byteLength < 0 ||
        !/^[0-9a-f]{64}$/u.test(row.sha256)
    )
  ) {
    throw new Error(label + ": grounded manifest paths or task statuses are non-canonical");
  }
  const { manifestSha256, ...payload } = manifest;
  if (groundedProjectionSha256(payload) !== manifestSha256) {
    throw new Error(label + ": grounded manifest hash is invalid");
  }
  return manifest;
}

async function buildLiveGroundedChangeManifest(snapshot, label) {
  const [
    headBytes,
    branchBytes,
    porcelainBytes,
    stagedNameBytes,
    stagedNumstatBytes,
    unstagedNameBytes,
    unstagedNumstatBytes,
    untrackedBytes,
    snapshotNameBytes,
    headTreeBytes,
    indexStageBytes,
    headPatchBytes,
    stagedPatchBytes,
    unstagedPatchBytes,
    taskStatuses,
  ] = await Promise.all([
    gitBytes(["rev-parse", "HEAD"]),
    gitBytes(["branch", "--show-current"]),
    gitBytes(["status", "--porcelain=v2", "-z", "--untracked-files=all", "--no-renames"]),
    gitBytes(["diff", "--cached", "--name-status", "-z", "--no-renames", "HEAD", "--"]),
    gitBytes(["diff", "--cached", "--numstat", "-z", "--no-renames", "HEAD", "--"]),
    gitBytes(["diff", "--name-status", "-z", "--no-renames", "--"]),
    gitBytes(["diff", "--numstat", "-z", "--no-renames", "--"]),
    gitBytes(["ls-files", "--others", "--exclude-standard", "-z"]),
    gitBytes(["diff", "--name-only", "-z", "--no-renames", "HEAD", "--"]),
    gitBytes(["ls-tree", "-r", "-z", "--full-tree", "HEAD"]),
    gitBytes(["ls-files", "--stage", "-z"]),
    gitBytes(["diff", "--no-renames", "--text", "--unified=3", "HEAD", "--"]),
    gitBytes(["diff", "--cached", "--no-renames", "--text", "--unified=3", "HEAD", "--"]),
    gitBytes(["diff", "--no-renames", "--text", "--unified=3", "--"]),
    taskStatusState(),
  ]);
  const decodeLine = (bytes, description) => {
    let value;
    try {
      value = new TextDecoder("utf-8", { fatal: true }).decode(bytes).trim();
    } catch {
      throw new Error(label + ": " + description + " is not canonical UTF-8");
    }
    return value;
  };
  const head = decodeLine(headBytes, "HEAD");
  const branch = decodeLine(branchBytes, "branch");
  if (
    head !== snapshot.head ||
    branch !== snapshot.branch ||
    sanitizeSensitiveEvidence(branch) !== branch
  ) {
    throw new Error(label + ": HEAD or branch disagrees with repository authority");
  }
  const porcelain = parseGroundedPorcelain(porcelainBytes, label + " porcelain");
  const stagedNames = parseGroundedNameStatus(stagedNameBytes, label + " staged names");
  const stagedNumstat = parseGroundedNumstat(stagedNumstatBytes, label + " staged numstat");
  const unstagedNames = parseGroundedNameStatus(unstagedNameBytes, label + " unstaged names");
  const unstagedNumstat = parseGroundedNumstat(unstagedNumstatBytes, label + " unstaged numstat");
  const untrackedList = decodeGroundedNulProjection(untrackedBytes, label + " untracked").map(
    (path) => requireGroundedRepositoryPath(path, label + " untracked")
  );
  if (untrackedList.length > 256 || new Set(untrackedList).size !== untrackedList.length) {
    throw new Error(label + ": untracked projection is excessive or duplicated");
  }
  const untrackedPaths = new Set(untrackedList);
  const snapshotPathList = decodeGroundedNulProjection(
    snapshotNameBytes,
    label + " snapshot names"
  ).map((path) => requireGroundedRepositoryPath(path, label + " snapshot names"));
  const snapshotPaths = new Set(snapshotPathList);
  if (snapshotPaths.size !== snapshotPathList.length) {
    throw new Error(label + ": snapshot path projection is duplicated");
  }
  const completeUnion = new Set([
    ...porcelain.keys(),
    ...stagedNames.keys(),
    ...unstagedNames.keys(),
    ...untrackedPaths,
    ...snapshotPaths,
  ]);
  const headIdentities = parseGroundedHeadIdentity(
    headTreeBytes,
    completeUnion,
    label + " HEAD identities"
  );
  const indexIdentities = parseGroundedIndexIdentity(
    indexStageBytes,
    completeUnion,
    label + " index identities"
  );
  const stageProjection = Object.freeze({
    byteLength: indexStageBytes.length,
    sha256: createHash("sha256").update(indexStageBytes).digest("hex"),
  });
  if (
    stageProjection.byteLength !== snapshot.indexAuthority.stageProjection.byteLength ||
    stageProjection.sha256 !== snapshot.indexAuthority.stageProjection.sha256
  ) {
    throw new Error(label + ": exact index projection changed during manifest assembly");
  }
  const worktreeEntries = await captureGroundedWorktreeEntries(
    completeUnion,
    untrackedPaths,
    label + " worktree projection"
  );
  const patches = Object.freeze({
    headToWorktree: projectSanitizedGroundedPatch(headPatchBytes, label + " HEAD patch"),
    headToIndex: projectSanitizedGroundedPatch(stagedPatchBytes, label + " staged patch"),
    indexToWorktree: projectSanitizedGroundedPatch(unstagedPatchBytes, label + " unstaged patch"),
  });
  const records = reconcileGroundedChangeRecords(
    {
      porcelain,
      stagedNames,
      stagedNumstat,
      unstagedNames,
      unstagedNumstat,
      untrackedPaths,
      snapshotPaths,
      headIdentities,
      indexIdentities,
      worktreeEntries,
      patches,
    },
    label
  );
  const fingerprint = canonicalRepositoryFingerprint(snapshot);
  const payload = {
    kind: "GroundedChangeManifest",
    version: 1,
    head,
    branch,
    patches,
    indexProjection: safeGroundedIndexProjection(snapshot.indexAuthority),
    worktreeFingerprint: Object.freeze({
      pathCount: snapshot.paths.length,
      sha256: fingerprint.worktreeSha256,
    }),
    taskStatuses,
    records,
  };
  return deepFreezeExact({ ...payload, manifestSha256: groundedProjectionSha256(payload) });
}

function requireGroundedContextProjection(context, authority, label) {
  if (!hasExactOwnStringKeys(context, ["root", "changeManifest"]) || context.root !== ROOT) {
    throw new Error(label + ": grounded context shape is invalid");
  }
  const manifest = requireGroundedChangeManifest(context.changeManifest, label);
  const serialized = JSON.stringify(context);
  if (
    Buffer.byteLength(serialized, "utf8") > MAX_GROUNDED_CONTEXT_BYTES ||
    groundedProjectionSha256(context) !== authority.contextSha256 ||
    manifest.manifestSha256 !== authority.manifestSha256 ||
    manifest.indexProjection.indexFile.sha256 !== authority.indexFileSha256 ||
    manifest.indexProjection.stageProjection.sha256 !== authority.stageProjectionSha256 ||
    manifest.worktreeFingerprint.sha256 !== authority.fingerprint.worktreeSha256
  ) {
    throw new Error(label + ": grounded context projection or authority is invalid");
  }
  return serialized;
}

async function repoContext() {
  const [before, sensitiveEnvBefore] = await Promise.all([
    worktreeSnapshot("TASK-540 grounded context before projection", GROUNDED_TASK_STATUS_PATHS),
    hashSensitiveEnvProjection(),
  ]);
  const beforeFingerprint = canonicalRepositoryFingerprint(before);
  const changeManifest = await buildLiveGroundedChangeManifest(before, "TASK-540 grounded context");
  const context = deepFreezeExact({ root: ROOT, changeManifest });
  if (hasSensitiveEvidenceDeep(context)) {
    throw new Error("TASK-540 grounded context failed value-aware redaction");
  }
  const [after, sensitiveEnvAfter] = await Promise.all([
    worktreeSnapshot("TASK-540 grounded context after projection", GROUNDED_TASK_STATUS_PATHS),
    hashSensitiveEnvProjection(),
  ]);
  const afterFingerprint = canonicalRepositoryFingerprint(after);
  if (
    !sameRepositoryFingerprint(beforeFingerprint, afterFingerprint) ||
    !equalHashMaps(sensitiveEnvBefore, sensitiveEnvAfter)
  ) {
    throw new Error("TASK-540 grounded context changed while it was assembled");
  }
  const authority = Object.freeze({
    fingerprint: afterFingerprint,
    sensitiveEnv: sensitiveEnvAfter,
    contextSha256: groundedProjectionSha256(context),
    manifestSha256: changeManifest.manifestSha256,
    indexFileSha256: after.indexAuthority.indexFile.sha256,
    stageProjectionSha256: after.indexAuthority.stageProjection.sha256,
  });
  requireGroundedContextProjection(context, authority, "TASK-540 grounded context");
  GROUNDED_CONTEXT_AUTHORITY.set(context, authority);
  return context;
}

function requireGroundedPromptBytes(prompt, label) {
  if (
    typeof prompt !== "string" ||
    prompt.length === 0 ||
    Buffer.byteLength(prompt, "utf8") > MAX_GROUNDED_PROMPT_BYTES
  ) {
    throw new Error(label + ": grounded agent prompt exceeds 128 KiB");
  }
  return prompt;
}

const READ_ONLY_AGENT_SHARED_CONTRACT =
  "Read-only authority contract: inspect the local repository without editing, staging, " +
  "committing, starting a server or browser, running smoke, fixtures, cleanup, validation, " +
  "or another agent, or accessing credentials, .env files, raw logs, or user data. Use the exact " +
  "GroundedChangeManifest below for repository identity evidence; the local orchestrator " +
  "independently revalidates HEAD, branch, index, and worktree authority. The physical-line limit is inclusive: " +
  "a file at exactly 1,000 lines passes, and only a file above 1,000 lines is a defect.";
const READ_ONLY_AGENT_RESULT_CONTRACT =
  READ_ONLY_AGENT_SHARED_CONTRACT +
  " Result-schema contract: reserve errors[] exclusively for verified blocking " +
  "contract defects. Every verified blocking defect must be listed in errors[] and requires " +
  "pass=false; never hide a blocker only in summary. When no blocking defect exists, return " +
  "pass=true with errors=[] and put non-blocking limitations or observations in summary. " +
  "Return only the pass, summary, and errors fields required by the result schema.";
const READ_ONLY_AGENT_AUDIT_CONTRACT =
  READ_ONLY_AGENT_SHARED_CONTRACT +
  " Audit-schema contract: return only findings[]. Every verified HIGH, MEDIUM, or LOW defect " +
  "must be a separate findings[] item with its required owner, area, evidence, and recommendation; " +
  "never hide a defect outside findings[]. When no defect exists, return findings=[]. Do not " +
  "return pass, errors, or summary fields because the audit schema forbids them.";

function composeReadOnlyAgentPrompt(body, label, schema) {
  if (typeof body !== "string" || body.length === 0 || typeof label !== "string") {
    throw new Error(label + ": read-only agent prompt body is invalid");
  }
  const contract =
    schema === RESULT_SCHEMA
      ? READ_ONLY_AGENT_RESULT_CONTRACT
      : schema === AUDIT_SCHEMA
        ? READ_ONLY_AGENT_AUDIT_CONTRACT
        : null;
  if (contract === null) {
    throw new Error(label + ": read-only agent schema has no exact prompt contract");
  }
  return contract + "\n\n" + body;
}

function composeGroundedPrompt(body, serializedContext, label) {
  if (
    typeof serializedContext !== "string" ||
    Buffer.byteLength(serializedContext, "utf8") > MAX_GROUNDED_CONTEXT_BYTES
  ) {
    throw new Error(label + ": serialized grounded context exceeds 96 KiB");
  }
  return requireGroundedPromptBytes(
    body +
      "\n\nRoot-local GroundedChangeManifest captured immediately before dispatch is exact dirty " +
      "evidence, not permission to alter unrelated work. It intentionally contains no raw patch " +
      "or file bytes. Inspect current semantic state locally and verify every claim:\n" +
      serializedContext,
    label
  );
}

async function groundedPrompt(body) {
  const context = await repoContext();
  const authority = GROUNDED_CONTEXT_AUTHORITY.get(context);
  const serialized = requireGroundedContextProjection(
    context,
    authority,
    "TASK-540 grounded prompt"
  );
  const text = composeGroundedPrompt(body, serialized, "TASK-540 grounded prompt");
  return Object.freeze({ context, text });
}

async function requireGroundedContextCurrent(context, label) {
  const authority = GROUNDED_CONTEXT_AUTHORITY.get(context);
  if (!authority) throw new Error(label + ": grounded context authority is missing");
  requireGroundedContextProjection(context, authority, label);
  const [snapshot, sensitiveEnv] = await Promise.all([
    worktreeSnapshot(label + " repository snapshot", GROUNDED_TASK_STATUS_PATHS),
    hashSensitiveEnvProjection(),
  ]);
  if (
    !sameRepositoryFingerprint(authority.fingerprint, canonicalRepositoryFingerprint(snapshot)) ||
    !sameGitIndexAuthority(snapshot.indexAuthority, {
      ...snapshot.indexAuthority,
      indexFile: context.changeManifest.indexProjection.indexFile,
      stageProjection: context.changeManifest.indexProjection.stageProjection,
    }) ||
    !equalHashMaps(authority.sensitiveEnv, sensitiveEnv)
  ) {
    throw new Error(label + ": grounded context authority changed before dispatch");
  }
}

function nulFixtureBytes(tokens) {
  return Buffer.from(tokens.map((token) => token + "\0").join(""), "utf8");
}

function groundedFixtureWorktree(kind, seed, mode = 0o644) {
  if (kind === "missing") {
    return Object.freeze({ kind, mode: null, byteLength: 0, sha256: null });
  }
  const bytes = Buffer.from(seed, "utf8");
  return Object.freeze({
    kind,
    mode,
    byteLength: bytes.length,
    sha256: createHash("sha256").update(bytes).digest("hex"),
  });
}

function buildGroundedProjectionFixture() {
  const zeroBlob = "0".repeat(40);
  const blob = (character) => character.repeat(40);
  const text = (seed) => groundedFixtureWorktree("text", seed);
  const trackedRows = [
    {
      path: "fixture/add.ts",
      x: "A",
      y: ".",
      head: null,
      index: { mode: "100644", blob: blob("1") },
      worktree: text("add"),
      snapshot: true,
    },
    {
      path: "fixture/cancellation.ts",
      x: "A",
      y: "D",
      head: null,
      index: { mode: "100644", blob: blob("2") },
      worktree: groundedFixtureWorktree("missing", ""),
      snapshot: false,
    },
    {
      path: "fixture/delete.ts",
      x: "D",
      y: ".",
      head: { mode: "100644", blob: blob("3") },
      index: null,
      worktree: groundedFixtureWorktree("missing", ""),
      snapshot: true,
    },
    {
      path: "fixture/mm.ts",
      x: "M",
      y: "M",
      head: { mode: "100644", blob: blob("4") },
      index: { mode: "100644", blob: blob("5") },
      worktree: text("mm"),
      snapshot: true,
    },
    {
      path: "fixture/staged-only.ts",
      x: "M",
      y: ".",
      head: { mode: "100644", blob: blob("6") },
      index: { mode: "100644", blob: blob("7") },
      worktree: text("staged"),
      snapshot: true,
    },
    {
      path: "fixture/type.ts",
      x: "T",
      y: ".",
      head: { mode: "100644", blob: blob("8") },
      index: { mode: "120000", blob: blob("9") },
      worktree: groundedFixtureWorktree("symlink", "relative-module.ts", 0o777),
      snapshot: true,
    },
    {
      path: "fixture/unstaged-only.ts",
      x: ".",
      y: "M",
      head: { mode: "100644", blob: blob("a") },
      index: { mode: "100644", blob: blob("a") },
      worktree: text("unstaged"),
      snapshot: true,
    },
  ];
  const untrackedRows = [
    ["fixture/untracked-binary.bin", groundedFixtureWorktree("binary", "binary\0fixture")],
    ["fixture/untracked-link", groundedFixtureWorktree("symlink", "relative-target", 0o777)],
    ["fixture/untracked-text.ts", text("untracked text")],
  ];
  const porcelainTokens = trackedRows.map(({ path, x, y, head, index, worktree }) =>
    [
      "1",
      x + y,
      "N...",
      head?.mode ?? "000000",
      index?.mode ?? "000000",
      groundedGitMode(worktree),
      head?.blob ?? zeroBlob,
      index?.blob ?? zeroBlob,
      path,
    ].join(" ")
  );
  porcelainTokens.push(...untrackedRows.map(([path]) => "? " + path));
  const laneTokens = (lane) =>
    trackedRows.filter((row) => row[lane] !== ".").flatMap((row) => [row[lane], row.path]);
  const numstatTokens = (lane) =>
    trackedRows
      .filter((row) => row[lane] !== ".")
      .map((row) => (row.worktree.kind === "binary" ? "-\t-\t" : "1\t1\t") + row.path);
  const completePaths = new Set([
    ...trackedRows.map(({ path }) => path),
    ...untrackedRows.map(([path]) => path),
  ]);
  const headTreeTokens = trackedRows
    .filter(({ head }) => head)
    .map(({ path, head }) => head.mode + " blob " + head.blob + "\t" + path);
  const indexTokens = trackedRows
    .filter(({ index }) => index)
    .map(({ path, index }) => index.mode + " " + index.blob + " 0\t" + path);
  const porcelain = parseGroundedPorcelain(
    nulFixtureBytes(porcelainTokens),
    "TASK-540 grounded porcelain fixture"
  );
  const stagedNames = parseGroundedNameStatus(
    nulFixtureBytes(laneTokens("x")),
    "TASK-540 grounded staged fixture"
  );
  const stagedNumstat = parseGroundedNumstat(
    nulFixtureBytes(numstatTokens("x")),
    "TASK-540 grounded staged numstat fixture"
  );
  const unstagedNames = parseGroundedNameStatus(
    nulFixtureBytes(laneTokens("y")),
    "TASK-540 grounded unstaged fixture"
  );
  const unstagedNumstat = parseGroundedNumstat(
    nulFixtureBytes(numstatTokens("y")),
    "TASK-540 grounded unstaged numstat fixture"
  );
  const untrackedPaths = new Set(untrackedRows.map(([path]) => path));
  const snapshotPaths = new Set(
    trackedRows.filter(({ snapshot }) => snapshot).map(({ path }) => path)
  );
  const headIdentities = parseGroundedHeadIdentity(
    nulFixtureBytes(headTreeTokens),
    completePaths,
    "TASK-540 grounded HEAD fixture"
  );
  const indexIdentities = parseGroundedIndexIdentity(
    nulFixtureBytes(indexTokens),
    completePaths,
    "TASK-540 grounded index fixture"
  );
  const worktreeEntries = new Map([
    ...trackedRows.map(({ path, worktree }) => [path, worktree]),
    ...untrackedRows,
  ]);
  const patches = Object.freeze({
    headToWorktree: projectSanitizedGroundedPatch(
      Buffer.from("fixture HEAD patch\n"),
      "TASK-540 grounded fixture"
    ),
    headToIndex: projectSanitizedGroundedPatch(
      Buffer.from("fixture staged patch\n"),
      "TASK-540 grounded fixture"
    ),
    indexToWorktree: projectSanitizedGroundedPatch(
      Buffer.from("fixture unstaged patch\n"),
      "TASK-540 grounded fixture"
    ),
  });
  return Object.freeze({
    projection: {
      porcelain,
      stagedNames,
      stagedNumstat,
      unstagedNames,
      unstagedNumstat,
      untrackedPaths,
      snapshotPaths,
      headIdentities,
      indexIdentities,
      worktreeEntries,
      patches,
    },
    records: reconcileGroundedChangeRecords(
      {
        porcelain,
        stagedNames,
        stagedNumstat,
        unstagedNames,
        unstagedNumstat,
        untrackedPaths,
        snapshotPaths,
        headIdentities,
        indexIdentities,
        worktreeEntries,
        patches,
      },
      "TASK-540 grounded projection fixture"
    ),
  });
}

async function assertGroundedChangeManifestContract(context) {
  const label = "TASK-540 grounded manifest self-test";
  const authority = GROUNDED_CONTEXT_AUTHORITY.get(context);
  if (!authority) throw new Error(label + ": live authority is missing");
  const manifest = requireGroundedChangeManifest(context.changeManifest, label);
  const serialized = requireGroundedContextProjection(context, authority, label);
  const readOnlyResultPrompt = composeReadOnlyAgentPrompt(
    "Read-only live TASK-540 grounded-manifest diagnostic.",
    label,
    RESULT_SCHEMA
  );
  const prompt = composeGroundedPrompt(readOnlyResultPrompt, serialized, label);
  const readOnlyResultContractPass =
    readOnlyResultPrompt.startsWith(READ_ONLY_AGENT_RESULT_CONTRACT + "\n\n") &&
    readOnlyResultPrompt.endsWith("Read-only live TASK-540 grounded-manifest diagnostic.") &&
    readOnlyResultPrompt.includes("pass=true with errors=[]") &&
    readOnlyResultPrompt.includes("requires pass=false") &&
    readOnlyResultPrompt.includes("never hide a blocker only in summary") &&
    readOnlyResultPrompt.includes("exactly 1,000 lines passes") &&
    readOnlyResultPrompt.includes("without editing, staging") &&
    !readOnlyResultPrompt.includes("bounded tool set");
  const readOnlyAuditPrompt = composeReadOnlyAgentPrompt(
    "Read-only audit-contract fixture body.",
    label,
    AUDIT_SCHEMA
  );
  const readOnlyAuditGroundedPrompt = composeGroundedPrompt(readOnlyAuditPrompt, serialized, label);
  const readOnlyAuditContractPass =
    readOnlyAuditPrompt.startsWith(READ_ONLY_AGENT_AUDIT_CONTRACT + "\n\n") &&
    readOnlyAuditPrompt.endsWith("Read-only audit-contract fixture body.") &&
    readOnlyAuditPrompt.includes("Every verified HIGH, MEDIUM, or LOW defect") &&
    readOnlyAuditPrompt.includes("return findings=[]") &&
    readOnlyAuditPrompt.includes("Do not return pass, errors, or summary fields") &&
    !readOnlyAuditPrompt.includes("pass=true with errors=[]") &&
    Buffer.byteLength(readOnlyAuditGroundedPrompt, "utf8") < MAX_GROUNDED_PROMPT_BYTES;
  let unknownReadOnlySchemaRejected = false;
  try {
    composeReadOnlyAgentPrompt("unknown-schema fixture", label, Object.freeze({}));
  } catch {
    unknownReadOnlySchemaRejected = true;
  }
  const readOnlyResultMatrixPass =
    resultPassed({ pass: true, summary: "warning only", errors: [] }) &&
    !resultPassed({ pass: true, summary: "incoherent blocker", errors: ["blocking defect"] }) &&
    !resultPassed({ pass: false, summary: "blocking", errors: ["blocking defect"] }) &&
    !resultPassed({ pass: false, summary: "incoherent empty failure", errors: [] });
  const fixture = buildGroundedProjectionFixture();
  const byPath = new Map(fixture.records.map((record) => [record.path, record]));
  const fixturePass =
    byPath.get("fixture/staged-only.ts")?.staged !== null &&
    byPath.get("fixture/staged-only.ts")?.unstaged === null &&
    byPath.get("fixture/unstaged-only.ts")?.staged === null &&
    byPath.get("fixture/unstaged-only.ts")?.unstaged !== null &&
    byPath.get("fixture/mm.ts")?.staged !== null &&
    byPath.get("fixture/mm.ts")?.unstaged !== null &&
    byPath.get("fixture/cancellation.ts")?.staged?.status === "A" &&
    byPath.get("fixture/cancellation.ts")?.unstaged?.status === "D" &&
    byPath.get("fixture/add.ts")?.head === null &&
    byPath.get("fixture/delete.ts")?.index === null &&
    byPath.get("fixture/type.ts")?.index?.mode === "120000" &&
    byPath.get("fixture/untracked-text.ts")?.untracked?.kind === "text" &&
    byPath.get("fixture/untracked-binary.bin")?.untracked?.kind === "binary" &&
    byPath.get("fixture/untracked-link")?.untracked?.kind === "symlink";
  if (!fixturePass) throw new Error(label + ": pure staged/unstaged/kind fixtures failed");

  const fixtureMutations = [
    {
      name: "staged numstat omission",
      mutate(projection) {
        projection.stagedNumstat = new Map(projection.stagedNumstat);
        projection.stagedNumstat.delete("fixture/add.ts");
      },
    },
    {
      name: "unstaged status disagreement",
      mutate(projection) {
        projection.unstagedNames = new Map(projection.unstagedNames);
        projection.unstagedNames.set("fixture/mm.ts", "D");
      },
    },
    {
      name: "snapshot path omission from porcelain",
      mutate(projection) {
        projection.porcelain = new Map(projection.porcelain);
        projection.porcelain.delete("fixture/type.ts");
      },
    },
  ];
  let fixtureMutationRejections = 0;
  for (const { name, mutate } of fixtureMutations) {
    const projection = { ...fixture.projection };
    mutate(projection);
    try {
      reconcileGroundedChangeRecords(projection, label + " " + name);
    } catch {
      fixtureMutationRejections += 1;
    }
  }
  let duplicateProjectionRejected = false;
  try {
    parseGroundedNameStatus(
      nulFixtureBytes(["M", "fixture/duplicate.ts", "M", "fixture/duplicate.ts"]),
      label + " duplicate"
    );
  } catch {
    duplicateProjectionRejected = true;
  }
  if (fixtureMutationRejections !== fixtureMutations.length || !duplicateProjectionRejected) {
    throw new Error(label + ": projection disagreement mutation escaped");
  }

  const manifestMutations = [
    ["record collection type", (copy) => (copy.changeManifest.records = {})],
    [
      "task status duplicate",
      (copy) => copy.changeManifest.taskStatuses.push(copy.changeManifest.taskStatuses[0]),
    ],
    ["task status reorder", (copy) => copy.changeManifest.taskStatuses.reverse()],
    ["patch byte length", (copy) => (copy.changeManifest.patches.headToWorktree.byteLength += 1)],
    ["manifest hash", (copy) => (copy.changeManifest.manifestSha256 = "0".repeat(64))],
    ["task status", (copy) => (copy.changeManifest.taskStatuses[0].status += " tampered")],
    [
      "index projection",
      (copy) => (copy.changeManifest.indexProjection.stageProjection.sha256 = "0".repeat(64)),
    ],
    [
      "worktree fingerprint",
      (copy) => (copy.changeManifest.worktreeFingerprint.sha256 = "0".repeat(64)),
    ],
  ];
  let manifestMutationRejections = 0;
  for (const [name, mutate] of manifestMutations) {
    const copy = JSON.parse(JSON.stringify(context));
    mutate(copy);
    try {
      requireGroundedContextProjection(copy, authority, label + " " + name);
    } catch {
      manifestMutationRejections += 1;
    }
  }
  if (manifestMutationRejections !== manifestMutations.length) {
    throw new Error(label + ": manifest tamper mutation escaped");
  }
  let missingOpaqueAuthorityRejected = false;
  try {
    await requireGroundedContextCurrent(JSON.parse(JSON.stringify(context)), label);
  } catch {
    missingOpaqueAuthorityRejected = true;
  }
  if (!missingOpaqueAuthorityRejected) {
    throw new Error(label + ": copied context acquired opaque dispatch authority");
  }

  const { manifestSha256, ...payload } = manifest;
  const reversedPayload = Object.fromEntries(Object.entries(payload).reverse());
  const canonicalHashPass =
    groundedProjectionSha256(payload) === manifestSha256 &&
    groundedProjectionSha256(reversedPayload) === manifestSha256;
  const secretPatch = Buffer.from('+password="grounded omitted fixture secret"\n', "utf8");
  const secretProjection = projectSanitizedGroundedPatch(secretPatch, label + " secret patch");
  const sanitizedSecret = Buffer.from(sanitizeSensitiveEvidence(secretPatch.toString("utf8")));
  const secretProjectionPass =
    secretProjection.sha256 === createHash("sha256").update(sanitizedSecret).digest("hex") &&
    secretProjection.sha256 !== createHash("sha256").update(secretPatch).digest("hex") &&
    !JSON.stringify(secretProjection).includes("grounded omitted fixture secret");
  const largePatchBytes = Buffer.alloc(1024 * 1024 + 1, 0x61);
  const largePatchProjection = projectSanitizedGroundedPatch(
    largePatchBytes,
    label + " large patch"
  );
  const largePatchProjectionPass =
    largePatchProjection.byteLength === largePatchBytes.length &&
    largePatchProjection.sha256 === createHash("sha256").update(largePatchBytes).digest("hex");
  requireGroundedPromptBytes("a".repeat(MAX_GROUNDED_PROMPT_BYTES), label);
  requireGroundedPromptBytes("ą".repeat(MAX_GROUNDED_PROMPT_BYTES / 2), label);
  let promptCapRejections = 0;
  for (const value of [
    "a".repeat(MAX_GROUNDED_PROMPT_BYTES + 1),
    "a".repeat(MAX_GROUNDED_PROMPT_BYTES - 1) + "ą",
  ]) {
    try {
      requireGroundedPromptBytes(value, label);
    } catch {
      promptCapRejections += 1;
    }
  }
  let contextCapRejected = false;
  try {
    composeGroundedPrompt("fixture", "a".repeat(MAX_GROUNDED_CONTEXT_BYTES + 1), label);
  } catch {
    contextCapRejected = true;
  }
  const paths = manifest.records.map(({ path }) => path);
  const liveProjectionPass =
    paths.length === new Set(paths).size &&
    JSON.stringify(paths) === JSON.stringify([...paths].sort()) &&
    Buffer.byteLength(serialized, "utf8") < MAX_GROUNDED_CONTEXT_BYTES &&
    Buffer.byteLength(prompt, "utf8") < MAX_GROUNDED_PROMPT_BYTES &&
    Number.isSafeInteger(manifest.patches.headToWorktree.byteLength) &&
    manifest.patches.headToWorktree.byteLength >= 0 &&
    !serialized.includes('"diffPatch"') &&
    !serialized.includes('"content"') &&
    !serialized.includes('"target"') &&
    !hasSensitiveEvidenceDeep(context);
  if (
    !canonicalHashPass ||
    !readOnlyResultContractPass ||
    !readOnlyAuditContractPass ||
    !unknownReadOnlySchemaRejected ||
    !readOnlyResultMatrixPass ||
    !secretProjectionPass ||
    !largePatchProjectionPass ||
    promptCapRejections !== 2 ||
    !contextCapRejected ||
    !liveProjectionPass
  ) {
    throw new Error(label + ": canonical hash, secret scan, cap, or live projection failed");
  }
  return Object.freeze({
    cases: 35,
    contextBytes: Buffer.byteLength(serialized, "utf8"),
    promptBytes: Buffer.byteLength(prompt, "utf8"),
    rawHeadPatchSafeBytes: manifest.patches.headToWorktree.byteLength,
    changedPaths: manifest.records.length,
    manifestMutationRejections,
    fixtureMutationRejections: fixtureMutationRejections + 1,
  });
}

async function runReadOnlyAgent(prompt, options) {
  const [before, sensitiveEnvBefore] = await Promise.all([
    worktreeSnapshot(options.label + " before read-only dispatch"),
    hashSensitiveEnvProjection(),
  ]);
  let result = null;
  let dispatchError = null;
  try {
    result = await dispatchAgentSafely(
      await groundedPrompt(composeReadOnlyAgentPrompt(prompt, options.label, options.schema)),
      options
    );
  } catch (error) {
    dispatchError = error;
  }
  let stateError = null;
  try {
    const [after, sensitiveEnvAfter] = await Promise.all([
      worktreeSnapshot(options.label + " after read-only dispatch"),
      hashSensitiveEnvProjection(),
    ]);
    const delta = snapshotDelta(before, after);
    if (
      before.head !== after.head ||
      before.branch !== after.branch ||
      !sameGitIndexAuthority(before.indexAuthority, after.indexAuthority) ||
      !equalHashMaps(sensitiveEnvBefore, sensitiveEnvAfter) ||
      delta.length > 0
    ) {
      stateError = new Error(
        options.label + ": read-only agent changed repository state: " + delta.join(", ")
      );
    }
  } catch (error) {
    stateError = error;
  }
  if (dispatchError && stateError) {
    throw new AggregateError(
      [dispatchError, stateError],
      options.label + ": read-only dispatch failed and changed repository state"
    );
  }
  if (dispatchError) throw dispatchError;
  if (stateError) throw stateError;
  return result;
}

