async function assertTask540R01EffectiveRepairOwnerContract() {
  const leaf = LEAF_BY_ID.get("540-01-L01");
  const group = LEAF_STATUS_GROUPS["540-01-L01"];
  if (!leaf || !group) throw new Error("TASK-540 R01 effective repair owner is missing");
  const taskContracts = [ROOT_TASK_PATH, group.childPath, group.leafPath];
  const preClosure = effectiveRepairMutationOwner(leaf);
  const afterClosure = effectiveRepairMutationOwner(leaf, { afterClosure: true });
  const preClosureRollback = repairMutationRollbackPlan(
    preClosure,
    taskContracts,
    "TASK-540 R01 pre-closure rollback self-test"
  );
  const afterClosureRollback = repairMutationRollbackPlan(
    afterClosure,
    taskContracts,
    "TASK-540 R01 after-closure rollback self-test"
  );
  let partialTaskAuthorityRejected = false;
  try {
    repairMutationRollbackPlan(
      Object.freeze({
        ...preClosure,
        allowedFiles: Object.freeze([...preClosure.allowedFiles, taskContracts[0]]),
      }),
      taskContracts,
      "TASK-540 R01 partial rollback self-test"
    );
  } catch {
    partialTaskAuthorityRejected = true;
  }
  const restriction = leafRestrictionPrompt(leaf);
  const readOnlyConsumers = [
    "tests/vitest/assistant/action-plan-schema.test.ts",
    "tests/vitest/assistant/catalogBlueprintEngine.test.ts",
    "tests/vitest/customScreens/screen-document-insertion.test.ts",
    "tests/vitest/customScreens/screen-document-sections.test.ts",
  ];
  const fullMatrixReadOnlyConsumers = readOnlyConsumers.slice(0, 2);
  const namedR01CommandFiles = leaf.commands.flatMap(({ command: value }) =>
    namedTestFilesForCommand(value)
  );
  const splitFixtureSource = await readFile(
    ROOT + "/" + ASSISTANT_ACTION_EXECUTOR_FIXTURE_ONLY_PATH,
    "utf8"
  );
  const legacySplitFixtureSource = CUSTOM_SCREEN_PATCH_FIXTURE_REPLACEMENTS.reduce(
    (source, [legacy, canonical]) => {
      const canonicalCount = source.split(canonical).length - 1;
      if (canonicalCount !== 1) return "";
      return source.replace(canonical, legacy);
    },
    splitFixtureSource
  );
  const splitFixtureProjectionPass =
    legacySplitFixtureSource.length > 0 &&
    canonicalizeCustomScreenPatchFixtureSource(splitFixtureSource) === splitFixtureSource &&
    canonicalizeCustomScreenPatchFixtureSource(legacySplitFixtureSource) === splitFixtureSource;
  const allWorkflowWritableFiles = LEAVES.flatMap(({ allowedFiles }) => allowedFiles);
  const cases = [
    {
      label: "R01 pre-closure audit fixer retains the full declared owner set",
      pass:
        !Object.hasOwn(leaf, "repairAllowedFiles") &&
        JSON.stringify(preClosure.allowedFiles) === JSON.stringify(leaf.allowedFiles),
    },
    {
      label: "R01 schema, composer, document-op, and route regressions retain mutation authority",
      pass:
        preClosure.allowedFiles.includes(
          "core/services/assistant/blueprints/blueprintBindingComposer.ts"
        ) &&
        preClosure.allowedFiles.includes("tests/vitest/admin/custom-screen-schemas.test.ts") &&
        preClosure.allowedFiles.includes(
          "tests/vitest/assistant/blueprint-binding-composer.test.ts"
        ) &&
        preClosure.allowedFiles.includes("core/services/customScreens/screenDocumentOps.ts") &&
        preClosure.allowedFiles.includes("tests/vitest/customScreens/screenDocumentOps.test.ts") &&
        namedR01CommandFiles.includes(
          "tests/vitest/assistant/blueprint-binding-composer.test.ts"
        ) &&
        TARGET_VITEST_FILES.includes("tests/vitest/assistant/blueprint-binding-composer.test.ts") &&
        SOURCE_OWNER_TEST_FILES.includes(
          "tests/vitest/assistant/blueprint-binding-composer.test.ts"
        ) &&
        namedR01CommandFiles.includes("tests/vitest/customScreens/screenDocumentOps.test.ts") &&
        preClosure.allowedFiles.includes("tests/integration/routes/customScreensRoutes.test.ts"),
    },
    {
      label: "R01 Assistant consumers have exact explicit read-only metadata",
      pass:
        JSON.stringify(leaf.readOnlyConsumerFiles) === JSON.stringify(readOnlyConsumers) &&
        readOnlyConsumers.every((file) => !allWorkflowWritableFiles.includes(file)) &&
        readOnlyConsumers.every((file) => !leaf.requiredFiles.includes(file)) &&
        readOnlyConsumers.every((file) => !preClosure.allowedFiles.includes(file)) &&
        readOnlyConsumers.every((file) => !afterClosure.allowedFiles.includes(file)),
    },
    {
      label: "R01 read-only consumers remain targeted-command and aggregate covered",
      pass:
        readOnlyConsumers.every((file) => namedR01CommandFiles.includes(file)) &&
        fullMatrixReadOnlyConsumers.every((file) => TARGET_VITEST_FILES.includes(file)) &&
        fullMatrixReadOnlyConsumers.every((file) => SOURCE_OWNER_TEST_FILES.includes(file)),
    },
    {
      label: "R01 after-closure audit fixer adds only its three task contracts",
      pass:
        JSON.stringify(afterClosure.allowedFiles) ===
        JSON.stringify([...leaf.allowedFiles, ...taskContracts]),
    },
    {
      label: "R01 pre-closure rollback protects all task authority files",
      pass:
        JSON.stringify(preClosureRollback.rollbackAuthorityPaths) ===
          JSON.stringify([...taskContracts, "_docs/_TASKS/README.md"]) &&
        JSON.stringify(preClosureRollback.allowedResidualPaths) ===
          JSON.stringify(preClosure.allowedFiles),
    },
    {
      label: "R01 after-closure rollback preserves only non-task owner residuals",
      pass:
        JSON.stringify(afterClosureRollback.rollbackAuthorityPaths) ===
          JSON.stringify([...taskContracts, "_docs/_TASKS/README.md"]) &&
        JSON.stringify(afterClosureRollback.allowedResidualPaths) ===
          JSON.stringify(leaf.allowedFiles),
    },
    {
      label: "R01 rollback rejects partial task authority",
      pass: partialTaskAuthorityRejected,
    },
    {
      label: "R01 historical Assistant executor path retains its exact fixture-only verifier",
      pass:
        JSON.stringify(leaf.fixtureOnlyFiles) ===
        JSON.stringify(["tests/unit/assistant/actionExecutorCustomScreens.test.ts"]),
    },
    {
      label: "R01 split Assistant fixture projection supports a final test at EOF",
      pass: splitFixtureProjectionPass,
    },
    {
      label: "R01 restriction is conditional instead of globally fixture-only",
      pass:
        restriction.includes("Touch that listed path only when the verified finding requires it") &&
        restriction.includes("full declared owner set") &&
        restriction.includes("dependency-shaped consumer gates are read-only") &&
        readOnlyConsumers.every((file) => restriction.includes(file)) &&
        !restriction.includes(". Change only the existing custom-screen.block.patch test"),
    },
  ];
  for (const testCase of cases) {
    if (!testCase.pass) {
      throw new Error("TASK-540 R01 effective repair owner self-test failed: " + testCase.label);
    }
  }
  return cases.length;
}

