function isCanonicalIsoDate(value) {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(value + "T00:00:00.000Z");
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

const IMPLEMENTATION_COMPLETE_SUFFIX =
  " — assigned work was completed; canonical `✅ Done` transition awaits family changelog 1252.";

function requireCanonicalReceiptDate(value, label) {
  if (!isCanonicalIsoDate(value) || value > RUN_DATE) {
    throw new Error(label + ": receipt date must be canonical and no later than " + RUN_DATE);
  }
  return value;
}

function requireCanonicalCompleted(value, label) {
  return requireCanonicalReceiptDate(value, label + " Completed");
}

function requireAbsentCompleted(value, label) {
  if (value !== null) throw new Error(label + ": Completed must be absent");
  return null;
}

function requireCanonicalImplementationComplete(value, label) {
  if (typeof value !== "string" || !value.endsWith(IMPLEMENTATION_COMPLETE_SUFFIX)) {
    throw new Error(label + ": Implementation Complete has a non-canonical suffix");
  }
  const date = value.slice(0, -IMPLEMENTATION_COMPLETE_SUFFIX.length);
  requireCanonicalReceiptDate(date, label + " Implementation Complete");
  if (value !== date + IMPLEMENTATION_COMPLETE_SUFFIX) {
    throw new Error(label + ": Implementation Complete is not byte-canonical");
  }
  return value;
}

function requireAbsentImplementationComplete(value, label) {
  if (value !== null) throw new Error(label + ": Implementation Complete must be absent");
  return null;
}

function preClosureRegateValue(fixStartedDate) {
  if (!isCanonicalIsoDate(fixStartedDate)) {
    throw new Error("TASK-540 pre-closure re-gate requires a canonical Fix Started date");
  }
  return "pre-closure remediation / fix-started " + fixStartedDate + " / gate green";
}

function matchesReservedPreClosureRegatedSourceRepair({
  resumeState,
  fixStartedDate,
  gateReceipts,
  indexKind,
  hasSharedPending,
  hasExistingChangelog,
}) {
  if (!isCanonicalIsoDate(fixStartedDate)) return false;
  const gateValue = preClosureRegateValue(fixStartedDate);
  return Boolean(
    indexKind === "reserved" &&
    !hasSharedPending &&
    !hasExistingChangelog &&
    gateReceipts.length === 1 &&
    gateReceipts[0].field === "Revalidation Passed" &&
    gateReceipts[0].value === gateValue &&
    resumeState.mode === "repair" &&
    resumeState.repair?.id &&
    resumeState.repair.id !== "540-06-L01" &&
    resumeState.startLeafId === resumeState.repair.id &&
    JSON.stringify(resumeState.remainingLeafIds) === JSON.stringify([resumeState.repair.id]) &&
    JSON.stringify(resumeState.reservedPreClosureRegatedSibling) ===
      JSON.stringify({ fixStartedDate, gateValue })
  );
}

function assertTask540ReservedPreClosureRegatedSourceRepairContract() {
  const fixStartedDate = "2026-07-15";
  const gateValue = preClosureRegateValue(fixStartedDate);
  const resumeState = Object.freeze({
    mode: "repair",
    repair: Object.freeze({ id: "540-04-L03", pending: "synthetic" }),
    startLeafId: "540-04-L03",
    remainingLeafIds: Object.freeze(["540-04-L03"]),
    reservedPreClosureRegatedSibling: Object.freeze({ fixStartedDate, gateValue }),
  });
  const gateReceipts = Object.freeze([
    Object.freeze({ field: "Revalidation Passed", value: gateValue }),
  ]);
  const base = Object.freeze({
    resumeState,
    fixStartedDate,
    gateReceipts,
    indexKind: "reserved",
    hasSharedPending: false,
    hasExistingChangelog: false,
  });
  const cases = [
    ["exact reserved source repair", base, true],
    ["consumed anchor", { ...base, indexKind: "consumed" }, false],
    ["existing changelog draft", { ...base, hasExistingChangelog: true }, false],
    ["closure pending", { ...base, hasSharedPending: true }, false],
    [
      "targeted gate field",
      { ...base, gateReceipts: [{ field: "Targeted Gate Passed", value: gateValue }] },
      false,
    ],
    [
      "wrong gate value",
      { ...base, gateReceipts: [{ field: "Revalidation Passed", value: "different" }] },
      false,
    ],
    ["child leaf date mismatch", { ...base, fixStartedDate: "2026-07-14" }, false],
    [
      "closure repair owner",
      {
        ...base,
        resumeState: { ...resumeState, repair: { id: "540-06-L01", pending: "synthetic" } },
      },
      false,
    ],
    [
      "extra remaining leaf",
      {
        ...base,
        resumeState: {
          ...resumeState,
          remainingLeafIds: ["540-04-L03", "540-06-L01"],
        },
      },
      false,
    ],
    [
      "missing prepared sibling authority",
      { ...base, resumeState: { ...resumeState, reservedPreClosureRegatedSibling: null } },
      false,
    ],
  ];
  for (const [label, input, expected] of cases) {
    if (matchesReservedPreClosureRegatedSourceRepair(input) !== expected) {
      throw new Error("TASK-540 reserved pre-closure source-repair self-test failed: " + label);
    }
  }
  return cases.length;
}

function matchingPreClosureFixStartedDate(childSource, leafSource, label) {
  const childFixStarted = readTaskMetadataField(childSource, "Fix Started");
  const leafFixStarted = readTaskMetadataField(leafSource, "Fix Started");
  if (childFixStarted === null && leafFixStarted === null) return null;
  if (
    !childFixStarted ||
    childFixStarted !== leafFixStarted ||
    !isCanonicalIsoDate(childFixStarted) ||
    childFixStarted > RUN_DATE
  ) {
    throw new Error(label + ": closure child/leaf Fix Started markers are not exact");
  }
  return childFixStarted;
}

async function readPersistedPreClosureFixStartedDate(leaf, label) {
  if (leaf.id !== "540-06-L01") return null;
  const group = LEAF_STATUS_GROUPS[leaf.id];
  if (!group) throw new Error(label + ": closure leaf status group is missing");
  const [childState, leafState] = await Promise.all([
    readCanonicalTaskStatus(group.childPath),
    readCanonicalTaskStatus(group.leafPath),
  ]);
  return matchingPreClosureFixStartedDate(childState.source, leafState.source, label);
}

const CLOSURE_GATE_FIELDS = Object.freeze(["Targeted Gate Passed", "Revalidation Passed"]);
const CLOSURE_RECEIPT_FIELDS = Object.freeze([
  "Closure Pending",
  "Closure Evidence SHA-256",
  "Closure Generation",
  "Closure Board Baseline",
  CLOSURE_CHANGELOG_PATH_FIELD,
]);

function readTaskGateReceipts(source) {
  return CLOSURE_GATE_FIELDS.flatMap((field) => {
    const value = readTaskMetadataField(source, field);
    return value ? [Object.freeze({ field, value })] : [];
  });
}

function readTaskGateReceipt(source, label) {
  const receipts = readTaskGateReceipts(source);
  if (receipts.length !== 1) {
    throw new Error(label + ": task leaf must carry exactly one gate receipt");
  }
  return receipts[0];
}

function readClosureLeafGateReceipt(source, label) {
  return readTaskGateReceipt(source, label);
}

function equalClosureGateReceipts(left, right) {
  return Boolean(left && right && left.field === right.field && left.value === right.value);
}

function closureContractReceiptProjection(relativePath, source) {
  parseCanonicalTaskStatusSource(source, relativePath);
  return Object.freeze({
    relativePath,
    receipts: Object.freeze(
      Object.fromEntries(
        CLOSURE_RECEIPT_FIELDS.map((field) => [field, readTaskMetadataField(source, field)])
      )
    ),
    gates: Object.freeze(
      Object.fromEntries(
        CLOSURE_GATE_FIELDS.map((field) => [field, readTaskMetadataField(source, field)])
      )
    ),
  });
}

function captureClosureContractReceiptsFromSnapshot(snapshot, label) {
  return Object.freeze(
    closureContractPaths().map((relativePath) =>
      closureContractReceiptProjection(
        relativePath,
        requireExactRollbackSnapshotUtf8(snapshot, relativePath, label)
      )
    )
  );
}

async function captureClosureContractReceipts() {
  return Promise.all(
    closureContractPaths().map(async (relativePath) =>
      closureContractReceiptProjection(
        relativePath,
        (await readCanonicalTaskStatus(relativePath)).source
      )
    )
  );
}

async function verifyClosureContractReceipts(before, label, { allowGateChange = false } = {}) {
  const after = await captureClosureContractReceipts();
  for (let index = 0; index < before.length; index += 1) {
    const gateMayChange =
      allowGateChange && before[index].relativePath === LEAF_STATUS_GROUPS["540-06-L01"].leafPath;
    if (
      before[index].relativePath !== after[index].relativePath ||
      JSON.stringify(before[index].receipts) !== JSON.stringify(after[index].receipts) ||
      (!gateMayChange && JSON.stringify(before[index].gates) !== JSON.stringify(after[index].gates))
    ) {
      throw new Error(
        label + ": closure receipt projection changed at " + before[index].relativePath
      );
    }
  }
}

function readTaskBoardStats(source) {
  const read = (label) => {
    const matches = [
      ...source.matchAll(new RegExp("^- \\*\\*" + label + ":\\*\\* (\\d+) tasks$", "gm")),
    ];
    if (matches.length !== 1) {
      throw new Error("TASK-540 board statistic missing or duplicated: " + label);
    }
    const value = Number(matches[0][1]);
    if (!Number.isSafeInteger(value) || value < 0) {
      throw new Error("TASK-540 board statistic is invalid: " + label);
    }
    return value;
  };
  return Object.freeze({
    toDo: read("To Do"),
    inProgress: read("In Progress"),
    done: read("Done"),
  });
}

const TASK_540_BOARD_BUCKET_MARKERS = Object.freeze({
  toDo: "⏳ To Do",
  inProgress: "🚧 In progress",
  done: "✅ Done",
});

function requireTask540BoardNotesMarker(notes, bucket, label) {
  const marker = TASK_540_BOARD_BUCKET_MARKERS[bucket];
  if (!marker || (notes !== marker && !notes.startsWith(marker + " "))) {
    throw new Error(label + ": Notes must start with exact bucket marker " + marker);
  }
  return marker;
}

function readTask540BoardState(source) {
  const rows = [...source.matchAll(/^\| TASK-540 \|.*$/gm)];
  if (rows.length !== 1) throw new Error("TASK-540 board row is missing or duplicated");
  const row = rows[0][0];
  const cells = row
    .slice(1, -1)
    .split("|")
    .map((cell) => cell.trim());
  if (cells.length !== 5 || cells[0] !== "TASK-540") {
    throw new Error("TASK-540 board row must contain exactly five canonical cells");
  }
  const rowIndex = rows[0].index ?? -1;
  const headingIndex = (heading) => {
    const matches = [...source.matchAll(new RegExp("^## " + heading + "$", "gm"))];
    if (matches.length !== 1) {
      throw new Error("TASK-540 board heading is missing or duplicated: " + heading);
    }
    return matches[0].index ?? -1;
  };
  const toDoStart = headingIndex("To Do");
  const inProgressStart = headingIndex("In Progress");
  const doneStart = headingIndex("Done");
  if (!(toDoStart < inProgressStart && inProgressStart < doneStart)) {
    throw new Error("TASK-540 board headings are not in canonical order");
  }
  const bucket =
    rowIndex > toDoStart && rowIndex < inProgressStart
      ? "toDo"
      : rowIndex > inProgressStart && rowIndex < doneStart
        ? "inProgress"
        : rowIndex > doneStart
          ? "done"
          : null;
  if (!bucket) throw new Error("TASK-540 board row is outside a canonical bucket");
  const notes = cells[4];
  requireTask540BoardNotesMarker(notes, bucket, "TASK-540 board row");
  return Object.freeze({
    bucket,
    row,
    cells: Object.freeze(cells),
    notes,
    stats: readTaskBoardStats(source),
  });
}

function formatClosureBoardBaseline(stats) {
  return "toDo " + stats.toDo + " / inProgress " + stats.inProgress + " / done " + stats.done;
}

function parseClosureBoardBaseline(value, label) {
  const match = value?.match(/^toDo (\d+) \/ inProgress (\d+) \/ done (\d+)$/);
  if (!match) throw new Error(label + ": malformed Closure Board Baseline");
  const stats = { toDo: Number(match[1]), inProgress: Number(match[2]), done: Number(match[3]) };
  if (Object.values(stats).some((value) => !Number.isSafeInteger(value) || value < 0)) {
    throw new Error(label + ": invalid Closure Board Baseline");
  }
  return Object.freeze(stats);
}

function closedBoardStatsFromBaseline(baseline, label) {
  if (baseline.inProgress < 1) {
    throw new Error(label + ": Closure Board Baseline has no active TASK-540 row");
  }
  return Object.freeze({
    toDo: baseline.toDo,
    inProgress: baseline.inProgress - 1,
    done: baseline.done + 1,
  });
}

function parsePositiveClosureGeneration(value, label) {
  if (typeof value !== "string" || !/^[1-9]\d*$/.test(value)) {
    throw new Error(label + ": malformed closure generation");
  }
  const generation = Number(value);
  if (!Number.isSafeInteger(generation)) {
    throw new Error(label + ": unsafe closure generation");
  }
  return generation;
}

function parseClosurePending(value, label) {
  const match = value?.match(/^generation ([1-9]\d*) \/ ([0-9a-f]{12})$/);
  if (!match) throw new Error(label + ": malformed Closure Pending receipt");
  return Object.freeze({
    value,
    generation: parsePositiveClosureGeneration(match[1], label),
    token: match[2],
  });
}

function parseRepairPending(value, label) {
  const match = value?.match(/^generation ([0-9a-f]{32}) \/ token ([0-9a-f]{32})$/);
  if (!match) throw new Error(label + ": malformed Repair Pending receipt");
  return Object.freeze({ value, generation: match[1], token: match[2] });
}

function repairGateValue(repairPending) {
  parseRepairPending(repairPending, "TASK-540 repair gate");
  return repairPending + " / gate green";
}

function repairPendingFromGateValue(value, label) {
  const suffix = " / gate green";
  if (typeof value !== "string" || !value.endsWith(suffix)) {
    throw new Error(label + ": repaired gate value has no exact pending receipt");
  }
  const repairPending = value.slice(0, -suffix.length);
  parseRepairPending(repairPending, label);
  if (repairGateValue(repairPending) !== value) {
    throw new Error(label + ": repaired gate value is not canonical");
  }
  return repairPending;
}

function closureContractPaths() {
  return [
    ROOT_TASK_PATH,
    LEAF_STATUS_GROUPS["540-06-L01"].childPath,
    LEAF_STATUS_GROUPS["540-06-L01"].leafPath,
  ];
}

async function readSharedClosurePending({ required = false, allowMissingGate = false } = {}) {
  const states = await Promise.all(closureContractPaths().map(readCanonicalTaskStatus));
  const pendingValues = states.map(({ source }) =>
    readTaskMetadataField(source, "Closure Pending")
  );
  const boardBaselineValues = states.map(({ source }) =>
    readTaskMetadataField(source, "Closure Board Baseline")
  );
  const changelogPathValues = states.map(({ source }) =>
    readTaskMetadataField(source, CLOSURE_CHANGELOG_PATH_FIELD)
  );
  const evidenceValues = states.map(({ source }) =>
    readTaskMetadataField(source, "Closure Evidence SHA-256")
  );
  const receiptGenerationValues = states.map(({ source }) =>
    readTaskMetadataField(source, "Closure Generation")
  );
  const repairPendingValues = states.map(({ source }) =>
    readTaskMetadataField(source, "Repair Pending")
  );
  const parentGateValues = states
    .slice(0, 2)
    .flatMap(({ source }) =>
      CLOSURE_GATE_FIELDS.map((field) => readTaskMetadataField(source, field))
    );
  if (repairPendingValues[0] || repairPendingValues[1] || parentGateValues.some(Boolean)) {
    throw new Error("TASK-540 closure root/parent retained leaf-only repair or gate evidence");
  }
  for (let index = 0; index < states.length; index += 1) {
    const completed = readTaskMetadataField(states[index].source, "Completed");
    if (states[index].status === RESUME_TASK_STATUS.done) {
      requireCanonicalCompleted(completed, "TASK-540 shared closure contract " + index);
    } else {
      requireAbsentCompleted(completed, "TASK-540 shared closure contract " + index);
    }
  }
  requireAbsentImplementationComplete(
    readTaskMetadataField(states[0].source, "Implementation Complete"),
    "TASK-540 shared closure root"
  );
  const closureLeafGateCount = readTaskGateReceipts(states[2].source).length;
  const closureImplementationExpected = closureLeafGateCount === 1 && !repairPendingValues[2];
  for (const index of [1, 2]) {
    const value = readTaskMetadataField(states[index].source, "Implementation Complete");
    if (closureImplementationExpected) {
      requireCanonicalImplementationComplete(value, "TASK-540 shared closure contract " + index);
    } else {
      requireAbsentImplementationComplete(value, "TASK-540 shared closure contract " + index);
    }
  }
  if (pendingValues.every((value) => value === null)) {
    if (
      evidenceValues.some((value) => value !== null) ||
      receiptGenerationValues.some((value) => value !== null) ||
      boardBaselineValues.some((value) => value !== null) ||
      changelogPathValues.some((value) => value !== null)
    ) {
      throw new Error("TASK-540 closure-only receipt exists without a pending closure");
    }
    const closureLeafRepairPending = repairPendingValues[2];
    const closureLeafHasGate = CLOSURE_GATE_FIELDS.some((field) =>
      readTaskMetadataField(states[2].source, field)
    );
    if (closureLeafRepairPending) {
      parseRepairPending(closureLeafRepairPending, "TASK-540 pre-pending closure repair");
      if (
        !allowMissingGate ||
        closureLeafHasGate ||
        states.some(({ status }) => status !== RESUME_TASK_STATUS.active)
      ) {
        throw new Error("TASK-540 invalid Repair Pending state without Closure Pending");
      }
    }
    if (required) throw new Error("TASK-540 closure restart is missing Closure Pending");
    return null;
  }
  if (
    states.some(({ status }) => status !== RESUME_TASK_STATUS.active) ||
    !pendingValues[0] ||
    !pendingValues.every((value) => value === pendingValues[0]) ||
    !boardBaselineValues[0] ||
    !boardBaselineValues.every((value) => value === boardBaselineValues[0]) ||
    !changelogPathValues[0] ||
    !changelogPathValues.every((value) => value === changelogPathValues[0])
  ) {
    throw new Error("TASK-540 closure contracts have mismatched pending state");
  }
  const evidenceAbsent = evidenceValues.every((value) => value === null);
  const generationsAbsent = receiptGenerationValues.every((value) => value === null);
  if (evidenceAbsent !== generationsAbsent) {
    throw new Error("TASK-540 pending evidence/generation receipts are only partially absent");
  }
  if (
    !evidenceAbsent &&
    (!/^[0-9a-f]{64}$/.test(evidenceValues[0]) ||
      !evidenceValues.every((value) => value === evidenceValues[0]) ||
      !receiptGenerationValues.every((value) => value === receiptGenerationValues[0]))
  ) {
    throw new Error("TASK-540 pending evidence/generation receipts are mismatched");
  }
  const priorGeneration = evidenceAbsent
    ? null
    : parsePositiveClosureGeneration(
        receiptGenerationValues[0],
        "TASK-540 pending prior generation"
      );
  const boardBaseline = parseClosureBoardBaseline(
    boardBaselineValues[0],
    "TASK-540 closure restart"
  );
  const changelogPath = requireSafeTask540ChangelogPath(
    changelogPathValues[0],
    "TASK-540 closure restart"
  );
  if (changelogPath !== CHANGELOG_REL) {
    throw new Error("TASK-540 closure restart path differs from the startup path pin");
  }
  const boardState = readTask540BoardState(await readFile(TASKS + "/README.md", "utf8"));
  if (
    boardState.bucket !== "inProgress" ||
    JSON.stringify(boardState.stats) !== JSON.stringify(boardBaseline)
  ) {
    throw new Error("TASK-540 pending closure board does not match its pinned baseline");
  }
  const pending = parseClosurePending(pendingValues[0], "TASK-540 closure restart");
  const closureLeafRepairPending = repairPendingValues[2];
  const hasGateReceipt = CLOSURE_GATE_FIELDS.some((field) =>
    readTaskMetadataField(states[2].source, field)
  );
  if (closureLeafRepairPending && hasGateReceipt) {
    throw new Error("TASK-540 closure leaf retained both Repair Pending and a gate receipt");
  }
  if (!hasGateReceipt && (!allowMissingGate || !closureLeafRepairPending)) {
    throw new Error("TASK-540 closure restart lost its closure leaf gate receipt");
  }
  const gateReceipt = hasGateReceipt
    ? readClosureLeafGateReceipt(states[2].source, "TASK-540 closure restart")
    : null;
  return Object.freeze({
    ...pending,
    boardBaseline: boardBaselineValues[0],
    changelogPath,
    gateReceipt,
    priorEvidenceHash: evidenceValues[0],
    priorGeneration,
  });
}

async function requireTask540ChangelogIndex() {
  const changelogIndex = await readFile(ROOT + "/_docs/_CHANGELOG/README.md", "utf8");
  parseClosureAnchor(changelogIndex, "TASK-540 changelog index", { required: true });
  requireTask540NeighborReservations(changelogIndex, "TASK-540 changelog index");
  const indexRows = [...changelogIndex.matchAll(/^\| 1252 \|.*$/gm)];
  const rows1253 = [...changelogIndex.matchAll(/^\| 1253 \|.*$/gm)];
  const row1252 = indexRows[0]?.index ?? -1;
  const rows1250 = [...changelogIndex.matchAll(/^\| 1250 \|.*$/gm)];
  const row1253 = rows1253[0]?.index ?? -1;
  const row1250 = rows1250[0]?.index ?? -1;
  const filename = CHANGELOG_REL.split("/").at(-1) ?? "";
  const filenameDate = filename.match(/^1252-(\d{4}-\d{2}-\d{2})-/)?.[1] ?? null;
  const cells =
    indexRows.length === 1
      ? indexRows[0][0]
          .slice(1, -1)
          .split("|")
          .map((cell) => cell.trim())
      : [];
  const prose = changelogIndex.slice(0, changelogIndex.indexOf("| No. |"));
  const staleReservation = prose
    .replace(/\s+/g, " ")
    .split(/[.!?](?:\s|$)/)
    .some(
      (sentence) =>
        /\b1252\b/.test(sentence) && /\b(?:reserved|reservation|reservations)\b/i.test(sentence)
    );
  if (
    indexRows.length !== 1 ||
    !filenameDate ||
    cells.length !== 4 ||
    cells[0] !== "1252" ||
    cells[1] !== filenameDate ||
    !cells[2].startsWith(CHANGELOG_TITLE_PREFIX + " —") ||
    cells[3] !== CHANGELOG_TYPE ||
    !prose.includes("Changelog 1252 is consumed by the completed TASK-540 family.") ||
    staleReservation ||
    rows1253.length !== 1 ||
    rows1250.length !== 1 ||
    row1253 < 0 ||
    row1250 < 0 ||
    !(row1253 < row1252 && row1252 < row1250)
  ) {
    throw new Error("TASK-540 changelog index row is missing, duplicated, or misordered");
  }
  const changelogSource = await readFile(ROOT + "/" + CHANGELOG_REL, "utf8");
  const h1Lines = changelogSource.match(/^# 1252 - .*$/gm) ?? [];
  const dateLines = [...changelogSource.matchAll(/^Date:\s*(.+)$/gm)].map((match) => match[1]);
  const versionLines = [...changelogSource.matchAll(/^Version:\s*(.+)$/gm)].map(
    (match) => match[1]
  );
  const taskLines = changelogSource.match(/^Tasks:.*$/gm) ?? [];
  const expectedTaskIds = CHANGELOG_TASKS_LINE.slice("Tasks: ".length).split(", ");
  const actualTaskIds =
    taskLines.length === 1
      ? taskLines[0]
          .slice("Tasks:".length)
          .split(",")
          .map((taskId) => taskId.trim())
      : [];
  const hasExactUniqueOrderedTaskIds =
    new Set(expectedTaskIds).size === expectedTaskIds.length &&
    new Set(actualTaskIds).size === actualTaskIds.length &&
    actualTaskIds.length === expectedTaskIds.length &&
    actualTaskIds.every((taskId, index) => taskId === expectedTaskIds[index]);
  if (
    !changelogSource.startsWith("# 1252 - " + CHANGELOG_TITLE_PREFIX + "\n") ||
    h1Lines.length !== 1 ||
    dateLines.length !== 1 ||
    dateLines[0] !== filenameDate ||
    versionLines.length !== 1 ||
    versionLines[0] !== "Unreleased" ||
    taskLines.length !== 1 ||
    taskLines[0] !== CHANGELOG_TASKS_LINE ||
    !hasExactUniqueOrderedTaskIds
  ) {
    throw new Error("TASK-540 changelog metadata does not match its pinned file/index contract");
  }
  return indexRows[0][0];
}

async function validateTerminalResumeState() {
  const leafPathSet = new Set(LEAF_TASK_PATHS);
  const childPathSet = new Set(CHILD_TASK_PATHS);
  const taskStates = await Promise.all(
    TASK_PATHS.map(async (relativePath) => ({
      relativePath,
      ...(await readCanonicalTaskStatus(relativePath)),
    }))
  );
  for (const state of taskStates) {
    const completed = readTaskMetadataField(state.source, "Completed");
    const implementationComplete = readTaskMetadataField(state.source, "Implementation Complete");
    if (state.status !== RESUME_TASK_STATUS.done) {
      throw new Error("TASK-540 terminal restart found an open contract: " + state.relativePath);
    }
    requireCanonicalCompleted(completed, "TASK-540 terminal " + state.relativePath);
    if (leafPathSet.has(state.relativePath) || childPathSet.has(state.relativePath)) {
      requireCanonicalImplementationComplete(
        implementationComplete,
        "TASK-540 terminal " + state.relativePath
      );
    } else {
      requireAbsentImplementationComplete(
        implementationComplete,
        "TASK-540 terminal " + state.relativePath
      );
    }
    const gateReceipts = readTaskGateReceipts(state.source);
    if (leafPathSet.has(state.relativePath)) {
      if (gateReceipts.length !== 1 || readTaskMetadataField(state.source, "Repair Pending")) {
        throw new Error(
          "TASK-540 terminal leaf lacks its unique landed receipt: " + state.relativePath
        );
      }
    } else if (gateReceipts.length !== 0 || readTaskMetadataField(state.source, "Repair Pending")) {
      throw new Error(
        "TASK-540 terminal non-leaf retained leaf-only evidence: " + state.relativePath
      );
    }
  }

  const closurePathSet = new Set(closureContractPaths());
  const closureStates = taskStates.filter(({ relativePath }) => closurePathSet.has(relativePath));
  const closureLeafState = closureStates.find(
    ({ relativePath }) => relativePath === LEAF_STATUS_GROUPS["540-06-L01"].leafPath
  );
  if (!closureLeafState) {
    throw new Error("TASK-540 terminal closure leaf is missing its gate receipt");
  }
  const gateReceipt = readClosureLeafGateReceipt(
    closureLeafState.source,
    "TASK-540 terminal restart"
  );
  const evidenceHashes = closureStates.map(({ source }) =>
    readTaskMetadataField(source, "Closure Evidence SHA-256")
  );
  const generationValues = closureStates.map(({ source }) =>
    readTaskMetadataField(source, "Closure Generation")
  );
  const boardBaselineValues = closureStates.map(({ source }) =>
    readTaskMetadataField(source, "Closure Board Baseline")
  );
  const changelogPathValues = closureStates.map(({ source }) =>
    readTaskMetadataField(source, CLOSURE_CHANGELOG_PATH_FIELD)
  );
  if (
    !evidenceHashes[0]?.match(/^[0-9a-f]{64}$/) ||
    !evidenceHashes.every((value) => value === evidenceHashes[0]) ||
    !generationValues[0] ||
    !generationValues.every((value) => value === generationValues[0]) ||
    !boardBaselineValues[0] ||
    !boardBaselineValues.every((value) => value === boardBaselineValues[0]) ||
    !changelogPathValues[0] ||
    !changelogPathValues.every((value) => value === changelogPathValues[0]) ||
    requireSafeTask540ChangelogPath(changelogPathValues[0], "TASK-540 terminal restart") !==
      CHANGELOG_REL ||
    closureStates.some(({ source }) => readTaskMetadataField(source, "Closure Pending"))
  ) {
    throw new Error("TASK-540 terminal restart has invalid shared closure evidence");
  }
  for (const state of taskStates.filter(({ relativePath }) => !closurePathSet.has(relativePath))) {
    if (
      [
        "Closure Pending",
        "Closure Evidence SHA-256",
        "Closure Generation",
        "Closure Board Baseline",
        CLOSURE_CHANGELOG_PATH_FIELD,
      ].some((field) => readTaskMetadataField(state.source, field))
    ) {
      throw new Error(
        "TASK-540 terminal source descendant has closure-only evidence: " + state.relativePath
      );
    }
  }

  const terminalGeneration = parsePositiveClosureGeneration(
    generationValues[0],
    "TASK-540 terminal restart"
  );
  const anchor = await readClosureAnchor({ required: true, label: "TASK-540 terminal restart" });
  const closureControl = anchor.closureControl;
  if (
    anchor.evidenceSha256 !== evidenceHashes[0] ||
    anchor.repairAuthorization !== null ||
    closureControl.generation !== terminalGeneration ||
    closureControl.boardBaseline !== boardBaselineValues[0] ||
    closureControl.changelogPath !== changelogPathValues[0] ||
    closureControl.gateReceipt.field !== gateReceipt.field ||
    closureControl.gateReceipt.valueSha256 !== closureGateValueHash(gateReceipt)
  ) {
    throw new Error("TASK-540 terminal closureControl does not match task receipts");
  }
  const boardSource = await readFile(TASKS + "/README.md", "utf8");
  const boardState = readTask540BoardState(boardSource);
  requireBoardRowMarker(boardState, "TASK-540 terminal restart");
  const boardBaseline = parseClosureBoardBaseline(
    boardBaselineValues[0],
    "TASK-540 terminal restart"
  );
  const expectedClosedStats = closedBoardStatsFromBaseline(
    boardBaseline,
    "TASK-540 terminal restart"
  );
  if (
    boardState.bucket !== "done" ||
    JSON.stringify(boardState.stats) !== JSON.stringify(expectedClosedStats)
  ) {
    throw new Error("TASK-540 terminal board row/statistics do not match the closure baseline");
  }
  let changelogValid = false;
  if (EXISTING_CHANGELOG_REL === CHANGELOG_REL) {
    try {
      const source = await readFile(ROOT + "/" + CHANGELOG_REL, "utf8");
      const start = source.indexOf(EVIDENCE_BEGIN);
      const end = source.indexOf(EVIDENCE_END, start + EVIDENCE_BEGIN.length);
      const block =
        start >= 0 && end >= 0 ? source.slice(start, end + EVIDENCE_END.length) : "<missing>";
      changelogValid =
        source.split(EVIDENCE_BEGIN).length - 1 === 1 &&
        source.split(EVIDENCE_END).length - 1 === 1 &&
        createHash("sha256").update(block).digest("hex") === anchor.evidenceSha256 &&
        JSON.stringify(parseClosureControlFromEvidenceBlock(block, "TASK-540 terminal draft")) ===
          JSON.stringify(closureControl);
      if (changelogValid) await requireTask540ChangelogIndex();
    } catch {
      changelogValid = false;
    }
  }
  return Object.freeze({
    path: CHANGELOG_REL,
    evidenceHash: anchor.evidenceSha256,
    generation: terminalGeneration,
    boardBaseline: boardBaselineValues[0],
    changelogPath: changelogPathValues[0],
    gateReceipt,
    closureControl,
    anchor,
    changelogNeedsRecovery: !changelogValid,
  });
}

async function resolveLeafResumeState({
  readTaskStatus = readCanonicalTaskStatus,
  readBoardSource = () => readFile(TASKS + "/README.md", "utf8"),
  validateTerminal = validateTerminalResumeState,
} = {}) {
  if (
    typeof readTaskStatus !== "function" ||
    typeof readBoardSource !== "function" ||
    typeof validateTerminal !== "function"
  ) {
    throw new Error("TASK-540 resume reader authority is malformed");
  }
  if ((await hashPath(HISTORICAL_FIX_WORKFLOW_REL)) === "<missing>") {
    throw new Error("TASK-540 historical corrective workflow evidence is missing");
  }

  const rootState = await readTaskStatus(ROOT_TASK_PATH);
  const terminalCandidate = rootState.status === RESUME_TASK_STATUS.done;
  if (!terminalCandidate && rootState.status !== RESUME_TASK_STATUS.active) {
    throw new Error("TASK-540 resumable workflow requires the root In Progress or terminal Done");
  }
  const rootCompleted = readTaskMetadataField(rootState.source, "Completed");
  const rootImplementationComplete = readTaskMetadataField(
    rootState.source,
    "Implementation Complete"
  );
  if (terminalCandidate) {
    requireCanonicalCompleted(rootCompleted, "TASK-540 terminal root");
  } else {
    requireAbsentCompleted(rootCompleted, "TASK-540 active root");
  }
  requireAbsentImplementationComplete(rootImplementationComplete, "TASK-540 root");

  const leafPathSet = new Set(LEAVES.map((leaf) => LEAF_STATUS_GROUPS[leaf.id].leafPath));
  const allContractStates = await Promise.all(
    TASK_PATHS.map(async (relativePath) => ({
      relativePath,
      ...(relativePath === ROOT_TASK_PATH ? rootState : await readTaskStatus(relativePath)),
    }))
  );
  for (const state of allContractStates) {
    const repairPending = readTaskMetadataField(state.source, "Repair Pending");
    if (repairPending && !leafPathSet.has(state.relativePath)) {
      throw new Error("TASK-540 Repair Pending escaped its single leaf owner");
    }
    if (terminalCandidate && repairPending) {
      throw new Error("TASK-540 terminal graph retained Repair Pending");
    }
  }
  for (const relativePath of [ROOT_TASK_PATH, LEAF_STATUS_GROUPS["540-06-L01"].childPath]) {
    const state = allContractStates.find((candidate) => candidate.relativePath === relativePath);
    if (CLOSURE_GATE_FIELDS.some((field) => readTaskMetadataField(state.source, field))) {
      throw new Error("TASK-540 root/closure parent retained a leaf-only gate receipt");
    }
  }

  const leafStates = [];
  for (const leaf of LEAVES) {
    const group = LEAF_STATUS_GROUPS[leaf.id];
    const state = await readTaskStatus(group.leafPath);
    if (!Object.values(RESUME_TASK_STATUS).includes(state.status)) {
      throw new Error("TASK-" + leaf.id + ": non-resumable status " + state.status);
    }

    const completed = readTaskMetadataField(state.source, "Completed");
    const implementationComplete = readTaskMetadataField(state.source, "Implementation Complete");
    const targetedGate = readTaskMetadataField(state.source, "Targeted Gate Passed");
    const revalidation = readTaskMetadataField(state.source, "Revalidation Passed");
    const repairPending = readTaskMetadataField(state.source, "Repair Pending");
    const closurePending = readTaskMetadataField(state.source, "Closure Pending");
    if (repairPending) parseRepairPending(repairPending, "TASK-" + leaf.id);
    if (targetedGate && revalidation) {
      throw new Error("TASK-" + leaf.id + ": multiple current gate receipts");
    }
    if (state.status === RESUME_TASK_STATUS.done) {
      requireCanonicalCompleted(completed, "TASK-" + leaf.id);
    } else {
      requireAbsentCompleted(completed, "TASK-" + leaf.id);
    }
    if (state.status === RESUME_TASK_STATUS.done && repairPending) {
      throw new Error("TASK-" + leaf.id + ": Done with a pending repair");
    }
    const landed =
      state.status === RESUME_TASK_STATUS.done ||
      (state.status === RESUME_TASK_STATUS.active &&
        !repairPending &&
        Boolean(targetedGate || revalidation));
    if (landed) {
      requireCanonicalImplementationComplete(implementationComplete, "TASK-" + leaf.id);
    } else {
      requireAbsentImplementationComplete(implementationComplete, "TASK-" + leaf.id);
    }
    leafStates.push({
      id: leaf.id,
      status: state.status,
      landed,
      completed,
      implementationComplete,
      targetedGate,
      revalidation,
      repairPending,
      closurePending,
      evidence:
        state.status === RESUME_TASK_STATUS.done
          ? "Completed: " + completed
          : targetedGate
            ? "Targeted Gate Passed: " + targetedGate
            : revalidation
              ? "Revalidation Passed: " + revalidation
              : null,
      source: state.source,
    });
  }

  const pendingRepairs = leafStates.filter(({ repairPending }) => repairPending);
  if (pendingRepairs.length > 1) {
    throw new Error("TASK-540 resumable workflow found multiple pending repair owners");
  }
  const repairState = pendingRepairs[0] ?? null;
  let mode = terminalCandidate ? "terminal" : "initial";
  let startIndex = null;
  let reservedPreClosureRegatedSibling = null;
  if (terminalCandidate) {
    if (repairState || leafStates.some(({ status }) => status !== RESUME_TASK_STATUS.done)) {
      throw new Error("TASK-540 terminal restart requires every leaf Done without pending repair");
    }
    startIndex = leafStates.length;
  } else if (repairState) {
    mode = "repair";
    if (
      repairState.status !== RESUME_TASK_STATUS.active ||
      repairState.completed ||
      repairState.targetedGate ||
      repairState.revalidation
    ) {
      throw new Error("TASK-" + repairState.id + ": invalid pending repair receipts");
    }
    if (repairState.id !== "540-06-L01") {
      const closureGroup = LEAF_STATUS_GROUPS["540-06-L01"];
      const closureLeafState = leafStates.find(({ id }) => id === "540-06-L01");
      const closureChildState = allContractStates.find(
        ({ relativePath }) => relativePath === closureGroup.childPath
      );
      if (!closureLeafState || !closureChildState) {
        throw new Error("TASK-540 prepared closure sibling contract is missing");
      }
      const fixStartedDate = matchingPreClosureFixStartedDate(
        closureChildState.source,
        closureLeafState.source,
        "TASK-540 prepared closure sibling"
      );
      const closureReceiptsAbsent = closureContractPaths().every((relativePath) => {
        const contractState = allContractStates.find(
          (candidate) => candidate.relativePath === relativePath
        );
        return Boolean(
          contractState &&
          CLOSURE_RECEIPT_FIELDS.every(
            (field) => readTaskMetadataField(contractState.source, field) === null
          )
        );
      });
      if (
        fixStartedDate &&
        closureReceiptsAbsent &&
        closureLeafState.status === RESUME_TASK_STATUS.active &&
        !closureLeafState.completed &&
        !closureLeafState.repairPending &&
        !closureLeafState.targetedGate &&
        closureLeafState.revalidation === preClosureRegateValue(fixStartedDate)
      ) {
        reservedPreClosureRegatedSibling = Object.freeze({
          fixStartedDate,
          gateValue: closureLeafState.revalidation,
        });
      }
    }
    for (const state of leafStates) {
      if (state.id === repairState.id) continue;
      if (
        !isTask540RepairSiblingStateAllowed(state, {
          allowCoveredDone: true,
          reservedPreClosureRegated: reservedPreClosureRegatedSibling,
        })
      ) {
        throw new Error("TASK-" + state.id + ": invalid sibling state during repair resume");
      }
    }
  } else {
    const firstUnlandedIndex = leafStates.findIndex((state) => !state.landed);
    startIndex = firstUnlandedIndex === -1 ? leafStates.length : firstUnlandedIndex;
    for (let index = 0; index < leafStates.length; index += 1) {
      const state = leafStates[index];
      if (index < startIndex && !state.landed) {
        throw new Error("TASK-" + state.id + ": missing landed evidence before resume cursor");
      }
      if (index > startIndex && state.status !== RESUME_TASK_STATUS.todo) {
        throw new Error(
          "TASK-" +
            state.id +
            ": later leaf was started or landed before TASK-" +
            leafStates[startIndex].id
        );
      }
    }
  }

  const childIds = [...new Set(LEAVES.map((leaf) => LEAF_STATUS_GROUPS[leaf.id].childId))];
  for (const childId of childIds) {
    const childLeaves = leafStates.filter(
      (state) => LEAF_STATUS_GROUPS[state.id].childId === childId
    );
    const group = LEAF_STATUS_GROUPS[childLeaves[0].id];
    const childState = await readTaskStatus(group.childPath);
    const expectedChildStatus = childLeaves.every(
      (state) => state.status === RESUME_TASK_STATUS.done
    )
      ? RESUME_TASK_STATUS.done
      : childLeaves.every((state) => state.status === RESUME_TASK_STATUS.todo)
        ? RESUME_TASK_STATUS.todo
        : RESUME_TASK_STATUS.active;
    if (childState.status !== expectedChildStatus) {
      throw new Error(
        "TASK-" + childId + ": expected " + expectedChildStatus + ", got " + childState.status
      );
    }
    const childCompleted = readTaskMetadataField(childState.source, "Completed");
    const childImplementationComplete = readTaskMetadataField(
      childState.source,
      "Implementation Complete"
    );
    if (expectedChildStatus === RESUME_TASK_STATUS.done) {
      requireCanonicalCompleted(childCompleted, "TASK-" + childId);
    } else {
      requireAbsentCompleted(childCompleted, "TASK-" + childId);
    }
    if (childLeaves.every(({ landed }) => landed)) {
      requireCanonicalImplementationComplete(childImplementationComplete, "TASK-" + childId);
    } else {
      requireAbsentImplementationComplete(childImplementationComplete, "TASK-" + childId);
    }
    for (const leafState of childLeaves) {
      requireTableStatus(
        childState.source,
        leafState.id,
        leafState.status,
        "TASK-540 resumable child"
      );
    }
    requireTableStatus(rootState.source, childId, expectedChildStatus, "TASK-540 resumable root");
  }

  const boardState = readTask540BoardState(await readBoardSource());
  const expectedBoardBucket = terminalCandidate ? "done" : "inProgress";
  if (boardState.bucket !== expectedBoardBucket) {
    throw new Error("TASK-540 resumable workflow requires board bucket " + expectedBoardBucket);
  }
  const terminal = terminalCandidate ? await validateTerminal() : null;

  return Object.freeze({
    mode,
    startIndex,
    startLeafId: repairState?.id ?? LEAVES[startIndex]?.id ?? null,
    repair: repairState
      ? Object.freeze({ id: repairState.id, pending: repairState.repairPending })
      : null,
    reservedPreClosureRegatedSibling,
    terminal,
    landedLeafIds: Object.freeze(leafStates.filter(({ landed }) => landed).map(({ id }) => id)),
    remainingLeafIds: Object.freeze(
      repairState ? [repairState.id] : leafStates.slice(startIndex).map(({ id }) => id)
    ),
    leafStates: Object.freeze(
      leafStates.map(
        ({
          id,
          status,
          landed,
          completed,
          implementationComplete,
          targetedGate,
          revalidation,
          repairPending,
          closurePending,
          evidence,
        }) =>
          Object.freeze({
            id,
            status,
            landed,
            completed,
            implementationComplete,
            targetedGate,
            revalidation,
            repairPending,
            closurePending,
            evidence,
          })
      )
    ),
  });
}

async function resolveChangelogResumeState(resumeState) {
  if (resumeState.mode === "terminal") {
    if (!resumeState.terminal || resumeState.terminal.path !== CHANGELOG_REL) {
      throw new Error("TASK-540 terminal resume lost its validated changelog state");
    }
    return Object.freeze({
      mode: "terminal-reopen",
      path: resumeState.terminal.path,
      closurePending: null,
      generation: resumeState.terminal.generation,
      evidenceHash: resumeState.terminal.evidenceHash,
      boardBaseline: resumeState.terminal.boardBaseline,
      changelogPath: resumeState.terminal.changelogPath,
      gateReceipt: resumeState.terminal.gateReceipt,
      closureControl: resumeState.terminal.closureControl,
      anchor: resumeState.terminal.anchor,
      changelogNeedsRecovery: resumeState.terminal.changelogNeedsRecovery,
    });
  }
  const allowMissingGate = resumeState.mode === "repair" && resumeState.repair?.id === "540-06-L01";
  const sharedPending = await readSharedClosurePending({ allowMissingGate });
  const indexState = classifyClosureEvidenceIndex(
    await readFile(ROOT + "/_docs/_CHANGELOG/README.md", "utf8"),
    "TASK-540 closure restart"
  );
  const anchor = indexState.anchor;
  if (resumeState.reservedPreClosureRegatedSibling && (sharedPending || anchor)) {
    throw new Error(
      "TASK-540 reserved pre-closure regated source repair cannot use consumed authority"
    );
  }
  if ((sharedPending || allowMissingGate) && !anchor) {
    throw new Error("TASK-540 closure restart requires a canonical consumed anchor");
  }
  if (!sharedPending) {
    if (!anchor) {
      const closureGroup = LEAF_STATUS_GROUPS["540-06-L01"];
      const [childState, leafState] = await Promise.all([
        readCanonicalTaskStatus(closureGroup.childPath),
        readCanonicalTaskStatus(closureGroup.leafPath),
      ]);
      const childFixStarted = readTaskMetadataField(childState.source, "Fix Started");
      const leafFixStarted = readTaskMetadataField(leafState.source, "Fix Started");
      let reservedMode = EXISTING_CHANGELOG_REL ? "overwrite-draft" : "reserved";
      if (childFixStarted || leafFixStarted) {
        const fixStartedDate = matchingPreClosureFixStartedDate(
          childState.source,
          leafState.source,
          "TASK-540 reserved pre-closure remediation restart"
        );
        const gateReceipts = CLOSURE_GATE_FIELDS.flatMap((field) => {
          const value = readTaskMetadataField(leafState.source, field);
          return value ? [Object.freeze({ field, value })] : [];
        });
        const exactClosureCursorRestart =
          gateReceipts.length === 0 &&
          resumeState.mode === "initial" &&
          resumeState.startIndex === LEAVES.length - 1 &&
          resumeState.startLeafId === "540-06-L01" &&
          JSON.stringify(resumeState.remainingLeafIds) === JSON.stringify(["540-06-L01"]);
        const exactEarlierRepairRestart =
          gateReceipts.length === 0 &&
          resumeState.mode === "repair" &&
          Boolean(resumeState.repair?.id) &&
          resumeState.repair.id !== "540-06-L01" &&
          resumeState.startLeafId === resumeState.repair.id &&
          JSON.stringify(resumeState.remainingLeafIds) === JSON.stringify([resumeState.repair.id]);
        const exactUngatedRestart = exactClosureCursorRestart || exactEarlierRepairRestart;
        const exactRegatedContinuation =
          gateReceipts.length === 1 &&
          gateReceipts[0].field === "Revalidation Passed" &&
          gateReceipts[0].value === preClosureRegateValue(fixStartedDate) &&
          resumeState.mode === "initial" &&
          resumeState.startIndex === LEAVES.length &&
          resumeState.startLeafId === null &&
          resumeState.remainingLeafIds.length === 0;
        const exactRegatedSourceRepair = matchesReservedPreClosureRegatedSourceRepair({
          resumeState,
          fixStartedDate,
          gateReceipts,
          indexKind: indexState.kind,
          hasSharedPending: Boolean(sharedPending),
          hasExistingChangelog: Boolean(EXISTING_CHANGELOG_REL),
        });
        if (
          EXISTING_CHANGELOG_REL ||
          (!exactUngatedRestart && !exactRegatedContinuation && !exactRegatedSourceRepair)
        ) {
          throw new Error("TASK-540 reserved pre-closure remediation state is not exact");
        }
        reservedMode = exactUngatedRestart
          ? "reserved-pre-closure-ungated"
          : exactRegatedSourceRepair
            ? "reserved-pre-closure-regated-source-repair"
            : "reserved-pre-closure-regated";
      }
      if (EXISTING_CHANGELOG_REL && resumeState.startIndex !== LEAVES.length) {
        throw new Error("TASK-540 pre-pending changelog draft appeared before all leaves landed");
      }
      return Object.freeze({
        mode: reservedMode,
        path: CHANGELOG_REL,
        closurePending: null,
        generation: 0,
        evidenceHash: null,
        boardBaseline: null,
        changelogPath: null,
        gateReceipt: null,
        closureControl: null,
        anchor: null,
        changelogNeedsRecovery: Boolean(EXISTING_CHANGELOG_REL),
      });
    }
    const closureGroup = LEAF_STATUS_GROUPS["540-06-L01"];
    const [rootState, childState, leafState, boardSource] = await Promise.all([
      readCanonicalTaskStatus(ROOT_TASK_PATH),
      readCanonicalTaskStatus(closureGroup.childPath),
      readCanonicalTaskStatus(closureGroup.leafPath),
      readFile(TASKS + "/README.md", "utf8"),
    ]);
    const boardState = readTask540BoardState(boardSource);
    const gateReceipts = CLOSURE_GATE_FIELDS.flatMap((field) => {
      const value = readTaskMetadataField(leafState.source, field);
      return value ? [Object.freeze({ field, value })] : [];
    });
    if (gateReceipts.length > 1) {
      throw new Error("TASK-540 evidence-before-pending leaf has duplicate gate authority");
    }
    const gateReceipt = gateReceipts[0] ?? null;
    const boardBaseline = formatClosureBoardBaseline(boardState.stats);
    const closureControl = anchor.closureControl;
    const activeClosureGraph = [rootState, childState, leafState].every(
      ({ status, source }) =>
        status === RESUME_TASK_STATUS.active && !readTaskMetadataField(source, "Completed")
    );
    if (
      !activeClosureGraph ||
      CLOSURE_GATE_FIELDS.some(
        (field) =>
          readTaskMetadataField(rootState.source, field) ||
          readTaskMetadataField(childState.source, field)
      )
    ) {
      throw new Error("TASK-540 evidence-before-pending closure graph is not exactly active");
    }
    requireTableStatus(
      childState.source,
      "540-06-L01",
      RESUME_TASK_STATUS.active,
      "TASK-540 evidence-before-pending child"
    );
    requireTableStatus(
      rootState.source,
      "540-06",
      RESUME_TASK_STATUS.active,
      "TASK-540 evidence-before-pending root"
    );
    const gateControlMatches = Boolean(
      gateReceipt &&
      closureControl.gateReceipt.field === gateReceipt.field &&
      closureControl.gateReceipt.valueSha256 === closureGateValueHash(gateReceipt)
    );
    const fixStartedDate = matchingPreClosureFixStartedDate(
      childState.source,
      leafState.source,
      "TASK-540 evidence-before-pending repair"
    );
    const leafRepairPending = readTaskMetadataField(leafState.source, "Repair Pending");
    const authorization = anchor.repairAuthorization;
    let authorizedSuccessorRepairPending = null;
    if (authorization && gateReceipt) {
      if (gateReceipt.field !== "Revalidation Passed") {
        throw new Error("TASK-540 authorized pre-pending repair retained a non-successor gate");
      }
      authorizedSuccessorRepairPending = repairPendingFromGateValue(
        gateReceipt.value,
        "TASK-540 authorized pre-pending successor"
      );
    }
    const normalGateMatches =
      leafRepairPending === null && authorization === null && gateControlMatches;
    const pendingRepairMatches = Boolean(
      fixStartedDate &&
      leafRepairPending &&
      gateReceipt === null &&
      resumeState.mode === "repair" &&
      resumeState.repair?.id === "540-06-L01" &&
      leafRepairPending === resumeState.repair.pending &&
      authorization &&
      authorization.repairPendingSha256 === hashRepairPendingReceipt(leafRepairPending) &&
      equalHashedGateReceipts(authorization.priorGate, closureControl.gateReceipt) &&
      equalHashedGateReceipts(
        authorization.successorGate,
        hashedGateReceipt({
          field: "Revalidation Passed",
          value: repairGateValue(leafRepairPending),
        })
      )
    );
    const authorizedSuccessorMatches = Boolean(
      fixStartedDate &&
      leafRepairPending === null &&
      gateReceipt &&
      resumeState.mode === "initial" &&
      resumeState.startIndex === LEAVES.length &&
      resumeState.startLeafId === null &&
      resumeState.remainingLeafIds.length === 0 &&
      authorization &&
      authorizedSuccessorRepairPending &&
      authorization.repairPendingSha256 ===
        hashRepairPendingReceipt(authorizedSuccessorRepairPending) &&
      equalHashedGateReceipts(authorization.priorGate, closureControl.gateReceipt) &&
      equalHashedGateReceipts(authorization.successorGate, hashedGateReceipt(gateReceipt))
    );
    if (
      boardState.bucket !== "inProgress" ||
      closureControl.boardBaseline !== boardBaseline ||
      closureControl.changelogPath !== CHANGELOG_REL ||
      (!normalGateMatches && !pendingRepairMatches && !authorizedSuccessorMatches)
    ) {
      throw new Error("TASK-540 evidence-before-pending control does not match active graph");
    }
    return Object.freeze({
      mode: pendingRepairMatches
        ? "evidence-before-pending-repair"
        : authorizedSuccessorMatches
          ? "evidence-before-pending-after-gate-repair"
          : "evidence-before-pending",
      path: CHANGELOG_REL,
      closurePending: null,
      generation: closureControl.generation,
      evidenceHash: anchor.evidenceSha256,
      boardBaseline,
      changelogPath: CHANGELOG_REL,
      gateReceipt,
      closureControl,
      anchor,
      changelogNeedsRecovery: true,
    });
  }
  if (resumeState.mode !== "repair" && resumeState.startIndex !== LEAVES.length) {
    throw new Error("TASK-540 closure pending state appeared before all leaves landed");
  }
  const requiredPending = sharedPending;
  const closureControl = anchor.closureControl;
  const authorization = anchor.repairAuthorization;
  const gateControlMatches =
    !authorization &&
    requiredPending.gateReceipt &&
    equalHashedGateReceipts(
      closureControl.gateReceipt,
      hashedGateReceipt(requiredPending.gateReceipt)
    );
  let authorizedSuccessorRepairPending = null;
  if (authorization && requiredPending.gateReceipt) {
    if (requiredPending.gateReceipt.field !== "Revalidation Passed") {
      throw new Error("TASK-540 authorized closure repair retained a non-successor gate");
    }
    authorizedSuccessorRepairPending = repairPendingFromGateValue(
      requiredPending.gateReceipt.value,
      "TASK-540 authorized closure successor"
    );
  }
  const pendingRepairMatches = Boolean(
    !requiredPending.gateReceipt &&
    resumeState.repair?.id === "540-06-L01" &&
    authorization &&
    authorization.repairPendingSha256 === hashRepairPendingReceipt(resumeState.repair.pending) &&
    equalHashedGateReceipts(authorization.priorGate, closureControl.gateReceipt) &&
    equalHashedGateReceipts(
      authorization.successorGate,
      hashedGateReceipt({
        field: "Revalidation Passed",
        value: repairGateValue(resumeState.repair.pending),
      })
    )
  );
  const successorGateMatches = Boolean(
    requiredPending.gateReceipt &&
    authorization &&
    authorizedSuccessorRepairPending &&
    authorization.repairPendingSha256 ===
      hashRepairPendingReceipt(authorizedSuccessorRepairPending) &&
    equalHashedGateReceipts(authorization.priorGate, closureControl.gateReceipt) &&
    equalHashedGateReceipts(
      authorization.successorGate,
      hashedGateReceipt(requiredPending.gateReceipt)
    )
  );
  if (
    closureControl.generation !== requiredPending.generation ||
    closureControl.boardBaseline !== requiredPending.boardBaseline ||
    closureControl.changelogPath !== requiredPending.changelogPath ||
    (!gateControlMatches && !pendingRepairMatches && !successorGateMatches)
  ) {
    throw new Error("TASK-540 pending restart does not match independent closureControl");
  }
  return Object.freeze({
    mode: successorGateMatches ? "closure-restart-after-gate-repair" : "closure-restart",
    path: CHANGELOG_REL,
    closurePending: requiredPending.value,
    generation: requiredPending.generation,
    evidenceHash: anchor.evidenceSha256,
    boardBaseline: requiredPending.boardBaseline,
    changelogPath: requiredPending.changelogPath,
    gateReceipt: requiredPending.gateReceipt,
    closureControl,
    anchor,
    changelogNeedsRecovery: true,
  });
}

const COVERED_CHANGELOG_MODES = new Set([
  "terminal-reopen",
  "closure-restart",
  "closure-restart-after-gate-repair",
]);

function hasIndependentTask540CoverageAuthority(changelogState) {
  if (!COVERED_CHANGELOG_MODES.has(changelogState?.mode)) return false;
  const control = changelogState.closureControl;
  const anchor = changelogState.anchor;
  if (!control || !anchor || !changelogState.evidenceHash?.match(/^[0-9a-f]{64}$/)) return false;
  try {
    const canonicalControl = validateClosureControl(control, "TASK-540 coverage authority");
    const canonicalAnchor = buildClosureAnchor(
      anchor.evidenceSha256,
      canonicalControl,
      anchor.collaborationLedgerPrefix,
      anchor.terminalCollaborationReceipt,
      anchor.repairAuthorization
    );
    parseClosureBoardBaseline(changelogState.boardBaseline, "TASK-540 coverage authority");
    if (
      JSON.stringify(canonicalControl) !== JSON.stringify(control) ||
      JSON.stringify(canonicalAnchor) !== JSON.stringify(anchor)
    ) {
      return false;
    }
  } catch {
    return false;
  }
  if (
    changelogState.path !== CHANGELOG_REL ||
    changelogState.changelogPath !== CHANGELOG_REL ||
    !Number.isSafeInteger(changelogState.generation) ||
    changelogState.generation < 1 ||
    !changelogState.boardBaseline ||
    anchor.evidenceSha256 !== changelogState.evidenceHash ||
    JSON.stringify(anchor.closureControl) !== JSON.stringify(control) ||
    control.generation !== changelogState.generation ||
    control.boardBaseline !== changelogState.boardBaseline ||
    control.changelogPath !== CHANGELOG_REL
  ) {
    return false;
  }
  if (
    changelogState.mode === "terminal-reopen" &&
    (changelogState.closurePending !== null || anchor.repairAuthorization !== null)
  ) {
    return false;
  }
  if (
    changelogState.mode !== "terminal-reopen" &&
    typeof changelogState.closurePending !== "string"
  ) {
    return false;
  }
  if (changelogState.gateReceipt) {
    const currentGate = hashedGateReceipt(changelogState.gateReceipt);
    const gateAuthorized =
      equalHashedGateReceipts(control.gateReceipt, currentGate) ||
      Boolean(
        anchor.repairAuthorization &&
        equalHashedGateReceipts(anchor.repairAuthorization.successorGate, currentGate)
      );
    if (!gateAuthorized) return false;
  } else if (!anchor.repairAuthorization) {
    return false;
  }
  return true;
}

function validateResumeLeafCoverageContract(
  leafStates,
  { allowCoveredDone = false, repairId = null, startLeafId = null } = {}
) {
  if (
    !Array.isArray(leafStates) ||
    leafStates.length !== LEAF_ORDER.length ||
    leafStates.some((state, index) => state.id !== LEAF_ORDER[index])
  ) {
    throw new Error("TASK-540 resume coverage requires every leaf in strict land order");
  }
  let doneCount = 0;
  let activeCount = 0;
  let landedCount = 0;
  for (const state of leafStates) {
    const isClosureLeaf = state.id === "540-06-L01";
    const gateCount = Number(Boolean(state.targetedGate)) + Number(Boolean(state.revalidation));
    if (gateCount > 1) {
      throw new Error("TASK-" + state.id + ": resume coverage found both gate receipts");
    }
    if (!isClosureLeaf && state.closurePending) {
      throw new Error("TASK-" + state.id + ": source leaf retained Closure Pending");
    }
    if (state.repairPending && state.id !== repairId) {
      throw new Error("TASK-" + state.id + ": Repair Pending escaped the exact repair owner");
    }
    if (state.status === RESUME_TASK_STATUS.done) {
      doneCount += 1;
      requireCanonicalCompleted(state.completed, "TASK-" + state.id + " covered leaf");
      requireCanonicalImplementationComplete(
        state.implementationComplete,
        "TASK-" + state.id + " covered leaf"
      );
      if (
        !allowCoveredDone ||
        gateCount !== 1 ||
        state.repairPending ||
        state.closurePending ||
        !state.landed
      ) {
        throw new Error(
          "TASK-" + state.id + ": Done is not covered by exact terminal leaf authority"
        );
      }
      landedCount += 1;
      continue;
    }
    requireAbsentCompleted(state.completed, "TASK-" + state.id + " nonterminal leaf");
    if (state.status === RESUME_TASK_STATUS.todo) {
      requireAbsentImplementationComplete(
        state.implementationComplete,
        "TASK-" + state.id + " To Do leaf"
      );
      if (
        gateCount !== 0 ||
        state.repairPending ||
        state.closurePending ||
        state.implementationComplete ||
        state.landed
      ) {
        throw new Error("TASK-" + state.id + ": To Do leaf retained landed evidence");
      }
      continue;
    }
    if (state.status !== RESUME_TASK_STATUS.active) {
      throw new Error("TASK-" + state.id + ": unsupported resume coverage status");
    }
    activeCount += 1;
    if (state.repairPending) {
      requireAbsentImplementationComplete(
        state.implementationComplete,
        "TASK-" + state.id + " repair leaf"
      );
      if (gateCount !== 0 || state.implementationComplete || state.landed) {
        throw new Error("TASK-" + state.id + ": repair owner retained stale landed evidence");
      }
      continue;
    }
    if (gateCount === 1) {
      requireCanonicalImplementationComplete(
        state.implementationComplete,
        "TASK-" + state.id + " landed leaf"
      );
      if (!state.landed) {
        throw new Error("TASK-" + state.id + ": gated leaf lacks Implementation Complete");
      }
      if (state.closurePending && (!isClosureLeaf || !allowCoveredDone)) {
        throw new Error("TASK-" + state.id + ": Closure Pending lacks covered authority");
      }
      landedCount += 1;
      continue;
    }
    requireAbsentImplementationComplete(
      state.implementationComplete,
      "TASK-" + state.id + " active ungated leaf"
    );
    if (
      state.implementationComplete ||
      state.landed ||
      state.closurePending ||
      (state.id !== repairId && state.id !== startLeafId && !(isClosureLeaf && repairId))
    ) {
      throw new Error("TASK-" + state.id + ": unexpected active ungated leaf");
    }
  }
  return Object.freeze({ doneCount, activeCount, landedCount });
}

async function validateResumeGraphCoverage(resumeState, changelogState, label) {
  const reservedRegatedSourceRepairMode =
    changelogState?.mode === "reserved-pre-closure-regated-source-repair";
  if (
    Boolean(resumeState.reservedPreClosureRegatedSibling) !== reservedRegatedSourceRepairMode ||
    (reservedRegatedSourceRepairMode &&
      (resumeState.mode !== "repair" ||
        !resumeState.repair?.id ||
        resumeState.repair.id === "540-06-L01" ||
        resumeState.startLeafId !== resumeState.repair.id ||
        JSON.stringify(resumeState.remainingLeafIds) !== JSON.stringify([resumeState.repair.id])))
  ) {
    throw new Error(label + ": reserved pre-closure regated repair authority is not bidirectional");
  }
  const allowCoveredDone = hasIndependentTask540CoverageAuthority(changelogState);
  const leafSummary = validateResumeLeafCoverageContract(resumeState.leafStates, {
    allowCoveredDone,
    repairId: resumeState.repair?.id ?? null,
    startLeafId: resumeState.startLeafId,
  });
  if (resumeState.mode === "terminal" && !allowCoveredDone) {
    throw new Error(label + ": terminal graph lacks independently validated changelog 1252");
  }

  const taskStates = new Map(
    await Promise.all(
      TASK_PATHS.map(async (relativePath) => [
        relativePath,
        Object.freeze({ relativePath, ...(await readCanonicalTaskStatus(relativePath)) }),
      ])
    )
  );
  const leafById = new Map(resumeState.leafStates.map((state) => [state.id, state]));
  const closurePathSet = new Set(closureContractPaths());
  for (const leafId of LEAF_ORDER) {
    const group = LEAF_STATUS_GROUPS[leafId];
    const persisted = taskStates.get(group.leafPath);
    const projected = leafById.get(leafId);
    const persistedProjection = {
      status: persisted.status,
      completed: readTaskMetadataField(persisted.source, "Completed"),
      implementationComplete: readTaskMetadataField(persisted.source, "Implementation Complete"),
      targetedGate: readTaskMetadataField(persisted.source, "Targeted Gate Passed"),
      revalidation: readTaskMetadataField(persisted.source, "Revalidation Passed"),
      repairPending: readTaskMetadataField(persisted.source, "Repair Pending"),
      closurePending: readTaskMetadataField(persisted.source, "Closure Pending"),
    };
    const resumeProjection = {
      status: projected.status,
      completed: projected.completed,
      implementationComplete: projected.implementationComplete,
      targetedGate: projected.targetedGate,
      revalidation: projected.revalidation,
      repairPending: projected.repairPending,
      closurePending: projected.closurePending,
    };
    if (JSON.stringify(persistedProjection) !== JSON.stringify(resumeProjection)) {
      throw new Error(label + ": leaf graph changed during coverage validation: TASK-" + leafId);
    }
    if (
      leafId !== "540-06-L01" &&
      CLOSURE_RECEIPT_FIELDS.some((field) => readTaskMetadataField(persisted.source, field))
    ) {
      throw new Error(label + ": source leaf retained closure-only authority: TASK-" + leafId);
    }
  }
  for (const childId of CHILD_IDS_IN_LAND_ORDER) {
    const leafIds = LEAF_ORDER.filter((leafId) => LEAF_STATUS_GROUPS[leafId].childId === childId);
    const group = LEAF_STATUS_GROUPS[leafIds[0]];
    const state = taskStates.get(group.childPath);
    const childLeaves = leafIds.map((leafId) => leafById.get(leafId));
    const expectedStatus = childLeaves.every(({ status }) => status === RESUME_TASK_STATUS.done)
      ? RESUME_TASK_STATUS.done
      : childLeaves.every(({ status }) => status === RESUME_TASK_STATUS.todo)
        ? RESUME_TASK_STATUS.todo
        : RESUME_TASK_STATUS.active;
    const completed = readTaskMetadataField(state.source, "Completed");
    const implementationComplete = readTaskMetadataField(state.source, "Implementation Complete");
    const allLeavesLanded = childLeaves.every(({ landed }) => landed);
    if (expectedStatus === RESUME_TASK_STATUS.done) {
      requireCanonicalCompleted(completed, label + " TASK-" + childId);
    } else {
      requireAbsentCompleted(completed, label + " TASK-" + childId);
    }
    if (allLeavesLanded) {
      requireCanonicalImplementationComplete(implementationComplete, label + " TASK-" + childId);
    } else {
      requireAbsentImplementationComplete(implementationComplete, label + " TASK-" + childId);
    }
    if (
      state.status !== expectedStatus ||
      (expectedStatus === RESUME_TASK_STATUS.done && !allowCoveredDone) ||
      readTaskGateReceipts(state.source).length !== 0 ||
      readTaskMetadataField(state.source, "Repair Pending")
    ) {
      throw new Error(label + ": child graph coverage mismatch for TASK-" + childId);
    }
    if (
      !closurePathSet.has(group.childPath) &&
      CLOSURE_RECEIPT_FIELDS.some((field) => readTaskMetadataField(state.source, field))
    ) {
      throw new Error(label + ": source child retained closure-only authority: TASK-" + childId);
    }
    for (const leafId of leafIds) {
      requireTableStatus(state.source, leafId, leafById.get(leafId).status, label + " child");
    }
  }

  const rootState = taskStates.get(ROOT_TASK_PATH);
  const childStates = CHILD_IDS_IN_LAND_ORDER.map((childId) => {
    const leafId = LEAF_ORDER.find(
      (candidate) => LEAF_STATUS_GROUPS[candidate].childId === childId
    );
    return taskStates.get(LEAF_STATUS_GROUPS[leafId].childPath);
  });
  const expectedRootStatus = childStates.every(({ status }) => status === RESUME_TASK_STATUS.done)
    ? RESUME_TASK_STATUS.done
    : RESUME_TASK_STATUS.active;
  const persistedRootCompleted = readTaskMetadataField(rootState.source, "Completed");
  const persistedRootImplementationComplete = readTaskMetadataField(
    rootState.source,
    "Implementation Complete"
  );
  if (expectedRootStatus === RESUME_TASK_STATUS.done) {
    requireCanonicalCompleted(persistedRootCompleted, label + " root");
  } else {
    requireAbsentCompleted(persistedRootCompleted, label + " root");
  }
  requireAbsentImplementationComplete(persistedRootImplementationComplete, label + " root");
  if (
    rootState.status !== expectedRootStatus ||
    (expectedRootStatus === RESUME_TASK_STATUS.done && !allowCoveredDone) ||
    readTaskGateReceipts(rootState.source).length !== 0 ||
    readTaskMetadataField(rootState.source, "Repair Pending")
  ) {
    throw new Error(label + ": root graph coverage mismatch");
  }
  for (let index = 0; index < CHILD_IDS_IN_LAND_ORDER.length; index += 1) {
    requireTableStatus(
      rootState.source,
      CHILD_IDS_IN_LAND_ORDER[index],
      childStates[index].status,
      label + " root"
    );
  }

  const boardState = readTask540BoardState(await readFile(TASKS + "/README.md", "utf8"));
  const expectedBoardBucket =
    expectedRootStatus === RESUME_TASK_STATUS.done ? "done" : "inProgress";
  if (boardState.bucket !== expectedBoardBucket) {
    throw new Error(label + ": board bucket does not match the covered graph");
  }
  const statusByPath = Object.freeze(
    Object.fromEntries(
      FAMILY_STATUS_ORDER.map((relativePath) => [relativePath, taskStates.get(relativePath).status])
    )
  );
  const completedByPath = Object.freeze(
    Object.fromEntries(
      FAMILY_STATUS_ORDER.map((relativePath) => [
        relativePath,
        readTaskMetadataField(taskStates.get(relativePath).source, "Completed"),
      ])
    )
  );
  const activePaths = Object.freeze(
    FAMILY_STATUS_ORDER.filter(
      (relativePath) => statusByPath[relativePath] === RESUME_TASK_STATUS.active
    )
  );
  return Object.freeze({
    allowCoveredDone,
    leafSummary,
    statusByPath,
    completedByPath,
    activePaths,
    activeLeafIds: Object.freeze(
      LEAF_ORDER.filter(
        (leafId) => statusByPath[LEAF_STATUS_GROUPS[leafId].leafPath] === RESUME_TASK_STATUS.active
      )
    ),
    activeChildIds: Object.freeze(
      CHILD_IDS_IN_LAND_ORDER.filter((childId) => {
        const leafId = LEAF_ORDER.find(
          (candidate) => LEAF_STATUS_GROUPS[candidate].childId === childId
        );
        return statusByPath[LEAF_STATUS_GROUPS[leafId].childPath] === RESUME_TASK_STATUS.active;
      })
    ),
    allActive: activePaths.length === FAMILY_STATUS_ORDER.length,
  });
}

function implementationCompleteValue(date = RUN_DATE) {
  requireCanonicalReceiptDate(date, "TASK-540 Implementation Complete value");
  return date + IMPLEMENTATION_COMPLETE_SUFFIX;
}

function requireFinalCompletedForEntry(relativePath, value, entryGraph, label) {
  requireCanonicalCompleted(value, label + " " + relativePath);
  if (!entryGraph) return value;
  const priorStatus = entryGraph.statusByPath[relativePath];
  const priorCompleted = entryGraph.completedByPath[relativePath];
  if (priorStatus === RESUME_TASK_STATUS.active) {
    if (value !== RUN_DATE) {
      throw new Error(label + ": newly closed contract requires Completed " + RUN_DATE);
    }
    return value;
  }
  if (priorStatus === RESUME_TASK_STATUS.done) {
    requireCanonicalCompleted(priorCompleted, label + " historical " + relativePath);
    if (value !== priorCompleted) {
      throw new Error(label + ": covered Done contract changed historical Completed");
    }
    return value;
  }
  throw new Error(label + ": final entry status is not active or covered Done");
}

const STATUS_TRANSITION_FROZEN_TASK_INVARIANT =
  " The task board, non-target closure parent/leaf, sibling task files, every existing " +
  "metadata date, and every existing Modularity Repair Revalidated field are read-only " +
  "and must remain byte-identical. The root task is also byte-identical except for the exact " +
  "To-Do to In-Progress status cell of this direct child during a cold start. RUN_DATE applies " +
  "only to a newly inserted field whose " +
  "exact value is explicitly required by this transition. Never normalize, refresh, or " +
  "rewrite historical dates, receipts, prose, or already-correct active status rows.";

function statusTransitionAllowedFiles(group, { includeRoot = false } = {}) {
  if (
    !group ||
    typeof group.childPath !== "string" ||
    typeof group.leafPath !== "string" ||
    group.childPath === group.leafPath ||
    group.childPath === ROOT_TASK_PATH ||
    group.leafPath === ROOT_TASK_PATH
  ) {
    throw new Error("TASK-540 status transition file authority is invalid");
  }
  return Object.freeze([...(includeRoot ? [ROOT_TASK_PATH] : []), group.childPath, group.leafPath]);
}

function requireStatusTransitionStartField(beforeSource, afterSource, field, label) {
  const beforeValue = readTaskMetadataField(beforeSource, field);
  const afterValue = readTaskMetadataField(afterSource, field);
  if (beforeValue === null) {
    if (afterValue !== RUN_DATE) {
      throw new Error(label + ": newly inserted " + field + " must equal " + RUN_DATE);
    }
    return afterValue;
  }
  if (afterValue !== beforeValue) {
    throw new Error(label + ": existing " + field + " must remain byte-identical");
  }
  return afterValue;
}

const ORDINARY_GATE_RECEIPT_PREFIX = "orchestrator-local-v1 sha256 ";
const ORDINARY_GATE_RECEIPT_SUFFIX = " / gate green";

function requireOrdinaryGateReceiptValue(value, label) {
  if (
    typeof value !== "string" ||
    !/^orchestrator-local-v1 sha256 [0-9a-f]{64} \/ gate green$/u.test(value)
  ) {
    throw new Error(label + ": ordinary gate receipt is not canonical");
  }
  return value;
}

function transitionGateReceiptValue(gate, label) {
  if (
    !gate?.pass ||
    !Array.isArray(gate.commands) ||
    gate.commands.length === 0 ||
    gate.commands.some(
      (receipt) =>
        typeof receipt.id !== "string" ||
        typeof receipt.command !== "string" ||
        receipt.status !== 0 ||
        typeof receipt.stdoutSha256 !== "string" ||
        !/^[0-9a-f]{64}$/u.test(receipt.stdoutSha256) ||
        typeof receipt.stderrSha256 !== "string" ||
        !/^[0-9a-f]{64}$/u.test(receipt.stderrSha256) ||
        receipt.repository?.unchanged !== true
    ) ||
    gate.authority?.unchanged !== true
  ) {
    throw new Error(label + ": cannot issue a receipt for a non-green gate");
  }
  const projection = {
    commands: gate.commands.map((receipt) => ({
      id: receipt.id,
      command: receipt.command,
      status: receipt.status,
      stdoutSha256: receipt.stdoutSha256,
      stderrSha256: receipt.stderrSha256,
      repositoryUnchanged: receipt.repository.unchanged,
    })),
    lineCounts: (gate.lineCounts ?? []).map(({ path, lines, owner, sha256 }) => ({
      path,
      lines,
      owner,
      sha256,
    })),
  };
  return requireOrdinaryGateReceiptValue(
    ORDINARY_GATE_RECEIPT_PREFIX +
      createHash("sha256").update(JSON.stringify(projection)).digest("hex") +
      ORDINARY_GATE_RECEIPT_SUFFIX,
    label
  );
}

function snapshotRepairTransitionAuthority(
  leafSource,
  transition,
  reason,
  suppliedRepairPending,
  label
) {
  const repairPending = readTaskMetadataField(leafSource, "Repair Pending");
  const modularityRepairPending = readTaskMetadataField(leafSource, "Modularity Repair Pending");
  const modularityRequested = reason.includes("modularity-repair");
  if (suppliedRepairPending !== repairPending) {
    throw new Error(label + ": supplied Repair Pending differs from the transaction snapshot");
  }
  if (
    (repairPending !== null && transition !== "complete") ||
    (modularityRepairPending !== null && repairPending === null) ||
    modularityRequested !== (modularityRepairPending !== null)
  ) {
    throw new Error(label + ": repair/modularity transition authority is stale or inconsistent");
  }
  if (repairPending !== null) parseRepairPending(repairPending, label);
  return Object.freeze({
    repairPending,
    modularityRepairPending,
    repairCompletion: transition === "complete" && repairPending !== null,
    modularityCompletion:
      transition === "complete" && repairPending !== null && modularityRepairPending !== null,
  });
}

function assertTask540StatusTransitionIsolationContract() {
  const group = LEAF_STATUS_GROUPS["540-04-L03"];
  const allowedFiles = statusTransitionAllowedFiles(group);
  const closureGroup = LEAF_STATUS_GROUPS["540-06-L01"];
  const existingStartSource =
    "**Status:** 🚧 In Progress\n" +
    "**Started:** 2026-07-17\n\n" +
    "| ID | Title | Status |\n" +
    "| --- | --- | --- |\n" +
    "| TASK-540-04-L03 | Entry guard | 🚧 In Progress |\n";
  const absentStartSource = existingStartSource.replace("**Started:** 2026-07-17\n", "");
  const frozenMutation = Object.freeze({
    mutableStatus: false,
    tableTaskIds: Object.freeze([]),
    tableStatusTaskIds: Object.freeze([]),
    mutableFields: Object.freeze([]),
  });
  const insertStartMutation = Object.freeze({
    mutableStatus: false,
    tableTaskIds: Object.freeze([]),
    tableStatusTaskIds: Object.freeze([]),
    mutableFields: Object.freeze(["Started"]),
  });
  const frozenProjection = projectTaskContractUnrelatedBytes(
    existingStartSource,
    frozenMutation,
    "TASK-540 status isolation fixture"
  );
  const insertedStartSource = absentStartSource.replace(
    "\n\n| ID |",
    "\n**Started:** " + RUN_DATE + "\n\n| ID |"
  );
  const coldTodoSource = absentStartSource.replaceAll(
    RESUME_TASK_STATUS.active,
    RESUME_TASK_STATUS.todo
  );
  const coldActiveSource = insertedStartSource;
  const coldActivationMutation = Object.freeze({
    mutableStatus: true,
    tableTaskIds: Object.freeze([]),
    tableStatusTaskIds: Object.freeze(["540-04-L03"]),
    mutableFields: Object.freeze(["Started"]),
  });
  const gateHash = "a".repeat(64);
  const ordinaryGateValue = transitionGateReceiptValue(
    Object.freeze({
      pass: true,
      commands: Object.freeze([
        Object.freeze({
          id: "fixture",
          command: "node --check fixture.mjs",
          status: 0,
          stdoutSha256: gateHash,
          stderrSha256: gateHash,
          repository: Object.freeze({ unchanged: true }),
        }),
      ]),
      lineCounts: Object.freeze([]),
      authority: Object.freeze({ unchanged: true }),
    }),
    "TASK-540 status isolation fixture gate"
  );
  const repairPendingFixture = "generation " + "1".repeat(32) + " / token " + "2".repeat(32);
  const otherRepairPendingFixture = "generation " + "3".repeat(32) + " / token " + "4".repeat(32);
  const repairLeafSource = absentStartSource.replace(
    "\n\n| ID |",
    "\n**Repair Pending:** " + repairPendingFixture + "\n\n| ID |"
  );
  const modularityRepairLeafSource = repairLeafSource.replace(
    "\n\n| ID |",
    "\n**Modularity Repair Pending:** cohesive split\n\n| ID |"
  );
  const rejectsStartField = (beforeSource, afterSource, expectedFragment) => {
    try {
      requireStatusTransitionStartField(
        beforeSource,
        afterSource,
        "Started",
        "TASK-540 status isolation fixture"
      );
      return false;
    } catch (error) {
      return error instanceof Error && error.message.includes(expectedFragment);
    }
  };
  const rejectsRepairAuthority = (source, reason, supplied, expectedFragment) => {
    try {
      snapshotRepairTransitionAuthority(
        source,
        "complete",
        reason,
        supplied,
        "TASK-540 status isolation repair fixture"
      );
      return false;
    } catch (error) {
      return error instanceof Error && error.message.includes(expectedFragment);
    }
  };
  const cases = [
    {
      label: "status transition owns only its direct parent and leaf",
      pass: sameUniqueSet(allowedFiles, [group.childPath, group.leafPath]),
    },
    {
      label: "status transition freezes the root task",
      pass: !allowedFiles.includes(ROOT_TASK_PATH),
    },
    {
      label: "source status transition freezes closure task contracts",
      pass:
        !allowedFiles.includes(closureGroup.childPath) &&
        !allowedFiles.includes(closureGroup.leafPath),
    },
    {
      label: "cold child activation conditionally owns the root table",
      pass: sameUniqueSet(statusTransitionAllowedFiles(group, { includeRoot: true }), [
        ROOT_TASK_PATH,
        group.childPath,
        group.leafPath,
      ]),
    },
    {
      label: "status rollback snapshots the complete task family and board",
      pass: sameUniqueSet(FULL_STATUS_ROLLBACK_PATHS, [...TASK_PATHS, "_docs/_TASKS/README.md"]),
    },
    {
      label: "status prompt freezes existing metadata dates",
      pass:
        STATUS_TRANSITION_FROZEN_TASK_INVARIANT.includes("every existing metadata date") &&
        STATUS_TRANSITION_FROZEN_TASK_INVARIANT.includes("remain byte-identical"),
    },
    {
      label: "status prompt forbids historical receipt normalization",
      pass:
        STATUS_TRANSITION_FROZEN_TASK_INVARIANT.includes("Never normalize") &&
        STATUS_TRANSITION_FROZEN_TASK_INVARIANT.includes("Modularity Repair Revalidated"),
    },
    {
      label: "frozen status-line mutation is detected",
      pass:
        projectTaskContractUnrelatedBytes(
          existingStartSource.replace("🚧 In Progress", "✅ Done"),
          frozenMutation,
          "TASK-540 status isolation fixture"
        ) !== frozenProjection,
    },
    {
      label: "frozen non-status table-cell mutation is detected",
      pass:
        projectTaskContractUnrelatedBytes(
          existingStartSource.replace("Entry guard", "Changed title"),
          frozenMutation,
          "TASK-540 status isolation fixture"
        ) !== frozenProjection,
    },
    {
      label: "existing start-date mutation is detected by projection",
      pass:
        projectTaskContractUnrelatedBytes(
          existingStartSource.replace("2026-07-17", RUN_DATE),
          frozenMutation,
          "TASK-540 status isolation fixture"
        ) !== frozenProjection,
    },
    {
      label: "absent start field permits only its projected insertion",
      pass:
        projectTaskContractUnrelatedBytes(
          absentStartSource,
          insertStartMutation,
          "TASK-540 status isolation fixture"
        ) ===
        projectTaskContractUnrelatedBytes(
          insertedStartSource,
          insertStartMutation,
          "TASK-540 status isolation fixture"
        ),
    },
    {
      label: "cold To-Do activation projects only exact status cells and start insertion",
      pass:
        projectTaskContractUnrelatedBytes(
          coldTodoSource,
          coldActivationMutation,
          "TASK-540 cold activation fixture"
        ) ===
        projectTaskContractUnrelatedBytes(
          coldActiveSource,
          coldActivationMutation,
          "TASK-540 cold activation fixture"
        ),
    },
    {
      label: "cold activation still detects unrelated table-cell edits",
      pass:
        projectTaskContractUnrelatedBytes(
          coldTodoSource,
          coldActivationMutation,
          "TASK-540 cold activation fixture"
        ) !==
        projectTaskContractUnrelatedBytes(
          coldActiveSource.replace("Entry guard", "Changed title"),
          coldActivationMutation,
          "TASK-540 cold activation fixture"
        ),
    },
    {
      label: "exact required start insertion is accepted",
      pass:
        requireStatusTransitionStartField(
          absentStartSource,
          insertedStartSource,
          "Started",
          "TASK-540 status isolation fixture"
        ) === RUN_DATE,
    },
    {
      label: "missing required start insertion is rejected",
      pass: rejectsStartField(absentStartSource, absentStartSource, "must equal"),
    },
    {
      label: "wrong required start insertion is rejected",
      pass: rejectsStartField(
        absentStartSource,
        insertedStartSource.replace(RUN_DATE, "2026-07-16"),
        "must equal"
      ),
    },
    {
      label: "existing start date rewrite is rejected explicitly",
      pass: rejectsStartField(
        existingStartSource,
        existingStartSource.replace("2026-07-17", RUN_DATE),
        "remain byte-identical"
      ),
    },
    {
      label: "ordinary completion gate receipt is byte-canonical",
      pass:
        requireOrdinaryGateReceiptValue(
          ordinaryGateValue,
          "TASK-540 status isolation fixture gate"
        ) === ordinaryGateValue,
    },
    {
      label: "arbitrary ordinary completion gate receipt is rejected",
      pass: (() => {
        try {
          requireOrdinaryGateReceiptValue("bogus", "TASK-540 status isolation fixture gate");
          return false;
        } catch (error) {
          return error instanceof Error && error.message.includes("not canonical");
        }
      })(),
    },
    {
      label: "non-green gate cannot issue a completion receipt",
      pass: (() => {
        try {
          transitionGateReceiptValue(
            Object.freeze({ pass: false, commands: Object.freeze([]) }),
            "TASK-540 status isolation fixture gate"
          );
          return false;
        } catch (error) {
          return error instanceof Error && error.message.includes("non-green gate");
        }
      })(),
    },
    {
      label: "snapshot repair token authorizes only its exact completion",
      pass:
        snapshotRepairTransitionAuthority(
          repairLeafSource,
          "complete",
          "repair-resume-regate-green",
          repairPendingFixture,
          "TASK-540 status isolation repair fixture"
        ).repairPending === repairPendingFixture,
    },
    {
      label: "stale-null repair authority is rejected",
      pass: rejectsRepairAuthority(
        repairLeafSource,
        "repair-resume-regate-green",
        null,
        "differs from the transaction snapshot"
      ),
    },
    {
      label: "stale-token repair authority is rejected",
      pass: rejectsRepairAuthority(
        repairLeafSource,
        "repair-resume-regate-green",
        otherRepairPendingFixture,
        "differs from the transaction snapshot"
      ),
    },
    {
      label: "stale modularity omission is rejected",
      pass: rejectsRepairAuthority(
        modularityRepairLeafSource,
        "repair-resume-regate-green",
        repairPendingFixture,
        "stale or inconsistent"
      ),
    },
    {
      label: "stale modularity request is rejected",
      pass: rejectsRepairAuthority(
        repairLeafSource,
        "modularity-repair-resume-regate-green",
        repairPendingFixture,
        "stale or inconsistent"
      ),
    },
  ];
  for (const testCase of cases) {
    if (!testCase.pass) {
      throw new Error("TASK-540 status transition isolation self-test failed: " + testCase.label);
    }
  }
  return cases.length;
}

async function transitionLeafStatus(
  leaf,
  transition,
  reason,
  suppliedRepairPending = null,
  exactGateReceiptValue = null
) {
  const group = LEAF_STATUS_GROUPS[leaf.id];
  if (!group) throw new Error("Missing status group for " + leaf.id);
  const expectedLeafStatus = RESUME_TASK_STATUS.active;
  const expectedChildStatus = RESUME_TASK_STATUS.active;
  const rollbackOwner = Object.freeze({
    id: "status-" + leaf.id + "-rollback",
    allowedFiles: FULL_STATUS_ROLLBACK_PATHS,
    requiredFiles: Object.freeze([]),
  });
  const transactionSnapshot = await captureExactRollbackFiles(
    rollbackOwner.allowedFiles,
    "TASK-540 transition pre-dispatch " + leaf.id + ":" + transition
  );
  const childSourceBefore = requireExactRollbackSnapshotUtf8(
    transactionSnapshot,
    group.childPath,
    "TASK-540 status transition child prestate"
  );
  const leafSourceBefore = requireExactRollbackSnapshotUtf8(
    transactionSnapshot,
    group.leafPath,
    "TASK-540 status transition leaf prestate"
  );
  const rootSourceBefore = requireExactRollbackSnapshotUtf8(
    transactionSnapshot,
    ROOT_TASK_PATH,
    "TASK-540 status transition root prestate"
  );
  const childStatusBefore = parseCanonicalTaskStatusSource(
    childSourceBefore,
    group.childPath
  ).status;
  const leafStatusBefore = parseCanonicalTaskStatusSource(leafSourceBefore, group.leafPath).status;
  const childTableRowBefore = readCanonicalTaskStatusTableRow(
    childSourceBefore,
    leaf.id,
    "TASK-540 status transition child prestate"
  );
  const leafTableStatusBefore = childTableRowBefore.cells.at(-1);
  const rootStatusBefore = parseCanonicalTaskStatusSource(rootSourceBefore, ROOT_TASK_PATH).status;
  const childTableStatusBefore = readCanonicalTaskStatusTableRow(
    rootSourceBefore,
    group.childId,
    "TASK-540 status transition root prestate"
  ).cells.at(-1);
  const validPreStatus = (status) =>
    status === RESUME_TASK_STATUS.active ||
    (transition === "start" && status === RESUME_TASK_STATUS.todo);
  if (
    rootStatusBefore !== RESUME_TASK_STATUS.active ||
    !validPreStatus(childStatusBefore) ||
    !validPreStatus(leafStatusBefore) ||
    leafTableStatusBefore !== leafStatusBefore ||
    childTableStatusBefore !== childStatusBefore
  ) {
    throw new Error("TASK-540 status transition prestate is not an exact active/To-Do frontier");
  }
  const closureReceiptsBefore = captureClosureContractReceiptsFromSnapshot(
    transactionSnapshot,
    "TASK-540 status transition closure prestate"
  );
  const repairAuthority = snapshotRepairTransitionAuthority(
    leafSourceBefore,
    transition,
    reason,
    suppliedRepairPending,
    "TASK-540 status transition " + leaf.id
  );
  const repairPending = repairAuthority.repairPending;
  const repairCompletion = repairAuthority.repairCompletion;
  const modularityCompletion = repairAuthority.modularityCompletion;
  const modularityRevalidatedValue =
    RUN_DATE + " — cohesive <=1,000-line split and exact owner gate passed.";
  const siblingStates = group.leafIds.map((leafId) => {
    if (leafId === leaf.id) {
      return { id: leafId, status: expectedLeafStatus, landed: transition === "complete" };
    }
    const siblingGroup = LEAF_STATUS_GROUPS[leafId];
    const siblingState = parseCanonicalTaskStatusSource(
      requireExactRollbackSnapshotUtf8(
        transactionSnapshot,
        siblingGroup.leafPath,
        "TASK-540 status transition sibling prestate"
      ),
      siblingGroup.leafPath
    );
    const targetedGate = readTaskMetadataField(siblingState.source, "Targeted Gate Passed");
    const revalidation = readTaskMetadataField(siblingState.source, "Revalidation Passed");
    return {
      id: leafId,
      status: siblingState.status,
      landed:
        siblingState.status === RESUME_TASK_STATUS.done ||
        (siblingState.status === RESUME_TASK_STATUS.active &&
          !readTaskMetadataField(siblingState.source, "Repair Pending") &&
          !readTaskMetadataField(siblingState.source, "Modularity Repair Pending") &&
          Boolean(targetedGate) !== Boolean(revalidation)),
    };
  });
  const childImplementationComplete = siblingStates.every(({ landed }) => landed);
  const exactImplementationComplete = implementationCompleteValue();
  const startMetadataField = reason.includes("repair") ? "Fix Started" : "Started";
  const childMutableFields =
    transition === "start"
      ? readTaskMetadataField(childSourceBefore, startMetadataField) === null
        ? [startMetadataField]
        : []
      : childImplementationComplete
        ? [
            "Implementation Complete",
            ...(modularityCompletion
              ? ["Modularity Repair Pending", "Modularity Repair Revalidated"]
              : []),
          ]
        : [];
  const leafGateMutableFields = [
    "Implementation Complete",
    "Targeted Gate Passed",
    "Revalidation Passed",
    "Repair Pending",
    ...(modularityCompletion ? ["Modularity Repair Pending", "Modularity Repair Revalidated"] : []),
  ];
  const leafMutableFields =
    transition === "start"
      ? readTaskMetadataField(leafSourceBefore, startMetadataField) === null
        ? [startMetadataField]
        : []
      : leafGateMutableFields;
  const owner = Object.freeze({
    id: "status-" + leaf.id,
    allowedFiles: statusTransitionAllowedFiles(group, {
      includeRoot: childTableStatusBefore !== expectedChildStatus,
    }),
    requiredFiles: Object.freeze([]),
    taskContractMutations: Object.freeze([
      ...(childTableStatusBefore === expectedChildStatus
        ? []
        : [
            Object.freeze({
              relativePath: ROOT_TASK_PATH,
              mutableStatus: false,
              tableTaskIds: [],
              tableStatusTaskIds: Object.freeze([group.childId]),
              mutableFields: Object.freeze([]),
            }),
          ]),
      Object.freeze({
        relativePath: group.childPath,
        mutableStatus: childStatusBefore !== expectedChildStatus,
        tableTaskIds: [],
        tableStatusTaskIds:
          leafTableStatusBefore === expectedLeafStatus ? [] : Object.freeze([leaf.id]),
        mutableFields: Object.freeze([...new Set(childMutableFields)]),
      }),
      Object.freeze({
        relativePath: group.leafPath,
        mutableStatus: leafStatusBefore !== expectedLeafStatus,
        tableTaskIds: [],
        tableStatusTaskIds: [],
        mutableFields: Object.freeze([...new Set(leafMutableFields)]),
      }),
    ]),
  });
  const statusTransitionProjectionBefore = Object.freeze(
    Object.fromEntries(
      owner.taskContractMutations.map((mutation) => [
        mutation.relativePath,
        projectTaskContractUnrelatedBytes(
          requireExactRollbackSnapshotUtf8(
            transactionSnapshot,
            mutation.relativePath,
            "TASK-540 status transition owned projection prestate"
          ),
          mutation,
          "TASK-540 status transition owned projection prestate"
        ),
      ])
    )
  );
  const verifyOwnedStatusTransitionProjections = async (label) => {
    for (const mutation of owner.taskContractMutations) {
      const actual = projectTaskContractUnrelatedBytes(
        await readFile(ROOT + "/" + mutation.relativePath, "utf8"),
        mutation,
        label
      );
      if (actual !== statusTransitionProjectionBefore[mutation.relativePath]) {
        throw new Error(
          label + ": owned task contract changed outside its snapshot-derived authority"
        );
      }
    }
  };
  const frozenStatusTransitionPaths = rollbackOwner.allowedFiles.filter(
    (relativePath) => !owner.allowedFiles.includes(relativePath)
  );
  const preClosureFixStartedDate =
    transition === "complete" &&
    leaf.id === "540-06-L01" &&
    !repairPending &&
    reason.includes("regate")
      ? matchingPreClosureFixStartedDate(
          requireExactRollbackSnapshotUtf8(
            transactionSnapshot,
            group.childPath,
            "TASK-540 pre-closure re-gate transition"
          ),
          requireExactRollbackSnapshotUtf8(
            transactionSnapshot,
            group.leafPath,
            "TASK-540 pre-closure re-gate transition"
          ),
          "TASK-540 pre-closure re-gate transition"
        )
      : null;
  const preClosureGateValue = preClosureFixStartedDate
    ? preClosureRegateValue(preClosureFixStartedDate)
    : null;
  const requiredGateReceiptValue =
    transition !== "complete"
      ? null
      : repairCompletion
        ? repairGateValue(repairPending)
        : (preClosureGateValue ??
          requireOrdinaryGateReceiptValue(
            exactGateReceiptValue,
            "TASK-540 status transition " + leaf.id
          ));
  if (
    (transition === "start" && exactGateReceiptValue !== null) ||
    (transition === "complete" && exactGateReceiptValue !== requiredGateReceiptValue)
  ) {
    throw new Error("TASK-540 status transition gate receipt authority mismatch for " + leaf.id);
  }
  const requiresColdActivation =
    childStatusBefore !== expectedChildStatus ||
    leafStatusBefore !== expectedLeafStatus ||
    childTableStatusBefore !== expectedChildStatus ||
    leafTableStatusBefore !== expectedLeafStatus;
  const action =
    transition === "start"
      ? requiresColdActivation
        ? "Activate only the exact To-Do leaf/direct-child status fields and their exact parent-table status cells as In Progress; add Started for first implementation or Fix Started for a verified repair only when that field is currently absent."
        : "Keep the exact leaf and its child In Progress before implementation/fix; add Started for first implementation or Fix Started for a verified repair only when that field is currently absent."
      : repairCompletion
        ? "Keep the exact repaired leaf and its child In Progress, remove the leaf's exact Repair Pending and old gate receipts, and record its canonical Implementation Complete plus one fresh matching Revalidation Passed receipt for this repair generation/token."
        : reason.includes("regate")
          ? "Keep the exact leaf and its child In Progress, record canonical Implementation Complete, remove the opposite/stale gate receipt, and add one dedicated Revalidation Passed field with the green re-gate evidence."
          : "Keep the exact leaf and its child In Progress, record canonical Implementation Complete, remove the opposite/stale gate receipt, and add one dedicated Targeted Gate Passed field with the green targeted-gate evidence.";

  let transitionMutationError = null;
  try {
    await verifyExactRollbackFiles(
      transactionSnapshot,
      "TASK-540 status transition exact pre-dispatch state " + leaf.id
    );
    await runMutatingAgent(
      "Repository " +
        ROOT +
        ". TASK-540 task-state transition only. " +
        action +
        " Read the root parent, exact child, exact leaf, and _docs/_TASKS/README.md fresh. " +
        STATUS_TRANSITION_FROZEN_TASK_INVARIANT +
        "Edit only " +
        JSON.stringify(owner.allowedFiles) +
        ". The required exact post-transition statuses are leaf=" +
        expectedLeafStatus +
        ", child=" +
        expectedChildStatus +
        ", root=🚧 In Progress." +
        (transition === "start"
          ? " For the child and leaf independently, preserve any existing exact `**" +
            startMetadataField +
            ":**` value; only where absent, insert exact `**" +
            startMetadataField +
            ":** " +
            RUN_DATE +
            "`."
          : "") +
        (transition === "complete"
          ? " Write exact leaf field `**Implementation Complete:** " +
            exactImplementationComplete +
            "`. " +
            (childImplementationComplete
              ? "Every physical leaf under the direct child is now landed, so write the same exact Implementation Complete field on that child."
              : "The direct child is not fully landed, so it must not carry Implementation Complete.")
          : "") +
        (repairCompletion
          ? " The leaf's exact current `**Repair Pending:** " +
            repairPending +
            "` must be removed atomically only now, after the green gate. Remove any Targeted Gate Passed value and write `**Revalidation Passed:** " +
            requiredGateReceiptValue +
            "` exactly; a different or stale generation/token is invalid."
          : preClosureGateValue
            ? " Remove any Targeted Gate Passed and Repair Pending value and write exact `**Revalidation Passed:** " +
              requiredGateReceiptValue +
              "` from the persisted matching child/leaf Fix Started date. A different date or value is invalid."
            : transition === "complete"
              ? " Write exact `**" +
                (reason.includes("regate") ? "Revalidation Passed" : "Targeted Gate Passed") +
                ":** " +
                requiredGateReceiptValue +
                "`; missing, arbitrary, or stale evidence is invalid."
              : "") +
        (modularityCompletion
          ? " Remove the exact leaf's Modularity Repair Pending field and write exact `**Modularity Repair Revalidated:** " +
            modularityRevalidatedValue +
            "`. " +
            (childImplementationComplete
              ? "All direct-child leaves now have current gates, so remove the child's Modularity Repair Pending field and write the same exact Modularity Repair Revalidated value there."
              : "Other direct-child modularity work remains, so preserve the child's Modularity Repair Pending field and do not add Modularity Repair Revalidated there.")
          : "") +
        (requiresColdActivation
          ? " Change only the exact To-Do status cells required above; every non-status table cell and every already-active status cell must remain byte-identical."
          : " The child leaf-status table and root subtask-status table already have the required active values and must remain byte-identical.") +
        " Keep TASK-540's board " +
        "row/statistics byte-identical and In Progress. Preserve every " +
        "unrelated descendant status byte-identically. Use canonical " +
        "status fields and dedicated Started/Fix Started/Implementation Complete/Targeted Gate Passed/Revalidation Passed fields " +
        "with only the exact new values stated above; do not put dates in **Status:**. Do not edit source, tests, docs outside these task " +
        "files, board, workflow, changelog, or another task. Never stage or commit. Transition " +
        "reason: " +
        reason +
        ".",
      { label: "status:" + leaf.id + ":" + transition + ":" + reason, phase: leaf.phase },
      owner,
      false
    );
    await verifyOwnedStatusTransitionProjections(
      "TASK-540 status transition owned post-dispatch state " + leaf.id
    );
    await verifyExactRollbackFileSubset(
      transactionSnapshot,
      frozenStatusTransitionPaths,
      "TASK-540 status transition frozen post-dispatch state " + leaf.id
    );
  } catch (error) {
    transitionMutationError = error;
  }

  let transitionVerificationError = null;
  let verifiedClosureGateReceipt = null;
  try {
    await verifyOwnedStatusTransitionProjections(
      "TASK-540 status transition owned verification state " + leaf.id
    );
    await verifyExactRollbackFileSubset(
      transactionSnapshot,
      frozenStatusTransitionPaths,
      "TASK-540 status transition frozen verification state " + leaf.id
    );
    const [rootState, childState, leafState, boardSource] = await Promise.all([
      readCanonicalTaskStatus(ROOT_TASK_PATH),
      readCanonicalTaskStatus(group.childPath),
      readCanonicalTaskStatus(group.leafPath),
      readFile(TASKS + "/README.md", "utf8"),
    ]);
    if (rootState.status !== "🚧 In Progress" || leafState.status !== expectedLeafStatus) {
      throw new Error("TASK-540 status transition field mismatch for " + leaf.id);
    }
    requireAbsentCompleted(
      readTaskMetadataField(rootState.source, "Completed"),
      "TASK-540 active root after transition " + leaf.id
    );
    requireAbsentImplementationComplete(
      readTaskMetadataField(rootState.source, "Implementation Complete"),
      "TASK-540 active root after transition " + leaf.id
    );
    if (childState.status !== expectedChildStatus) {
      throw new Error("TASK-540 child status transition mismatch for " + group.childId);
    }
    requireAbsentCompleted(
      readTaskMetadataField(leafState.source, "Completed"),
      "TASK-540 active leaf " + leaf.id
    );
    requireAbsentCompleted(
      readTaskMetadataField(childState.source, "Completed"),
      "TASK-540 active child " + group.childId
    );
    requireTableStatus(childState.source, leaf.id, expectedLeafStatus, "TASK-540 child");
    requireTableStatus(rootState.source, group.childId, expectedChildStatus, "TASK-540 root");
    if (transition === "complete") {
      const gateReceipt = readTaskGateReceipt(
        leafState.source,
        "TASK-540 landed transition " + leaf.id
      );
      const expectedGateField =
        repairCompletion || preClosureGateValue || reason.includes("regate")
          ? "Revalidation Passed"
          : "Targeted Gate Passed";
      const expectedGateValue = repairCompletion
        ? repairGateValue(repairPending)
        : requiredGateReceiptValue;
      if (gateReceipt.field !== expectedGateField || gateReceipt.value !== expectedGateValue) {
        throw new Error("TASK-540 missing gate evidence field for " + leaf.id);
      }
      if (
        readTaskMetadataField(leafState.source, "Implementation Complete") !==
          exactImplementationComplete ||
        Boolean(readTaskMetadataField(childState.source, "Implementation Complete")) !==
          childImplementationComplete ||
        (childImplementationComplete &&
          readTaskMetadataField(childState.source, "Implementation Complete") !==
            exactImplementationComplete)
      ) {
        throw new Error("TASK-540 missing canonical Implementation Complete for " + leaf.id);
      }
      if (leaf.id === "540-06-L01") {
        const currentGateReceipt = gateReceipt;
        const mayReplacePinnedGate =
          !closureLeafGateReceipt || repairCompletion || reason.includes("regate");
        if (
          closureLeafGateReceipt &&
          !equalClosureGateReceipts(closureLeafGateReceipt, currentGateReceipt) &&
          !mayReplacePinnedGate
        ) {
          throw new Error("TASK-540 closure leaf transition changed its pinned gate receipt");
        }
        verifiedClosureGateReceipt = currentGateReceipt;
      }
      if (
        repairCompletion &&
        (readTaskMetadataField(leafState.source, "Repair Pending") ||
          readTaskMetadataField(leafState.source, "Targeted Gate Passed"))
      ) {
        throw new Error(
          "TASK-540 repaired leaf retained stale pending/targeted evidence: " + leaf.id
        );
      }
      if (
        modularityCompletion &&
        (readTaskMetadataField(leafState.source, "Modularity Repair Pending") ||
          readTaskMetadataField(leafState.source, "Modularity Repair Revalidated") !==
            modularityRevalidatedValue ||
          (childImplementationComplete
            ? readTaskMetadataField(childState.source, "Modularity Repair Pending") ||
              readTaskMetadataField(childState.source, "Modularity Repair Revalidated") !==
                modularityRevalidatedValue
            : !readTaskMetadataField(childState.source, "Modularity Repair Pending") ||
              readTaskMetadataField(childState.source, "Modularity Repair Revalidated")))
      ) {
        throw new Error("TASK-540 modularity repair metadata did not close for " + leaf.id);
      }
      if (
        preClosureGateValue &&
        (readTaskMetadataField(leafState.source, "Repair Pending") ||
          readTaskMetadataField(leafState.source, "Targeted Gate Passed"))
      ) {
        throw new Error("TASK-540 pre-closure re-gate retained stale repair/gate evidence");
      }
      if (
        !repairCompletion &&
        !preClosureGateValue &&
        readTaskMetadataField(leafState.source, "Repair Pending")
      ) {
        throw new Error("TASK-540 landed leaf retained Repair Pending: " + leaf.id);
      }
    } else {
      requireStatusTransitionStartField(
        leafSourceBefore,
        leafState.source,
        startMetadataField,
        "TASK-540 starting leaf " + leaf.id
      );
      requireStatusTransitionStartField(
        childSourceBefore,
        childState.source,
        startMetadataField,
        "TASK-540 starting child " + group.childId
      );
      requireAbsentImplementationComplete(
        readTaskMetadataField(leafState.source, "Implementation Complete"),
        "TASK-540 starting leaf " + leaf.id
      );
      requireAbsentImplementationComplete(
        readTaskMetadataField(childState.source, "Implementation Complete"),
        "TASK-540 starting child " + group.childId
      );
    }
    const boardBefore = requireExactRollbackSnapshotUtf8(
      transactionSnapshot,
      "_docs/_TASKS/README.md",
      "TASK-540 task transition"
    );
    if (boardSource !== boardBefore) {
      throw new Error("TASK-540 task transition changed the board or its statistics");
    }
    const boardRow = boardSource.split("\n").find((line) => line.startsWith("| TASK-540 |"));
    if (!boardRow?.includes("🚧 In progress")) {
      throw new Error("TASK-540 board row left In Progress contract");
    }
    await verifyClosureContractReceipts(
      closureReceiptsBefore,
      "TASK-540 task transition " + leaf.id,
      { allowGateChange: transition === "complete" && leaf.id === "540-06-L01" }
    );
    await verifyExactRollbackFileSubset(
      transactionSnapshot,
      frozenStatusTransitionPaths,
      "TASK-540 status transition frozen final state " + leaf.id
    );
    await verifyOwnedStatusTransitionProjections(
      "TASK-540 status transition owned final state " + leaf.id
    );
  } catch (error) {
    transitionVerificationError = error;
  }

  if (transitionMutationError || transitionVerificationError) {
    const primaryError =
      transitionMutationError && transitionVerificationError
        ? new AggregateError(
            [transitionMutationError, transitionVerificationError],
            "TASK-540 task transition dispatch and persisted-state verification both failed"
          )
        : (transitionMutationError ?? transitionVerificationError);
    try {
      await restoreExactRollbackFiles(
        transactionSnapshot,
        rollbackOwner,
        "TASK-540 transition rollback " + leaf.id + ":" + transition
      );
    } catch (rollbackError) {
      throw new AggregateError(
        [primaryError, rollbackError],
        "TASK-540 task transition failure and exact transaction rollback both failed"
      );
    }
    throw primaryError;
  }
  if (verifiedClosureGateReceipt) {
    closureLeafGateReceipt = Object.freeze({ ...verifiedClosureGateReceipt });
  }
}

async function runLeafGate(
  leaf,
  attempt,
  phaseName = leaf.phase,
  { requireModularityCompleteness = false } = {}
) {
  void phaseName;
  const label = "gate:" + leaf.id + ":" + attempt;
  await rePinCorrectiveProtectedTests(leaf, label + ":protected-tests");
  await requireTask540TouchedModuleLineLimit(label + ":before-commands", leaf.allowedFiles);
  const execution = await runLocalCommandSequence(leaf.commands, { label });
  const lineCounts = await requireTask540TouchedModuleLineLimit(
    label + ":after-commands",
    leaf.allowedFiles
  );
  const completenessErrors = requireModularityCompleteness
    ? modularityRepairCompletenessErrors(leaf, lineCounts)
    : [];
  const settingsBaselineErrors =
    leaf.id === "540-06-L01" && !settingsHygieneBaselineUnchanged(execution.receipts, label)
      ? [leaf.id + ": settings hygiene changed the required smoke baseline"]
      : [];
  const failed = execution.failedReceipt;
  const pass =
    failed === null &&
    execution.receipts.length === leaf.commands.length &&
    execution.authority.unchanged &&
    completenessErrors.length === 0 &&
    settingsBaselineErrors.length === 0;
  const result = Object.freeze({
    pass,
    summary: pass
      ? leaf.id + " local gate passed"
      : leaf.id + " local gate stopped at " + (failed?.id ?? "unknown"),
    errors: pass
      ? []
      : [
          ...completenessErrors,
          ...settingsBaselineErrors,
          ...(failed === null
            ? []
            : [
                leaf.id +
                  ": orchestrator-local command failed: " +
                  (failed?.id ?? "repositoryFingerprint") +
                  " status=" +
                  (failed?.status ?? 1),
              ]),
        ],
    failureKind: pass ? "none" : failed === null ? "behavior" : localFailureKind(failed),
    failedCommand: pass
      ? null
      : (failed?.command ??
        (settingsBaselineErrors.length > 0 ? "settingsBaselineHygiene" : "modularityCompleteness")),
    commands: execution.receipts,
    isolationCommands: execution.isolationReceipts,
    lineCounts,
    authority: execution.authority,
  });
  if (pass && result.commands.some((receipt) => receipt.status !== 0)) {
    throw new Error(leaf.id + ": local gate attempted to authorize a non-green command");
  }
  return result;
}

function gateFailurePrompt(gate) {
  return gate.errors.join("\n- ");
}

async function implementAndGate(leaf) {
  phase(leaf.phase);
  await transitionLeafStatus(leaf, "start", "implementation");
  await runMutatingAgent(
    COMMON +
      "\n\nImplement exactly " +
      leaf.id +
      " from " +
      TASKS +
      "/" +
      leaf.taskFile +
      ". Edit only these exact single-writer paths: " +
      JSON.stringify(leaf.allowedFiles) +
      leafRestrictionPrompt(leaf) +
      ". Read every owned file fresh. Do not edit tasks, workflow, product docs, or " +
      "changelog in a source leaf; 540-06-L01 may edit only its declared aggregate test " +
      "and documentation paths. Return exact repo-relative touchedFiles.",
    { label: "impl:" + leaf.id, phase: leaf.phase },
    leaf
  );

  let gate = await runLeafGate(leaf, 1);
  for (let attempt = 1; !gate.pass && attempt <= 3; attempt += 1) {
    if (gate.failureKind === "infrastructure") {
      throw new Error(leaf.id + ": infrastructure gate failure: " + gate.errors.join("; "));
    }
    await runMutatingAgent(
      COMMON +
        "\n\nFix only the verified " +
        leaf.id +
        " gate defect within " +
        JSON.stringify(leaf.allowedFiles) +
        ". Do not weaken a behavior assertion. Failures:\n- " +
        gateFailurePrompt(gate) +
        leafRestrictionPrompt(leaf),
      { label: "fix:" + leaf.id + ":" + attempt, phase: leaf.phase },
      leaf,
      false
    );
    gate = await runLeafGate(leaf, attempt + 1);
  }
  if (!gate.pass) throw new Error(leaf.id + ": targeted gate remained red");
  await transitionLeafStatus(
    leaf,
    "complete",
    "targeted-gate-green",
    null,
    transitionGateReceiptValue(gate, "TASK-540 targeted gate " + leaf.id)
  );
}

async function resumeActiveUngatedLeaf(leaf) {
  phase(leaf.phase);
  const preClosureFixStartedDate = await readPersistedPreClosureFixStartedDate(
    leaf,
    "TASK-540 active ungated resume"
  );
  let gate = await runLeafGate(leaf, 1, leaf.phase);
  let behaviorFixRan = false;
  for (let attempt = 1; !gate.pass && attempt <= 3; attempt += 1) {
    if (gate.failureKind === "infrastructure") {
      throw new Error(leaf.id + ": active resume stopped on infrastructure failure");
    }
    behaviorFixRan = true;
    await runMutatingAgent(
      COMMON +
        "\n\nResume the already-active/no-gate " +
        leaf.id +
        " after its prior dispatch may have completed an allowed mutation. Fix only the verified " +
        "behavior failure within " +
        JSON.stringify(leaf.allowedFiles) +
        ". Do not require a file mutation, weaken assertions, edit task state, stage, or commit. " +
        "Failures:\n- " +
        gateFailurePrompt(gate) +
        leafRestrictionPrompt(leaf),
      { label: "resume-active-fix:" + leaf.id + ":" + attempt, phase: leaf.phase },
      leaf,
      false
    );
    gate = await runLeafGate(leaf, attempt + 1, leaf.phase);
  }
  if (!gate.pass) throw new Error(leaf.id + ": active/no-gate resume remained red");
  const exactGateReceiptValue = preClosureFixStartedDate
    ? preClosureRegateValue(preClosureFixStartedDate)
    : transitionGateReceiptValue(gate, "TASK-540 active resume gate " + leaf.id);
  await transitionLeafStatus(
    leaf,
    "complete",
    preClosureFixStartedDate
      ? "resume-pre-closure-regate-green"
      : behaviorFixRan
        ? "resume-regate-green"
        : "targeted-gate-green",
    null,
    exactGateReceiptValue
  );
}

async function resumeInterruptedRepair(resumeState) {
  const repair = resumeState.repair;
  const leaf = repair ? LEAF_BY_ID.get(repair.id) : null;
  if (!repair || !leaf) throw new Error("TASK-540 repair resume owner is missing");
  const persistedLeafState = await readCanonicalTaskStatus(LEAF_STATUS_GROUPS[leaf.id].leafPath);
  const modularityRepair = Boolean(
    readTaskMetadataField(persistedLeafState.source, "Modularity Repair Pending")
  );
  const repairOwner = modularityRepair
    ? modularityRepairMutationOwner(leaf)
    : effectiveRepairMutationOwner(leaf);
  const repairInvariant = await capturePersistedRepairInvariant(leaf, repair.pending);
  phase(leaf.phase);
  await runRepairMutationWithInvariant(
    COMMON +
      "\n\nResume only the persisted interrupted repair for " +
      leaf.id +
      " with exact `Repair Pending` receipt " +
      repair.pending +
      ". Re-read the entire exact leaf contract, current owned source/tests/docs and full diff, " +
      "then complete every still-missing behavior in that owner's contract." +
      (modularityRepair
        ? " This is the mandatory cohesive <=1,000-line modularity repair; preserve public contracts, test cardinality, and independently runnable lanes exactly."
        : "") +
      " Old gate receipts " +
      "were invalidated and may not be recreated here. Edit only " +
      JSON.stringify(repairOwner.allowedFiles) +
      leafRestrictionPrompt(leaf, { modularityRepair }) +
      ". Preserve every later Done leaf byte-identically. Return exact touchedFiles; no task, " +
      "board, changelog, workflow, stage, or commit changes.",
    { label: "repair-resume:" + leaf.id, phase: leaf.phase },
    repairOwner,
    leaf,
    repairInvariant,
    modularityRepair
  );

  let gate = await runLeafGate(leaf, 1, leaf.phase, {
    requireModularityCompleteness: modularityRepair,
  });
  for (let attempt = 1; !gate.pass && attempt <= 3; attempt += 1) {
    if (gate.failureKind === "infrastructure") {
      throw new Error(leaf.id + ": repair-resume infrastructure failure");
    }
    await runRepairMutationWithInvariant(
      COMMON +
        "\n\nFix only the persisted repair owner's verified gate defect within " +
        JSON.stringify(repairOwner.allowedFiles) +
        leafRestrictionPrompt(leaf, { modularityRepair }) +
        ". Do not weaken an assertion. Failures:\n- " +
        gateFailurePrompt(gate),
      { label: "repair-resume-fix:" + leaf.id + ":" + attempt, phase: leaf.phase },
      repairOwner,
      leaf,
      repairInvariant,
      false
    );
    gate = await runLeafGate(leaf, attempt + 1, leaf.phase, {
      requireModularityCompleteness: modularityRepair,
    });
  }
  if (!gate.pass) throw new Error(leaf.id + ": interrupted repair re-gate remained red");
  await transitionLeafStatus(
    leaf,
    "complete",
    modularityRepair ? "modularity-repair-resume-regate-green" : "repair-resume-regate-green",
    repair.pending,
    repairGateValue(repair.pending)
  );
}

function task540ModularityRepairAction({ leafId, modularityPending, repairPending, resumeState }) {
  if (!modularityPending) return "skip";
  if (!repairPending) return "reopen";
  if (
    resumeState?.mode !== "repair" ||
    resumeState.repair?.id !== leafId ||
    resumeState.repair?.pending !== repairPending
  ) {
    throw new Error("TASK-540 modularity repair pending owner/token drifted: " + leafId);
  }
  return "resume";
}

async function pendingTask540ModularityRepairLeafIds() {
  const pending = [];
  for (const leafId of MODULARITY_REPAIR_LEAF_IDS) {
    const group = LEAF_STATUS_GROUPS[leafId];
    const { source } = await readCanonicalTaskStatus(group.leafPath);
    if (readTaskMetadataField(source, "Modularity Repair Pending")) pending.push(leafId);
  }
  return Object.freeze(pending);
}

async function runTask540ModularityStartGate() {
  const pendingLeafIds = await pendingTask540ModularityRepairLeafIds();
  if (pendingLeafIds.length === 0) return;
  const result = await runReadOnlyAgent(
    "Read-only TASK-540 modularity-repair start gate at " +
      ROOT +
      ". Current pending owners in exact dependency order: " +
      JSON.stringify(pendingLeafIds) +
      ". Read root AGENTS.md, all " +
      PENDING_MODULARITY_REPAIR_TASK_FILES.length +
      " affected leaf contracts and every direct parent, TASK-540 root and closure contracts, " +
      "TASK-9999-01/L01 plus superseded L02, the complete current source/tests, workflow, " +
      "HEAD, status, " +
      "staged/unstaged diff, and target matrix fresh. Verify exact single-writer paths, public " +
      "facades, dependency directions, test no-loss/cardinality, line-count enforcement, restart " +
      "authority, security/cleanup invariants, and 540-01-L01 -> 540-02-L01 -> 540-03-L01 -> " +
      "540-04-L01 -> 540-04-L03 -> 540-04-L04 -> 540-05-L01 -> 540-05-L02 order. Pass only when " +
      "the contracts are implementation-ready with no HIGH/MEDIUM contradiction. Do not edit, " +
      "stage, commit, or run a mutating command.",
    { label: "start-gate:task-540-modularity", phase: "Start gate", schema: RESULT_SCHEMA }
  );
  if (!resultPassed(result)) {
    throw new Error("TASK-540 modularity start gate failed: " + result.errors.join("; "));
  }
}

async function runPendingTask540ModularityRepairs() {
  if (
    MODULARITY_REPAIR_LEAF_IDS.length !== PENDING_MODULARITY_REPAIR_TASK_FILES.length ||
    new Set(MODULARITY_REPAIR_LEAF_IDS).size !== MODULARITY_REPAIR_LEAF_IDS.length
  ) {
    throw new Error("TASK-540 modularity repair order is invalid");
  }
  const pendingLeafIds = await pendingTask540ModularityRepairLeafIds();
  if (pendingLeafIds.length > 0) {
    const initialResumeState = await resolveLeafResumeState();
    if (initialResumeState.mode === "repair") {
      await resumeInterruptedRepair(initialResumeState);
    }
  }
  for (let index = 0; index < MODULARITY_REPAIR_LEAF_IDS.length; index += 1) {
    const leafId = MODULARITY_REPAIR_LEAF_IDS[index];
    const leaf = LEAF_BY_ID.get(leafId);
    const expectedTaskFile = PENDING_MODULARITY_REPAIR_TASK_FILES[index];
    if (!leaf || leaf.taskFile !== expectedTaskFile) {
      throw new Error("TASK-540 modularity repair owner mapping drifted: " + leafId);
    }
    const leafState = await readCanonicalTaskStatus(LEAF_STATUS_GROUPS[leafId].leafPath);
    const modularityPending = readTaskMetadataField(leafState.source, "Modularity Repair Pending");
    const persistedRepairPending = readTaskMetadataField(leafState.source, "Repair Pending");
    const persistedResumeState = persistedRepairPending ? await resolveLeafResumeState() : null;
    const action = task540ModularityRepairAction({
      leafId,
      modularityPending,
      repairPending: persistedRepairPending,
      resumeState: persistedResumeState,
    });
    if (action === "skip") continue;
    if (action === "resume") {
      await resumeInterruptedRepair(persistedResumeState);
      continue;
    }
    await reopenLeafForRepair(leaf, "mandatory <=1,000-line modularity repair", leaf.phase);
    const resumeState = await resolveLeafResumeState();
    if (resumeState.mode !== "repair" || resumeState.repair?.id !== leafId) {
      throw new Error("TASK-540 modularity repair did not establish exact resume state: " + leafId);
    }
    await resumeInterruptedRepair(resumeState);
  }
  await requireNoPendingTask540ModularityRepairs("TASK-540 modularity repair phase");
  await synchronizeTask540ModularityFamilyMetadata();
  await requireTask540ModularityFamilyMetadata("TASK-540 modularity repair phase");
}

const FULL_VALIDATION_RESULT_KEYS = Object.freeze([
  "authority",
  "commands",
  "database",
  "errors",
  "isolationCommands",
  "lineCounts",
  "pass",
  "strictScan",
  "summary",
]);
const FULL_VALIDATION_DATABASE_KEYS = Object.freeze(["configured", "reachable", "selectOne"]);
const FULL_VALIDATION_AUTHORITY_KEYS = Object.freeze(["end", "runner", "start", "unchanged"]);
const FULL_VALIDATION_FINGERPRINT_KEYS = Object.freeze(["branch", "head", "worktreeSha256"]);
const FULL_VALIDATION_LINE_COUNT_KEYS = Object.freeze(["lines", "owner", "path", "sha256"]);

function requireExactFullValidationFingerprint(fingerprint, label) {
  requireExactStrictScanObjectKeys(fingerprint, FULL_VALIDATION_FINGERPRINT_KEYS, label);
  if (
    typeof fingerprint.head !== "string" ||
    !/^[0-9a-f]{40}$/u.test(fingerprint.head) ||
    fingerprint.branch !== EXPECTED_BRANCH ||
    typeof fingerprint.worktreeSha256 !== "string" ||
    !/^[0-9a-f]{64}$/u.test(fingerprint.worktreeSha256)
  ) {
    throw new Error(label + ": repository fingerprint is invalid");
  }
  return fingerprint;
}

function requireExactFullValidationCommandReceipt(receipt, expected, label) {
  requireStrictScanReceiptShape(receipt, label);
  requireExactFullValidationFingerprint(receipt.repository.start, label + " start");
  requireExactFullValidationFingerprint(receipt.repository.end, label + " end");
  if (
    receipt.runnerVersion !== "orchestrator-local-v1" ||
    receipt.id !== expected.id ||
    receipt.command !== expected.command ||
    receipt.status !== 0 ||
    receipt.signal !== null ||
    receipt.timedOut !== false ||
    receipt.outputLimitExceeded !== false ||
    receipt.stdoutTruncated !== false ||
    receipt.stderrTruncated !== false ||
    receipt.repository.unchanged !== true ||
    !Number.isSafeInteger(receipt.startedAtEpochMs) ||
    receipt.startedAtEpochMs < 0 ||
    !Number.isSafeInteger(receipt.endedAtEpochMs) ||
    receipt.endedAtEpochMs < receipt.startedAtEpochMs ||
    !Number.isSafeInteger(receipt.stdoutBytes) ||
    receipt.stdoutBytes < 0 ||
    !Number.isSafeInteger(receipt.stderrBytes) ||
    receipt.stderrBytes < 0 ||
    typeof receipt.stdoutSha256 !== "string" ||
    !/^[0-9a-f]{64}$/u.test(receipt.stdoutSha256) ||
    typeof receipt.stderrSha256 !== "string" ||
    !/^[0-9a-f]{64}$/u.test(receipt.stderrSha256)
  ) {
    throw new Error(label + ": command receipt values are invalid");
  }
  return receipt;
}

function requireTask540LineCountEvidence(lineCounts, label) {
  requireExactStrictScanArrayObserved(lineCounts, label + " line counts");
  for (const [index, lineCount] of lineCounts.entries()) {
    requireExactStrictScanObjectKeys(
      lineCount,
      FULL_VALIDATION_LINE_COUNT_KEYS,
      label + " line count " + index
    );
  }
  if (
    lineCounts.length === 0 ||
    new Set(lineCounts.map(({ path }) => path)).size !== lineCounts.length ||
    lineCounts.some(
      ({ path, lines, owner, sha256 }) =>
        typeof path !== "string" ||
        !isLineLimitedHumanAuthoredModule(path) ||
        !Number.isInteger(lines) ||
        lines < 0 ||
        lines > HUMAN_AUTHORED_MODULE_LINE_LIMIT ||
        !LEAF_ORDER.includes(owner) ||
        typeof sha256 !== "string" ||
        !/^[0-9a-f]{64}$/u.test(sha256)
    ) ||
    lineCounts.map(({ path }) => path).join("\n") !==
      [...lineCounts.map(({ path }) => path)].sort().join("\n")
  ) {
    throw new Error(label + ": physical-line evidence is invalid");
  }
  const requiredPaths = [
    ...new Set(
      Object.values(MODULARITY_REPAIR_ALLOWED_FILES).flat().filter(isLineLimitedHumanAuthoredModule)
    ),
  ];
  if (requiredPaths.some((path) => !lineCounts.some((entry) => entry.path === path))) {
    throw new Error(label + ": physical-line evidence omits a modularity owner path");
  }
  return lineCounts;
}

function requireExactFullValidationResultShape(result, label) {
  requireExactStrictScanObjectKeys(result, FULL_VALIDATION_RESULT_KEYS, label + " result");
  requireExactStrictScanArray(result.errors, 0, label + " errors");
  requireExactStrictScanArray(result.commands, FULL_GATE_COMMANDS.length, label + " commands");
  requireExactStrictScanArray(result.isolationCommands, 0, label + " isolation commands");
  requireExactStrictScanArrayObserved(result.lineCounts, label + " line counts");
  requireExactStrictScanObjectKeys(
    result.database,
    FULL_VALIDATION_DATABASE_KEYS,
    label + " database"
  );
  requireExactStrictScanObjectKeys(
    result.authority,
    FULL_VALIDATION_AUTHORITY_KEYS,
    label + " authority"
  );
  requireExactFullValidationFingerprint(result.authority.start, label + " authority start");
  requireExactFullValidationFingerprint(result.authority.end, label + " authority end");
  requireExactZeroFindingStrictScanProjection(result.strictScan, label + " strict scan");
  for (const [index, receipt] of result.commands.entries()) {
    requireExactFullValidationCommandReceipt(
      receipt,
      FULL_GATE_COMMANDS[index],
      label + " command " + index
    );
  }
  requireTask540LineCountEvidence(result.lineCounts, label);
  if (
    result.pass !== true ||
    result.summary !==
      "TASK-540 orchestrator-local full validation passed with zero strict findings" ||
    result.database.configured !== true ||
    result.database.reachable !== true ||
    result.database.selectOne !== 1 ||
    result.authority.runner !== "orchestrator-local-v1" ||
    result.authority.unchanged !== true
  ) {
    throw new Error(label + ": full-validation result values are invalid");
  }
  return result;
}

function requireFullValidation(result, label) {
  requireExactFullValidationResultShape(result, label);
  if (
    result.commands.some((receipt, index) => {
      const expected = FULL_GATE_COMMANDS[index];
      return (
        receipt.id !== expected.id || receipt.command !== expected.command || receipt.status !== 0
      );
    }) ||
    !smokeBaselineUnchanged(result.commands, label) ||
    result.database.configured !== true
  ) {
    throw new Error(
      label + ": full command receipt mismatch (" + fullValidationMismatchDetail(result) + ")"
    );
  }
  return result;
}

async function runFullValidation(label, phaseName) {
  void phaseName;
  await requireNoPendingTask540ModularityRepairs(label + ":modularity-repairs");
  await requireTask540ModularityFamilyMetadata(label + ":modularity-family-metadata");
  await requireTask540TouchedModuleLineLimit(label + ":before-commands");
  const execution = await runLocalCommandSequence(FULL_GATE_COMMANDS, { label });
  const lineCounts = await requireTask540TouchedModuleLineLimit(label + ":after-commands");
  const dbReceipt = execution.receipts.find(({ id }) => id === "dbPreflight");
  const database = dbReceipt
    ? parseDatabasePreflightReceipt(dbReceipt, label + ":dbPreflight")
    : Object.freeze({ configured: false, reachable: false, selectOne: 0 });
  const baselineUnchanged = smokeBaselineUnchanged(execution.receipts, label);
  const pass =
    execution.failedReceipt === null &&
    execution.receipts.length === FULL_GATE_COMMANDS.length &&
    execution.authority.unchanged &&
    baselineUnchanged &&
    execution.strictScan?.accepted === true;
  const result = Object.freeze({
    pass,
    summary: pass
      ? "TASK-540 orchestrator-local full validation passed with zero strict findings"
      : "TASK-540 orchestrator-local full validation failed",
    errors: pass
      ? []
      : [
          "TASK-540 local full validation stopped at " +
            (execution.failedReceipt?.id ?? "incomplete-command-matrix"),
        ],
    commands: execution.receipts,
    isolationCommands: execution.isolationReceipts,
    lineCounts,
    database,
    strictScan:
      execution.strictScan ??
      Object.freeze({
        accepted: false,
        exitCode: execution.failedReceipt?.status ?? -1,
        green: false,
        classification: "rejected",
        task540Findings: 1,
        toolingFailure: true,
        suppressed: false,
        externalFindings: [],
        scannerIds: [...STRICT_SCAN_SCANNER_IDS],
      }),
    authority: execution.authority,
  });
  const verified = requireFullValidation(result, label);
  const executorAuthority = await captureFrozenSmokeExecutorAuthority(
    label + " validated smoke executor"
  );
  if (!sameFrozenSmokeExecutorAuthority(IMPORTED_SMOKE_EXECUTOR_AUTHORITY, executorAuthority)) {
    throw new Error(label + ": validated smoke executor differs from imported authority");
  }
  FULL_VALIDATION_AUTHORITY.set(verified, executorAuthority);
  return verified;
}

const POST_AUDIT_LENSES = Object.freeze([
  [
    "schema-url",
    "Fixed-kind recursive reject-unknown, route/domain error split, legacy read repair, URL policy, byte identity, binding GC.",
  ],
  [
    "tabs-renderer",
    "Tab/slot identity, host-owned builder state, roving keyboard/ARIA/DOM IDs, direct-image versus media-field UUID semantics, non-interactive wrappers.",
  ],
  [
    "async-dirty-cache",
    "Entry/media promise authority and exact identity, one forced read per unique target, request/attempt cancellation, all subscriptions, commit-time dirty generations, navigation bypass only after successful create.",
  ],
  [
    "preferences-responsive-security",
    "Narrow/wide geometry and landmark role; isolated per-user settings with no localStorage/aggregate leak; a no-user toggle is hook-mount-local in-memory fallback that issues zero isolated GET/PATCH requests, writes zero browser storage, and resets on remount; direct provider A→B publishes B without an intermediate null while explicit sign-out/null and provider unmount still publish null; malformed GET/PATCH responses are rejected, and a malformed PATCH retains the exact optimistic intent as unsynced without automatic replay; central 400 mapping plus auth/CSRF/rate/self-scope route proof.",
  ],
  [
    "tests-docs-scope",
    "Single-writer ownership, correct Vitest/Bun lanes, non-weakened tests, product/cache/API/user docs, forbidden Page/widget paths, task/changelog reservation and executable smoke feasibility only; runtime evidence does not exist yet.",
  ],
]);

function authorizeClosureLeafRepair(snapshot, repairPending, priorGate, label) {
  const relativePath = "_docs/_CHANGELOG/README.md";
  const source = requireExactRollbackSnapshotUtf8(
    snapshot,
    relativePath,
    "TASK-540 closure-leaf repair authorization"
  );
  const indexState = classifyClosureEvidenceIndex(
    source,
    "TASK-540 closure-leaf repair authorization"
  );
  if (indexState.kind !== "consumed" || !indexState.anchor) {
    throw new Error("TASK-540 closure-leaf repair requires exact consumed anchor authority");
  }
  const anchor = indexState.anchor;
  const priorGateHash = hashedGateReceipt(priorGate);
  if (!equalHashedGateReceipts(anchor.closureControl.gateReceipt, priorGateHash)) {
    throw new Error("TASK-540 closure-leaf repair prior gate differs from durable control");
  }
  const successorGate = Object.freeze({
    field: "Revalidation Passed",
    value: repairGateValue(repairPending),
  });
  const repairAuthorization = Object.freeze({
    repairPendingSha256: hashRepairPendingReceipt(repairPending),
    priorGate: priorGateHash,
    successorGate: hashedGateReceipt(successorGate),
  });
  const authorizedAnchor = buildClosureAnchor(
    anchor.evidenceSha256,
    anchor.closureControl,
    anchor.collaborationLedgerPrefix,
    anchor.terminalCollaborationReceipt,
    repairAuthorization
  );
  const priorAnchorLine = formatClosureAnchor(anchor);
  const anchorLine = formatClosureAnchor(authorizedAnchor);
  const exactPriorAnchorLines = source.split("\n").filter((line) => line === priorAnchorLine);
  if (exactPriorAnchorLines.length !== 1 || priorAnchorLine === anchorLine) {
    throw new Error("TASK-540 closure-leaf repair anchor line is not uniquely replaceable");
  }
  const afterSource = source.replace(priorAnchorLine, anchorLine);
  if (
    projectTask540IndexUnrelatedBytes(
      source,
      "anchor-only",
      "TASK-540 closure-leaf repair authorization before"
    ) !==
      projectTask540IndexUnrelatedBytes(
        afterSource,
        "anchor-only",
        "TASK-540 closure-leaf repair authorization after"
      ) ||
    JSON.stringify(
      parseClosureAnchor(afterSource, "TASK-540 closure-leaf repair authorization after", {
        required: true,
      })
    ) !== JSON.stringify(authorizedAnchor)
  ) {
    throw new Error("TASK-540 closure-leaf repair changed bytes outside the exact anchor line");
  }
  return Object.freeze({
    authorizedAnchor,
    successorGate,
    entry: Object.freeze({
      relativePath,
      beforeSource: source,
      afterSource,
      changed: true,
    }),
    label,
  });
}

async function reopenClosureLeafUngated(leaf, label, phaseName) {
  const group = LEAF_STATUS_GROUPS[leaf.id];
  if (leaf.id !== "540-06-L01" || !group) {
    throw new Error("TASK-540 ungated remediation requires the closure leaf");
  }
  if (await readSharedClosurePending()) {
    throw new Error("TASK-540 ungated closure remediation cannot run after Closure Pending");
  }
  const indexState = classifyClosureEvidenceIndex(
    await readFile(ROOT + "/_docs/_CHANGELOG/README.md", "utf8"),
    "TASK-540 ungated closure remediation authority"
  );
  if (indexState.kind !== "reserved" || EXISTING_CHANGELOG_REL) {
    throw new Error("TASK-540 ungated closure remediation requires reserved/no-anchor authority");
  }
  const taskContractMutations = ungatedClosureReopenTaskContractMutations(group, leaf.id);
  const owner = Object.freeze({
    id: "reopen-ungated-" + leaf.id,
    allowedFiles: Object.freeze([ROOT_TASK_PATH, group.childPath, group.leafPath]),
    requiredFiles: Object.freeze([]),
    taskContractMutations,
  });
  const rollbackOwner = Object.freeze({
    id: owner.id + "-rollback",
    allowedFiles: Object.freeze([
      ...owner.allowedFiles,
      "_docs/_TASKS/README.md",
      "_docs/_CHANGELOG/README.md",
    ]),
    requiredFiles: Object.freeze([]),
  });
  const transactionSnapshot = await captureExactRollbackFiles(
    rollbackOwner.allowedFiles,
    "TASK-540 ungated closure repair pre-transaction"
  );
  if ((await readSharedClosurePending()) !== null) {
    throw new Error("TASK-540 ungated closure repair snapshot gained Closure Pending");
  }
  const boardBefore = requireExactRollbackSnapshotUtf8(
    transactionSnapshot,
    "_docs/_TASKS/README.md",
    "TASK-540 ungated closure repair"
  );
  if (readTask540BoardState(boardBefore).bucket !== "inProgress") {
    throw new Error("TASK-540 ungated closure remediation requires an active board row");
  }
  const changelogIndexBefore = requireExactRollbackSnapshotUtf8(
    transactionSnapshot,
    "_docs/_CHANGELOG/README.md",
    "TASK-540 ungated closure repair"
  );
  if (
    classifyClosureEvidenceIndex(
      changelogIndexBefore,
      "TASK-540 ungated closure repair snapshot authority"
    ).kind !== "reserved"
  ) {
    throw new Error("TASK-540 ungated closure repair snapshot lost reserved index authority");
  }
  const closureReceiptsBefore = captureClosureContractReceiptsFromSnapshot(
    transactionSnapshot,
    "TASK-540 ungated closure repair receipts"
  );
  const closureLeafSnapshot = requireExactRollbackSnapshotEntry(
    transactionSnapshot,
    group.leafPath,
    "TASK-540 ungated closure repair"
  );
  const taskSources = Object.freeze({
    root: requireExactRollbackSnapshotUtf8(
      transactionSnapshot,
      ROOT_TASK_PATH,
      "TASK-540 ungated closure repair root snapshot"
    ),
    child: requireExactRollbackSnapshotUtf8(
      transactionSnapshot,
      group.childPath,
      "TASK-540 ungated closure repair child snapshot"
    ),
    leaf: exactRollbackEntryUtf8(
      closureLeafSnapshot,
      "TASK-540 ungated closure repair leaf snapshot"
    ),
  });
  for (const [taskLabel, source] of Object.entries(taskSources)) {
    requireAbsentCompleted(
      readTaskMetadataField(source, "Completed"),
      "TASK-540 ungated closure repair snapshot " + taskLabel
    );
    if (readTaskMetadataField(source, "Repair Pending") !== null) {
      throw new Error(
        "TASK-540 ungated closure repair snapshot retained Repair Pending at " + taskLabel
      );
    }
  }
  const oldGate = readClosureLeafGateReceipt(
    parseCanonicalTaskStatusSource(taskSources.leaf, group.leafPath).source,
    "TASK-540 ungated closure repair"
  );
  if (readTaskMetadataField(taskSources.leaf, oldGate.field) !== oldGate.value) {
    throw new Error("TASK-540 ungated closure repair old gate is not snapshot-exact");
  }
  const entries = buildRepairReopenTaskContractSources(
    taskSources,
    group,
    leaf.id,
    null,
    taskContractMutations,
    "TASK-540 ungated closure repair source projection"
  );
  await runSnapshotDerivedExactTransaction(
    transactionSnapshot,
    rollbackOwner,
    entries,
    "TASK-540 ungated closure repair " + phaseName + ":" + label,
    async () => {
      const [rootState, childState, leafState, boardSource] = await Promise.all([
        readCanonicalTaskStatus(ROOT_TASK_PATH),
        readCanonicalTaskStatus(group.childPath),
        readCanonicalTaskStatus(group.leafPath),
        readFile(TASKS + "/README.md", "utf8"),
      ]);
      for (const [index, state] of [rootState, childState, leafState].entries()) {
        requireAbsentCompleted(
          readTaskMetadataField(state.source, "Completed"),
          "TASK-540 ungated closure repair contract " + index
        );
        requireAbsentImplementationComplete(
          readTaskMetadataField(state.source, "Implementation Complete"),
          "TASK-540 ungated closure repair contract " + index
        );
      }
      if (
        [rootState, childState, leafState].some(
          ({ status, source }) =>
            status !== RESUME_TASK_STATUS.active || readTaskMetadataField(source, "Repair Pending")
        ) ||
        readTaskMetadataField(childState.source, "Fix Started") !== RUN_DATE ||
        readTaskMetadataField(leafState.source, "Fix Started") !== RUN_DATE ||
        CLOSURE_GATE_FIELDS.some((field) => readTaskMetadataField(leafState.source, field))
      ) {
        throw new Error("TASK-540 pre-closure ungated repair state is not exact");
      }
      requireTableStatus(childState.source, leaf.id, RESUME_TASK_STATUS.active, "TASK-540 child");
      requireTableStatus(
        rootState.source,
        group.childId,
        RESUME_TASK_STATUS.active,
        "TASK-540 root"
      );
      if (boardSource !== boardBefore) {
        throw new Error("TASK-540 ungated closure repair changed the board or statistics");
      }
      if ((await readFile(ROOT + "/_docs/_CHANGELOG/README.md", "utf8")) !== changelogIndexBefore) {
        throw new Error("TASK-540 ungated closure repair changed the changelog index");
      }
      await verifyClosureContractReceipts(
        closureReceiptsBefore,
        "TASK-540 pre-closure ungated repair",
        { allowGateChange: true }
      );
    }
  );
  return Object.freeze({ mode: "ungated-closure", repairPending: null });
}

function repairReopenTaskContractMutations(group, leafId) {
  if (typeof leafId !== "string" || leafId.length === 0) {
    throw new Error("TASK-540 repair-reopen leaf authority is invalid");
  }
  return Object.freeze([
    Object.freeze({
      relativePath: ROOT_TASK_PATH,
      mutableStatus: true,
      tableTaskIds: Object.freeze([]),
      tableStatusTaskIds: Object.freeze([group.childId]),
      mutableFields: Object.freeze([]),
    }),
    Object.freeze({
      relativePath: group.childPath,
      mutableStatus: true,
      tableTaskIds: Object.freeze([]),
      tableStatusTaskIds: Object.freeze([leafId]),
      mutableFields: Object.freeze(["Fix Started", "Implementation Complete", "Completed"]),
    }),
    Object.freeze({
      relativePath: group.leafPath,
      mutableStatus: true,
      tableTaskIds: Object.freeze([]),
      tableStatusTaskIds: Object.freeze([]),
      mutableFields: Object.freeze([
        "Fix Started",
        "Implementation Complete",
        "Completed",
        "Targeted Gate Passed",
        "Revalidation Passed",
        "Repair Pending",
      ]),
    }),
  ]);
}

function ungatedClosureReopenTaskContractMutations(group, leafId) {
  if (leafId !== "540-06-L01") {
    throw new Error("TASK-540 ungated repair-reopen authority requires the closure leaf");
  }
  return Object.freeze([
    Object.freeze({
      relativePath: ROOT_TASK_PATH,
      mutableStatus: true,
      tableTaskIds: Object.freeze([]),
      tableStatusTaskIds: Object.freeze([group.childId]),
      mutableFields: Object.freeze([]),
    }),
    Object.freeze({
      relativePath: group.childPath,
      mutableStatus: true,
      tableTaskIds: Object.freeze([]),
      tableStatusTaskIds: Object.freeze([leafId]),
      mutableFields: Object.freeze(["Fix Started", "Implementation Complete"]),
    }),
    Object.freeze({
      relativePath: group.leafPath,
      mutableStatus: true,
      tableTaskIds: Object.freeze([]),
      tableStatusTaskIds: Object.freeze([]),
      mutableFields: Object.freeze([
        "Fix Started",
        "Implementation Complete",
        "Targeted Gate Passed",
        "Revalidation Passed",
      ]),
    }),
  ]);
}

function setCanonicalTaskStatus(source, status, label) {
  const current = parseCanonicalTaskStatusSource(source, label).status;
  if (current === status) return source;
  return source.replace(/^\*\*Status:\*\*.*$/m, "**Status:** " + status);
}

function setCanonicalTaskTableStatus(source, taskId, status, label) {
  const row = readCanonicalTaskStatusTableRow(source, taskId, label);
  if (row.cells.at(-1) === status) return source;
  const marker = "<TASK-540-MUTABLE-STATUS-CELL:" + taskId + ">";
  const projected = projectTaskStatusTableCell(row, taskId, label);
  if (projected.split(marker).length !== 2) {
    throw new Error(label + ": canonical task status-cell marker is not unique");
  }
  const lines = source.split("\n");
  lines[row.lineIndex] = projected.replace(marker, status);
  return lines.join("\n");
}

function taskMetadataLineIndex(lines, field, label) {
  const prefix = "**" + field + ":**";
  const matches = [];
  for (let index = 0; index < lines.length; index += 1) {
    if (lines[index].startsWith(prefix)) matches.push(index);
  }
  if (matches.length > 1) {
    throw new Error(label + ": duplicated mutable task metadata field " + field);
  }
  return matches[0] ?? -1;
}

function removeCanonicalTaskMetadataFields(source, fields, label) {
  const lines = source.split("\n");
  for (const field of fields) {
    const index = taskMetadataLineIndex(lines, field, label);
    if (index >= 0) lines.splice(index, 1);
  }
  return lines.join("\n");
}

function setCanonicalTaskMetadataField(source, field, value, insertAfterFields, label) {
  if (
    typeof value !== "string" ||
    value.length === 0 ||
    value.includes("\n") ||
    value.includes("\r")
  ) {
    throw new Error(label + ": invalid task metadata value for " + field);
  }
  const lines = source.split("\n");
  const existingIndex = taskMetadataLineIndex(lines, field, label);
  const exactLine = "**" + field + ":** " + value;
  if (existingIndex >= 0) {
    lines[existingIndex] = exactLine;
    return lines.join("\n");
  }
  let anchorIndex = -1;
  for (const anchorField of insertAfterFields) {
    anchorIndex = taskMetadataLineIndex(lines, anchorField, label);
    if (anchorIndex >= 0) break;
  }
  if (anchorIndex < 0) {
    throw new Error(label + ": task metadata insertion anchor is missing for " + field);
  }
  lines.splice(anchorIndex + 1, 0, exactLine);
  return lines.join("\n");
}

function buildRepairReopenTaskContractSources(
  sources,
  group,
  leafId,
  repairPending,
  mutations,
  label
) {
  if (repairPending !== null) {
    parseRepairPending(repairPending, label + " Repair Pending");
  }
  const sourceByPath = new Map([
    [ROOT_TASK_PATH, sources.root],
    [group.childPath, sources.child],
    [group.leafPath, sources.leaf],
  ]);
  if (
    new Set(sourceByPath.keys()).size !== 3 ||
    [...sourceByPath.values()].some((source) => typeof source !== "string")
  ) {
    throw new Error(label + ": repair-reopen source authority is invalid");
  }

  let root = setCanonicalTaskStatus(sources.root, RESUME_TASK_STATUS.active, label + " root");
  root = setCanonicalTaskTableStatus(
    root,
    group.childId,
    RESUME_TASK_STATUS.active,
    label + " root"
  );

  let child = setCanonicalTaskStatus(sources.child, RESUME_TASK_STATUS.active, label + " child");
  child = setCanonicalTaskTableStatus(child, leafId, RESUME_TASK_STATUS.active, label + " child");
  child = removeCanonicalTaskMetadataFields(
    child,
    repairPending === null ? ["Implementation Complete"] : ["Implementation Complete", "Completed"],
    label + " child"
  );
  child = setCanonicalTaskMetadataField(
    child,
    "Fix Started",
    RUN_DATE,
    ["Repair Started", "Started", "Status"],
    label + " child"
  );

  let leaf = setCanonicalTaskStatus(sources.leaf, RESUME_TASK_STATUS.active, label + " leaf");
  leaf = removeCanonicalTaskMetadataFields(
    leaf,
    repairPending === null
      ? ["Implementation Complete", "Targeted Gate Passed", "Revalidation Passed"]
      : [
          "Implementation Complete",
          "Completed",
          "Targeted Gate Passed",
          "Revalidation Passed",
          "Repair Pending",
        ],
    label + " leaf"
  );
  leaf = setCanonicalTaskMetadataField(
    leaf,
    "Fix Started",
    RUN_DATE,
    ["Repair Started", "Started", "Status"],
    label + " leaf"
  );
  if (repairPending !== null) {
    leaf = setCanonicalTaskMetadataField(
      leaf,
      "Repair Pending",
      repairPending,
      ["Fix Started"],
      label + " leaf"
    );
  }

  const expectedByPath = new Map([
    [ROOT_TASK_PATH, root],
    [group.childPath, child],
    [group.leafPath, leaf],
  ]);
  const entries = mutations.map((mutation) => {
    const beforeSource = sourceByPath.get(mutation.relativePath);
    const afterSource = expectedByPath.get(mutation.relativePath);
    if (typeof beforeSource !== "string" || typeof afterSource !== "string") {
      throw new Error(label + ": repair-reopen mutation path is not source-backed");
    }
    if (
      projectTaskContractUnrelatedBytes(beforeSource, mutation, label + " before") !==
      projectTaskContractUnrelatedBytes(afterSource, mutation, label + " after")
    ) {
      throw new Error(label + ": repair-reopen changed bytes outside exact status authority");
    }
    return Object.freeze({
      relativePath: mutation.relativePath,
      beforeSource,
      afterSource,
      changed: beforeSource !== afterSource,
    });
  });
  return Object.freeze(entries);
}

function exactRollbackEntryWithUtf8Source(entry, source, label) {
  exactRollbackEntryUtf8(entry, label);
  if (typeof source !== "string") {
    throw new Error(label + ": snapshot-derived task source is invalid");
  }
  const bytes = Buffer.from(source, "utf8");
  return Object.freeze({
    ...entry,
    bytesBase64: bytes.toString("base64"),
    byteLength: bytes.length,
    sha256: exactBytesSha256(bytes),
  });
}

function buildSnapshotDerivedExactTransaction(snapshot, entries, label) {
  if (!snapshot || !Array.isArray(snapshot.entries) || !Array.isArray(entries)) {
    throw new Error(label + ": snapshot-derived exact transaction is malformed");
  }
  const mutationByPath = new Map();
  for (const entry of entries) {
    if (
      !entry ||
      typeof entry.relativePath !== "string" ||
      typeof entry.beforeSource !== "string" ||
      typeof entry.afterSource !== "string" ||
      typeof entry.changed !== "boolean" ||
      entry.changed !== (entry.beforeSource !== entry.afterSource) ||
      mutationByPath.has(entry.relativePath)
    ) {
      throw new Error(label + ": snapshot-derived source mutation is invalid or duplicated");
    }
    const snapshotEntry = requireExactRollbackSnapshotEntry(snapshot, entry.relativePath, label);
    if (exactRollbackEntryUtf8(snapshotEntry, label) !== entry.beforeSource) {
      throw new Error(label + ": source mutation differs from its exact transaction snapshot");
    }
    mutationByPath.set(entry.relativePath, entry);
  }
  const expectedEntries = snapshot.entries.map((snapshotEntry) => {
    const mutation = mutationByPath.get(snapshotEntry.relativePath);
    return mutation
      ? exactRollbackEntryWithUtf8Source(snapshotEntry, mutation.afterSource, label)
      : snapshotEntry;
  });
  if (mutationByPath.size !== entries.length) {
    throw new Error(label + ": snapshot-derived transaction omitted a source mutation");
  }
  const changedPaths = entries
    .filter(({ changed }) => changed)
    .map(({ relativePath }) => relativePath);
  const expectedByPath = new Map(expectedEntries.map((entry) => [entry.relativePath, entry]));
  return Object.freeze({
    expectedSnapshot: Object.freeze({
      ...snapshot,
      entries: Object.freeze(expectedEntries),
    }),
    changedEntries: Object.freeze(changedPaths.map((path) => expectedByPath.get(path))),
    changedPaths: Object.freeze(changedPaths),
  });
}

async function snapshotDerivedTransactionAuthority(label, allowedDeltaPaths) {
  const allowed = new Set(allowedDeltaPaths);
  const [head, branch, tracked, untracked, indexAuthority] = await Promise.all([
    git(["rev-parse", "HEAD"]),
    git(["branch", "--show-current"]),
    git(["diff", "--name-only", "-z", "HEAD"]),
    git(["ls-files", "--others", "--exclude-standard", "-z"]),
    requireInitialGitIndexBaseline(label + " index authority"),
  ]);
  const paths = [...new Set([...splitNul(tracked), ...splitNul(untracked)])].sort();
  const hashes = Object.create(null);
  for (const path of paths) {
    // Exact transaction paths are observed through independent FileHandle samples.
    // Their post-rename inode/ctime visibility is not repository authority.
    if (!allowed.has(path)) hashes[path] = await hashPath(path);
  }
  return Object.freeze({
    head: head.trim(),
    branch: branch.trim(),
    indexAuthority,
    paths: Object.freeze(paths),
    hashes: Object.freeze(hashes),
  });
}

async function requireSnapshotDerivedExactAuthority(snapshot, allowedDeltaPaths, label) {
  if (new Set(allowedDeltaPaths).size !== allowedDeltaPaths.length) {
    throw new Error(label + ": exact transaction authority paths are duplicated");
  }
  const [current, sensitiveEnv] = await Promise.all([
    snapshotDerivedTransactionAuthority(label + " repository snapshot", allowedDeltaPaths),
    hashSensitiveEnvProjection(),
  ]);
  const allowed = new Set(allowedDeltaPaths);
  const authorityPaths = [...new Set([...snapshot.authority.paths, ...current.paths])].sort();
  const unrelatedDelta = authorityPaths.filter(
    (relativePath) =>
      !allowed.has(relativePath) &&
      (snapshot.authority.hashes[relativePath] ?? "<clean>") !==
        (current.hashes[relativePath] ?? "<clean>")
  );
  if (
    current.head !== snapshot.authority.head ||
    current.branch !== snapshot.authority.branch ||
    !sameGitIndexAuthority(current.indexAuthority, snapshot.authority.indexAuthority) ||
    !equalHashMaps(sensitiveEnv, snapshot.sensitiveEnv) ||
    unrelatedDelta.length > 0
  ) {
    throw new Error(label + ": snapshot-derived exact transaction authority changed");
  }
}

function equalExactRollbackEntryState(left, right) {
  return Boolean(
    left &&
    right &&
    left.relativePath === right.relativePath &&
    left.exists === right.exists &&
    left.bytesBase64 === right.bytesBase64 &&
    left.byteLength === right.byteLength &&
    left.sha256 === right.sha256 &&
    left.mode === right.mode
  );
}

function sequenceExactWriteReceipt(receipt, sequence, beforeEntry, afterEntry, label) {
  if (
    !receipt ||
    receipt.committed !== true ||
    !["rename", "unlink"].includes(receipt.operation) ||
    receipt.relativePath !== beforeEntry.relativePath ||
    receipt.relativePath !== afterEntry.relativePath ||
    JSON.stringify(receipt.before) !==
      JSON.stringify(exactRollbackEntrySafeDiagnostic(beforeEntry)) ||
    JSON.stringify(receipt.after) !==
      JSON.stringify(exactRollbackEntrySafeDiagnostic(afterEntry)) ||
    receipt.mountClass !== EXACT_TRANSACTION_MOUNT_CLASS ||
    !Number.isSafeInteger(sequence) ||
    sequence < 1
  ) {
    throw new Error(label + ": committed exact-write receipt is malformed");
  }
  return Object.freeze({ ...receipt, sequence });
}

async function verifySnapshotDerivedExactSnapshot(expectedSnapshot, label, options = {}) {
  return observeExactRollbackSnapshot(expectedSnapshot, label, options);
}

async function writeSnapshotDerivedExactEntry(beforeEntry, afterEntry, label, options = {}) {
  if (beforeEntry.relativePath !== afterEntry.relativePath) {
    throw new Error(label + ": exact write boundary paths differ");
  }
  return restoreExactRollbackEntry(afterEntry, label, {
    expectedCurrentEntry: beforeEntry,
    observeCommitted: true,
    ...options,
  });
}

async function restoreSnapshotDerivedExactReceipts(
  snapshot,
  expectedSnapshot,
  receipts,
  owner,
  label,
  { observationOptions = undefined, requireAuthority = requireSnapshotDerivedExactAuthority } = {}
) {
  const expectedByPath = new Map(
    expectedSnapshot.entries.map((entry) => [entry.relativePath, entry])
  );
  if (
    expectedByPath.size !== expectedSnapshot.entries.length ||
    expectedByPath.size !== snapshot.entries.length ||
    !sameUniqueSet(
      snapshot.entries.map(({ relativePath }) => relativePath),
      owner.allowedFiles
    ) ||
    !Array.isArray(receipts) ||
    new Set(receipts.map(({ relativePath }) => relativePath)).size !== receipts.length ||
    typeof requireAuthority !== "function"
  ) {
    throw new Error(label + ": receipt rollback authority is malformed");
  }
  const beforeByPath = new Map(snapshot.entries.map((entry) => [entry.relativePath, entry]));
  const receiptPaths = Object.freeze(receipts.map(({ relativePath }) => relativePath));
  const rollbackWrites = [];
  const alreadyBefore = [];
  try {
    for (const receipt of [...receipts].reverse()) {
      const beforeEntry = beforeByPath.get(receipt.relativePath);
      const afterEntry = expectedByPath.get(receipt.relativePath);
      if (!beforeEntry || !afterEntry) {
        throw new Error(label + ": receipt rollback path escaped its snapshot authority");
      }
      sequenceExactWriteReceipt(receipt, receipt.sequence, beforeEntry, afterEntry, label);
      const boundary = await observeExactRollbackSemanticState(
        beforeEntry.relativePath,
        [beforeEntry, afterEntry],
        [],
        label + " stable rollback boundary",
        observationOptions
      );
      await requireAuthority(
        snapshot,
        receiptPaths,
        label + " authority after rollback boundary " + beforeEntry.relativePath
      );
      if (sameExactRollbackSemanticState(boundary.state, beforeEntry)) {
        alreadyBefore.push(beforeEntry.relativePath);
        continue;
      }
      let rollbackReceipt = null;
      try {
        rollbackReceipt = await restoreExactRollbackEntry(
          beforeEntry,
          label + " one-shot reverse rollback",
          {
            expectedCurrentEntry: afterEntry,
            observeCommitted: true,
            observationOptions,
          }
        );
      } catch (error) {
        const committed = exactWriteReceiptFromError(error);
        if (committed) {
          rollbackWrites.push(
            sequenceExactWriteReceipt(
              committed,
              rollbackWrites.length + 1,
              afterEntry,
              beforeEntry,
              label + " failed rollback receipt"
            )
          );
        }
        throw error;
      }
      rollbackWrites.push(
        sequenceExactWriteReceipt(
          rollbackReceipt,
          rollbackWrites.length + 1,
          afterEntry,
          beforeEntry,
          label + " rollback receipt"
        )
      );
      await requireAuthority(
        snapshot,
        receiptPaths,
        label + " authority after rollback write observation " + beforeEntry.relativePath
      );
    }
    await requireAuthority(
      snapshot,
      receiptPaths,
      label + " authority before final rollback state"
    );
    await observeExactRollbackSnapshot(snapshot, label + " stable receipt rollback", {
      transitionalSnapshot: expectedSnapshot,
      observationOptions,
    });
    await requireAuthority(snapshot, receiptPaths, label + " authority after final rollback state");
  } catch (error) {
    throw wrapAccumulatedExactRollbackError(error, rollbackWrites, label);
  }
  return Object.freeze({
    rollbackWrites: Object.freeze(rollbackWrites),
    alreadyBefore: Object.freeze(alreadyBefore),
  });
}

const SNAPSHOT_DERIVED_EXACT_TRANSACTION_IO = Object.freeze({
  requireAuthority: requireSnapshotDerivedExactAuthority,
  verifySnapshot: verifySnapshotDerivedExactSnapshot,
  writeEntry: writeSnapshotDerivedExactEntry,
  restoreReceipts: restoreSnapshotDerivedExactReceipts,
});

function requireSnapshotDerivedExactTransactionIo(io, label) {
  const keys = ["requireAuthority", "verifySnapshot", "writeEntry", "restoreReceipts"];
  if (
    io !== SNAPSHOT_DERIVED_EXACT_TRANSACTION_IO &&
    (!HERMETIC_SELF_TEST_MODE ||
      JSON.stringify(Object.keys(io ?? {}).sort()) !== JSON.stringify([...keys].sort()))
  ) {
    throw new Error(label + ": non-production exact transaction I/O lacks hermetic authority");
  }
  for (const key of keys) {
    if (typeof io?.[key] !== "function") {
      throw new Error(label + ": exact transaction I/O is missing " + key);
    }
  }
  return io;
}

async function persistSnapshotDerivedExactSources(
  snapshot,
  entries,
  label,
  io = SNAPSHOT_DERIVED_EXACT_TRANSACTION_IO,
  preparedTransaction = null,
  committedReceipts = []
) {
  requireSnapshotDerivedExactTransactionIo(io, label);
  if (!Array.isArray(committedReceipts) || committedReceipts.length !== 0) {
    throw new Error(label + ": committed receipt sink must begin empty");
  }
  const transaction =
    preparedTransaction ?? buildSnapshotDerivedExactTransaction(snapshot, entries, label);
  const beforeByPath = new Map(snapshot.entries.map((entry) => [entry.relativePath, entry]));
  const committedPaths = () => committedReceipts.map(({ relativePath }) => relativePath);
  await io.requireAuthority(snapshot, [], label + " pre-mutation authority");
  await io.verifySnapshot(snapshot, label + " pre-mutation exact snapshot");
  await io.requireAuthority(snapshot, [], label + " authority after pre-mutation exact snapshot");
  for (const afterEntry of transaction.changedEntries) {
    const beforeEntry = beforeByPath.get(afterEntry.relativePath);
    await io.requireAuthority(
      snapshot,
      committedPaths(),
      label + " authority immediately before forward write " + afterEntry.relativePath
    );
    let receipt = null;
    try {
      receipt = await io.writeEntry(beforeEntry, afterEntry, label + " one-shot atomic mutation");
    } catch (error) {
      const committed = exactWriteReceiptFromError(error);
      if (committed) {
        committedReceipts.push(
          sequenceExactWriteReceipt(
            committed,
            committedReceipts.length + 1,
            beforeEntry,
            afterEntry,
            label
          )
        );
      }
      if (committed) {
        try {
          await io.requireAuthority(
            snapshot,
            committedPaths(),
            label +
              " authority after failed committed forward observation " +
              afterEntry.relativePath
          );
        } catch (authorityError) {
          throw new AggregateError(
            [error, authorityError],
            label + ": committed forward failure and closing authority both failed"
          );
        }
      }
      throw error;
    }
    committedReceipts.push(
      sequenceExactWriteReceipt(
        receipt,
        committedReceipts.length + 1,
        beforeEntry,
        afterEntry,
        label
      )
    );
    await io.requireAuthority(
      snapshot,
      committedPaths(),
      label + " authority after committed forward observation " + afterEntry.relativePath
    );
  }
  await io.requireAuthority(
    snapshot,
    committedPaths(),
    label + " authority before full exact state"
  );
  await io.verifySnapshot(transaction.expectedSnapshot, label + " persisted exact mutation", {
    transitionalSnapshot: snapshot,
  });
  await io.requireAuthority(
    snapshot,
    committedPaths(),
    label + " authority after full exact state"
  );
  return Object.freeze({ transaction, committedReceipts: Object.freeze([...committedReceipts]) });
}

async function runSnapshotDerivedExactTransaction(
  snapshot,
  owner,
  entries,
  label,
  verifyMutation,
  io = SNAPSHOT_DERIVED_EXACT_TRANSACTION_IO
) {
  requireSnapshotDerivedExactTransactionIo(io, label);
  if (typeof verifyMutation !== "function") {
    throw new Error(label + ": exact transaction verifier is missing");
  }
  const transaction = buildSnapshotDerivedExactTransaction(snapshot, entries, label);
  const committedReceipts = [];
  let mutationError = null;
  try {
    await persistSnapshotDerivedExactSources(
      snapshot,
      entries,
      label,
      io,
      transaction,
      committedReceipts
    );
  } catch (error) {
    mutationError = error;
  }
  let verificationError = null;
  if (!mutationError) {
    const receiptPaths = committedReceipts.map(({ relativePath }) => relativePath);
    try {
      await io.requireAuthority(
        snapshot,
        receiptPaths,
        label + " authority immediately before semantic verification"
      );
    } catch (error) {
      verificationError = error;
    }
    if (!verificationError) {
      const semanticErrors = [];
      try {
        await verifyMutation(transaction.expectedSnapshot);
      } catch (error) {
        semanticErrors.push(error);
      }
      try {
        await io.verifySnapshot(
          transaction.expectedSnapshot,
          label + " exact state after semantic verification",
          { transitionalSnapshot: snapshot }
        );
      } catch (error) {
        semanticErrors.push(error);
      }
      try {
        await io.requireAuthority(
          snapshot,
          receiptPaths,
          label + " authority after semantic exact state"
        );
      } catch (error) {
        semanticErrors.push(error);
      }
      verificationError =
        semanticErrors.length === 0
          ? null
          : semanticErrors.length === 1
            ? semanticErrors[0]
            : new AggregateError(
                semanticErrors,
                label + ": semantic exact-state authority sandwich failed"
              );
    }
  }
  if (mutationError || verificationError) {
    const primaryError =
      mutationError && verificationError
        ? new AggregateError(
            [mutationError, verificationError],
            label + ": exact mutation and verification both failed"
          )
        : (mutationError ?? verificationError);
    if (
      committedReceipts.length === 0 ||
      exactTransactionErrorContains(primaryError, ExactTransactionCollisionError)
    ) {
      throw primaryError;
    }
    const receiptPaths = committedReceipts.map(({ relativePath }) => relativePath);
    try {
      await io.requireAuthority(
        snapshot,
        receiptPaths,
        label + " pre-rollback repository authority"
      );
      await io.restoreReceipts(
        snapshot,
        transaction.expectedSnapshot,
        Object.freeze([...committedReceipts]),
        owner,
        label + " one-shot receipt rollback",
        { requireAuthority: io.requireAuthority }
      );
      await io.requireAuthority(
        snapshot,
        receiptPaths,
        label + " authority before final rollback verification"
      );
      await io.verifySnapshot(snapshot, label + " exact state after one-shot rollback", {
        transitionalSnapshot: transaction.expectedSnapshot,
      });
      await io.requireAuthority(
        snapshot,
        receiptPaths,
        label + " authority after final rollback verification"
      );
    } catch (rollbackError) {
      throw new AggregateError(
        [primaryError, rollbackError],
        label + ": exact transaction and one-shot rollback both failed"
      );
    }
    throw primaryError;
  }
  return transaction;
}

const INTERRUPTED_REOPEN_RECOVERY_ARGUMENT = "--recover-interrupted-reopen=540-01-L01";
const INTERRUPTED_REOPEN_RECOVERY_PINS = deepFreezeExact({
  relativePath: "_docs/_TASKS/TASK-540-01-Strict-Screen-Data-Urls-Tabs-And-Binding-Gc.md",
  head: "d803bbcfa5b52cb1e5036836592bd92ee2c03b6f",
  branch: "feature/tasks-fixes",
  stagedDiffSha256: "76ab9281213b1f39ebe90865b5e26de67c3178bbd7b2e570757c0324756d280f",
  stageProjectionSha256: "43ffd83de864b933ec9890aff30d0b74d580a3165df3ddcc2111d633f440d996",
  indexMode: "100644",
  indexBlob: "7ecf425f97469b71de7eac1d91d032f2d6ad5678",
  indexByteLength: 21_005,
  indexSha256: "c1acb5fae33783b1bc330cf8b36c4ceac5750f2eb886037a226f0f8ac839dd8a",
  partialByteLength: 20_898,
  partialSha256: "36d0a688bb700a216cca68ef1c937fe305a3aec01dd42c1dacfbb68f07e6fcbf",
  worktreeMode: 0o644,
  fixStartedDate: "2026-07-18",
});

function parseInterruptedReopenRecoveryArgv(argv) {
  if (
    !Array.isArray(argv) ||
    argv.length !== 1 ||
    argv[0] !== INTERRUPTED_REOPEN_RECOVERY_ARGUMENT
  ) {
    throw new Error("TASK-540 interrupted-reopen recovery requires its one exact argument");
  }
  return argv[0];
}

function requireInterruptedReopenRecoveryPins(pins, label) {
  const keys = Object.keys(INTERRUPTED_REOPEN_RECOVERY_PINS);
  if (
    !pins ||
    Object.getPrototypeOf(pins) !== Object.prototype ||
    JSON.stringify(Object.keys(pins).sort()) !== JSON.stringify([...keys].sort()) ||
    typeof pins.relativePath !== "string" ||
    !pins.relativePath.startsWith("_docs/_TASKS/") ||
    !/^[0-9a-f]{40}$/u.test(pins.head) ||
    typeof pins.branch !== "string" ||
    !/^[0-9a-f]{64}$/u.test(pins.stagedDiffSha256) ||
    !/^[0-9a-f]{64}$/u.test(pins.stageProjectionSha256) ||
    !/^[0-7]{6}$/u.test(pins.indexMode) ||
    !/^[0-9a-f]{40}$/u.test(pins.indexBlob) ||
    !Number.isSafeInteger(pins.indexByteLength) ||
    pins.indexByteLength <= 0 ||
    !/^[0-9a-f]{64}$/u.test(pins.indexSha256) ||
    !Number.isSafeInteger(pins.partialByteLength) ||
    pins.partialByteLength <= 0 ||
    !/^[0-9a-f]{64}$/u.test(pins.partialSha256) ||
    pins.worktreeMode !== 0o644 ||
    !isCanonicalIsoDate(pins.fixStartedDate)
  ) {
    throw new Error(label + ": interrupted-reopen recovery pins are malformed");
  }
  return pins;
}

function interruptedReopenRecoveryMutation(relativePath) {
  return Object.freeze({
    relativePath,
    mutableStatus: false,
    tableTaskIds: Object.freeze([]),
    tableStatusTaskIds: Object.freeze([]),
    mutableFields: Object.freeze(["Fix Started", "Implementation Complete"]),
  });
}

function deriveInterruptedReopenPartialSource(indexSource, pins, label) {
  let partial = removeCanonicalTaskMetadataFields(indexSource, ["Implementation Complete"], label);
  partial = setCanonicalTaskMetadataField(
    partial,
    "Fix Started",
    pins.fixStartedDate,
    ["Repair Started", "Started", "Status"],
    label
  );
  return partial;
}

function buildInterruptedReopenRecoveryPlan(
  { pins, authority, indexSource, currentEntry, siblingsPrepared },
  label
) {
  requireInterruptedReopenRecoveryPins(pins, label);
  if (
    !authority ||
    Object.getPrototypeOf(authority) !== Object.prototype ||
    authority.head !== pins.head ||
    authority.branch !== pins.branch ||
    authority.stagedDiffSha256 !== pins.stagedDiffSha256 ||
    authority.stageProjectionSha256 !== pins.stageProjectionSha256 ||
    authority.indexMode !== pins.indexMode ||
    authority.indexBlob !== pins.indexBlob ||
    authority.indexByteLength !== pins.indexByteLength ||
    authority.indexSha256 !== pins.indexSha256
  ) {
    throw new Error(label + ": interrupted-reopen authority pins changed");
  }
  if (siblingsPrepared !== true || typeof indexSource !== "string") {
    throw new Error(label + ": interrupted-reopen prepared sibling authority is absent");
  }
  const indexBytes = Buffer.from(indexSource, "utf8");
  if (
    indexBytes.length !== pins.indexByteLength ||
    exactBytesSha256(indexBytes) !== pins.indexSha256
  ) {
    throw new Error(label + ": interrupted-reopen index source differs from its exact pin");
  }
  const partialSource = deriveInterruptedReopenPartialSource(indexSource, pins, label);
  const partialBytes = Buffer.from(partialSource, "utf8");
  if (
    partialBytes.length !== pins.partialByteLength ||
    exactBytesSha256(partialBytes) !== pins.partialSha256
  ) {
    throw new Error(label + ": interrupted-reopen partial source is not snapshot-derived");
  }
  const mutation = interruptedReopenRecoveryMutation(pins.relativePath);
  if (
    projectTaskContractUnrelatedBytes(indexSource, mutation, label + " index projection") !==
    projectTaskContractUnrelatedBytes(partialSource, mutation, label + " partial projection")
  ) {
    throw new Error(label + ": interrupted-reopen partial projection escaped authority");
  }
  const currentSource = exactRollbackEntryUtf8(currentEntry, label);
  if (currentEntry.relativePath !== pins.relativePath || currentEntry.mode !== pins.worktreeMode) {
    throw new Error(label + ": interrupted-reopen worktree path or mode changed");
  }
  const state =
    currentEntry.byteLength === pins.partialByteLength &&
    currentEntry.sha256 === pins.partialSha256 &&
    currentSource === partialSource
      ? "partial"
      : currentEntry.byteLength === pins.indexByteLength &&
          currentEntry.sha256 === pins.indexSha256 &&
          currentSource === indexSource
        ? "prior"
        : null;
  if (!state) {
    throw new Error(label + ": interrupted-reopen worktree is neither exact partial nor prior");
  }
  return Object.freeze({
    state,
    entries: Object.freeze([
      Object.freeze({
        relativePath: pins.relativePath,
        beforeSource: currentSource,
        afterSource: indexSource,
        changed: state === "partial",
      }),
    ]),
  });
}

function requireInterruptedReopenPreparedState(resumeState, changelogState, label) {
  if (
    resumeState.mode !== "initial" ||
    resumeState.startIndex !== LEAVES.length ||
    resumeState.startLeafId !== null ||
    resumeState.repair !== null ||
    JSON.stringify(resumeState.landedLeafIds) !== JSON.stringify(LEAF_ORDER) ||
    resumeState.remainingLeafIds.length !== 0 ||
    changelogState.mode !== "reserved-pre-closure-regated"
  ) {
    throw new Error(label + ": interrupted-reopen siblings are not exact prepared state");
  }
  return Object.freeze({ resumeState, changelogState });
}

async function validateInterruptedReopenPreparedSiblings(indexSource, pins, label) {
  const resumeState = await resolveLeafResumeState({
    async readTaskStatus(relativePath) {
      return relativePath === pins.relativePath
        ? parseCanonicalTaskStatusSource(indexSource, relativePath)
        : readCanonicalTaskStatus(relativePath);
    },
  });
  const changelogState = await resolveChangelogResumeState(resumeState);
  return requireInterruptedReopenPreparedState(resumeState, changelogState, label);
}

function parseInterruptedReopenIndexStage(bytes, pins, label) {
  const records = decodeGroundedNulProjection(bytes, label);
  if (records.length !== 1) {
    throw new Error(label + ": interrupted-reopen index stage entry is missing or duplicated");
  }
  const separator = records[0].indexOf("\t");
  const metadata = separator < 0 ? "" : records[0].slice(0, separator);
  const relativePath = separator < 0 ? "" : records[0].slice(separator + 1);
  const match = metadata.match(/^([0-7]{6}) ([0-9a-f]{40}) 0$/u);
  if (!match || relativePath !== pins.relativePath) {
    throw new Error(label + ": interrupted-reopen index stage entry is malformed");
  }
  return Object.freeze({ indexMode: match[1], indexBlob: match[2] });
}

async function captureInterruptedReopenRecoveryAuthority(pins, indexAuthority, label) {
  const [head, branch, stagedDiff, stageEntry, indexBytes] = await Promise.all([
    git(["rev-parse", "HEAD"]),
    git(["branch", "--show-current"]),
    gitBytes(["diff", "--cached", "--binary"]),
    gitBytes(["ls-files", "--stage", "-z", "--", pins.relativePath]),
    gitBytes(["cat-file", "blob", ":" + pins.relativePath]),
  ]);
  const parsedStage = parseInterruptedReopenIndexStage(stageEntry, pins, label);
  let indexSource;
  try {
    indexSource = new TextDecoder("utf-8", { fatal: true }).decode(indexBytes);
  } catch {
    throw new Error(label + ": interrupted-reopen index source is not canonical UTF-8");
  }
  const authority = Object.freeze({
    head: head.trim(),
    branch: branch.trim(),
    stagedDiffSha256: exactBytesSha256(stagedDiff),
    stageProjectionSha256: indexAuthority.stageProjection.sha256,
    ...parsedStage,
    indexByteLength: indexBytes.length,
    indexSha256: exactBytesSha256(indexBytes),
  });
  return Object.freeze({ authority, indexSource });
}

const INTERRUPTED_REOPEN_RECOVERY_OUTPUT_KEYS = Object.freeze([
  "mode",
  "recovered",
  "stagedDiffSha256",
  "stageProjectionSha256",
  "worktreeSha256",
]);

function buildInterruptedReopenRecoveryOutput(recovered, authority, freshEntry, label) {
  const output = {
    recovered,
    stagedDiffSha256: authority?.stagedDiffSha256,
    stageProjectionSha256: authority?.stageProjectionSha256,
    worktreeSha256: freshEntry?.sha256,
    mode:
      Number.isSafeInteger(freshEntry?.mode) && freshEntry.mode >= 0
        ? "0" + freshEntry.mode.toString(8)
        : null,
  };
  if (
    typeof output.recovered !== "boolean" ||
    !/^[0-9a-f]{64}$/u.test(output.stagedDiffSha256 ?? "") ||
    !/^[0-9a-f]{64}$/u.test(output.stageProjectionSha256 ?? "") ||
    !/^[0-9a-f]{64}$/u.test(output.worktreeSha256 ?? "") ||
    !/^0[0-7]{3,4}$/u.test(output.mode ?? "") ||
    JSON.stringify(Object.keys(output).sort()) !==
      JSON.stringify([...INTERRUPTED_REOPEN_RECOVERY_OUTPUT_KEYS].sort())
  ) {
    throw new Error(label + ": interrupted-reopen safe output projection is invalid");
  }
  return Object.freeze(output);
}

const INTERRUPTED_REOPEN_RECOVERY_COORDINATOR_IO = Object.freeze({
  captureInitialIndex: captureInitialGitIndexBaseline,
  captureRecoveryAuthority: captureInterruptedReopenRecoveryAuthority,
  captureSnapshot: captureExactRollbackFiles,
  validatePrepared: validateInterruptedReopenPreparedSiblings,
  validateCoverage: validateResumeGraphCoverage,
  runTransaction: runSnapshotDerivedExactTransaction,
  requireInitialIndex: requireInitialGitIndexBaseline,
  requireSnapshotAuthority: requireSnapshotDerivedExactAuthority,
  observeFinal: observeExactRollbackSemanticState,
});

function requireInterruptedReopenRecoveryCoordinatorIo(io, label) {
  const keys = [
    "captureInitialIndex",
    "captureRecoveryAuthority",
    "captureSnapshot",
    "observeFinal",
    "requireInitialIndex",
    "requireSnapshotAuthority",
    "runTransaction",
    "validateCoverage",
    "validatePrepared",
  ];
  if (
    io !== INTERRUPTED_REOPEN_RECOVERY_COORDINATOR_IO &&
    (!HERMETIC_SELF_TEST_MODE ||
      JSON.stringify(Object.keys(io ?? {}).sort()) !== JSON.stringify(keys))
  ) {
    throw new Error(label + ": interrupted-reopen coordinator I/O lacks hermetic authority");
  }
  for (const key of keys) {
    if (typeof io?.[key] !== "function") {
      throw new Error(label + ": interrupted-reopen coordinator I/O is missing " + key);
    }
  }
  return io;
}

function requireSameInterruptedReopenAuthority(current, initial, label) {
  if (JSON.stringify(current?.authority) !== JSON.stringify(initial?.authority)) {
    throw new Error(label + ": interrupted-reopen staged authority changed");
  }
  return current;
}

function requireInterruptedReopenFreshPriorEntry(entry, pins, label) {
  if (
    entry?.relativePath !== pins.relativePath ||
    entry.exists !== true ||
    entry.sha256 !== pins.indexSha256 ||
    entry.byteLength !== pins.indexByteLength ||
    entry.mode !== pins.worktreeMode
  ) {
    throw new Error(label + ": interrupted-reopen final worktree state is not exact prior");
  }
  return entry;
}

async function runInterruptedReopenRecoveryCoordinator(
  pins,
  io = INTERRUPTED_REOPEN_RECOVERY_COORDINATOR_IO,
  label = "TASK-540 interrupted-reopen recovery"
) {
  requireInterruptedReopenRecoveryPins(pins, label);
  requireInterruptedReopenRecoveryCoordinatorIo(io, label);
  const initialIndex = await io.captureInitialIndex(label + " initial Git index");
  const captured = await io.captureRecoveryAuthority(pins, initialIndex, label + " preflight");
  const snapshot = await io.captureSnapshot([pins.relativePath], label + " exact current snapshot");
  const prepared = await io.validatePrepared(captured.indexSource, pins, label + " preflight");
  const plan = buildInterruptedReopenRecoveryPlan(
    {
      pins,
      authority: captured.authority,
      indexSource: captured.indexSource,
      currentEntry: snapshot.entries[0],
      siblingsPrepared: Boolean(prepared),
    },
    label
  );
  const owner = Object.freeze({
    id: "recover-interrupted-reopen-540-01-L01",
    allowedFiles: Object.freeze([pins.relativePath]),
    requiredFiles: Object.freeze([]),
  });
  const transaction = await io.runTransaction(
    snapshot,
    owner,
    plan.entries,
    label + " one-shot transaction",
    async () => {
      const state = await io.validatePrepared(
        captured.indexSource,
        pins,
        label + " semantic verification"
      );
      await io.validateCoverage(
        state.resumeState,
        state.changelogState,
        label + " semantic verification"
      );
    }
  );
  const expectedPriorEntry = requireInterruptedReopenFreshPriorEntry(
    transaction.expectedSnapshot.entries.find(
      ({ relativePath }) => relativePath === pins.relativePath
    ),
    pins,
    label + " expected transaction state"
  );

  const checkpointIndex = await io.requireInitialIndex(label + " checkpoint Git index");
  requireSameInterruptedReopenAuthority(
    await io.captureRecoveryAuthority(pins, checkpointIndex, label + " checkpoint authority"),
    captured,
    label + " checkpoint authority"
  );
  await io.requireSnapshotAuthority(
    snapshot,
    [pins.relativePath],
    label + " authority before final prepared resolver"
  );
  const finalPrepared = await io.validatePrepared(
    captured.indexSource,
    pins,
    label + " final prepared resolver"
  );
  await io.validateCoverage(
    finalPrepared.resumeState,
    finalPrepared.changelogState,
    label + " final prepared resolver"
  );
  await io.requireSnapshotAuthority(
    snapshot,
    [pins.relativePath],
    label + " authority after final prepared resolver"
  );

  const firstFinalObservation = await io.observeFinal(
    pins.relativePath,
    [expectedPriorEntry],
    [],
    label + " final exact prior observation"
  );
  requireInterruptedReopenFreshPriorEntry(
    firstFinalObservation.state,
    pins,
    label + " final exact prior observation"
  );
  await io.requireSnapshotAuthority(
    snapshot,
    [pins.relativePath],
    label + " authority after final exact prior observation"
  );
  const finalIndex = await io.requireInitialIndex(label + " final Git index");
  const finalAuthority = requireSameInterruptedReopenAuthority(
    await io.captureRecoveryAuthority(pins, finalIndex, label + " final authority"),
    captured,
    label + " final authority"
  );
  const outputObservation = await io.observeFinal(
    pins.relativePath,
    [expectedPriorEntry],
    [],
    label + " output exact prior observation"
  );
  const freshEntry = requireInterruptedReopenFreshPriorEntry(
    outputObservation.state,
    pins,
    label + " output exact prior observation"
  );
  return buildInterruptedReopenRecoveryOutput(
    plan.state === "partial",
    finalAuthority.authority,
    freshEntry,
    label
  );
}

async function recoverInterruptedReopen54001L01() {
  return runInterruptedReopenRecoveryCoordinator(INTERRUPTED_REOPEN_RECOVERY_PINS);
}

