const TASK540_LOCAL_ORCHESTRATOR_IMPORTS = Object.freeze([
  "node:child_process",
  "node:crypto",
  "node:fs",
  "node:fs/promises",
  "node:path",
  "node:url",
  "node:util",
  "./task-540-codex-agent-bridge.mjs",
]);
const TASK540_LOCAL_ORCHESTRATOR_IMPORT_BINDINGS = Object.freeze([
  "{execFile,spawn}",
  "{createHash,randomBytes}",
  "{constantsasFS_CONSTANTS}",
  "{lstat,mkdir,open,readFile,readdir,realpath,rename,rmdir,unlink,}",
  "{basename,dirname,resolve}",
  "{fileURLToPath,pathToFileURL}",
  "{promisify}",
  "{sweepPriorBridgeLaunchesForRecovery}",
]);

function requireTask540LocalOrchestratorEntrypointSource(source, label) {
  if (!source.startsWith('import { execFile, spawn } from "node:child_process";')) {
    throw new Error(label + ": imports must remain the first local-orchestrator statements");
  }
  const entrypointBoundary = "const ROOT_AUTHORITY = await deriveRoot(import.meta.url);";
  const entrypointEnd = source.indexOf(entrypointBoundary);
  if (entrypointEnd <= 0) {
    throw new Error(label + ": local-orchestrator entrypoint boundary is missing");
  }
  const entrypoint = source.slice(0, entrypointEnd);
  const staticImports = [
    ...entrypoint.matchAll(/^[\t ]*import\s+(\{[\s\S]*?\})\s+from\s+["']([^"']+)["'];[\t ]*$/gm),
  ];
  const importTokens = entrypoint.match(/\bimport\b/g) ?? [];
  const bindings = staticImports.map((match) => match[1].replace(/\s+/g, ""));
  const specifiers = staticImports.map((match) => match[2]);
  if (
    importTokens.length !== TASK540_LOCAL_ORCHESTRATOR_IMPORTS.length ||
    JSON.stringify(specifiers) !== JSON.stringify(TASK540_LOCAL_ORCHESTRATOR_IMPORTS) ||
    JSON.stringify(bindings) !== JSON.stringify(TASK540_LOCAL_ORCHESTRATOR_IMPORT_BINDINGS)
  ) {
    throw new Error(label + ": local-orchestrator static import contract drifted");
  }
  const dynamicImports = source.match(/\bimport\s*\(/gu) ?? [];
  if (
    dynamicImports.length !== 1 ||
    source.split("await import(pathToFileURL(IMPLEMENTER).href);").length - 1 !== 1
  ) {
    throw new Error(label + ": frozen implementer dynamic import contract drifted");
  }
}

async function assertTask540LocalOrchestratorEntrypointContract() {
  const source = await readFile(ROOT + "/" + LOCAL_ORCHESTRATOR_WORKFLOW_REL, "utf8");
  requireTask540LocalOrchestratorEntrypointSource(source, "TASK-540 local entrypoint");
  const mutations = [
    source.replace(
      'import { execFile, spawn } from "node:child_process";',
      'import { execFile, spawn } from "node:path";'
    ),
    source.replace(
      "const ROOT_AUTHORITY = await deriveRoot(import.meta.url);",
      'import { stat } from "node:fs/promises";\n' +
        "const ROOT_AUTHORITY = await deriveRoot(import.meta.url);"
    ),
    source.replace(
      "const ROOT_AUTHORITY = await deriveRoot(import.meta.url);",
      'await import ("node:path");\n' + "const ROOT_AUTHORITY = await deriveRoot(import.meta.url);"
    ),
    source.replace(
      "const ROOT_AUTHORITY = await deriveRoot(import.meta.url);",
      'const sixth = import("node:path");\n' +
        "const ROOT_AUTHORITY = await deriveRoot(import.meta.url);"
    ),
    source.replace('from "node:url";', 'from "node:url-copy";'),
    source.replace(
      "await import(pathToFileURL(IMPLEMENTER).href);",
      "await import(pathToFileURL(IMPLEMENTER + '-copy').href);"
    ),
    source.replace(
      'import { execFile, spawn } from "node:child_process";',
      'import { spawn } from "node:child_process";'
    ),
    "\n" + source,
  ];
  for (const [index, mutation] of mutations.entries()) {
    let rejected = false;
    try {
      requireTask540LocalOrchestratorEntrypointSource(
        mutation,
        "TASK-540 local entrypoint mutation " + (index + 1)
      );
    } catch {
      rejected = true;
    }
    if (!rejected) {
      throw new Error("TASK-540 local entrypoint mutation escaped validation");
    }
  }
  return mutations.length + 1;
}

